/** 2-3 P16：例2 的应用——绳在圆柱（滚筒）上绕若干圈后，一端的张力 F 可以平衡
 *  另一端大得多的载荷 mg；绕的圈数越多、张角 θ 越大，所需 F 越小（F = mg·e^{-μθ}）。静态图。 */
export function CylDrum() {
  const cy = 236                       // 滚筒轴线
  const x0 = 252, x1 = 648             // 滚筒两端
  const ry = 62                        // 端面椭圆半短轴（半径）
  const rx = 28
  return (
    <svg viewBox="0 0 900 560" width="100%" height="100%">
      <defs>
        <linearGradient id="cdBody" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#9fd0f0" />
          <stop offset="42%" stopColor="#5b9ed0" />
          <stop offset="100%" stopColor="#2b5f8f" />
        </linearGradient>
        <radialGradient id="cdEnd" cx="0.36" cy="0.3" r="0.95">
          <stop offset="0%" stopColor="#cfe8fa" />
          <stop offset="100%" stopColor="#3a7099" />
        </radialGradient>
      </defs>
      {/* 筒身 */}
      <rect x={x0} y={cy - ry} width={x1 - x0} height={2 * ry} fill="url(#cdBody)" />
      <ellipse cx={x1} cy={cy} rx={rx} ry={ry} fill="url(#cdEnd)" stroke="#2b5f8f" strokeWidth="3" />
      <ellipse cx={x0} cy={cy} rx={rx} ry={ry} fill="url(#cdEnd)" stroke="#2b5f8f" strokeWidth="3" />
      {/* 绕在筒上的若干圈绳 */}
      {Array.from({ length: 5 }, (_, i) => {
        const cx = 320 + i * 70
        return (
          <g key={i}>
            <ellipse cx={cx} cy={cy} rx={13} ry={ry + 2} fill="none" stroke="#c62828" strokeWidth="8" />
            <path d={`M ${cx - 13} ${cy - ry - 6} Q ${cx + 22} ${cy - ry - 34} ${cx + 13 + 54} ${cy - ry - 6}`}
              fill="none" stroke="#c62828" strokeWidth="8" />
          </g>
        )
      })}
      {/* 左端绳（下端施加力 F） */}
      <path d={`M ${x0 - 6} ${cy + 8} L ${x0 - 6} ${cy + 150} L 196 ${cy + 150} L 196 468`}
        fill="none" stroke="#c62828" strokeWidth="8" />
      <Arrow x1={196} y1={462} x2={196} y2={516} color="#c62828" w={9} />
      <Vec ch="F" x={214} y={514} size={52} fill="#C00000" />
      {/* 右端绳（悬挂物块） */}
      <path d={`M ${x1 + 6} ${cy + 8} L ${x1 + 6} ${cy + 96} L 700 ${cy + 96} L 700 392`}
        fill="none" stroke="#c62828" strokeWidth="8" />
      <rect x={646} y={392} width="108" height="92" rx="8" fill="#f2f2f2" stroke="#666" strokeWidth="4" />
      <Vec ch="m" x={682} y={448} size={50} fill="#111" />
    </svg>
  )
}

