/** 2-4 P11/P12：例3 —— 圆锥摆：摆长 l 的细绳悬挂质量为 m 的小球，
 *  球在水平面内以角速度 ω 作匀速率圆周运动，求绳与铅直方向的夹角 θ。
 *  几何全部由解析式给出：悬点 A、轨道圆心 O 在 A 正下方 l cosθ 处，
 *  轨道半径 r = l sinθ；斜二测投影下圆成椭圆 (rx, 0.28rx)，
 *  球位置 P(φ) = O + (r cosφ, 0.28 r sinφ)，速度 v ∝ (−r sinφ, 0.28 r cosφ)。
 *  取 φ = 25°（椭圆前右侧），v 指向左下方且不穿轨道。静态图。 */
export function ConicalPendulum() {
  const A: [number, number] = [300, 52]        // 悬点
  const l = 380
  const th = 32 * D2R
  const O: [number, number] = [A[0], A[1] + l * Math.cos(th)]   // 轨道圆心（A 正下方）
  const r = l * Math.sin(th)                                    // 轨道半径
  const ky = 0.28
  const phi = 25 * D2R
  const B: [number, number] = [O[0] + r * Math.cos(phi), O[1] + ky * r * Math.sin(phi)]
  const vd: [number, number] = (() => {
    const dx = -r * Math.sin(phi), dy = ky * r * Math.cos(phi)
    const n = Math.hypot(dx, dy)
    return [dx / n, dy / n]
  })()
  const vT = tipL(B, vd, 100)
  return (
    <svg viewBox="0 0 620 560" width="100%" height="100%">
      <defs>
        <Hatch id="cp-h" />
      </defs>
      {/* 天花板与悬点 */}
      <rect x="120" y="22" width="360" height="30" fill="url(#cp-h)" stroke="#555" strokeWidth="2.5" />
      <circle cx={A[0]} cy={A[1]} r="8" fill="#111" />
      {/* 铅直轴 */}
      <line x1={A[0]} y1={A[1]} x2={A[0]} y2="452" stroke="#999" strokeWidth="2.5" strokeDasharray="14 10" />
      {/* 圆轨道（斜二测成椭圆）与半径 */}
      <ellipse cx={O[0]} cy={O[1]} rx={r} ry={ky * r} fill="none" stroke="#888" strokeWidth="3" strokeDasharray="12 9" />
      <line x1={O[0]} y1={O[1]} x2={B[0]} y2={B[1]} stroke="#111" strokeWidth="3" />
      <text x={386} y={362} fontSize="46" fontStyle="italic" fontFamily={SERIF} fill="#111">r</text>
      <text x={254} y={366} fontSize="44" fontStyle="italic" fontFamily={SERIF} fill="#111">O</text>
      {/* 绳与 θ */}
      <line x1={A[0]} y1={A[1]} x2={B[0]} y2={B[1]} stroke="#333" strokeWidth="4.5" />
      <ArcLine cx={A[0]} cy={A[1]} r={90} a0={62.2 * D2R} a1={90 * D2R} color="#C000C0" w={4.5} />
      <text x={312} y={168} fontSize="46" fontStyle="italic" fontFamily={SERIF} fill="#C000C0">θ</text>
      {/* 球与速度 */}
      <Arrow x1={B[0]} y1={B[1]} x2={vT[0]} y2={vT[1]} color="#2E8B57" w={8} />
      <Vec ch="v" x={368} y={478} size={48} fill="#2E8B57" />
      <circle cx={B[0]} cy={B[1]} r="16" fill="#c0392b" stroke="#7a1a10" strokeWidth="3" />
      <text x={520} y={380} fontSize="44" fontStyle="italic" fontFamily={SERIF} fill="#111">m</text>
      {/* 转动角速度 ω */}
      <ArcArrow cx={300} cy={496} r={60} a0={20 * D2R} a1={160 * D2R} color="#C000C0" w={5} />
      <text x={382} y={540} fontSize="48" fontStyle="italic" fontFamily={SERIF} fill="#C000C0">ω</text>
    </svg>
  )
}

