/* ============ 2-1 牛顿定律 图示 ============ */

/** 2-4 P22：例5 的 v–t 曲线 —— v(t) = (F₀/b)[1 − e^{−(b/m)t}]，t → ∞ 时趋近极限速度 F₀/b。
 *  曲线按解析式逐点生成；虚线为极限速度的水平渐近线。静态图。 */
export function VtLimit() {
  const O: [number, number] = [90, 400]
  const XW = 555, YW = 260
  const tMax = 4.5
  const pts: string[] = []
  for (let i = 0; i <= 90; i++) {
    const t = (tMax * i) / 90
    pts.push(`${(O[0] + (XW * t) / tMax).toFixed(1)},${(O[1] - YW * (1 - Math.exp(-t))).toFixed(1)}`)
  }
  return (
    <svg viewBox="0 0 700 480" width="100%" height="100%">
      {/* 坐标轴 */}
      <Arrow x1={O[0]} y1={O[1]} x2={O[0] + XW + 15} y2={O[1]} color="#111" w={4.5} />
      <Arrow x1={O[0]} y1={O[1]} x2={O[0]} y2={O[1] - YW - 40} color="#111" w={4.5} />
      <text x="58" y="104" fontSize="46" fontStyle="italic" fontFamily={SERIF} fill="#111">v</text>
      <text x="672" y="418" fontSize="46" fontStyle="italic" fontFamily={SERIF} fill="#111">t</text>
      <text x="52" y="422" fontSize="46" fontStyle="italic" fontFamily={SERIF} fill="#111">O</text>
      {/* 极限速度渐近线 */}
      <line x1={O[0]} y1={O[1] - YW} x2={O[0] + XW + 10} y2={O[1] - YW}
        stroke="#C000C0" strokeWidth="3.5" strokeDasharray="14 10" />
      <text x="14" y={O[1] - YW + 16} fontSize="42" fontStyle="italic" fontFamily={SERIF} fill="#C000C0">F₀/b</text>
      {/* v(t) */}
      <polyline points={pts.join(' ')} fill="none" stroke="#E00" strokeWidth="5" />
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 2-4 P23：例5 的讨论 —— 若球在水面具有竖直向下的速率 v₀，且浮力与重力抵消
 *  （F_B = P），球在水中只受阻力 F_r = −b v，则 v(t) = v₀ e^{−(b/m)t}，速率按指数衰减。
 *  曲线按解析式逐点生成；竖直标尺与 VtLimit 取同一高度比例，便于两图对照。静态图。 */
export function VtDecay() {
  const O: [number, number] = [90, 400]
  const XW = 555, YW = 260
  const tMax = 4.5
  const pts: string[] = []
  for (let i = 0; i <= 90; i++) {
    const t = (tMax * i) / 90
    pts.push(`${(O[0] + (XW * t) / tMax).toFixed(1)},${(O[1] - YW * Math.exp(-t)).toFixed(1)}`)
  }
  return (
    <svg viewBox="0 0 700 480" width="100%" height="100%">
      <Arrow x1={O[0]} y1={O[1]} x2={O[0] + XW + 15} y2={O[1]} color="#111" w={4.5} />
      <Arrow x1={O[0]} y1={O[1]} x2={O[0]} y2={O[1] - YW - 40} color="#111" w={4.5} />
      <text x="58" y="104" fontSize="46" fontStyle="italic" fontFamily={SERIF} fill="#111">v</text>
      <text x="672" y="418" fontSize="46" fontStyle="italic" fontFamily={SERIF} fill="#111">t</text>
      <text x="52" y="422" fontSize="46" fontStyle="italic" fontFamily={SERIF} fill="#111">O</text>
      {/* 初速水平参考线 */}
      <line x1={O[0]} y1={O[1] - YW} x2={O[0] + XW + 10} y2={O[1] - YW}
        stroke="#999" strokeWidth="3" strokeDasharray="14 10" />
      <text x="14" y={O[1] - YW + 16} fontSize="42" fontStyle="italic" fontFamily={SERIF} fill="#111">v₀</text>
      {/* v(t) = v₀ e^{−(b/m)t} */}
      <polyline points={pts.join(' ')} fill="none" stroke="#E00" strokeWidth="5" />
    </svg>
  )
}

/* ================= 2-5 非惯性系 惯性力 =================
   配色：支持力 / 向心力 红 #E00；重力 mḡ 蓝 #0000CD；惯性力与惯性离心力 橙 #E07000；
        加速度 紫 #7B1FA2；绳张力 洋红 #C000C0；几何与坐标轴 黑 #111。
   本组全部为静态图 —— 这一节讲「换个参考系方程怎么变」，画面本身不随时间演化。 */

/** 椭圆弧 + 末端箭头（斜二测圆盘的转动方向指示） */
function EllArrow({ cx, cy, rx, ry, a0, a1, color = '#E8862E', w = 6 }: {
  cx: number; cy: number; rx: number; ry: number; a0: number; a1: number; color?: string; w?: number
}) {
  const n = 22
  const pts: [number, number][] = []
  for (let i = 0; i <= n; i++) {
    const a = a0 + ((a1 - a0) * i) / n
    pts.push([cx + rx * Math.cos(a), cy + ry * Math.sin(a)])
  }
  const [hx, hy] = pts[n]
  const da = Math.atan2(hy - pts[n - 1][1], hx - pts[n - 1][0])
  const p = da + Math.PI / 2
  const xb = hx - 26 * Math.cos(da), yb = hy - 26 * Math.sin(da)
  return (
    <g>
      <polyline points={pts.map(q => q.join(',')).join(' ')} fill="none" stroke={color} strokeWidth={w} />
      <polygon
        points={`${hx},${hy} ${xb + 13 * Math.cos(p)},${yb + 13 * Math.sin(p)} ${xb - 13 * Math.cos(p)},${yb - 13 * Math.sin(p)}`}
        fill={color} />
    </g>
  )
}

/** m 乘矢量（mā₀、mḡ 这类）：斜体 m + 矢量字母（可带角标），共用一条基线 */
function MVecN({ ch, sub, x, y, size = 44, fill = '#E00' }: {
  ch: string; sub?: string; x: number; y: number; size?: number; fill?: string
}) {
  return (
    <g>
      <text x={x} y={y} fontSize={size} fontStyle="italic" fill={fill} fontFamily={SERIF}>m</text>
      {sub
        ? <VecN ch={ch} sub={sub} x={x + size * 0.72} y={y} size={size} fill={fill} />
        : <Vec ch={ch} x={x + size * 0.72} y={y} size={size} fill={fill} />}
    </g>
  )
}

/* ---- 2-5 三棱柱（斜面）统一几何 ----
   右直角在右下、斜面自左下向右上抬升，a₀ 指向左。
   推导图 / 地面系解 / 非惯性系解 三张图必须**同形** → 全部由这一份常量派生（改一处三张全对）。 */
const W25 = { gy: 470, x0: 300, x1: 800, topY: 250, gx0: 40, gx1: 880 }
const W25rad = Math.atan2(W25.gy - W25.topY, W25.x1 - W25.x0)
const W25deg = (W25rad * 180) / Math.PI
/** 斜面外法向（指向上方偏左，即物体受支持力的方向） */
const W25eN: [number, number] = [-Math.sin(W25rad), -Math.cos(W25rad)]
/** 斜面上比例位置 t 处的方块中心：底面与斜面贴合 ⇒ 沿外法向偏移半个边长 */
function w25Blk(t: number, half = 46): [number, number] {
  const px = W25.x0 + (W25.x1 - W25.x0) * t
  const py = W25.gy - (W25.gy - W25.topY) * t
  return [px + W25eN[0] * half, py + W25eN[1] * half]
}
/** 地面 + 楔体 + θ + 方块（三张图共用的底图，保证同形） */
function W25Base() {
  const c = w25Blk(0.5)
  const rt = 96
  return (
    <g>
      <line x1={W25.gx0} y1={W25.gy} x2={W25.gx1} y2={W25.gy} stroke="#111" strokeWidth="6" />
      <polygon points={`${W25.x0},${W25.gy} ${W25.x1},${W25.topY} ${W25.x1},${W25.gy}`}
        fill="#3B62C8" stroke="#111" strokeWidth="4" />
      <ArcLine cx={W25.x0} cy={W25.gy} r={rt} a0={-W25rad} a1={0} color="#111" w={3.5} />
      <text x={W25.x0 + rt * 1.5} y={W25.gy - 18} fontSize="46" fontStyle="italic"
        fontFamily={SERIF}>θ</text>
      <rect x={c[0] - 46} y={c[1] - 46} width="92" height="92" fill="#D01B1B" stroke="#111"
        strokeWidth="3.5" transform={`rotate(${-W25deg} ${c[0]} ${c[1]})`} />
      <text x={W25.x1 + 52} y={W25.gy - 20} fontSize="50" fontStyle="italic"
        fontFamily={SERIF}>S</text>
      <text x={W25.x0 + 118} y={W25.gy + 48} fontSize="46" fontStyle="italic" fill="#1F4E9C"
        fontFamily={SERIF}>S′</text>
    </g>
  )
}

