/** 3-4 第 3 页：恒力做功 —— 位移与力的分量分层画，互不遮挡 */
export function WorkConst() {
  const A: [number, number] = [240, 296]          // 受力点（物块中心）
  const L = 300, a = 35 * D2R
  const E: [number, number] = [A[0] + L * Math.cos(a), A[1] - L * Math.sin(a)]
  const H: [number, number] = [A[0] + L * Math.cos(a), A[1]]
  const V: [number, number] = [A[0], A[1] - L * Math.sin(a)]
  const r0 = 118
  return (
    <svg viewBox="0 0 1300 560" width="100%" height="100%">
      {/* 路径 */}
      <line x1={140} y1={320} x2={1040} y2={320} stroke="#C8D3DE" strokeWidth="2.5" />
      <text x={122} y={366} fontSize="34" fontStyle="italic" fontFamily={SERIF} fill="#333">a</text>
      <text x={1052} y={366} fontSize="34" fontStyle="italic" fontFamily={SERIF} fill="#333">b</text>
      {/* 物块（起始位置实线 / 终止位置虚线） */}
      <rect x={200} y={272} width={80} height={48} fill="#F2F5F8" stroke="#333" strokeWidth="2.5" />
      <rect x={900} y={272} width={80} height={48} fill="none" stroke="#C8D3DE"
        strokeWidth="2.5" strokeDasharray="8 6" />
      {/* 位移（单独一层，画在路径下方） */}
      <line x1={240} y1={320} x2={240} y2={386} stroke="#C8D3DE" strokeWidth="2"
        strokeDasharray="6 6" />
      <line x1={940} y1={320} x2={940} y2={386} stroke="#C8D3DE" strokeWidth="2"
        strokeDasharray="6 6" />
      <Line2Arrows x1={240} y1={386} x2={940} y2={386} color="#0A8A0A" w={5} />
      <Vec ch="s" x={576} y={430} size={40} fill="#0A8A0A" anchor="middle" />
      {/* 力：从受力点出发 */}
      <Arrow x1={A[0]} y1={A[1]} x2={E[0]} y2={E[1]} color="#E00" w={8} />
      <Vec ch="F" x={E[0] + 14} y={E[1] + 12} size={42} fill="#E00" />
      {/* 两个分量：虚线，与 F 严格构成矩形 */}
      <line x1={H[0]} y1={H[1]} x2={E[0]} y2={E[1]} stroke="#E9A0A0" strokeWidth="2"
        strokeDasharray="8 6" />
      <line x1={V[0]} y1={V[1]} x2={E[0]} y2={E[1]} stroke="#E9A0A0" strokeWidth="2"
        strokeDasharray="8 6" />
      <Arrow x1={A[0]} y1={A[1]} x2={H[0]} y2={H[1]} color="#E00" w={5} dashed />
      <Arrow x1={A[0]} y1={A[1]} x2={V[0]} y2={V[1]} color="#E00" w={5} dashed />
      <text x={H[0] + 12} y={A[1] + 34} fontSize="30" fontFamily={SERIF} fill="#E00">F cosα</text>
      <text x={V[0] - 14} y={V[1] + 14} fontSize="30" fontFamily={SERIF} fill="#E00"
        textAnchor="end">F sinα</text>
      {/* α 角 */}
      <ArcLine cx={A[0]} cy={A[1]} r={r0} a0={0} a1={-a} color="#333" w={2.5} />
      <text x={A[0] + r0 * 1.26} y={A[1] - r0 * 0.42} fontSize="34" fontFamily={SERIF} fill="#333">α</text>
      {/* 公式 */}
      <text x={900} y={132} fontSize="42" fontFamily={SERIF} fill="#111">W = F s cosα</text>
      <text x={900} y={196} fontSize="36" fontFamily={SERIF} fill="#666">= F · s</text>
      <text x={140} y={520} fontSize="30" fontFamily={HEI} fill="#666">
        只有沿位移方向的分量做功；垂直分力不做功
      </text>
    </svg>
  )
}

/** 3-4 第 4 页：变力的功 —— 路径分割 + 逐段求功（F 与弧元夹角处处相同） */
export function WorkCurve() {
  const BEZ: BezSeg = [[180, 460], [400, 400], [520, 190], [900, 175]]
  const N = 6
  const pts: string[] = []
  for (let i = 0; i <= 60; i++) pts.push(bezPt(BEZ, i / 60).join(','))
  const at = (s: number) => bezPt(BEZ, s)
  const tg = (s: number) => unitP(bezD1(BEZ, s))
  const rot = (v: [number, number], d: number): [number, number] =>
    [v[0] * Math.cos(d) - v[1] * Math.sin(d), v[0] * Math.sin(d) + v[1] * Math.cos(d)]
  const areaPts: string[] = ['966,486']
  for (let i = 0; i <= 30; i++) {
    const u = i / 30
    areaPts.push(`${966 + 372 * u},${486 - 250 * (0.28 + 0.72 * Math.sin((Math.PI * u) / 2))}`)
  }
  areaPts.push('1338,486')
  return (
    <svg viewBox="0 0 1440 620" width="100%" height="100%">
      <polyline points={pts.join(' ')} fill="none" stroke="#7A9FD8" strokeWidth="6" />
      <text x={150} y={500} fontSize="34" fontStyle="italic" fontFamily={SERIF} fill="#333">a</text>
      <text x={912} y={168} fontSize="34" fontStyle="italic" fontFamily={SERIF} fill="#333">b</text>
      {/* 分段点 + 各段的弧元与力 */}
      {Array.from({ length: N }).map((_, i) => {
        const s0 = i / N, s1 = (i + 1) / N
        const P = at(s0), Q = at(s1)
        const t = tg((s0 + s1) / 2)
        return (
          <g key={i}>
            <Arrow x1={P[0]} y1={P[1]} x2={Q[0]} y2={Q[1]} color="#0A8A0A" w={5} />
            {i % 2 === 0 && (() => {
              const fd = rot(t, -55 * D2R)
              const LF = 104
              return (
                <>
                  <Arrow x1={P[0]} y1={P[1]} x2={P[0] + fd[0] * LF} y2={P[1] + fd[1] * LF}
                    color="#E00" w={5} />
                  <text x={P[0] + fd[0] * LF + 8} y={P[1] + fd[1] * LF + 6}
                    fontSize="28" fontFamily={SERIF} fill="#E00">F</text>
                  {i === 2 && (
                    <>
                      <ArcLine cx={P[0]} cy={P[1]} r={62}
                        a0={Math.atan2(t[1], t[0])} a1={Math.atan2(fd[1], fd[0])}
                        color="#333" w={2} />
                      <text x={P[0] + 46 * fd[0] + 16 * t[0]}
                        y={P[1] + 46 * fd[1] + 16 * t[1] + 10}
                        fontSize="28" fontFamily={SERIF} fill="#333">θ</text>
                    </>
                  )}
                </>
              )
            })()}
          </g>
        )
      })}
      <text x={232} y={452} fontSize="28" fontFamily={SERIF} fill="#0A8A0A">Δr</text>
      {/* 右侧：F–s 曲线下的面积 */}
      <line x1={940} y1={486} x2={1372} y2={486} stroke="#333" strokeWidth="3.5" />
      <line x1={966} y1={510} x2={966} y2={170} stroke="#333" strokeWidth="3.5" />
      <text x={1380} y={500} fontSize="32" fontStyle="italic" fontFamily={SERIF} fill="#333">s</text>
      <text x={982} y={196} fontSize="32" fontStyle="italic" fontFamily={SERIF} fill="#333">F</text>
      <polygon points={areaPts.join(' ')} fill="#DDEBDD" />
      <text x={1155} y={534} textAnchor="middle" fontSize="30" fontFamily={HEI} fill="#0A8A0A">
        W 等于曲线下的面积
      </text>
      {/* 公式 */}
      <text x={150} y={112} fontSize="40" fontFamily={SERIF} fill="#111">dW = F·dr = F cosθ ds</text>
      <text x={780} y={112} fontSize="40" fontFamily={SERIF} fill="#111">W = ∫ F·dr　（沿 a → b）</text>
      <text x={150} y={586} fontSize="30" fontFamily={HEI} fill="#666">
        把路径切成无数小段，逐段求功再相加
      </text>
    </svg>
  )
}

/** 3-4 第 9 页：质点动能定理的推导 —— 法向不做功，a_t ds = v dv */
export function KeTheorem() {
  const BEZ: BezSeg = [[150, 500], [340, 410], [430, 200], [790, 150]]
  const pts: string[] = []
  for (let i = 0; i <= 60; i++) pts.push(bezPt(BEZ, i / 60).join(','))
  const sp = 0.46
  const P = bezPt(BEZ, sp)
  const tan = unitP(bezD1(BEZ, sp))
  const nrm: [number, number] = [-tan[1], tan[0]]
  const phi = -45 * D2R
  const Fd: [number, number] = [
    tan[0] * Math.cos(phi) - tan[1] * Math.sin(phi),
    tan[0] * Math.sin(phi) + tan[1] * Math.cos(phi),
  ]
  const ct = Fd[0] * tan[0] + Fd[1] * tan[1]   // cosθ
  const sn = Fd[0] * nrm[0] + Fd[1] * nrm[1]   // sinθ（|ct|²+|sn|² = 1）
  const LF = 215, LV = 180
  const FE: [number, number] = [P[0] + LF * Fd[0], P[1] + LF * Fd[1]]
  const Ft: [number, number] = [P[0] + LF * ct * tan[0], P[1] + LF * ct * tan[1]]
  const Fn: [number, number] = [P[0] + LF * sn * nrm[0], P[1] + LF * sn * nrm[1]]
  const VE: [number, number] = [P[0] + LV * tan[0], P[1] + LV * tan[1]]
  return (
    <svg viewBox="0 0 1400 620" width="100%" height="100%">
      <polyline points={pts.join(' ')} fill="none" stroke="#7A9FD8" strokeWidth="4.5" />
      <text x={110} y={534} fontSize="36" fontStyle="italic" fontFamily={SERIF} fill="#333">A</text>
      <text x={806} y={142} fontSize="36" fontStyle="italic" fontFamily={SERIF} fill="#333">B</text>
      {/* 速度（严格沿轨迹切向） */}
      <Arrow x1={P[0]} y1={P[1]} x2={VE[0]} y2={VE[1]} color="#0000CD" w={7} />
      <Vec ch="v" x={VE[0] + 14 * tan[0] + 30 * nrm[0]} y={VE[1] + 14 * tan[1] + 30 * nrm[1] + 12}
        size={36} fill="#0000CD" />
      {/* 力与它的两个分量（垫在下面，虚线） */}
      <line x1={Ft[0]} y1={Ft[1]} x2={FE[0]} y2={FE[1]} stroke="#E9A0A0" strokeWidth="2"
        strokeDasharray="8 6" />
      <line x1={Fn[0]} y1={Fn[1]} x2={FE[0]} y2={FE[1]} stroke="#E9A0A0" strokeWidth="2"
        strokeDasharray="8 6" />
      <Arrow x1={P[0]} y1={P[1]} x2={Ft[0]} y2={Ft[1]} color="#E00" w={5} dashed />
      <Arrow x1={P[0]} y1={P[1]} x2={Fn[0]} y2={Fn[1]} color="#E00" w={5} dashed />
      <Arrow x1={P[0]} y1={P[1]} x2={FE[0]} y2={FE[1]} color="#E00" w={8} />
      <Vec ch="F" x={FE[0] + 12} y={FE[1] + 6} size={38} fill="#E00" />
      <VecN ch="F" sub="t" x={Ft[0] - 34 * nrm[0]} y={Ft[1] - 34 * nrm[1] + 10}
        size={34} fill="#E00" />
      <VecN ch="F" sub="n" x={Fn[0] - 46} y={Fn[1] + 16} size={34} fill="#E00" />
      <circle cx={P[0]} cy={P[1]} r={7} fill="#333" />
      {/* 推导链（纯文字，无卡片） */}
      <line x1={880} y1={150} x2={880} y2={520} stroke="#DDE3EA" strokeWidth="2" />
      <text x={920} y={200} fontSize="38" fontFamily={SERIF} fill="#111">
        dW = Fₜ ds = m aₜ ds
      </text>
      <text x={920} y={272} fontSize="38" fontFamily={SERIF} fill="#111">aₜ ds = v dv</text>
      <text x={920} y={344} fontSize="32" fontFamily="SimSun, serif" fill="#666">
        （aₜ = dv/dt，ds = v dt）
      </text>
      <text x={920} y={430} fontSize="38" fontFamily={SERIF} fill="#111">W = ∫ m v dv</text>
      <text x={150} y={586} fontSize="30" fontFamily={HEI} fill="#666">
        法向分量只改变速度方向、不做功；只有切向分量做功
      </text>
    </svg>
  )
}

/** 3-4 第 7 页：例1 小球落水 —— 三个力都从球心出发，浮力与重力等长反向 */
export function BallWater() {
  const c: [number, number] = [300, 430]   // 水中球心
  const Lg = 74
  return (
    <svg viewBox="0 0 1250 620" width="100%" height="100%">
      {/* 水面与坐标 */}
      <line x1={60} y1={150} x2={1190} y2={150} stroke="#4A9EB8" strokeWidth="5" />
      <text x={1180} y={132} textAnchor="end" fontSize="30" fontFamily={HEI} fill="#2E7C94">水面</text>
      <line x1={140} y1={150} x2={140} y2={540} stroke="#333" strokeWidth="3.5" />
      <polygon points="140,552 131,526 149,526" fill="#333" />
      <text x={160} y={534} fontSize="34" fontStyle="italic" fontFamily={SERIF} fill="#333">y</text>
      {/* 刚入水 */}
      <line x1={c[0]} y1={150} x2={c[0]} y2={396} stroke="#C8D3DE" strokeWidth="2"
        strokeDasharray="9 7" />
      <circle cx={300} cy={180} r={26} fill="#F2F5F8" stroke="#333" strokeWidth="2.5" />
      <Arrow x1={300} y1={208} x2={300} y2={280} color="#0000CD" w={7} />
      <VecN ch="v" sub="0" x={318} y={272} size={36} fill="#0000CD" />
      <text x={336} y={196} fontSize="28" fontFamily={HEI} fill="#666">刚接触水面</text>
      {/* 水中球：三个力都从球心出发 */}
      <circle cx={c[0]} cy={c[1]} r={26} fill="#F2F5F8" stroke="#333" strokeWidth="2.5" />
      <Arrow x1={c[0]} y1={c[1]} x2={c[0]} y2={c[1] + Lg} color="#E00" w={7} />
      <Vec ch="P" x={c[0] + 12} y={c[1] + Lg + 8} size={36} fill="#E00" />
      <Arrow x1={c[0]} y1={c[1]} x2={c[0]} y2={c[1] - Lg} color="#E00" w={7} />
      <VecN ch="F" sub="浮" x={c[0] - 12} y={c[1] - Lg + 16} size={34} fill="#E00" anchor="end" />
      <Arrow x1={c[0] + 20} y1={c[1]} x2={c[0] + 20} y2={c[1] - 118} color="#E07000" w={6} />
      <VecN ch="F" sub="阻" x={c[0] + 36} y={c[1] - 110} size={34} fill="#E07000" />
      <text x={c[0] - 36} y={c[1] + 60} textAnchor="end" fontSize="26" fontFamily={HEI}
        fill="#666">浮力 = 重力</text>
      {/* 结论（纯文字） */}
      <line x1={620} y1={180} x2={1190} y2={180} stroke="#DDE3EA" strokeWidth="2" />
      <text x={620} y={232} fontSize="30" fontFamily={HEI} fill="#111">
        浮力与重力等大反向 ⇒ 只有阻力做功
      </text>
      <text x={620} y={316} fontSize="34" fontFamily={SERIF} fill="#111">v = v₀ e^(−bt/m)</text>
      <text x={620} y={390} fontSize="34" fontFamily={SERIF} fill="#111">A = ∫₀ʸ(−b v) dy</text>
      <text x={620} y={446} fontSize="34" fontFamily={SERIF} fill="#111">
        = −½mv₀²(1 − e^(−2bt/m))
      </text>
      <text x={620} y={526} fontSize="32" fontFamily={SERIF} fill="#E00">½mv² − ½mv₀² = A</text>
      <text x={150} y={598} fontSize="30" fontFamily={HEI} fill="#666">
        取水面为原点、y 轴向下：功是过程量，须沿实际路径积分
      </text>
    </svg>
  )
}

/** 3-4 第 11 页：例2 单摆 —— 绳张力不做功，只有重力做功 */
export function PendulumArc() {
  const Pv: [number, number] = [600, 90]
  const L = 400
  const th1 = 60 * D2R
  const th2 = 30 * D2R
  const A: [number, number] = [Pv[0] - L * Math.sin(th1), Pv[1] + L * Math.cos(th1)]
  const B: [number, number] = [Pv[0] - L * Math.sin(th2), Pv[1] + L * Math.cos(th2)]
  // 速度严格垂直于半径：从轴心指向球的方向为径向，转动方向取右手侧的切向
  const rad = unitP([B[0] - Pv[0], B[1] - Pv[1]])
  const vdir: [number, number] = [rad[1], -rad[0]]
  return (
    <svg viewBox="0 0 1250 700" width="100%" height="100%">
      <line x1={420} y1={70} x2={790} y2={70} stroke="#333" strokeWidth="5" />
      <line x1={Pv[0]} y1={70} x2={Pv[0]} y2={Pv[1]} stroke="#333" strokeWidth="4" />
      <circle cx={Pv[0]} cy={Pv[1]} r={7} fill="#333" />
      <line x1={Pv[0]} y1={Pv[1]} x2={Pv[0]} y2={580} stroke="#C8D3DE" strokeWidth="2"
        strokeDasharray="9 7" />
      <line x1={Pv[0]} y1={Pv[1]} x2={A[0]} y2={A[1]} stroke="#9AA7B5" strokeWidth="3.5"
        strokeDasharray="12 8" />
      <line x1={Pv[0]} y1={Pv[1]} x2={B[0]} y2={B[1]} stroke="#333" strokeWidth="4.5" />
      <ArcLine cx={Pv[0]} cy={Pv[1]} r={152} a0={Math.PI / 2} a1={Math.PI / 2 + th1}
        color="#7B4FA2" w={2.5} />
      <ArcLine cx={Pv[0]} cy={Pv[1]} r={98} a0={Math.PI / 2} a1={Math.PI / 2 + th2}
        color="#2E7C94" w={2.5} />
      <text x={Pv[0] - 138} y={Pv[1] + 176} fontSize="34" fontFamily={SERIF} fill="#7B4FA2">θ₁</text>
      <text x={Pv[0] - 106} y={Pv[1] + 126} fontSize="34" fontFamily={SERIF} fill="#2E7C94">θ₂</text>
      <circle cx={A[0]} cy={A[1]} r={26} fill="#F1F5FB" stroke="#333" strokeWidth="2.5" />
      <text x={A[0] - 36} y={A[1] + 8} textAnchor="end" fontSize="28" fontFamily={HEI} fill="#666">
        放手处 v = 0
      </text>
      <circle cx={B[0]} cy={B[1]} r={26} fill="#FAF2F2" stroke="#333" strokeWidth="2.5" />
      <Arrow x1={B[0]} y1={B[1]} x2={B[0] + vdir[0] * 200} y2={B[1] + vdir[1] * 200}
        color="#0000CD" w={7} />
      <Vec ch="v" x={B[0] + vdir[0] * 200 + 10} y={B[1] + vdir[1] * 200 - 16} size={38}
        fill="#0000CD" />
      {/* 高度差 */}
      <line x1={288} y1={A[1]} x2={A[0] - 30} y2={A[1]} stroke="#0A8A0A" strokeWidth="2"
        strokeDasharray="8 6" />
      <line x1={288} y1={B[1]} x2={B[0] - 30} y2={B[1]} stroke="#0A8A0A" strokeWidth="2"
        strokeDasharray="8 6" />
      <Line2Arrows x1={288} y1={A[1]} x2={288} y2={B[1]} color="#0A8A0A" w={5} />
      <text x={274} y={(A[1] + B[1]) / 2 + 12} textAnchor="end" fontSize="34"
        fontFamily={SERIF} fill="#0A8A0A">h</text>
      {/* 结论 */}
      <line x1={840} y1={170} x2={840} y2={470} stroke="#DDE3EA" strokeWidth="2" />
      <text x={876} y={226} fontSize="36" fontFamily={SERIF} fill="#111">h = l(cosθ₂ − cosθ₁)</text>
      <text x={876} y={300} fontSize="36" fontFamily={SERIF} fill="#111">W = mgh = ½mv²</text>
      <text x={150} y={628} fontSize="30" fontFamily="SimSun, serif" fill="#111">
        v = √(2gl(cosθ₂ − cosθ₁))
      </text>
      <text x={150} y={684} fontSize="28" fontFamily={HEI} fill="#666">
        绳的张力不做功，只有重力做功 ⇒ 代入数据得 v = 2.68 m·s⁻¹
      </text>
    </svg>
  )
}

/* ==================== 3-5 图示 ====================
配色与画法沿用本批约定：
  红＝力；蓝＝速度/位矢；绿＝位移/路径/功；灰＝几何辅助。
  矢量箭尾一律在作用点上；曲线上的点与切向由贝塞尔解析式给出；角弧用 ArcLine。
==================================================== */

/** 3-5 第 2~3 页：万有引力做功 —— ē_r·dr̄ = dr */
export function GravWork() {
  const O: [number, number] = [300, 500]          // 引力源 m′
  const BEZ: BezSeg = [[150, 140], [520, 60], [880, 260], [740, 610]]
  const pts: string[] = []
  for (let i = 0; i <= 70; i++) pts.push(bezPt(BEZ, i / 70).join(','))
  const sp = 0.40
  const P = bezPt(BEZ, sp)
  const tan = unitP(bezD1(BEZ, sp))
  const er = unitP([P[0] - O[0], P[1] - O[1]])    // ē_r：由 m′ 指向 m
  const A = bezPt(BEZ, 0)
  const B = bezPt(BEZ, 1)
  const LF = 170, LR = 120
  const tipF: [number, number] = [P[0] - er[0] * LF, P[1] - er[1] * LF]   // F 指向 m′
  const tipE: [number, number] = [P[0] + er[0] * LR, P[1] + er[1] * LR]
  const tipD: [number, number] = [P[0] + tan[0] * LR, P[1] + tan[1] * LR]
  const rA = bezPt(BEZ, 0.30)
  const rB = bezPt(BEZ, 0.80)
  return (
    <svg viewBox="0 0 1000 700" width="100%" height="100%">
      {/* 路径（虚线）与两端 */}
      <polyline points={pts.join(' ')} fill="none" stroke="#C8D3DE" strokeWidth="3"
        strokeDasharray="12 9" />
      <circle cx={A[0]} cy={A[1]} r={7} fill="#333" />
      <circle cx={B[0]} cy={B[1]} r={7} fill="#333" />
      <text x={A[0] - 30} y={A[1] - 8} fontSize="34" fontStyle="italic" fontFamily={SERIF}
        fill="#333">A</text>
      <text x={B[0] + 16} y={B[1] + 20} fontSize="34" fontStyle="italic" fontFamily={SERIF}
        fill="#333">B</text>
      {/* 位矢 r_A、r_B */}
      <line x1={O[0]} y1={O[1]} x2={A[0]} y2={A[1]} stroke="#9AA7B5" strokeWidth="3"
        strokeDasharray="10 8" />
      <line x1={O[0]} y1={O[1]} x2={B[0]} y2={B[1]} stroke="#9AA7B5" strokeWidth="3"
        strokeDasharray="10 8" />
      <VecN ch="r" sub="A" x={rA[0] - 44} y={rA[1] + 6} size={34} fill="#7A8794" anchor="end" />
      <VecN ch="r" sub="B" x={rB[0] - 30} y={rB[1] + 24} size={34} fill="#7A8794" anchor="end" />
      {/* 引力源 */}
      <circle cx={O[0]} cy={O[1]} r={16} fill="#E00" />
      <text x={O[0] - 14} y={O[1] + 46} fontSize="32" fontStyle="italic" fontFamily={SERIF}
        fill="#E00">m′</text>
      {/* 位矢 r（实线） */}
      <Arrow x1={O[0]} y1={O[1]} x2={P[0]} y2={P[1]} color="#0000CD" w={6} />
      <Vec ch="r" x={(O[0] + P[0]) / 2 + 16} y={(O[1] + P[1]) / 2 - 10} size={36}
        fill="#0000CD" />
      {/* 质点 m 与三个矢量 */}
      <circle cx={P[0]} cy={P[1]} r={13} fill="#333" />
      <text x={P[0] + 20} y={P[1] - 16} fontSize="34" fontStyle="italic" fontFamily={SERIF}
        fill="#333">m</text>
      <Arrow x1={P[0]} y1={P[1]} x2={tipF[0]} y2={tipF[1]} color="#E00" w={8} />
      <Vec ch="F" x={tipF[0] - 6} y={tipF[1] + 34} size={40} fill="#E00" anchor="middle" />
      <Arrow x1={P[0]} y1={P[1]} x2={tipE[0]} y2={tipE[1]} color="#7A8794" w={5} dashed />
      <text x={tipE[0] + 10} y={tipE[1] - 8} fontSize="32" fontFamily={SERIF} fill="#7A8794">
        ē_r
      </text>
      <Arrow x1={P[0]} y1={P[1]} x2={tipD[0]} y2={tipD[1]} color="#0A8A0A" w={6} />
      <text x={tipD[0] + 12} y={tipD[1] + 14} fontSize="32" fontFamily={SERIF}
        fill="#0A8A0A">dr̄</text>
      {/* θ：ē_r 与 dr̄ 的夹角 */}
      <ArcLine cx={P[0]} cy={P[1]} r={62} a0={Math.atan2(er[1], er[0])}
        a1={Math.atan2(tan[1], tan[0])} color="#333" w={2.5} />
      <text x={P[0] + 74 * er[0] + 22 * tan[0]} y={P[1] + 74 * er[1] + 22 * tan[1] + 10}
        fontSize="32" fontFamily={SERIF} fill="#333">θ</text>
      {/* 结论 */}
      <text x={60} y={666} fontSize="30" fontFamily={HEI} fill="#666">
        F̄ 沿 r̄ 的反方向（引力），ē_r·dr̄ = |ē_r||dr̄|cosθ = dr
      </text>
    </svg>
  )
}

