/** 3-5 第 5 页：F–x 图上的功 —— F 为负，面积（含号）就是功 */
export function FxArea() {
  const Ox = 220, Oy = 170        // 坐标原点
  const SL = 0.60                 // 斜率（像素）：F = −(k) · x
  const x1 = 380, x2 = 720
  const fy = (x: number) => Oy + SL * (x - Ox)
  const stripA = 528, stripB = 556
  return (
    <svg viewBox="0 0 1040 620" width="100%" height="100%">
      {/* 坐标轴 */}
      <line x1={Ox} y1={520} x2={Ox} y2={70} stroke="#333" strokeWidth="3.5" />
      <polygon points={`${Ox},60 ${Ox - 9},86 ${Ox + 9},86`} fill="#333" />
      <line x1={80} y1={Oy} x2={960} y2={Oy} stroke="#333" strokeWidth="3.5" />
      <polygon points="970,170 944,161 944,179" fill="#333" />
      <text x={Ox - 16} y={96} fontSize="32" fontStyle="italic" fontFamily={SERIF}
        fill="#333" textAnchor="end">F</text>
      <text x={984} y={182} fontSize="32" fontStyle="italic" fontFamily={SERIF} fill="#333">x</text>
      <text x={Ox - 14} y={Oy + 40} fontSize="34" fontStyle="italic" fontFamily={SERIF}
        fill="#333" textAnchor="end">O</text>
      {/* 直线 F = −kx（含延长虚线） */}
      <line x1={90} y1={fy(90)} x2={Ox} y2={Oy} stroke="#9AA7B5" strokeWidth="2.5"
        strokeDasharray="10 8" />
      <line x1={Ox} y1={Oy} x2={800} y2={fy(800)} stroke="#0000CD" strokeWidth="4.5" />
      <line x1={800} y1={fy(800)} x2={930} y2={fy(930)} stroke="#9AA7B5" strokeWidth="2.5"
        strokeDasharray="10 8" />
      {/* 面积（F<0，带负号） */}
      <polygon points={`${x1},${Oy} ${x2},${Oy} ${x2},${fy(x2)} ${x1},${fy(x1)}`}
        fill="#DCE6F5" />
      {/* dx 窄条 */}
      <polygon points={`${stripA},${Oy} ${stripB},${Oy} ${stripB},${fy(stripB)} ${stripA},${fy(stripA)}`}
        fill="#0A8A0A" opacity="0.55" />
      <line x1={x1} y1={Oy} x2={x1} y2={fy(x1)} stroke="#7A9FD8" strokeWidth="2.5" />
      <line x1={x2} y1={Oy} x2={x2} y2={fy(x2)} stroke="#7A9FD8" strokeWidth="2.5" />
      <text x={x1} y={Oy - 18} textAnchor="middle" fontSize="32" fontStyle="italic"
        fontFamily={SERIF} fill="#333">x₁</text>
      <text x={x2} y={Oy - 18} textAnchor="middle" fontSize="32" fontStyle="italic"
        fontFamily={SERIF} fill="#333">x₂</text>
      <line x1={(stripA + stripB) / 2} y1={fy(stripB)} x2={(stripA + stripB) / 2} y2={Oy + 96}
        stroke="#0A8A0A" strokeWidth="2" />
      <text x={(stripA + stripB) / 2} y={Oy + 130} textAnchor="middle" fontSize="32"
        fontFamily={SERIF} fill="#0A8A0A">dx</text>
      <text x={(stripA + stripB) / 2} y={fy(stripB) - 14} textAnchor="middle" fontSize="30"
        fontFamily={SERIF} fill="#0A8A0A">dW</text>
      {/* 说明 */}
      <text x={280} y={fy(x2) + 60} fontSize="30" fontFamily={HEI} fill="#0000CD">
        F = −kx（x &gt; 0 时力为负，曲线在轴下方）
      </text>
      <text x={80} y={582} fontSize="30" fontFamily={HEI} fill="#666">
        W = ∫F dx = 曲线下的面积（带符号）；x₂ &gt; x₁ &gt; 0 时面积为负
      </text>
    </svg>
  )
}

/** 3-5 第 6~7 页：保守力做功与路径无关，沿闭合路径做功为零 */
export function ConsPath() {
  const A: [number, number] = [150, 150]
  const B: [number, number] = [770, 470]
  const up: BezSeg = [A, [520, 60], [880, 250], B]
  const dn: BezSeg = [A, [180, 430], [430, 560], B]
  const mk = (bez: BezSeg) => {
    const a: string[] = []
    for (let i = 0; i <= 50; i++) a.push(bezPt(bez, i / 50).join(','))
    return a.join(' ')
  }
  const arrowOn = (bez: BezSeg, s: number, color: string) => {
    const p0 = bezPt(bez, s)
    const t = unitP(bezD1(bez, s))
    return <Arrow x1={p0[0]} y1={p0[1]} x2={p0[0] + t[0] * 56} y2={p0[1] + t[1] * 56}
      color={color} w={6} />
  }
  return (
    <svg viewBox="0 0 1000 600" width="100%" height="100%">
      <polyline points={mk(up)} fill="none" stroke="#0A8A0A" strokeWidth="5" />
      <polyline points={mk(dn)} fill="none" stroke="#2E7C94" strokeWidth="5"
        strokeDasharray="14 10" />
      {arrowOn(up, 0.30, '#0A8A0A')}
      {arrowOn(up, 0.70, '#0A8A0A')}
      {arrowOn(dn, 0.35, '#2E7C94')}
      {arrowOn(dn, 0.75, '#2E7C94')}
      <circle cx={A[0]} cy={A[1]} r={8} fill="#333" />
      <circle cx={B[0]} cy={B[1]} r={8} fill="#333" />
      <text x={A[0] - 34} y={A[1] - 10} fontSize="36" fontStyle="italic" fontFamily={SERIF}
        fill="#333">A</text>
      <text x={B[0] + 18} y={B[1] + 16} fontSize="36" fontStyle="italic" fontFamily={SERIF}
        fill="#333">B</text>
      <text x={762} y={196} fontSize="36" fontStyle="italic" fontFamily={SERIF}
        fill="#0A8A0A">C</text>
      <text x={318} y={496} fontSize="36" fontStyle="italic" fontFamily={SERIF}
        fill="#2E7C94">D</text>
      <text x={560} y={110} fontSize="30" fontFamily={HEI} fill="#0A8A0A">路径 A→C→B</text>
      <text x={200} y={556} fontSize="30" fontFamily={HEI} fill="#2E7C94">路径 A→D→B</text>
      <text x={60} y={62} fontSize="30" fontFamily={HEI} fill="#666">
        同一对起点与终点，两条完全不同的路径
      </text>
    </svg>
  )
}

