/** 3-7 P10：二维完全弹性碰撞（等质量）—— 碰后两速度互相垂直
 *  直接用 v̄₀ = v̄₁ + v̄₂ 与 v₀² = v₁² + v₂² 的几何：三者构成直角三角形。
 *  取 v₁ 与 v₀ 成 35°、v₂ 与 v₀ 成 55°（35° + 55° = 90° ⇒ v₁ ⊥ v₂），
 *  比例按 1.428 : 1 取，保证 v₁ + v₂ 严格沿 v₀ 方向。 */
/** 3-7 P10：二维完全弹性碰撞（等质量）—— 碰后两速度互相垂直
 *  由 v̄₀ = v̄₁ + v̄₂ 与 v₀² = v₁² + v₂² 的几何：三者构成直角三角形。
 *  取 v₁ 与 v₀ 成 35°、v₂ 与 v₀ 成 55°（35° + 55° = 90° ⇒ v₁ ⊥ v₂），
 *  比例按 1.428 : 1 取，保证 v₁ + v₂ 严格沿 v₀ 方向（自检：合成后 y 分量 ≈ 0）。 */
export function Coll2d() {
  const S = 145                        // 145 px ↔ 1 速度单位
  const v1 = 1.428, v2 = 1
  const O: [number, number] = [210, 392]
  const d1 = -35 * D2R, d2 = 55 * D2R
  const E1: [number, number] = [O[0] + v1 * S * Math.cos(d1), O[1] + v1 * S * Math.sin(d1)]
  const E2: [number, number] = [O[0] + v2 * S * Math.cos(d2), O[1] + v2 * S * Math.sin(d2)]
  const E0: [number, number] = [E1[0] + E2[0] - O[0], E1[1] + E2[1] - O[1]]
  return (
    <svg viewBox="0 0 800 640" width="100%" height="100%">
      {/* 水平参考线 */}
      <line x1={O[0]} y1={O[1]} x2={E0[0] + 46} y2={O[1]} stroke="#B9C2CE" strokeWidth="2.4"
        strokeDasharray="11 8" />
      {/* 补齐平行四边形的两条虚线 */}
      <line x1={E1[0]} y1={E1[1]} x2={E0[0]} y2={E0[1]} stroke="#B9C2CE" strokeWidth="2.4"
        strokeDasharray="10 8" />
      <line x1={E2[0]} y1={E2[1]} x2={E0[0]} y2={E0[1]} stroke="#B9C2CE" strokeWidth="2.4"
        strokeDasharray="10 8" />
      {/* 三个速度：箭尾都在 O（碰撞发生点） */}
      <Arrow x1={O[0]} y1={O[1]} x2={E0[0]} y2={E0[1]} color="#E00" w={8} />
      <Arrow x1={O[0]} y1={O[1]} x2={E1[0]} y2={E1[1]} color="#0000CD" w={8} />
      <Arrow x1={O[0]} y1={O[1]} x2={E2[0]} y2={E2[1]} color="#0A8A0A" w={8} />
      <VecN ch="v" sub="0" x={E0[0] + 16} y={E0[1] + 14} size={40} fill="#E00" />
      <VecN ch="v" sub="1" x={E1[0] + 10} y={E1[1] - 10} size={40} fill="#0000CD" />
      <VecN ch="v" sub="2" x={E2[0] + 14} y={E2[1] + 10} size={40} fill="#0A8A0A" />
      {/* O 处的直角标记：v₁ ⊥ v₂ */}
      <RightAngle v={O} d1={[Math.cos(d1), Math.sin(d1)]} d2={[Math.cos(d2), Math.sin(d2)]}
        L={42} color="#333" />
      {/* θ₁：v₁ 与 v₀ 的夹角 */}
      <ArcLine cx={O[0]} cy={O[1]} r={136} a0={d1} a1={0} color="#555" w={2.2} />
      <text x={O[0] + 140} y={O[1] - 36} fontSize="32" fontStyle="italic"
        fontFamily={SERIF} fill="#555">θ₁</text>
      <circle cx={O[0]} cy={O[1]} r="7" fill="#333" />
      <text x={O[0] - 46} y={O[1] + 14} fontSize="34" fontStyle="italic" fontFamily={SERIF}
        fill="#333">O</text>
    </svg>
  )
}

/** ===== 3-9 质心 质心运动定理 ===== */

/** 3-9 P2：运动分解 —— 刚体在空中飞行时，质心走抛物线，物体本身绕质心匀速转动
 *  做法：先取抛物线上的点作质心，再让物体绕该点按匀角速度旋转 ——
 *  这样「质心在抛物线上」是构造出来的、不是估出来的。 */
export function CmBoardFlight() {
  const x0 = 160, x1 = 1240, yG = 470, H = 370
  const px = (t: number) => x0 + (x1 - x0) * t
  const py = (t: number) => yG - 4 * H * t * (1 - t)
  const board: [number, number][] = [[-80, -22], [58, -42], [82, 26], [-54, 38]]
  const ts = [0.06, 0.22, 0.38, 0.54, 0.70, 0.86]
  const rot = (p: [number, number], a: number): [number, number] => [
    p[0] * Math.cos(a) - p[1] * Math.sin(a),
    p[0] * Math.sin(a) + p[1] * Math.cos(a),
  ]
  const curve: string[] = []
  for (let i = 0; i <= 60; i++) {
    const t = i / 60
    curve.push(`${px(t)},${py(t)}`)
  }
  return (
    <svg viewBox="0 0 1400 600" width="100%" height="100%">
      <polyline points={curve.join(' ')} fill="none" stroke="#9AA7B5" strokeWidth="3"
        strokeDasharray="12 9" />
      {ts.map((t, i) => {
        const a = (-26 + 132 * t) * D2R
        const cx = px(t), cy = py(t)
        const pts = board.map(q => rot(q, a)).map(q => `${cx + q[0]},${cy + q[1]}`)
        return (
          <g key={i}>
            <polygon points={pts.join(' ')} fill="#F2F5F9" stroke="#333" strokeWidth="2.8" />
            <circle cx={cx} cy={cy} r="7.5" fill="#E00" />
          </g>
        )
      })}
      {/* 起抛点与落点 */}
      <circle cx={px(0)} cy={yG} r="6" fill="#333" />
      <circle cx={px(1)} cy={yG} r="6" fill="#333" />
      <text x={px(0) - 6} y={yG + 44} textAnchor="middle" fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#333">O</text>
      <text x={px(0.06) - 96} y={py(0.06) - 4} fontSize="34" fontStyle="italic"
        fontFamily={SERIF} fill="#E00">C</text>
    </svg>
  )
}

/** 3-9 P3：其余点的运动 = 随 C 的平动 + 绕 C 的转动
 *  同一块板：位置 1 → 平移副本（虚线）→ 绕 C₂ 转过 46° 到位置 2。
 *  板上一点 P 的轨迹正好是「平移一段 + 绕质心转一段」。 */
/** 3-9 P3：其余点的运动 = 随 C 的平动 + 绕 C 的转动
 *  同一块板：位置 1 → 平移副本（虚线）→ 绕 C₂ 转过 46° 到位置 2。
 *  板上一点 P 的轨迹正好是「平移一段 + 绕质心转一段」。 */
export function CmDecomp() {
  const board: [number, number][] = [[-80, -22], [58, -42], [82, 26], [-54, 38]]
  const P: [number, number] = [58, -42]
  const C1: [number, number] = [200, 362]
  const C2: [number, number] = [612, 262]
  const A = 46 * D2R
  const rot = (p: [number, number], a: number): [number, number] => [
    p[0] * Math.cos(a) - p[1] * Math.sin(a),
    p[0] * Math.sin(a) + p[1] * Math.cos(a),
  ]
  const poly = (c: [number, number], a: number) =>
    board.map(q => rot(q, a)).map(q => `${c[0] + q[0]},${c[1] + q[1]}`).join(' ')
  const P1: [number, number] = [C1[0] + P[0], C1[1] + P[1]]
  const Pp: [number, number] = [C2[0] + P[0], C2[1] + P[1]]
  const r2 = rot(P, A)
  const P2: [number, number] = [C2[0] + r2[0], C2[1] + r2[1]]
  return (
    <svg viewBox="0 0 900 620" width="100%" height="100%">
      {/* 位置 1 */}
      <polygon points={poly(C1, 0)} fill="#F2F5F9" stroke="#333" strokeWidth="3" />
      <circle cx={C1[0]} cy={C1[1]} r="7" fill="#E00" />
      <text x={C1[0] - 6} y={C1[1] + 96} textAnchor="end" fontSize="32" fontStyle="italic"
        fontFamily={SERIF} fill="#E00">C</text>
      <text x={C1[0] - 54} y={C1[1] + 158} fontSize="30" fontFamily={HEI} fill="#555">位置 1</text>
      {/* 平移副本（虚线） */}
      <polygon points={poly(C2, 0)} fill="none" stroke="#7A8794" strokeWidth="2.6"
        strokeDasharray="10 8" />
      {/* 位置 2 */}
      <polygon points={poly(C2, A)} fill="#F2F5F9" stroke="#333" strokeWidth="3" />
      <circle cx={C2[0]} cy={C2[1]} r="7" fill="#E00" />
      <text x={C2[0] - 8} y={C2[1] + 90} textAnchor="end" fontSize="32" fontStyle="italic"
        fontFamily={SERIF} fill="#E00">C</text>
      <text x={C2[0] + 24} y={C2[1] + 158} fontSize="30" fontFamily={HEI} fill="#555">位置 2</text>
      {/* 平动矢量 */}
      <Arrow x1={C1[0] + 16} y1={C1[1] + 118} x2={C2[0] - 4} y2={C2[1] + 118} color="#0000CD"
        w={6} />
      <text x={(C1[0] + C2[0]) / 2 + 26} y={C1[1] + 176} textAnchor="middle" fontSize="32"
        fontFamily={HEI} fill="#0000CD">随 C 的平动</text>
      {/* 绕 C₂ 的转角 */}
      <ArcLine cx={C2[0]} cy={C2[1]} r={158} a0={Math.atan2(P[1], P[0])}
        a1={Math.atan2(r2[1], r2[0])} color="#E00" w={4} />
      <text x={C2[0] + 34} y={C2[1] - 152} fontSize="28" fontFamily={HEI} fill="#E00">
        绕 C 的转动
      </text>
      {/* P 的轨迹：平移段 + 转动弧 */}
      <circle cx={P1[0]} cy={P1[1]} r="7" fill="#0A8A0A" />
      <circle cx={Pp[0]} cy={Pp[1]} r="7" fill="#0A8A0A" />
      <circle cx={P2[0]} cy={P2[1]} r="7" fill="#0A8A0A" />
      <line x1={P1[0]} y1={P1[1]} x2={Pp[0]} y2={Pp[1]} stroke="#0A8A0A" strokeWidth="2.6"
        strokeDasharray="10 8" />
      <ArcLine cx={C2[0]} cy={C2[1]} r={Math.hypot(P[0], P[1])}
        a0={Math.atan2(P[1], P[0])} a1={Math.atan2(r2[1], r2[0])} color="#0A8A0A" w={2.6}
        dash="10 8" />
      <text x={P1[0] - 8} y={P1[1] - 24} textAnchor="end" fontSize="34" fontStyle="italic"
        fontFamily={SERIF} fill="#0A8A0A">P</text>
      <text x={P2[0] + 14} y={P2[1] - 16} fontSize="34" fontStyle="italic" fontFamily={SERIF}
        fill="#0A8A0A">P</text>
      <text x={Pp[0] + 14} y={Pp[1] - 12} fontSize="28" fontStyle="italic" fontFamily={SERIF}
        fill="#7A8794">P′</text>
    </svg>
  )
}

export function CmDef() {
  const O: [number, number] = [330, 476]
  const S = 108
  const ex: [number, number] = [1, 0]
  const ey: [number, number] = [0, -1]
  const ez: [number, number] = [-0.62, 0.58]
  const P = (p: [number, number, number]): [number, number] => [
    O[0] + S * (p[0] * ex[0] + p[1] * ey[0] + p[2] * ez[0]),
    O[1] + S * (p[0] * ex[1] + p[1] * ey[1] + p[2] * ez[1]),
  ]
  const pts: { m: number; p: [number, number, number]; sub: string }[] = [
    { m: 3.0, p: [2.4, 0.6, 0.4], sub: '1' },
    { m: 1.5, p: [0.5, 2.2, -0.3], sub: '2' },
    { m: 2.0, p: [1.2, 1.4, 1.0], sub: 'i' },
    { m: 1.8, p: [2.8, 1.9, -0.5], sub: 'n' },
  ]
  const M = pts.reduce((s, q) => s + q.m, 0)
  const cen: [number, number, number] = [
    pts.reduce((s, q) => s + q.m * q.p[0], 0) / M,
    pts.reduce((s, q) => s + q.m * q.p[1], 0) / M,
    pts.reduce((s, q) => s + q.m * q.p[2], 0) / M,
  ]
  const C = P(cen)
  return (
    <svg viewBox="0 0 1100 660" width="100%" height="100%">
      {/* 坐标轴 */}
      <line x1={O[0]} y1={O[1]} x2="900" y2={O[1]} stroke="#111" strokeWidth="3.4" />
      <polygon points={`908,${O[1]} 882,${O[1] - 9} 882,${O[1] + 9}`} fill="#111" />
      <text x="918" y={O[1] + 14} fontSize="40" fontStyle="italic" fontFamily={SERIF}>x</text>
      <line x1={O[0]} y1={O[1]} x2={O[0]} y2="96" stroke="#111" strokeWidth="3.4" />
      <polygon points={`${O[0]},88 ${O[0] - 9},114 ${O[0] + 9},114`} fill="#111" />
      <text x={O[0] + 16} y="118" fontSize="40" fontStyle="italic" fontFamily={SERIF}>y</text>
      <line x1={O[0]} y1={O[1]} x2="180" y2="620" stroke="#111" strokeWidth="3.4" />
      <polygon points={`174,628 174,600 196,616`} fill="#111" />
      <text x="158" y="646" fontSize="40" fontStyle="italic" fontFamily={SERIF}>z</text>
      <text x={O[0] - 34} y={O[1] + 40} fontSize="40" fontFamily={SERIF}>O</text>
      {/* 位矢 */}
      {pts.map((q, i) => {
        const Q = P(q.p)
        return (
          <g key={i}>
            <line x1={O[0]} y1={O[1]} x2={Q[0]} y2={Q[1]} stroke="#0A8A0A" strokeWidth="2.6" />
            <circle cx={Q[0]} cy={Q[1]} r="16" fill="#EAF2FA" stroke="#1F4E9C" strokeWidth="2.8" />
            <Sca ch="m" sub={q.sub} x={Q[0] + 24} y={Q[1] - 16} size={32} fill="#1F4E9C" />
          </g>
        )
      })}
      {/* 质心位矢（加粗红） */}
      <line x1={O[0]} y1={O[1]} x2={C[0]} y2={C[1]} stroke="#E00" strokeWidth="6" />
      <circle cx={C[0]} cy={C[1]} r="9" fill="#E00" />
      <text x={C[0] - 40} y={C[1] - 14} textAnchor="end" fontSize="34" fontStyle="italic"
        fontFamily={SERIF} fill="#111">C</text>
      <VecN ch="r" sub="C" x={470} y={420} size={38} fill="#E00" />
    </svg>
  )
}

/** 3-9 P6：密度均匀、形状对称的物体，质心在几何中心（L 形按面积加权） */
export function CmSymmetric() {
  // L 形：上竖条 A + 下横条 B，质心按面积加权（真算，不是目测）
  const A = { x0: 20, x1: 220, y0: 20, y1: 140 }
  const B = { x0: 20, x1: 470, y0: 140, y1: 270 }
  const aA = (A.x1 - A.x0) * (A.y1 - A.y0)
  const aB = (B.x1 - B.x0) * (B.y1 - B.y0)
  const cA: [number, number] = [(A.x0 + A.x1) / 2, (A.y0 + A.y1) / 2]
  const cB: [number, number] = [(B.x0 + B.x1) / 2, (B.y0 + B.y1) / 2]
  const cL: [number, number] = [
    (aA * cA[0] + aB * cB[0]) / (aA + aB),
    (aA * cA[1] + aB * cB[1]) / (aA + aB),
  ]
  return (
    <svg viewBox="0 0 1400 420" width="100%" height="100%">
      {/* ① 椭圆板 */}
      <ellipse cx="140" cy="150" rx="112" ry="52" fill="#F2F5F9" stroke="#333" strokeWidth="2.8" />
      <line x1="28" y1="150" x2="252" y2="150" stroke="#C9D3DE" strokeWidth="2" strokeDasharray="9 7" />
      <line x1="140" y1="98" x2="140" y2="202" stroke="#C9D3DE" strokeWidth="2" strokeDasharray="9 7" />
      <circle cx="140" cy="150" r="8" fill="#E00" />
      <text x="140" y="238" textAnchor="middle" fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#111">O</text>
      <text x="140" y="330" textAnchor="middle" fontSize="30" fontFamily={HEI} fill="#555">椭圆板</text>

      {/* ② 圆柱（斜二测） */}
      <g>
        <path d="M 380 132 L 380 268 A 66 24 0 0 0 512 268 L 512 132 Z" fill="#F2F5F9"
          stroke="#333" strokeWidth="2.8" />
        <ellipse cx="446" cy="132" rx="66" ry="24" fill="#E8EEF6" stroke="#333" strokeWidth="2.8" />
        <ellipse cx="446" cy="268" rx="66" ry="24" fill="none" stroke="#333" strokeWidth="2.2"
          strokeDasharray="9 7" />
        <line x1="446" y1="76" x2="446" y2="330" stroke="#C9D3DE" strokeWidth="2.4"
          strokeDasharray="12 8" />
        <circle cx="446" cy="192" r="8" fill="#E00" />
        <text x="424" y="226" textAnchor="end" fontSize="30" fontStyle="italic"
          fontFamily={SERIF} fill="#111">O</text>
        <text x="446" y="392" textAnchor="middle" fontSize="30" fontFamily={HEI} fill="#555">圆柱体</text>
      </g>

      {/* ③ 矩形板 */}
      <g>
        <rect x="640" y="106" width="240" height="140" fill="#F2F5F9" stroke="#333" strokeWidth="2.8" />
        <line x1="640" y1="106" x2="880" y2="246" stroke="#C9D3DE" strokeWidth="2" strokeDasharray="9 7" />
        <line x1="880" y1="106" x2="640" y2="246" stroke="#C9D3DE" strokeWidth="2" strokeDasharray="9 7" />
        <circle cx="760" cy="176" r="8" fill="#E00" />
        <text x="760" y="286" textAnchor="middle" fontSize="30" fontStyle="italic"
          fontFamily={SERIF} fill="#111">O</text>
        <text x="760" y="392" textAnchor="middle" fontSize="30" fontFamily={HEI} fill="#555">矩形板</text>
      </g>

      {/* ④ L 形板：分两块，按面积定质心 */}
      <g transform="translate(950,20)">
        <path d={`M ${A.x0} ${A.y0} L ${A.x1} ${A.y0} L ${A.x1} ${A.y1} L ${B.x1} ${B.y0}
          L ${B.x1} ${B.y1} L ${B.x0} ${B.y1} Z`} fill="#F2F5F9" stroke="#333"
          strokeWidth="2.8" />
        <line x1={A.x0} y1={A.y1} x2={A.x1} y2={A.y1} stroke="#C9D3DE" strokeWidth="2.2"
          strokeDasharray="9 7" />
        <line x1={A.x0} y1={A.y0} x2={A.x1} y2={A.y1} stroke="#C9D3DE" strokeWidth="2"
          strokeDasharray="9 7" />
        <line x1={A.x1} y1={A.y0} x2={A.x0} y2={A.y1} stroke="#C9D3DE" strokeWidth="2"
          strokeDasharray="9 7" />
        <line x1={B.x0} y1={B.y0} x2={B.x1} y2={B.y1} stroke="#C9D3DE" strokeWidth="2"
          strokeDasharray="9 7" />
        <line x1={B.x1} y1={B.y0} x2={B.x0} y2={B.y1} stroke="#C9D3DE" strokeWidth="2"
          strokeDasharray="9 7" />
        <circle cx={cA[0]} cy={cA[1]} r="6" fill="#7A8794" />
        <circle cx={cB[0]} cy={cB[1]} r="6" fill="#7A8794" />
        <line x1={cA[0]} y1={cA[1]} x2={cB[0]} y2={cB[1]} stroke="#1F4E9C"
          strokeWidth="2.6" strokeDasharray="10 8" />
        <circle cx={cL[0]} cy={cL[1]} r="9" fill="#E00" />
        <text x={cL[0] + 20} y={cL[1] + 10} fontSize="30" fontStyle="italic"
          fontFamily={SERIF} fill="#111">O</text>
        <text x="250" y="392" textAnchor="middle" fontSize="30" fontFamily={HEI} fill="#555">L 形板</text>
      </g>
    </svg>
  )
}

/** 3-9 P8~P11：匀质半薄球壳的质心 —— 取圆环，θ 自 y 轴量起
 *  环半径 R sinθ、环宽 R dθ、环心高度 R cosθ；y_c = R/2。 */
/** 3-9 P13：质心运动定理 —— 所有外力之和，等效为一个作用在质心上的力
 *  三个质点各受外力（红），合力等效作用于质心 C。
 *  F^ex 与 a_C 严格同向（共线），为避免遮挡而沿法向错开 28 px 并排画出。 */
export function CmTheorem() {
  const bodies: { p: [number, number]; f: [number, number]; sub: string; lx: number; ly: number }[] = [
    { p: [140, 358], f: [70, -118], sub: '1', lx: 216, ly: 232 },
    { p: [308, 148], f: [54, -86], sub: '2', lx: 366, ly: 56 },
    { p: [430, 378], f: [-78, -72], sub: '3', lx: 336, ly: 300 },
  ]
  const C: [number, number] = [790, 254]
  const d: [number, number] = [0.923, -0.385]
  const nrm: [number, number] = [-d[1], d[0]]
  const pF: [number, number] = [C[0] + d[0] * 216, C[1] + d[1] * 216]
  const a0: [number, number] = [C[0] + nrm[0] * 28, C[1] + nrm[1] * 28]
  const a1: [number, number] = [a0[0] + d[0] * 136, a0[1] + d[1] * 136]
  return (
    <svg viewBox="0 0 1150 500" width="100%" height="100%">
      {bodies.map((b, i) => (
        <g key={i}>
          <circle cx={b.p[0]} cy={b.p[1]} r="24" fill="#EAF2FA" stroke="#1F4E9C"
            strokeWidth="3" />
          <Arrow x1={b.p[0]} y1={b.p[1]} x2={b.p[0] + b.f[0]} y2={b.p[1] + b.f[1]}
            color="#E00" w={6} />
          <Sca ch="m" sub={b.sub} x={b.p[0] - 26} y={b.p[1] + 52} size={30} fill="#1F4E9C" />
        </g>
      ))}
      <Sca ch="F" sub="1" x={bodies[0].lx} y={bodies[0].ly} size={34} fill="#E00" />
      <Sca ch="F" sub="2" x={bodies[1].lx} y={bodies[1].ly} size={34} fill="#E00" />
      <Sca ch="F" sub="3" x={bodies[2].lx} y={bodies[2].ly} size={34} fill="#E00" />

      {/* 等号 */}
      <line x1="545" y1="228" x2="607" y2="228" stroke="#111" strokeWidth="7" />
      <line x1="545" y1="266" x2="607" y2="266" stroke="#111" strokeWidth="7" />

      {/* 等效：全部质量集中于质心 */}
      <circle cx={C[0]} cy={C[1]} r="38" fill="#FDECEC" stroke="#E00" strokeWidth="3.6" />
      <text x={C[0] - 46} y={C[1] - 16} textAnchor="end" fontSize="36" fontStyle="italic"
        fontFamily={SERIF} fill="#111">C</text>
      <Arrow x1={C[0]} y1={C[1]} x2={pF[0]} y2={pF[1]} color="#E00" w={8} />
      <Sca ch="F" sub="" x={pF[0] + 12} y={pF[1] + 6} size={40} fill="#E00" />
      <text x={pF[0] + 46} y={pF[1] - 22} fontSize="24" fontStyle="italic" fontFamily={SERIF}
        fill="#E00">ex</text>
      <Arrow x1={a0[0]} y1={a0[1]} x2={a1[0]} y2={a1[1]} color="#7B1FA2" w={7} />
      <Sca ch="a" sub="C" x={a1[0] + 14} y={a1[1] + 8} size={38} fill="#7B1FA2" />
    </svg>
  )
}

export function CmShell() {
  const O: [number, number] = [396, 546]
  const R = 330
  const th = 50 * D2R
  const dth = 6.5 * D2R
  const E: [number, number] = [O[0] + R * Math.sin(th), O[1] - R * Math.cos(th)]
  const yc = O[1] - R * Math.cos(th)
  const ringR = R * Math.sin(th)
  const pr = (a: number, r: number): [number, number] =>
    [O[0] + r * Math.sin(a), O[1] - r * Math.cos(a)]
  const r0 = pr(th - dth / 2, R + 46)
  const r1 = pr(th + dth / 2, R + 46)
  return (
    <svg viewBox="0 0 1000 640" width="100%" height="100%">
      {/* 半圆弧与坐标轴 */}
      <ArcLine cx={O[0]} cy={O[1]} r={R} a0={Math.PI} a1={2 * Math.PI} color="#1F4E9C" w={5} />
      <line x1={O[0] - R - 56} y1={O[1]} x2={O[0] + R + 80} y2={O[1]} stroke="#111"
        strokeWidth="3.4" />
      <polygon points={`${O[0] + R + 88},${O[1]} ${O[0] + R + 62},${O[1] - 9} ${O[0] + R + 62},${O[1] + 9}`}
        fill="#111" />
      <text x={O[0] + R + 96} y={O[1] + 14} fontSize="38" fontStyle="italic"
        fontFamily={SERIF}>x</text>
      <line x1={O[0]} y1={O[1]} x2={O[0]} y2="112" stroke="#111" strokeWidth="3.4" />
      <polygon points={`${O[0]},104 ${O[0] - 9},130 ${O[0] + 9},130`} fill="#111" />
      <text x={O[0] + 18} y="136" fontSize="38" fontStyle="italic" fontFamily={SERIF}>y</text>
      <text x={O[0] - 36} y={O[1] + 42} fontSize="38" fontFamily={SERIF}>O</text>

      {/* 圆环：侧视图上就是球面上的一段弧 */}
      <ArcLine cx={O[0]} cy={O[1]} r={R} a0={-Math.PI / 2 + th - dth / 2}
        a1={-Math.PI / 2 + th + dth / 2} color="#D9A441" w={17} />
      {/* 环在空间是个圆，投影成椭圆（虚线上半） */}
      <path d={`M ${O[0] - ringR} ${yc} A ${ringR} ${ringR * 0.26} 0 0 1 ${O[0] + ringR} ${yc}`}
        fill="none" stroke="#9AA7B5" strokeWidth="2.2" strokeDasharray="10 8" />

      {/* 半径与 θ */}
      <line x1={O[0]} y1={O[1]} x2={E[0]} y2={E[1]} stroke="#333" strokeWidth="2.8" />
      <line x1={O[0]} y1={O[1]} x2={r0[0]} y2={r0[1]} stroke="#333" strokeWidth="2"
        strokeDasharray="9 7" />
      <line x1={O[0]} y1={O[1]} x2={r1[0]} y2={r1[1]} stroke="#333" strokeWidth="2"
        strokeDasharray="9 7" />
      <ArcLine cx={O[0]} cy={O[1]} r={150} a0={-Math.PI / 2} a1={-Math.PI / 2 + th}
        color="#333" w={2.6} />
      <text x={O[0] + 62} y={O[1] - 138} fontSize="34" fontStyle="italic"
        fontFamily={SERIF} fill="#333">θ</text>
      <text x={O[0] + 74} y={O[1] - 186} fontSize="34" fontStyle="italic"
        fontFamily={SERIF} fill="#333">R</text>

      {/* R sinθ：就是椭圆的半长轴，箭头画在长轴上，文字落在椭圆内部的空白处 */}
      <line x1={O[0]} y1={yc} x2={E[0]} y2={yc} stroke="#555" strokeWidth="2.4" />
      <polygon points={`${E[0]},${yc} ${E[0] - 20},${yc - 8} ${E[0] - 20},${yc + 8}`}
        fill="#555" />
      <polygon points={`${O[0]},${yc} ${O[0] + 20},${yc - 8} ${O[0] + 20},${yc + 8}`}
        fill="#555" />
      <text x={(O[0] + E[0]) / 2 - 14} y={yc - 22} textAnchor="middle" fontSize="32"
        fontStyle="italic" fontFamily={SERIF} fill="#555">R sinθ</text>

      {/* R cosθ：环心高度 */}
      <line x1={E[0] + 86} y1={yc} x2={E[0] + 86} y2={O[1]} stroke="#555" strokeWidth="2.2" />
      <polygon points={`${E[0] + 86},${yc} ${E[0] + 80},${yc + 20} ${E[0] + 92},${yc + 20}`}
        fill="#555" />
      <polygon points={`${E[0] + 86},${O[1]} ${E[0] + 80},${O[1] - 20} ${E[0] + 92},${O[1] - 20}`}
        fill="#555" />
      <text x={E[0] + 100} y={(yc + O[1]) / 2 + 10} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#555">R cosθ</text>

      {/* R dθ：环宽（沿切向的双向箭头） */}
      <line x1={r0[0]} y1={r0[1]} x2={r1[0]} y2={r1[1]} stroke="#C0392B" strokeWidth="2.6" />
      {(() => {
        const dx = r1[0] - r0[0], dy = r1[1] - r0[1]
        const L = Math.hypot(dx, dy) || 1
        const ux = dx / L, uy = dy / L
        const px = -uy, py = ux
        return (
          <>
            <polygon points={`${r0[0]},${r0[1]} ${r0[0] + ux * 20 + px * 9},${r0[1] + uy * 20 + py * 9}
              ${r0[0] + ux * 20 - px * 9},${r0[1] + uy * 20 - py * 9}`} fill="#C0392B" />
            <polygon points={`${r1[0]},${r1[1]} ${r1[0] - ux * 20 + px * 9},${r1[1] - uy * 20 + py * 9}
              ${r1[0] - ux * 20 - px * 9},${r1[1] - uy * 20 - py * 9}`} fill="#C0392B" />
          </>
        )
      })()}
      <text x={(r0[0] + r1[0]) / 2 + 30} y={(r0[1] + r1[1]) / 2 - 26} fontSize="30"
        fontStyle="italic" fontFamily={SERIF} fill="#C0392B">R dθ</text>
    </svg>
  )
}

export function CmBurst() {
  const yG = 560
  const xO = 600            // m₁ 落点（坐标原点）
  const half = 240          // 半射程 = x_C
  const top = 200
  const yOf = (x: number) => top + 360 * ((x - xO) / half) ** 2
  const arc: string[] = []
  for (let i = -30; i <= 30; i++) {
    const x = xO + (half * i) / 30
    arc.push(`${x},${yOf(x)}`)
  }
  const fall2: string[] = []
  for (let i = 0; i <= 24; i++) {
    const s = i / 24
    fall2.push(`${xO + 2 * half * s},${top + 360 * s * s}`)
  }
  return (
    <svg viewBox="0 0 1200 800" width="100%" height="100%">
      <line x1="200" y1={yG} x2="1150" y2={yG} stroke="#333" strokeWidth="4" />
      {/* 原抛物线（含上升段与"质心应走"的下降段） */}
      <polyline points={arc.join(' ')} fill="none" stroke="#9AA7B5" strokeWidth="3"
        strokeDasharray="12 9" />
      {/* m1 竖直下落 */}
      <line x1={xO} y1={top} x2={xO} y2={yG} stroke="#0A8A0A" strokeWidth="3"
        strokeDasharray="10 8" />
      {/* m2 水平抛出 */}
      <polyline points={fall2.join(' ')} fill="none" stroke="#C000C0" strokeWidth="3.4" />
      {/* 起抛点 */}
      <circle cx={xO - half} cy={yG} r="7" fill="#333" />
      <text x={xO - half} y={yG + 40} textAnchor="middle" fontSize="30" fontFamily={HEI}
        fill="#555">抛出点</text>
      {/* 最高点炸裂 */}
      <circle cx={xO} cy={top} r="16" fill="#F2F5F9" stroke="#C000C0" strokeWidth="3" />
      {[0, 45, 90, 135].map(a => (
        <line key={a} x1={xO + 22 * Math.cos(a * D2R)} y1={top + 22 * Math.sin(a * D2R)}
          x2={xO + 40 * Math.cos(a * D2R)} y2={top + 40 * Math.sin(a * D2R)}
          stroke="#C000C0" strokeWidth="3" />
      ))}
      <text x={xO + 54} y={top - 22} fontSize="30" fontFamily={HEI} fill="#C000C0">
        最高点炸裂
      </text>
      {/* 三个落点 */}
      <circle cx={xO} cy={yG} r="8" fill="#0A8A0A" />
      <circle cx={xO + half} cy={yG} r="8" fill="#E00" />
      <circle cx={xO + 2 * half} cy={yG} r="8" fill="#C000C0" />
      <text x={xO} y={yG + 76} textAnchor="middle" fontSize="34" fontStyle="italic"
        fontFamily={SERIF} fill="#0A8A0A">O</text>
      <Sca ch="m" sub="1" x={xO - 76} y={yG - 22} size={32} fill="#0A8A0A" />
      <text x={xO + half + 16} y={yG - 22} fontSize="34" fontStyle="italic"
        fontFamily={SERIF} fill="#E00">C</text>
      <Sca ch="m" sub="2" x={xO + 2 * half + 18} y={yG - 20} size={32} fill="#C000C0" />
      {/* x_C 与 x₂ 两条标注：x₂ 严格两倍长 */}
      <line x1={xO} y1={yG + 96} x2={xO} y2={yG + 74} stroke="#E00" strokeWidth="2.4" />
      <line x1={xO + half} y1={yG + 96} x2={xO + half} y2={yG + 74} stroke="#E00"
        strokeWidth="2.4" />
      <line x1={xO} y1={yG + 86} x2={xO + half} y2={yG + 86} stroke="#E00" strokeWidth="2.6" />
      <polygon points={`${xO + half},${yG + 86} ${xO + half - 18},${yG + 80} ${xO + half - 18},${yG + 92}`}
        fill="#E00" />
      <text x={xO + half / 2} y={yG + 132} textAnchor="middle" fontSize="32" fontStyle="italic"
        fontFamily={SERIF} fill="#E00">x</text>
      <text x={xO + half / 2 + 26} y={yG + 140} textAnchor="middle" fontSize="24"
        fontStyle="italic" fontFamily={SERIF} fill="#E00">C</text>
      <line x1={xO} y1={yG + 190} x2={xO} y2={yG + 160} stroke="#C000C0" strokeWidth="2.4" />
      <line x1={xO + 2 * half} y1={yG + 190} x2={xO + 2 * half} y2={yG + 160}
        stroke="#C000C0" strokeWidth="2.4" />
      <line x1={xO} y1={yG + 176} x2={xO + 2 * half} y2={yG + 176} stroke="#C000C0"
        strokeWidth="2.6" />
      <polygon points={`${xO + 2 * half},${yG + 176} ${xO + 2 * half - 18},${yG + 170} ${xO + 2 * half - 18},${yG + 182}`}
        fill="#C000C0" />
      <text x={xO + half} y={yG + 222} textAnchor="middle" fontSize="32" fontStyle="italic"
        fontFamily={SERIF} fill="#C000C0">x</text>
      <text x={xO + half + 26} y={yG + 230} textAnchor="middle" fontSize="24" fontStyle="italic"
        fontFamily={SERIF} fill="#C000C0">2</text>
      {/* 抛出速度 */}
      <Arrow x1={xO - half - 4} y1={yOf(xO - half + 40) - 52} x2={xO - half + 96} y2={yOf(xO - half + 40) - 52}
        color="#0000CD" w={5} />
      <text x={xO - half + 104} y={yOf(xO - half + 40) - 62} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#0000CD">v</text>
      <text x={xO - half + 130} y={yOf(xO - half + 40) - 62} fontSize="22" fontStyle="italic"
        fontFamily={SERIF} fill="#0000CD">0</text>
      <text x={xO - half - 40} y={yOf(xO - half + 40) - 70} textAnchor="end" fontSize="30"
        fontFamily={HEI} fill="#555">2m</text>
    </svg>
  )
}

/** 3-9 P18~P20：例4 匀速提链条 —— 质心高度 y_c = y²/(2l) 随 y 变，故有附加的力
 *  图上取 l = 550 px、y = 330 px ⇒ y_c = y²/(2l) = 99 px（严格小于 y/2 = 165）。 */
export function CmChain() {
  const yG = 600
  const L = 550, y = 330
  const yc = (y * y) / (2 * L)
  const xC = 520
  const beads: JSX.Element[] = []
  for (let i = 0; i <= 22; i++) {
    const yy = yG - (y * i) / 22
    beads.push(<circle key={i} cx={xC} cy={yy} r="7.5" fill="#DCE6F2" stroke="#1F4E9C"
      strokeWidth="2" />)
  }
  return (
    <svg viewBox="0 0 900 720" width="100%" height="100%">
      <Ground35 x0={120} x1={820} y={yG} />
      {/* 地上的一堆 */}
      {[0, 1, 2, 3, 4, 5, 6, 7].map(i => (
        <circle key={i} cx={xC - 62 + i * 18} cy={yG - 8 - (i % 3) * 9} r="7"
          fill="#DCE6F2" stroke="#1F4E9C" strokeWidth="2" />
      ))}
      {[0, 1, 2, 3, 4, 5].map(i => (
        <circle key={i} cx={xC - 50 + i * 18} cy={yG - 26 - (i % 2) * 8} r="7"
          fill="#DCE6F2" stroke="#1F4E9C" strokeWidth="2" />
      ))}
      {/* 提起段的链 */}
      {beads}
      {/* 手与提力 */}
      <Arrow x1={xC} y1={yG - y - 14} x2={xC} y2={yG - y - 128} color="#E00" w={6.5} />
      <Vec ch="F" x={xC + 16} y={yG - y - 116} size={38} fill="#E00" />
      {/* y 与 y_c 标注 */}
      <line x1="368" y1={yG} x2="368" y2={yG - y - 10} stroke="#555" strokeWidth="2.2" />
      <polygon points={`368,${yG - y - 22} 361,${yG - y + 4} 375,${yG - y + 4}`} fill="#555" />
      <line x1="358" y1={yG} x2="378" y2={yG} stroke="#555" strokeWidth="2.6" />
      <text x="352" y={yG - y / 2 + 8} textAnchor="end" fontSize="34" fontStyle="italic"
        fontFamily={SERIF} fill="#555">y</text>
      <line x1="434" y1={yG} x2="434" y2={yG - yc - 8} stroke="#E00" strokeWidth="2.2" />
      <polygon points={`434,${yG - yc - 20} 427,${yG - yc + 4} 441,${yG - yc + 4}`} fill="#E00" />
      <line x1="424" y1={yG} x2="444" y2={yG} stroke="#E00" strokeWidth="2.6" />
      <Sca ch="y" sub="C" x={424} y={yG - yc / 2 + 4} size={30} fill="#E00" anchor="end" />
      {/* 质心 */}
      <line x1={xC - 26} y1={yG - yc} x2={xC + 26} y2={yG - yc} stroke="#E00" strokeWidth="2.2"
        strokeDasharray="7 5" />
      <circle cx={xC} cy={yG - yc} r="8" fill="#E00" />
      <text x={xC + 22} y={yG - yc - 14} fontSize="34" fontStyle="italic" fontFamily={SERIF}
        fill="#111">c</text>
      {/* 辅助水平线 */}
      <line x1="368" y1={yG - y} x2={xC + 90} y2={yG - y} stroke="#9AA7B5" strokeWidth="2"
        strokeDasharray="9 7" />
      <line x1="434" y1={yG - yc} x2={xC + 54} y2={yG - yc} stroke="#E8B4B4"
        strokeWidth="2" strokeDasharray="9 7" />
    </svg>
  )
}

/* ================= 3-10 对称性与守恒律 ================= */

/** 六角雪花的枝线：6 条主枝，每枝两级对称分叉（纯几何，不带装饰） */
function snowSegs(cx: number, cy: number, R0: number): [number, number, number, number][] {
  const segs: [number, number, number, number][] = []
  for (let k = 0; k < 6; k++) {
    const a = -Math.PI / 2 + (k * Math.PI) / 3
    const ux = Math.cos(a), uy = Math.sin(a)
    segs.push([cx, cy, cx + R0 * ux, cy + R0 * uy])
    for (const [rr, ln] of [[0.44, 0.28], [0.70, 0.19]] as [number, number][]) {
      const bx = cx + rr * R0 * ux, by = cy + rr * R0 * uy
      for (const sgn of [-1, 1]) {
        const b = a + sgn * (Math.PI / 3)
        segs.push([bx, by, bx + ln * R0 * Math.cos(b), by + ln * R0 * Math.sin(b)])
      }
    }
  }
  return segs
}

