/** 3-32 空间平移不变性：一对粒子 A、B，只显示其中一种移法 */
function SymTrans({ mode }: { mode: 'A' | 'B' }) {
  const A: [number, number] = [380, 430]
  const B: [number, number] = [740, 220]
  const R = 28
  const DS = 200                                   // 两种移法的位移像素长度必须相等
  const Ap: [number, number] = [A[0] - DS, A[1]]
  const Bp: [number, number] = [B[0] + DS, B[1]]
  const u: [number, number] = [B[0] - A[0], B[1] - A[1]]
  const L = Math.hypot(u[0], u[1])
  const ux = u[0] / L, uy = u[1] / L
  const movA = mode === 'A'
  const sFrom: [number, number] = movA ? [A[0] - R, A[1]] : [B[0] + R, B[1]]
  const sTo: [number, number] = movA ? [Ap[0] + R, Ap[1]] : [Bp[0] - R, Bp[1]]
  // 只在各自那一页画对应的那一个力：A 页画 F_BA，B 页画 F_AB
  const f0: [number, number] = movA ? [A[0] + ux * R, A[1] + uy * R]
    : [B[0] - ux * R, B[1] - uy * R]
  const f1: [number, number] = movA ? [f0[0] + ux * 152, f0[1] + uy * 152]
    : [f0[0] - ux * 152, f0[1] - uy * 152]
  const n: [number, number] = [-uy, ux]              // 连线指向右下的法向
  const fm: [number, number] = [(f0[0] + f1[0]) / 2, (f0[1] + f1[1]) / 2]
  const lx = fm[0] - n[0] * 46, ly = fm[1] - n[1] * 46   // 标签放连线左上侧（离开图内）
  const sm: [number, number] = [(sFrom[0] + sTo[0]) / 2, (sFrom[1] + sTo[1]) / 2]
  const dot = (p: [number, number], _fill: string, dashed = false) => (
    <circle cx={p[0]} cy={p[1]} r={R} fill={dashed ? '#F4FAF5' : '#EAF2FA'}
      stroke={dashed ? '#12852F' : '#1F4E9C'} strokeWidth="2.8"
      strokeDasharray={dashed ? '8 6' : undefined} />
  )
  return (
    <svg viewBox="150 118 820 402" width="100%" height="100%">
      {/* 两粒子的相对位置 */}
      <line x1={A[0] + ux * R} y1={A[1] + uy * R} x2={B[0] - ux * R} y2={B[1] - uy * R}
        stroke="#B9C4D0" strokeWidth="2.2" strokeDasharray="10 8" />
      {/* 粒子 */}
      {dot(A, '#EAF2FA')}
      {dot(B, '#EAF2FA')}
      {movA ? dot(Ap, '#F4FAF5', true) : dot(Bp, '#F4FAF5', true)}
      {/* 位移 Δs（两种移法等长） */}
      <Arrow x1={sFrom[0]} y1={sFrom[1]} x2={sTo[0]} y2={sTo[1]} color="#12852F" w={5.5} />
      <text x={sm[0]} y={sm[1] + 46} textAnchor="middle" fontSize="36" fontStyle="italic"
        fontFamily={SERIF} fill="#12852F">Δs</text>
      {/* 相互作用力 */}
      <Arrow x1={f0[0]} y1={f0[1]} x2={f1[0]} y2={f1[1]} color="#E00" w={6} />
      <VecN ch="F" sub={movA ? 'BA' : 'AB'} x={lx} y={ly} size={34} fill="#E00" />
      {/* 记号 */}
      <text x={A[0] - R - 34} y={A[1] + 10} textAnchor="end" fontSize="36" fontStyle="italic"
        fontFamily={SERIF} fill="#111">A</text>
      <text x={B[0]} y={B[1] - R - 18} textAnchor="middle" fontSize="36" fontStyle="italic"
        fontFamily={SERIF} fill="#111">B</text>
      <text x={movA ? Ap[0] : Bp[0]} y={(movA ? Ap[1] : Bp[1]) - R - 18}
        textAnchor="middle" fontSize="36" fontStyle="italic" fontFamily={SERIF}
        fill="#12852F">{movA ? 'A′' : 'B′'}</text>
    </svg>
  )
}

/** 3-10 P5：B 不动，把 A 沿反方向平移 Δs */
export function SymTransA() {
  return <SymTrans mode="A" />
}

/** 3-10 P6：A 不动，把 B 沿反方向平移 Δs */
export function SymTransB() {
  return <SymTrans mode="B" />
}

/** 3-10 P9：动能与势能互相转化，任一时刻之和不变（时间平移不变性） */
export function SymTime() {
  const X0 = 168, Y0 = 470, XW = 964, EH = 306, T = 214
  const n = 240
  const ek: string[] = [], ep: string[] = []
  for (let i = 0; i <= n; i++) {
    const x = X0 + (XW * i) / n
    const ph = ((x - X0) / T) * Math.PI
    const s = Math.sin(ph), c = Math.cos(ph)
    ek.push(`${x.toFixed(1)},${(Y0 - EH * s * s).toFixed(1)}`)
    ep.push(`${x.toFixed(1)},${(Y0 - EH * c * c).toFixed(1)}`)
  }
  const EY = Y0 - EH
  const marks = [X0 + T * 0.5, X0 + T * 1.5]
  return (
    <svg viewBox="120 60 1070 440" width="100%" height="100%">
      {/* 坐标轴 */}
      <line x1={X0} y1={Y0} x2={1160} y2={Y0} stroke="#111" strokeWidth="3" />
      <polygon points={`1168,${Y0} 1144,${Y0 - 9} 1144,${Y0 + 9}`} fill="#111" />
      <line x1={X0} y1={Y0} x2={X0} y2={92} stroke="#111" strokeWidth="3" />
      <polygon points={`${X0},84 ${X0 - 9},108 ${X0 + 9},108`} fill="#111" />
      <text x="1152" y={Y0 + 46} fontSize="36" fontStyle="italic" fontFamily={SERIF}
        fill="#111">t</text>
      <text x={X0 - 46} y="118" fontSize="36" fontStyle="italic" fontFamily={SERIF}
        fill="#111">E</text>
      {/* 两条曲线 */}
      <polyline points={ep.join(' ')} fill="none" stroke="#D0021B" strokeWidth="5" />
      <polyline points={ek.join(' ')} fill="none" stroke="#1F6FBF" strokeWidth="5" />
      {/* 和恒为 E */}
      <line x1={X0} y1={EY} x2={1140} y2={EY} stroke="#111" strokeWidth="2.4"
        strokeDasharray="12 8" />
      <text x={X0 + 12} y={EY - 16} fontSize="32" fontFamily={HEI} fill="#333">E</text>
      {/* 两个时刻：读数不同，和相同 */}
      {marks.map((x, i) => (
        <g key={i}>
          <line x1={x} y1={EY} x2={x} y2={Y0} stroke="#9AA7B5" strokeWidth="2"
            strokeDasharray="9 7" />
          <text x={x} y={Y0 + 42} textAnchor="middle" fontSize="32" fontStyle="italic"
            fontFamily={SERIF} fill="#555">{i === 0 ? 't₁' : 't₂'}</text>
        </g>
      ))}
      {/* 图例 */}
      <line x1={X0 + 40} y1={112} x2={X0 + 104} y2={112} stroke="#1F6FBF" strokeWidth="5" />
      <text x={X0 + 116} y={124} fontSize="30" fontFamily={HEI} fill="#333">E k</text>
      <line x1={X0 + 196} y1={112} x2={X0 + 260} y2={112} stroke="#D0021B" strokeWidth="5" />
      <text x={X0 + 272} y={124} fontSize="30" fontFamily={HEI} fill="#333">E p</text>
    </svg>
  )
}

