/* ================= 4-2 力矩 转动定律 转动惯量 ================= */

/** 4-2 P3：力矩 M = F r sinθ = F d（d 为 O 到力作用线的垂距） */
export function TorqueDef() {
  const O: [number, number] = [330, 350]
  const P: [number, number] = [600, 296]
  const fa = (-45 * Math.PI) / 180
  const fd: [number, number] = [Math.cos(fa), Math.sin(fa)]
  const t = -((P[0] - O[0]) * fd[0] + (P[1] - O[1]) * fd[1])
  const H: [number, number] = [P[0] + t * fd[0], P[1] + t * fd[1]]
  const Ftip: [number, number] = [P[0] + 172 * fd[0], P[1] + 172 * fd[1]]
  const board = 'M 300 190 C 400 150 540 166 600 214 C 648 254 636 330 586 372 '
    + 'C 520 424 372 420 312 372 C 262 330 258 234 300 190 Z'
  return (
    <svg viewBox="225 140 520 390" width="100%" height="100%">
      <path d={board} fill="#EAF2DA" stroke="#5E7A3A" strokeWidth="3" />
      <line x1={O[0]} y1={O[1] - 120} x2={O[0]} y2={O[1] + 130} stroke="#333"
        strokeWidth="3" />
      <circle cx={O[0]} cy={O[1]} r="6" fill="#333" />
      <text x={O[0] - 18} y={O[1] + 34} textAnchor="end" fontSize="34" fontStyle="italic"
        fontFamily={SERIF} fill="#111">O</text>
      <text x={O[0] - 22} y={O[1] - 104} textAnchor="end" fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#555">z</text>
      {/* 位矢 */}
      <Arrow x1={O[0]} y1={O[1]} x2={P[0]} y2={P[1]} color="#C2185B" w={5} />
      <text x={(O[0] + P[0]) / 2 - 4} y={(O[1] + P[1]) / 2 - 18} fontSize="32"
        fontStyle="italic" fontFamily={SERIF} fill="#C2185B">r</text>
      <circle cx={P[0]} cy={P[1]} r="7" fill="#111" />
      <text x={P[0] + 12} y={P[1] + 34} fontSize="32" fontStyle="italic"
        fontFamily={SERIF} fill="#111">P</text>
      {/* 力与力臂 */}
      <Arrow x1={P[0]} y1={P[1]} x2={Ftip[0]} y2={Ftip[1]} color="#D0021B" w={6} />
      <text x={Ftip[0] - 34} y={Ftip[1] + 6} fontSize="34" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">F</text>
      <line x1={O[0]} y1={O[1]} x2={H[0]} y2={H[1]} stroke="#12852F" strokeWidth="3"
        strokeDasharray="9 7" />
      <line x1={P[0]} y1={P[1]} x2={H[0]} y2={H[1]} stroke="#9AA7B5" strokeWidth="1.8"
        strokeDasharray="7 6" />
      <text x={(O[0] + H[0]) / 2 - 26} y={(O[1] + H[1]) / 2 + 30} fontSize="30"
        fontStyle="italic" fontFamily={SERIF} fill="#12852F">d</text>
      {/* θ */}
      <ArcLine cx={P[0]} cy={P[1]} r={92}
        a0={Math.atan2(P[1] - O[1], P[0] - O[0])} a1={fa} color="#D0021B" w={3} />
      <text x={P[0] - 78} y={P[1] - 40} fontSize="32" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">θ</text>
    </svg>
  )
}

