      <text x={A[0] - 40} y={A[1] - 50} textAnchor="middle" fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#555">A</text>
      {/* 绳与滑轮 */}
      <line x1={A[0] + 62} y1={A[1] - 6} x2={CX - 42} y2={A[1] - 6} stroke="#333"
        strokeWidth="2.6" />
