/** 4-5 P10：圆盘沿斜面纯滚动（例2） */
export function DiscIncline() {
  const A: [number, number] = [300, 220]
  const B: [number, number] = [300, 560]
  const D: [number, number] = [760, 560]
  const th = Math.atan2(D[1] - A[1], D[0] - A[0])
  const R0 = 86
  // 底端圆盘（切于斜面与地面）
  const Cb: [number, number] = [499, 560 - R0]
  const n: [number, number] = [Math.sin(th), -Math.cos(th)]   // 斜面的上侧法向
  const Ct: [number, number] = [A[0] + 120 * Math.cos(th) + n[0] * R0,
    A[1] + 120 * Math.sin(th) + n[1] * R0]
  return (
    <svg viewBox="230 130 620 480" width="100%" height="100%">
      <polygon points={`${A[0]},${A[1]} ${B[0]},${B[1]} ${D[0]},${D[1]}`}
        fill="#EDE6D8" stroke="#8A6A3A" strokeWidth="3" />
      <line x1={A[0] - 40} y1={B[1]} x2={D[0] + 40} y2={D[1]} stroke="#333"
        strokeWidth="3" />
      {/* 起始位置（虚线） */}
      <circle cx={Ct[0]} cy={Ct[1]} r={R0} fill="none" stroke="#8FA3B8" strokeWidth="2.6"
        strokeDasharray="11 8" />
      {/* 底端圆盘 */}
      <circle cx={Cb[0]} cy={Cb[1]} r={R0} fill="#F2F5F9" stroke="#333" strokeWidth="3" />
      <circle cx={Cb[0]} cy={Cb[1]} r="6" fill="#333" />
      <text x={Cb[0] + 10} y={Cb[1] + 32} fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#111">C</text>
      {/* v_C 与 ω */}
      <Arrow x1={Cb[0]} y1={Cb[1]} x2={Cb[0] + 150} y2={Cb[1]} color="#1F6FBF" w={5.5} />
      <text x={Cb[0] + 150} y={Cb[1] + 34} fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#1F6FBF">v</text>
      <text x={Cb[0] + 172} y={Cb[1] + 40} fontSize="20" fontFamily={SERIF}
        fill="#1F6FBF">C</text>
      <ArcArrow cx={Cb[0]} cy={Cb[1]} r={R0 + 40} a0={-1.2} a1={-0.2} color="#D0021B"
        w={4.5} />
      <text x={Cb[0] + 30} y={Cb[1] - R0 - 46} fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">ω</text>
      {/* h 与 θ */}
      <line x1="268" y1={A[1]} x2="268" y2={B[1]} stroke="#9AA7B5" strokeWidth="2.2" />
      <text x="252" y={(A[1] + B[1]) / 2} textAnchor="end" fontSize="28"
        fontStyle="italic" fontFamily={SERIF} fill="#555">h</text>
      <ArcLine cx={D[0]} cy={D[1]} r={90} a0={Math.PI} a1={Math.PI + th} color="#12852F"
        w={3} />
      <text x={D[0] - 120} y={D[1] - 20} fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#12852F">θ</text>
    </svg>
  )
}

