/** 4-6 P2：陀螺的进动——自转轴绕竖直轴画圆锥 */
export function GyroPrecess() {
  const O: [number, number] = [380, 560]
  const T: [number, number] = [600, 210]
  const C: [number, number] = [490, 385]
  const ang = (Math.atan2(T[1] - O[1], T[0] - O[0]) * 180) / Math.PI
  return (
    <svg viewBox="220 110 580 540" width="100%" height="100%">
      {/* 竖直转轴 */}
      <line x1={O[0]} y1={O[1]} x2={O[0]} y2="150" stroke="#9AA7B5" strokeWidth="2.6"
        strokeDasharray="12 9" />
      {/* 进动轨迹（P 绕竖直轴画的圆，斜二测成椭圆） */}
      <ellipse cx={O[0]} cy="210" rx="220" ry="56" fill="none" stroke="#D0021B"
        strokeWidth="2.6" strokeDasharray="10 8" />
      {/* 自转轴 */}
      <line x1={O[0]} y1={O[1]} x2={T[0]} y2={T[1]} stroke="#1F4E9C" strokeWidth="9"
        strokeLinecap="round" />
      <circle cx={O[0]} cy={O[1]} r="10" fill="#333" />
      <text x={O[0] - 26} y={O[1] + 34} textAnchor="end" fontSize="34" fontStyle="italic"
        fontFamily={SERIF} fill="#111">O</text>
      {/* 陀螺盘 */}
      <ellipse cx={C[0]} cy={C[1]} rx="108" ry="34" fill="#F7EFE4" stroke="#8A6A3A"
        strokeWidth="3" transform={`rotate(${ang + 90} ${C[0]} ${C[1]})`} />
      {/* 自转角速度 */}
      <Arrow x1={C[0] + 2} y1={C[1] - 16} x2={C[0] + 52} y2={C[1] - 92} color="#D0021B"
        w={6} />
      <text x={C[0] + 62} y={C[1] - 88} fontSize="34" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">ω</text>
      {/* 进动方向：P 处切向 */}
      <Arrow x1={T[0]} y1={T[1]} x2={T[0] + 6} y2={T[1] - 96} color="#D0021B" w={6} />
      <text x={T[0] + 16} y={T[1] - 104} fontSize="34" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">Ω</text>
      {/* θ */}
      <ArcLine cx={O[0]} cy={O[1]} r={150} a0={-Math.PI / 2} a1={Math.atan2(T[1] - O[1], T[0] - O[0])}
        color="#12852F" w={3} />
      <text x={O[0] + 22} y={O[1] - 132} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#12852F">θ</text>
      {/* 重力 */}
      <Arrow x1={C[0]} y1={C[1]} x2={C[0]} y2={C[1] + 128} color="#D0021B" w={5}
        dashed />
      <text x={C[0] + 12} y={C[1] + 120} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">mg</text>
    </svg>
  )
}

/** 4-6 P4：dL 垂直于 L ⇒ L 只改方向不改大小 */
export function GyroDL() {
  const O: [number, number] = [400, 560]
  const P: [number, number] = [600, 240]
  const Q: [number, number] = [558, 214]
  return (
    <svg viewBox="240 140 540 500" width="100%" height="100%">
      <line x1={O[0]} y1={O[1]} x2={O[0]} y2="170" stroke="#9AA7B5" strokeWidth="2.4"
        strokeDasharray="12 9" />
      <ellipse cx={O[0]} cy="236" rx="204" ry="52" fill="none" stroke="#D0021B"
        strokeWidth="2.4" strokeDasharray="10 8" />
      {/* L 与 L' */}
      <Arrow x1={O[0]} y1={O[1]} x2={P[0]} y2={P[1]} color="#1F6FBF" w={6} />
      <text x={P[0] + 12} y={P[1] + 8} fontSize="34" fontStyle="italic"
        fontFamily={SERIF} fill="#1F6FBF">L</text>
      <line x1={O[0]} y1={O[1]} x2={Q[0]} y2={Q[1]} stroke="#8FA3B8" strokeWidth="3"
        strokeDasharray="9 7" />
      <text x={Q[0] - 54} y={Q[1] + 6} fontSize="32" fontStyle="italic"
        fontFamily={SERIF} fill="#8FA3B8">L′</text>
      {/* dL */}
      <Arrow x1={P[0]} y1={P[1]} x2={Q[0]} y2={Q[1]} color="#D0021B" w={5.5} />
      <text x={Q[0] + 6} y={Q[1] - 24} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">dL</text>
      <circle cx={O[0]} cy={O[1]} r="9" fill="#333" />
      <text x={O[0] - 24} y={O[1] + 32} textAnchor="end" fontSize="32" fontStyle="italic"
        fontFamily={SERIF} fill="#111">O</text>
      {/* θ */}
      <ArcLine cx={O[0]} cy={O[1]} r={130} a0={-Math.PI / 2}
        a1={Math.atan2(P[1] - O[1], P[0] - O[0])} color="#12852F" w={3} />
      <text x={O[0] + 26} y={O[1] - 142} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#12852F">θ</text>
    </svg>
  )
}

