/* ================= 4-7 流体 伯努利方程 ================= */

/** 4-7 P2：流线——流速大的地方密、小的地方稀 */
export function Streamlines() {
  const lines = [0, 1, 2, 3, 4, 5].map(i => {
    const y0 = 300 + (i - 2.5) * 36
    const y1 = 300 + (i - 2.5) * 12
    return `M 210 ${y0} C 380 ${y0} 430 ${y1} 560 ${y1} L 820 ${y1}`
  })
  return (
    <svg viewBox="190 190 660 230" width="100%" height="100%">
      {lines.map((d, i) => (
        <path key={i} d={d} fill="none" stroke="#1F4E9C" strokeWidth="2.6" />
      ))}
      {/* 方向箭头 */}
      {[0, 2, 4].map(i => {
        const y = 300 + (i - 2.5) * 9
        return <polygon key={i}
          points={`700,${y} 678,${y - 6} 678,${y + 6}`} fill="#1F4E9C" />
      })}
      <text x="330" y="230" fontSize="30" fontFamily={HEI} fill="#555">密（v 大）</text>
      <text x="640" y="380" fontSize="30" fontFamily={HEI} fill="#555">稀（v 小）</text>
    </svg>
  )
}

/** 4-7 P3：连续性方程——变截面管与两个截面 */
export function Continuity() {
  const x1 = 380, x2 = 760
  const y1c = 300, y2c = 300
  const h1 = 96, h2 = 44
  return (
    <svg viewBox="200 155 700 305" width="100%" height="100%">
      {/* 管壁 */}
      <path d={`M 210 ${y1c - h1} L ${x1} ${y1c - h1} C 520 ${y1c - h1} 600 ${y2c - h2} ${x2} ${y2c - h2} L 830 ${y2c - h2}`}
        fill="none" stroke="#1F4E9C" strokeWidth="3.4" />
      <path d={`M 210 ${y1c + h1} L ${x1} ${y1c + h1} C 520 ${y1c + h1} 600 ${y2c + h2} ${x2} ${y2c + h2} L 830 ${y2c + h2}`}
        fill="none" stroke="#1F4E9C" strokeWidth="3.4" />
      {/* 两个截面 */}
      <line x1={x1} y1={y1c - h1} x2={x1} y2={y1c + h1} stroke="#D0021B" strokeWidth="4" />
      <line x1={x2} y1={y2c - h2} x2={x2} y2={y2c + h2} stroke="#D0021B" strokeWidth="4" />
      <text x={x1 - 16} y={y1c - h1 - 16} textAnchor="end" fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">ΔS₁</text>
      <text x={x2 + 16} y={y2c - h2 - 16} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">ΔS₂</text>
      {/* 速度 */}
      <Arrow x1={x1 + 20} y1={y1c} x2={x1 + 120} y2={y1c} color="#12852F" w={5} />
      <text x={x1 + 60} y={y1c - 18} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#12852F">v₁</text>
      <Arrow x1={x2 + 20} y1={y2c} x2={x2 + 140} y2={y2c} color="#12852F" w={5} />
      <text x={x2 + 66} y={y2c - 18} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#12852F">v₂</text>
    </svg>
  )
}

