/* ================= 4-8 万有引力的牛顿命题 ================= */

/** 4-8 P4：球壳取细环，求对球外质点 P 的引力 */
export function ShellRing() {
  const O: [number, number] = [360, 330]
  const R0 = 150
  const P: [number, number] = [820, 330]
  const th = (34 * Math.PI) / 180
  const A: [number, number] = [O[0] + R0 * Math.cos(th), O[1] - R0 * Math.sin(th)]
  return (
    <svg viewBox="150 150 760 360" width="100%" height="100%">
      <circle cx={O[0]} cy={O[1]} r={R0} fill="#F2F5F9" stroke="#333" strokeWidth="3" />
      {/* 细环（球面上的一圈，斜二测成椭圆） */}
      <ellipse cx={O[0]} cy={A[1]} rx={R0 * Math.cos(th)} ry="26" fill="none"
        stroke="#1F6FBF" strokeWidth="6" opacity="0.75" />
      <ellipse cx={O[0]} cy={A[1]} rx={R0 * Math.cos(th)} ry="26" fill="none"
        stroke="#DCEBF7" strokeWidth="2.5" />
      {/* O 到环、O 到 P、环到 P */}
      <line x1={O[0]} y1={O[1]} x2={A[0]} y2={A[1]} stroke="#12852F" strokeWidth="2.8" />
      <line x1={O[0]} y1={O[1]} x2={P[0]} y2={P[1]} stroke="#333" strokeWidth="2.8" />
      <line x1={A[0]} y1={A[1]} x2={P[0]} y2={P[1]} stroke="#D0021B" strokeWidth="2.6" />
      <text x={(O[0] + A[0]) / 2 - 16} y={(O[1] + A[1]) / 2 - 12} fontSize="28"
        fontStyle="italic" fontFamily={SERIF} fill="#12852F">R</text>
      <text x={(O[0] + P[0]) / 2} y={O[1] - 14} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#111">r</text>
      <text x={(A[0] + P[0]) / 2} y={(A[1] + P[1]) / 2 - 12} fontSize="28"
        fontStyle="italic" fontFamily={SERIF} fill="#D0021B">s</text>
      {/* θ */}
      <ArcLine cx={O[0]} cy={O[1]} r={72} a0={0} a1={-th} color="#12852F" w={3} />
      <text x={O[0] + 78} y={O[1] - 24} fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#12852F">θ</text>
      {/* dθ */}
      <ArcLine cx={O[0]} cy={O[1]} r={R0} a0={-th} a1={-th - 0.12} color="#D0021B"
        w={5} />
      <text x={O[0] + 96} y={O[1] - 138} fontSize="24" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">dθ</text>
      {/* P */}
      <circle cx={P[0]} cy={P[1]} r="10" fill="#111" />
      <text x={P[0] + 14} y={P[1] + 34} fontSize="32" fontStyle="italic"
        fontFamily={SERIF} fill="#111">P</text>
      <text x={P[0] - 6} y={P[1] - 18} fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#555">m</text>
      <text x={O[0] - 26} y={O[1] + 30} textAnchor="end" fontSize="32" fontStyle="italic"
        fontFamily={SERIF} fill="#111">O</text>
    </svg>
  )
}

/** 4-8 P9：极坐标下的速度分解（e_r、e_θ） */
export function PolarVel() {
  const O: [number, number] = [300, 470]
  const P: [number, number] = [660, 250]
  const u: [number, number] = [P[0] - O[0], P[1] - O[1]]
  const L = Math.hypot(u[0], u[1])
  const er: [number, number] = [u[0] / L, u[1] / L]
  const et: [number, number] = [-er[1], er[0]]
  const tip = (k: number, v: [number, number]): [number, number] =>
    [P[0] + v[0] * k, P[1] + v[1] * k]
  const vr = tip(80, er)
  const vt = tip(110, et)
  const vv: [number, number] = [vr[0] + (vt[0] - P[0]), vr[1] + (vt[1] - P[1])]
  return (
    <svg viewBox="230 170 580 400" width="100%" height="100%">
      <line x1={O[0]} y1={O[1]} x2="760" y2={O[1]} stroke="#9AA7B5" strokeWidth="2.2" />
      <text x="700" y={O[1] + 34} fontSize="26" fontFamily={HEI} fill="#555">参考轴</text>
      <line x1={O[0]} y1={O[1]} x2={P[0]} y2={P[1]} stroke="#1F6FBF" strokeWidth="3.4" />
      <text x={(O[0] + P[0]) / 2 - 28} y={(O[1] + P[1]) / 2 - 10} fontSize="30"
        fontStyle="italic" fontFamily={SERIF} fill="#1F6FBF">r</text>
      <circle cx={O[0]} cy={O[1]} r="9" fill="#333" />
      <text x={O[0] - 20} y={O[1] + 34} textAnchor="end" fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#111">O</text>
      <text x={O[0] + 12} y={O[1] - 14} fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#555">m′</text>
      {/* θ */}
      <ArcLine cx={O[0]} cy={O[1]} r={86} a0={0} a1={Math.atan2(u[1], u[0])}
        color="#12852F" w={3} />
      <text x={O[0] + 96} y={O[1] - 26} fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#12852F">θ</text>
      {/* 单位矢量 */}
      <Arrow x1={P[0]} y1={P[1]} x2={tip(96, er)[0]} y2={tip(96, er)[1]} color="#D0021B"
        w={5} />
      <text x={tip(104, er)[0] + 4} y={tip(104, er)[1] - 6} fontSize="26"
        fontStyle="italic" fontFamily={SERIF} fill="#D0021B">e</text>
      <text x={tip(104, er)[0] + 22} y={tip(104, er)[1]} fontSize="19"
        fontFamily={SERIF} fill="#D0021B">r</text>
      <Arrow x1={P[0]} y1={P[1]} x2={tip(96, et)[0]} y2={tip(96, et)[1]} color="#D0021B"
        w={5} />
      <text x={tip(104, et)[0] - 34} y={tip(104, et)[1] + 4} fontSize="26"
        fontStyle="italic" fontFamily={SERIF} fill="#D0021B">e</text>
      <text x={tip(104, et)[0] - 16} y={tip(104, et)[1] + 10} fontSize="19"
        fontFamily={SERIF} fill="#D0021B">θ</text>
      {/* 速度分解：v = v_r + v_θ */}
      <Arrow x1={P[0]} y1={P[1]} x2={vr[0]} y2={vr[1]} color="#12852F" w={5} />
      <text x={vr[0] + 8} y={vr[1] + 28} fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#12852F">v</text>
      <text x={vr[0] + 26} y={vr[1] + 34} fontSize="19" fontFamily={SERIF}
        fill="#12852F">r</text>
      <Arrow x1={P[0]} y1={P[1]} x2={vt[0]} y2={vt[1]} color="#8A2BE2" w={5} />
      <text x={vt[0] + 4} y={vt[1] + 8} fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#8A2BE2">v</text>
      <text x={vt[0] + 22} y={vt[1] + 14} fontSize="19" fontFamily={SERIF}
        fill="#8A2BE2">θ</text>
      <line x1={vr[0]} y1={vr[1]} x2={vv[0]} y2={vv[1]} stroke="#9AA7B5" strokeWidth="1.8"
        strokeDasharray="8 6" />
      <line x1={vt[0]} y1={vt[1]} x2={vv[0]} y2={vv[1]} stroke="#9AA7B5" strokeWidth="1.8"
        strokeDasharray="8 6" />
      <Arrow x1={P[0]} y1={P[1]} x2={vv[0]} y2={vv[1]} color="#1F6FBF" w={6} />
      <text x={vv[0] + 8} y={vv[1] + 10} fontSize="32" fontStyle="italic"
        fontFamily={SERIF} fill="#1F6FBF">v</text>
      <circle cx={P[0]} cy={P[1]} r="7" fill="#333" />
      <text x={P[0] + 10} y={P[1] - 18} fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#111">P</text>
    </svg>
  )
}

/* ================= 4-9 经典力学的成就和局限性 ================= */

/** 4-9 P9：确定性系统中的随机轨迹 */
export function ChaosWalk() {
  const steps = [0.8, 2.1, 0.4, 4.6, 1.2, 5.3, 0.2, 3.4, 5.8, 2.6, 0.9, 4.2,
    1.8, 5.5, 0.6, 3.1, 5.9, 2.2, 0.3, 4.8, 1.5, 5.1, 0.7, 3.7, 5.6, 2.9]
  let x = 420, y = 400
  const pts: [number, number][] = [[x, y]]
  for (const a of steps) {
    x += Math.cos(a) * 62
    y += Math.sin(a) * 62
    pts.push([x, y])
  }
  const grid: JSX.Element[] = []
  for (let i = 0; i <= 14; i++) {
    grid.push(<line key={`v${i}`} x1={180 + i * 40} y1="200" x2={180 + i * 40} y2="560"
      stroke="#C9D3DE" strokeWidth="1.2" />)
    grid.push(<line key={`h${i}`} x1="180" y1={200 + i * 26} x2="740" y2={200 + i * 26}
      stroke="#C9D3DE" strokeWidth="1.2" />)
  }
  return (
    <svg viewBox="160 180 600 400" width="100%" height="100%">
      <rect x="180" y="200" width="560" height="364" fill="#FBFCFE" />
      {grid}
      <polyline points={pts.map(q => `${q[0].toFixed(1)},${q[1].toFixed(1)}`).join(' ')}
        fill="none" stroke="#1F6FBF" strokeWidth="3" />
      {pts.map((q, i) => (
        <circle key={i} cx={q[0]} cy={q[1]} r="4.5" fill="#1F6FBF" />
      ))}
    </svg>
  )
}

/** 4-9 P10：谐振子的能量阶梯 —— 抛物体势阱中，能级等间距排列，
 *  E_n = (n + ½)hν。经典情形是连续的，量子情形是一级一级的。 */
export function EnergyLevels() {
  const levels = [0, 1, 2, 3, 4]
  const Y = (n: number) => 300 - n * 42
  return (
    <svg viewBox="0 0 700 400" width="100%" height="100%">
      {/* 抛物线势阱 */}
      <path d="M 90 60 Q 350 500 610 60" fill="none" stroke="#8A96A6" strokeWidth="2.4" />

      {levels.map(n => (
        <g key={n}>
          <line x1={200 - n * 22} y1={Y(n)} x2={500 + n * 22} y2={Y(n)} stroke="#1F6FBF"
            strokeWidth="3" />
          <text x={490 + n * 22} y={Y(n) + 6} fontSize="17" fontFamily={HEI} fill="#1F6FBF">
            {n === 0 ? '0' : `${n}hν`}
          </text>
        </g>
      ))}

      {/* 等间距标注 */}
      <line x1="120" y1={Y(0)} x2="120" y2={Y(1)} stroke="#C00000" strokeWidth="2" />
      <polygon points={`120,${Y(1)} 116,${Y(1) + 10} 124,${Y(1) + 10}`} fill="#C00000" />
      <text x="106" y={(Y(0) + Y(1)) / 2 + 6} textAnchor="end" fontSize="17" fontFamily={HEI}
        fill="#C00000">hν</text>

      <text x="350" y="356" textAnchor="middle" fontSize="18" fontFamily={HEI} fill="#5B7290">
        能级等间距 —— 这是谐振子的特征
      </text>
      <text x="350" y="386" textAnchor="middle" fontSize="17" fontFamily={HEI} fill="#40556F">
        $E_n=(n+\\frac12)h\\nu$，$n=0,1,2\\cdots$
      </text>
    </svg>
  )
}

