/** 5-1 P8：静电力的叠加（平行四边形） */
export function Superpose() {
  const Q1: [number, number] = [300, 540]
  const Q2: [number, number] = [780, 500]
  const Q0: [number, number] = [520, 310]
  const R = 30
  const unit = (a: [number, number], b: [number, number]): [number, number] => {
    const d: [number, number] = [b[0] - a[0], b[1] - a[1]]
    const L = Math.hypot(d[0], d[1])
    return [d[0] / L, d[1] / L]
  }
  const u1 = unit(Q1, Q0)
  const u2 = unit(Q2, Q0)
  const L1 = 175, L2 = 140
  const T1: [number, number] = [Q0[0] + u1[0] * L1, Q0[1] + u1[1] * L1]
  const T2: [number, number] = [Q0[0] + u2[0] * L2, Q0[1] + u2[1] * L2]
  const TT: [number, number] = [T1[0] + (T2[0] - Q0[0]), T1[1] + (T2[1] - Q0[1])]
  const nodes: [number, number, string, string][] = [[Q1[0], Q1[1], 'q₁', '#D0021B'],
    [Q2[0], Q2[1], 'q₂', '#D0021B'], [Q0[0], Q0[1], 'q₀', '#1F4E9C']]
  return (
    <svg viewBox="200 140 660 490" width="100%" height="100%">
      {nodes.map((q, i) => (
        <g key={i}>
          <circle cx={q[0]} cy={q[1]} r={R} fill="#FBFCFE" stroke="#333" strokeWidth="3" />
          <text x={q[0]} y={q[1] + 14} textAnchor="middle" fontSize="36" fontFamily={SERIF}
            fill={q[3]}>+</text>
          <text x={q[0]} y={q[1] + 72} textAnchor="middle" fontSize="26" fontStyle="italic"
            fontFamily={SERIF} fill="#555">{q[2]}</text>
        </g>
      ))}
      <Arrow x1={Q0[0] + u1[0] * R} y1={Q0[1] + u1[1] * R} x2={T1[0]} y2={T1[1]}
        color="#D0021B" w={5.5} />
      <Arrow x1={Q0[0] + u2[0] * R} y1={Q0[1] + u2[1] * R} x2={T2[0]} y2={T2[1]}
        color="#D0021B" w={5.5} />
      <text x={T1[0] + 10} y={T1[1] + 32} fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">F₁₀</text>
      <text x={T2[0] + 10} y={T2[1] - 12} fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">F₂₀</text>
      <line x1={T1[0]} y1={T1[1]} x2={TT[0]} y2={TT[1]} stroke="#9AA7B5" strokeWidth="2"
        strokeDasharray="9 7" />
      <line x1={T2[0]} y1={T2[1]} x2={TT[0]} y2={TT[1]} stroke="#9AA7B5" strokeWidth="2"
        strokeDasharray="9 7" />
      <Arrow x1={Q0[0]} y1={Q0[1]} x2={TT[0]} y2={TT[1]} color="#7B1FA2" w={6.5} />
      <text x={TT[0] + 14} y={TT[1] + 8} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#7B1FA2">F</text>
    </svg>
  )
}

/** 5-1 P10：两固定电荷之间的平衡点（q₁ = 4q，q₂ = q） */
export function ChargeBalance() {
  const y = 330
  const x1 = 300, x2 = 860
  const xb = x1 + (2 / 3) * (x2 - x1)
  const nodes: [number, number, string, string][] = [[x1, y, '4q', '#D0021B'],
    [x2, y, 'q', '#D0021B'], [xb, y, 'q₀', '#1F4E9C']]
  return (
    <svg viewBox="230 210 700 330" width="100%" height="100%">
      <line x1="260" y1={y + 122} x2="900" y2={y + 122} stroke="#9AA7B5" strokeWidth="2" />
      {[x1, xb, x2].map((x, i) => (
        <line key={i} x1={x} y1={y + 32} x2={x} y2={y + 122} stroke="#9AA7B5"
          strokeWidth="1.6" strokeDasharray="8 6" />
      ))}
      {nodes.map((q, i) => (
        <g key={i}>
          <circle cx={q[0]} cy={q[1]} r="30" fill="#FBFCFE" stroke="#333" strokeWidth="3" />
          <text x={q[0]} y={q[1] + 12} textAnchor="middle" fontSize="32" fontStyle="italic"
            fontFamily={SERIF} fill={q[3]}>{q[2]}</text>
        </g>
      ))}
      <Arrow x1={xb - 30} y1={y} x2={xb - 130} y2={y} color="#7B1FA2" w={5} />
      <Arrow x1={xb + 30} y1={y} x2={xb + 130} y2={y} color="#7B1FA2" w={5} />
      <text x={xb - 80} y={y - 24} textAnchor="middle" fontSize="24" fontStyle="italic"
        fontFamily={SERIF} fill="#7B1FA2">F₁</text>
      <text x={xb + 80} y={y - 24} textAnchor="middle" fontSize="24" fontStyle="italic"
        fontFamily={SERIF} fill="#7B1FA2">F₂</text>
      <text x={(x1 + xb) / 2} y={y + 96} textAnchor="middle" fontSize="25" fontStyle="italic"
        fontFamily={SERIF} fill="#12852F">2d/3</text>
      <text x={(xb + x2) / 2} y={y + 96} textAnchor="middle" fontSize="25" fontStyle="italic"
        fontFamily={SERIF} fill="#12852F">d/3</text>
    </svg>
  )
}

