/** 5-1 P4：宏观台阶（细到连成斜坡）与微观台阶（一格即 e）并列 */
export function QuantScalePair() {
  const stair = (x0: number, yb: number, n: number, wStep: number, hStep: number) => {
    const pts: string[] = []
    for (let k = 0; k < n; k++) {
      const x = x0 + k * wStep
      const y = yb - k * hStep
      pts.push(`M ${x.toFixed(1)} ${(y + hStep).toFixed(1)} L ${x.toFixed(1)} ${y.toFixed(1)}
        L ${(x + wStep).toFixed(1)} ${y.toFixed(1)}`)
    }
    return pts.join(' ')
  }
  return (
    <svg viewBox="0 0 700 520" width="100%" height="100%">
      {/* 宏观 */}
      <line x1="90" y1="230" x2="656" y2="230" stroke="#333" strokeWidth="2.4" />
      <line x1="90" y1="236" x2="90" y2="36" stroke="#333" strokeWidth="2.4" />
      <text x="62" y="30" fontSize="26" fontStyle="italic" fontFamily={SERIF} fill="#111">Q</text>
      <path d={stair(90, 230, 44, 12.8, 4.3)} fill="none" stroke="#1F4E9C" strokeWidth="2.4" />
      <text x="373" y="278" textAnchor="middle" fontSize="28" fontFamily={HEI} fill="#1F4E9C">
        宏观：连成斜坡，看不出台阶
      </text>
      {/* 微观 */}
      <line x1="90" y1="300" x2="656" y2="300" stroke="#DCE5F0" strokeWidth="1.6"
        strokeDasharray="9 7" />
      <line x1="90" y1="452" x2="656" y2="452" stroke="#333" strokeWidth="2.4" />
      <line x1="90" y1="458" x2="90" y2="308" stroke="#333" strokeWidth="2.4" />
      <path d={stair(90, 452, 6, 94.3, 23.7)} fill="none" stroke="#D0021B" strokeWidth="3" />
      {[1, 2, 3, 4, 5].map(k => (
        <text key={k} x={90 + k * 94.3} y={444 - k * 23.7} textAnchor="middle"
          fontSize="21" fontFamily={SERIF} fill="#B00020">{`${k}e`}</text>
      ))}
      <text x="373" y="500" textAnchor="middle" fontSize="28" fontFamily={HEI} fill="#B00020">
        微观：一格就是 e
      </text>
    </svg>
  )
}

