/** 5-2 P9：带电直线的场元分解（对称元的平行分量相消） */
export function LineChargeSetup() {
  const lineX = 236
  const P: [number, number] = [556, 250]
  const y1 = 172, y2 = 328
  const u1: [number, number] = [P[0] - lineX, P[1] - y1]
  const u2: [number, number] = [P[0] - lineX, P[1] - y2]
  const n1 = Math.hypot(u1[0], u1[1]), n2 = Math.hypot(u2[0], u2[1])
  const L = 158
  const e1: [number, number] = [P[0] + (u1[0] / n1) * L, P[1] + (u1[1] / n1) * L]
  const e2: [number, number] = [P[0] + (u2[0] / n2) * L, P[1] + (u2[1] / n2) * L]
  return (
    <svg viewBox="120 4 590 490" width="100%" height="100%">
      <line x1={lineX} y1="46" x2={lineX} y2="430" stroke="#1F4E9C" strokeWidth="7" />
      <text x={lineX - 18} y="42" textAnchor="end" fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#1F4E9C">λ</text>
      {[y1, y2].map((yy, i) => (
        <circle key={i} cx={lineX} cy={yy} r="7" fill="#D0021B" />
      ))}
      <line x1={lineX - 54} y1={y1} x2={lineX - 54} y2={y2} stroke="#12852F" strokeWidth="2.2" />
      <line x1={lineX - 64} y1={y1} x2={lineX - 44} y2={y1} stroke="#12852F" strokeWidth="2.2" />
      <line x1={lineX - 64} y1={y2} x2={lineX - 44} y2={y2} stroke="#12852F" strokeWidth="2.2" />
      <text x={lineX - 70} y={(y1 + y2) / 2 + 8} textAnchor="end" fontSize="26"
        fontFamily={SERIF} fill="#12852F">dx</text>
      {/* 到 P 的连线 */}
      <line x1={lineX} y1={y1} x2={P[0]} y2={P[1]} stroke="#9AA7B5" strokeWidth="1.8"
        strokeDasharray="8 6" />
      <line x1={lineX} y1={y2} x2={P[0]} y2={P[1]} stroke="#9AA7B5" strokeWidth="1.8"
        strokeDasharray="8 6" />
      <text x="404" y="212" fontSize="25" fontStyle="italic" fontFamily={SERIF}
        fill="#777">r</text>
      {/* dE 与分解 */}
      <Arrow x1={P[0]} y1={P[1]} x2={e1[0]} y2={e1[1]} color="#7B1FA2" w={5} />
      <Arrow x1={P[0]} y1={P[1]} x2={e2[0]} y2={e2[1]} color="#7B1FA2" w={5} />
      <text x={e1[0] - 16} y={e1[1] + 32} fontSize="25" fontStyle="italic" fontFamily={SERIF}
        fill="#7B1FA2">dE</text>
      <text x={e2[0] - 16} y={e2[1] - 18} fontSize="25" fontStyle="italic" fontFamily={SERIF}
        fill="#7B1FA2">dE′</text>
      <circle cx={P[0]} cy={P[1]} r="8" fill="#111" />
      <text x={P[0] + 8} y={P[1] - 38} fontSize="28" fontStyle="italic" fontFamily={SERIF}
        fill="#111">P</text>
      <text x="350" y="466" textAnchor="middle" fontSize="25" fontFamily={HEI} fill="#666">
        对称元的平行分量相消，垂直分量相加
      </text>
    </svg>
  )
}

