/* ================= 5-3 通量 高斯定理 ================= */


/** 5-3 P3：面元通量 dΦ = E·dS = E dS cosθ */
export function FluxPlane() {
  const C: [number, number] = [520, 380]
  const u: [number, number] = [200, -40]
  const v: [number, number] = [-40, 170]
  const P = (a: number, b: number): [number, number] =>
    [C[0] + u[0] * a + v[0] * b, C[1] + u[1] * a + v[1] * b]
  const c1 = P(-0.5, -0.5), c2 = P(0.5, -0.5), c3 = P(0.5, 0.5), c4 = P(-0.5, 0.5)
  const nn: [number, number] = [-0.5, -0.866]           // 法线：朝左上
  const eu: [number, number] = [0.45, -0.893]           // 场线：朝右上（自下而上穿过）
  return (
    <svg viewBox="220 120 720 520" width="100%" height="100%">
      <polygon points={`${c1[0]},${c1[1]} ${c2[0]},${c2[1]} ${c3[0]},${c3[1]} ${c4[0]},${c4[1]}`}
        fill="#DCEBF7" fillOpacity="0.85" stroke="#1F4E9C" strokeWidth="3" />
      {/* 场线：三条，自下而上穿过面元 */}
      {[-0.55, 0, 0.55].map((k, i) => {
        const b: [number, number] = [C[0] + u[0] * k, C[1] + u[1] * k]
        return <Arrow key={i} x1={b[0] - eu[0] * 130} y1={b[1] - eu[1] * 130}
          x2={b[0] + eu[0] * 150} y2={b[1] + eu[1] * 150} color="#1F6FBF" w={3.8} />
      })}
      <text x={c2[0] - 34} y={c2[1] - 126} fontSize="32" fontStyle="italic"
        fontFamily={SERIF} fill="#1F6FBF">E</text>
      {/* 法线 */}
      <Arrow x1={C[0]} y1={C[1]} x2={C[0] + nn[0] * 165} y2={C[1] + nn[1] * 165} color="#D0021B"
        w={5} />
      <text x={C[0] + nn[0] * 180 - 12} y={C[1] + nn[1] * 180 - 14} fontSize="32"
        fontStyle="italic" fontFamily={SERIF} fill="#D0021B">n</text>
      {/* 面元标注 */}
      <text x={c3[0] + 10} y={c3[1] + 40} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#1F4E9C">dS</text>
      {/* θ：n 与 E 的夹角 */}
      <ArcLine cx={C[0]} cy={C[1]} r={96}
        a0={Math.atan2(nn[1], nn[0])} a1={Math.atan2(eu[1], eu[0])} color="#12852F" w={3} />
      <text x={C[0] - 4} y={C[1] - 112} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#12852F">θ</text>
    </svg>
  )
}

/** 5-3 P9：点电荷 + 同心球面，Φ = q/ε₀ */
export function GaussSphere() {
  const O: [number, number] = [470, 340]
  const R = 200
  return (
    <svg viewBox="230 130 620 460" width="100%" height="100%">
      <circle cx={O[0]} cy={O[1]} r={R} fill="none" stroke="#1F4E9C" strokeWidth="3.4"
        strokeDasharray="12 8" />
      {Array.from({ length: 12 }).map((_, i) => {
        const a = (i * 2 * Math.PI) / 12 + 0.12
        return <Arrow key={i} x1={O[0] + 40 * Math.cos(a)} y1={O[1] + 40 * Math.sin(a)}
          x2={O[0] + (R + 34) * Math.cos(a)} y2={O[1] + (R + 34) * Math.sin(a)}
          color="#1F6FBF" w={3.6} />
      })}
      <circle cx={O[0]} cy={O[1]} r="28" fill="#FBFCFE" stroke="#333" strokeWidth="3" />
      <line x1={O[0] - 15} y1={O[1]} x2={O[0] + 15} y2={O[1]} stroke="#D0021B" strokeWidth="6" />
      <line x1={O[0]} y1={O[1] - 15} x2={O[0]} y2={O[1] + 15} stroke="#D0021B" strokeWidth="6" />
      <text x={O[0] + 14} y={O[1] + 56} fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#555">q</text>
      <text x={O[0] + R * 0.72} y={O[1] - R * 0.72 - 10} fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#1F4E9C">r</text>
      <text x="300" y="586" fontSize="28" fontFamily={HEI} fill="#555">
        面元 ⊥ E ⇒ Φ = q/ε₀
      </text>
    </svg>
  )
}

/** 5-3 P16：均匀带电球壳（r<R 内 E=0，r>R 外等效点电荷） */
export function GaussShell() {
  const O: [number, number] = [470, 350]
  const R1 = 92, R2 = 168
  return (
    <svg viewBox="230 110 620 500" width="100%" height="100%">
      <circle cx={O[0]} cy={O[1]} r={R2} fill="none" stroke="#333" strokeWidth="3" />
      <circle cx={O[0]} cy={O[1]} r={R1} fill="none" stroke="#333" strokeWidth="3" />
      <path d={`M ${O[0] + R1} ${O[1]} A ${R1} ${R1} 0 1 1 ${O[0] - R1} ${O[1]}
        A ${R1} ${R1} 0 1 1 ${O[0] + R1} ${O[1]} Z`} fill="#EAF2FA" opacity="0.55" />
      {/* 内高斯面 */}
      <circle cx={O[0]} cy={O[1]} r="56" fill="none" stroke="#D0021B" strokeWidth="3"
        strokeDasharray="10 7" />
      <text x={O[0]} y={O[1] + 10} textAnchor="middle" fontSize="27" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">E = 0</text>
      {/* 外高斯面 */}
      <circle cx={O[0]} cy={O[1]} r="222" fill="none" stroke="#12852F" strokeWidth="3"
        strokeDasharray="10 7" />
      {[0, 1, 2, 3, 4, 5, 6, 7].map(i => {
        const a = (i * Math.PI) / 4 + 0.2
        return <Arrow key={i} x1={O[0] + (R2 + 6) * Math.cos(a)} y1={O[1] + (R2 + 6) * Math.sin(a)}
          x2={O[0] + 250 * Math.cos(a)} y2={O[1] + 250 * Math.sin(a)} color="#12852F" w={3.4} />
      })}
      <text x={O[0] + 150} y={O[1] + 172} fontSize="25" fontStyle="italic" fontFamily={SERIF}
        fill="#12852F">E = kq/r²</text>
    </svg>
  )
}

/** 5-3 P20：无限长带电圆柱 + 同轴圆柱形高斯面 */
export function GaussCyl() {
  const cx = 470, cyT = 200, cyB = 470, rx = 104, ry = 30, rc = 168
  return (
    <svg viewBox="230 110 660 490" width="100%" height="100%">
      {/* 带电圆柱 */}
      <rect x={cx - rx} y={cyT} width={2 * rx} height={cyB - cyT} fill="#DCEBF7"
        opacity="0.75" />
      <ellipse cx={cx} cy={cyT} rx={rx} ry={ry} fill="#EAF2FA" stroke="#1F4E9C" strokeWidth="3" />
      <line x1={cx - rx} y1={cyT} x2={cx - rx} y2={cyB} stroke="#1F4E9C" strokeWidth="3" />
      <line x1={cx + rx} y1={cyT} x2={cx + rx} y2={cyB} stroke="#1F4E9C" strokeWidth="3" />
      <ellipse cx={cx} cy={cyB} rx={rx} ry={ry} fill="none" stroke="#1F4E9C" strokeWidth="3"
        strokeDasharray="10 7" />
      {/* 高斯面 */}
      <ellipse cx={cx} cy={cyT - 40} rx={rc} ry={ry * 1.5} fill="none" stroke="#D0021B"
        strokeWidth="3" strokeDasharray="11 8" />
      <line x1={cx - rc} y1={cyT - 40} x2={cx - rc} y2={cyB + 40} stroke="#D0021B"
        strokeWidth="3" strokeDasharray="11 8" />
      <line x1={cx + rc} y1={cyT - 40} x2={cx + rc} y2={cyB + 40} stroke="#D0021B"
        strokeWidth="3" strokeDasharray="11 8" />
      <ellipse cx={cx} cy={cyB + 40} rx={rc} ry={ry * 1.5} fill="none" stroke="#D0021B"
        strokeWidth="3" strokeDasharray="11 8" />
      {/* 侧面法线与 E */}
      <Arrow x1={cx + rc} y1={cyT + 120} x2={cx + rc + 96} y2={cyT + 120} color="#1F6FBF"
        w={5} />
      <text x={cx + rc + 104} y={cyT + 128} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#1F6FBF">E</text>
      <text x={cx + rc + 12} y={cyT + 106} fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">n</text>
      {/* r 与 l */}
      <line x1={cx} y1={cyB + 76} x2={cx + rc} y2={cyB + 76} stroke="#12852F" strokeWidth="2.6" />
      <text x={cx + rc / 2} y={cyB + 68} textAnchor="middle" fontSize="26"
        fontStyle="italic" fontFamily={SERIF} fill="#12852F">r</text>
      <line x1={cx - rc - 44} y1={cyT - 40} x2={cx - rc - 44} y2={cyB + 40} stroke="#9AA7B5"
        strokeWidth="2" />
      <text x={cx - rc - 62} y={(cyT + cyB) / 2} textAnchor="end" fontSize="28"
        fontStyle="italic" fontFamily={SERIF} fill="#555">l</text>
    </svg>
  )
}

/** 5-3 P26：无限大带电平面 + 圆柱形高斯面 */
