/** 5-3 P4：通量的正负（穿出为正、穿入为负） */
export function FluxSign() {
  const S = 'M 170 250 C 170 132 530 132 530 250 C 530 368 170 368 170 250 Z'
  const ns: [number, number][] = [[170, 250], [230, 172], [350, 145], [470, 172], [530, 250], [470, 328], [350, 355], [230, 328]]
  return (
    <svg viewBox="76 66 540 376" width="100%" height="100%">
      <path d={S} fill="#EAF2FA" fillOpacity="0.6" stroke="#1F4E9C" strokeWidth="3.4" />
      {ns.map((p, i) => {
        const cx = 350, cy = 250
        const dx = p[0] - cx, dy = p[1] - cy
        const L = Math.hypot(dx, dy)
        return <Arrow key={i} x1={p[0]} y1={p[1]} x2={p[0] + (dx / L) * 34} y2={p[1] + (dy / L) * 34}
          color="#D0021B" w={3} />
      })}
      <text x="548" y="196" fontSize="24" fontFamily={SERIF} fill="#D0021B">n</text>
      {/* 穿出（右上） */}
      <Arrow x1={404} y1={196} x2={588} y2={126} color="#1F6FBF" w={4} />
      <text x="596" y="122" fontSize="27" fontFamily={SERIF} fill="#12852F">+</text>
      <text x="410" y="112" fontSize="24" fontFamily={HEI} fill="#12852F">穿出为正</text>
      {/* 穿入（左下） */}
      <Arrow x1={104} y1={352} x2={232} y2={306} color="#1F6FBF" w={4} />
      <text x="100" y="380" textAnchor="start" fontSize="24" fontFamily={HEI} fill="#B00020">穿入为负</text>
      <text x="300" y="410" textAnchor="middle" fontSize="25" fontFamily={HEI} fill="#666">
        闭合面取外法线
      </text>
    </svg>
  )
}

