/** 5-3 P8：任意闭合面的通量（面内电荷计入，面外不计） */
export function GaussAnySurface() {
  const S = 'M 240 150 C 330 92 470 108 512 196 C 552 282 470 386 350 384 C 250 382 186 316 196 240 C 202 196 218 172 240 150 Z'
  const Q: [number, number] = [352, 250]
  return (
    <svg viewBox="176 70 540 380" width="100%" height="100%">
      <path d={S} fill="#EAF2FA" fillOpacity="0.42" stroke="#1F4E9C" strokeWidth="3.6" />
      {/* 面内电荷 */}
      <circle cx={Q[0]} cy={Q[1]} r="26" fill="#FBEDEA" stroke="#333" strokeWidth="2.6" />
      <text x={Q[0]} y={Q[1] + 11} textAnchor="middle" fontSize="28" fontFamily={SERIF}
        fill="#D0021B">+</text>
      <text x={Q[0]} y={Q[1] + 58} textAnchor="middle" fontSize="24" fontFamily={HEI}
        fill="#B00020">面内 q 计入</text>
      {Array.from({ length: 8 }).map((_, i) => {
        const a = (i * 2 * Math.PI) / 8 + 0.2
        return <Arrow key={i} x1={Q[0] + 30 * Math.cos(a)} y1={Q[1] + 30 * Math.sin(a)}
          x2={Q[0] + 168 * Math.cos(a)} y2={Q[1] + 168 * Math.sin(a)} color="#1F6FBF" w={3} />
      })}
      {/* 面外电荷 */}
      <circle cx="628" cy="128" r="22" fill="#EAF2FA" stroke="#333" strokeWidth="2.4" />
      <text x="628" y="136" textAnchor="middle" fontSize="24" fontFamily={SERIF}
        fill="#1F4E9C">−</text>
      <text x="628" y="88" textAnchor="middle" fontSize="23" fontFamily={HEI} fill="#666">
        面外 q 不计
      </text>
      <text x="402" y="438" textAnchor="middle" fontSize="25" fontFamily={HEI} fill="#666">
        形状任意；只看面内电荷的代数和
      </text>
    </svg>
  )
}

