/* ================= 5-4 密立根油滴实验 ================= */


/** 5-4 P4/P5：平行板间的油滴（field=true 时加电场力） */
function OilDrop({ field }: { field: boolean }) {
  const cx = 500, yT = 250, yB = 520
  const cy = 385
  return (
    <svg viewBox="260 160 620 460" width="100%" height="100%">
      {/* 极板 */}
      <rect x="300" y={yT - 16} width="420" height="18" fill="#1F4E9C" />
      <rect x="300" y={yB} width="420" height="18" fill="#1F4E9C" />
      <text x="736" y={yT - 2} fontSize="28" fontFamily={SERIF} fill="#D0021B">+</text>
      <text x="736" y={yB + 16} fontSize="28" fontFamily={SERIF} fill="#1F4E9C">−</text>
      {/* 板间距 d */}
      <line x1="292" y1={yT} x2="292" y2={yB} stroke="#9AA7B5" strokeWidth="2" />
      <text x="276" y={(yT + yB) / 2} textAnchor="end" fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#555">d</text>
      {/* 油滴 */}
      <circle cx={cx} cy={cy} r="26" fill="#DCEBF7" stroke="#1F4E9C" strokeWidth="2.6" />
      {/* 重力 */}
      <Arrow x1={cx} y1={cy + 26} x2={cx} y2={cy + 150} color="#D0021B" w={5.5} />
      <text x={cx + 12} y={cy + 146} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">P</text>
      {/* 黏性力 */}
      <Arrow x1={cx - 16} y1={cy - 24} x2={cx - 16} y2={cy - 132} color="#8A6A3A" w={5} />
      <text x={cx - 62} y={cy - 116} fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#8A6A3A">F</text>
      <text x={cx - 42} y={cy - 110} fontSize="18" fontFamily={SERIF}
        fill="#8A6A3A">r</text>
      {/* 电场力（可选）与 E */}
      {field && (
        <g>
          <Arrow x1={cx + 16} y1={cy - 22} x2={cx + 16} y2={cy - 148} color="#12852F" w={5.5} />
          <text x={cx + 28} y={cy - 122} fontSize="26" fontStyle="italic"
            fontFamily={SERIF} fill="#12852F">F</text>
          <text x={cx + 46} y={cy - 116} fontSize="18" fontFamily={SERIF}
            fill="#12852F">e</text>
          <Arrow x1={cx - 150} y1={yT + 30} x2={cx - 150} y2={yB - 40} color="#1F6FBF" w={4.5}
            dashed />
          <text x={cx - 184} y={(yT + yB) / 2} fontSize="30" fontStyle="italic"
            fontFamily={SERIF} fill="#1F6FBF">E</text>
          <line x1="744" y1={yT} x2="744" y2={yB} stroke="#9AA7B5" strokeWidth="2" />
          <text x="758" y={(yT + yB) / 2} fontSize="28" fontStyle="italic"
            fontFamily={SERIF} fill="#555">U</text>
        </g>
      )}
    </svg>
  )
}

export function OilDropFree() {
  return <OilDrop field={false} />
}

export function OilDropField() {
  return <OilDrop field />
}

