/** 7-1 P4：条形磁铁的磁感线（外部 N→S，内部 S→N，闭合） */
export function MagFieldLines() {
  const L = 260, R = 440, cy = 270
  const top = (k: number) => {
    const yy = 196 - k * 44
    return `M ${L} ${cy - 26} C ${L - 96} ${yy} ${R + 96} ${yy} ${R} ${cy - 26}`
  }
  const bot = (k: number) => {
    const yy = 344 + k * 44
    return `M ${L} ${cy + 26} C ${L - 96} ${yy} ${R + 96} ${yy} ${R} ${cy + 26}`
  }
  return (
    <svg viewBox="120 96 560 380" width="100%" height="100%">
      {[0, 1, 2].map(k => (
        <path key={`t${k}`} d={top(k)} fill="none" stroke="#1F6FBF" strokeWidth="2.8" />
      ))}
      {[0, 1, 2].map(k => (
        <path key={`b${k}`} d={bot(k)} fill="none" stroke="#1F6FBF" strokeWidth="2.8" />
      ))}
      {/* 方向箭头（贴近磁铁两端） */}
      <Arrow x1={L - 18} y1={228} x2={L - 76} y2={186} color="#1F6FBF" w={3.4} />
      <Arrow x1={R + 76} y1={186} x2={R + 18} y2={228} color="#1F6FBF" w={3.4} />
      {/* 磁铁 */}
      <rect x={L} y={cy - 26} width="90" height="52" fill="#E8453C" />
      <rect x={L + 90} y={cy - 26} width="90" height="52" fill="#2F6DB5" />
      <text x={L + 45} y={cy + 13} textAnchor="middle" fontSize="30" fontFamily={SERIF}
        fill="#fff">N</text>
      <text x={L + 135} y={cy + 13} textAnchor="middle" fontSize="30" fontFamily={SERIF}
        fill="#fff">S</text>
      {/* 内部 S→N（画在磁铁上半部，避开字母） */}
      <Arrow x1={R - 12} y1={cy + 48} x2={L + 12} y2={cy + 48} color="#12852F" w={4.4}
        dashed />
      <text x={352} y={cy + 80} textAnchor="middle" fontSize="24" fontFamily={HEI}
        fill="#12852F">磁铁内部：S → N</text>
      <text x="352" y="430" textAnchor="middle" fontSize="26" fontFamily={HEI} fill="#333">
        磁感线闭合：没有起点，也没有终点
      </text>
    </svg>
  )
}

