/** 7-1 P6：B 的定义——F = qv×B，三个矢量两两垂直 */
export function BDefinition() {
  const O: [number, number] = [268, 312]
  return (
    <svg viewBox="78 58 646 456" width="100%" height="100%">
      <Arrow x1={O[0]} y1={O[1]} x2={O[0]} y2={O[1] - 200} color="#D0021B" w={6} />
      <text x={O[0] - 16} y={O[1] - 214} textAnchor="end" fontSize="34" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">v</text>
      <Arrow x1={O[0]} y1={O[1]} x2={O[0] + 290} y2={O[1]} color="#1F6FBF" w={6} />
      <text x={O[0] + 298} y={O[1] + 12} fontSize="34" fontStyle="italic"
        fontFamily={SERIF} fill="#1F6FBF">B</text>
      {/* F 出纸面 */}
      <line x1={O[0] + 18} y1={O[1] - 18} x2={O[0] + 96} y2={O[1] - 96} stroke="#7B1FA2"
        strokeWidth="2.6" strokeDasharray="8 6" />
      <circle cx={O[0]} cy={O[1]} r="17" fill="#fff" stroke="#7B1FA2" strokeWidth="3.6" />
      <circle cx={O[0]} cy={O[1]} r="5.5" fill="#7B1FA2" />
      <text x={O[0] + 104} y={O[1] - 100} fontSize="32" fontStyle="italic"
        fontFamily={SERIF} fill="#7B1FA2">F</text>
      <text x={O[0] + 104} y={O[1] - 64} fontSize="22" fontFamily={HEI} fill="#7B1FA2">
        垂直纸面向外
      </text>
      <text x="400" y="470" textAnchor="middle" fontSize="28" fontFamily={SERIF} fill="#333">
        F = q v × B，F ⊥ v 且 F ⊥ B
      </text>
    </svg>
  )
}

/** 7-1 P7/P11：带电粒子在匀强磁场中的圆周运动 */
