/* ================= 7-7 磁场对载流线圈的作用 ================= */

/** 7-7 P3：磁矩 p_m = ISn —— 法线由右手定则给出（四指沿电流，拇指为 n） */
export function MagMoment() {
  const C: [number, number] = [270, 292]
  const u: [number, number] = [168, -42]
  const v: [number, number] = [-30, 96]
  const P = (a: number, b: number): [number, number] =>
    [C[0] + u[0] * a + v[0] * b, C[1] + u[1] * a + v[1] * b]
  const p1 = P(-0.5, -0.5), p2 = P(0.5, -0.5), p3 = P(0.5, 0.5), p4 = P(-0.5, 0.5)
  const nn: [number, number] = [0.28, -0.96]
  return (
    <svg viewBox="60 52 640 410" width="100%" height="100%">
      <polygon points={`${p1[0]},${p1[1]} ${p2[0]},${p2[1]} ${p3[0]},${p3[1]} ${p4[0]},${p4[1]}`}
        fill="#EAF2FA" fillOpacity="0.8" stroke="#1F4E9C" strokeWidth="4" />
      {/* 电流方向 */}
      <Arrow x1={p1[0] + 12} y1={p1[1] + 3} x2={p2[0] + 10} y2={p2[1] - 16} color="#D0021B" w={4.4} />
      <text x={C[0] - 6} y={C[1] - 108} fontSize="27" fontStyle="italic" fontFamily={SERIF}
        fill="#D0021B">I</text>
      {/* 法线 */}
      <Arrow x1={C[0]} y1={C[1]} x2={C[0] + nn[0] * 150} y2={C[1] + nn[1] * 150} color="#12852F" w={5} />
      <text x={C[0] + nn[0] * 164} y={C[1] + nn[1] * 164} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#12852F">n</text>
      {/* 磁矩 */}
      <Arrow x1={C[0]} y1={C[1]} x2={C[0] + nn[0] * 210} y2={C[1] + nn[1] * 210} color="#7B1FA2" w={8} />
      <text x={C[0] + nn[0] * 224 + 8} y={C[1] + nn[1] * 224} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#7B1FA2">p<tspan fontSize="20" dy="7">m</tspan></text>
      {/* 面积标注 */}
      <text x={C[0] + 18} y={C[1] + 40} fontSize="27" fontStyle="italic" fontFamily={SERIF}
        fill="#1F4E9C">S</text>
      <text x="360" y="430" textAnchor="middle" fontSize="28" fontFamily={SERIF} fill="#B00020">
        p_m = I S n
      </text>

    </svg>
  )
}

