/** 7-8 P8：充满介质的螺绕环 —— 环内有介质芯，H 沿同心圆 */
export function ToroidMedium() {
  const cx = 330, cy = 252, R1 = 92, R2 = 150, mid = 121
  const ring = (r: number) =>
    `M ${cx - r} ${cy} a ${r} ${r} 0 1 0 ${2 * r} 0 a ${r} ${r} 0 1 0 ${-2 * r} 0`
  const turn = (deg: number, key: number) => {
    const a = (deg * Math.PI) / 180
    return (
      <line key={key} x1={cx + (R2 + 14) * Math.cos(a)} y1={cy + (R2 + 14) * Math.sin(a)}
        x2={cx + (R1 - 14) * Math.cos(a)} y2={cy + (R1 - 14) * Math.sin(a)}
        stroke="#8A6A3A" strokeWidth="7" strokeLinecap="round" />
    )
  }
  return (
    <svg viewBox="136 36 428 428" width="100%" height="100%">
      <path d={ring(R2) + ' ' + ring(R1)} fillRule="evenodd" fill="#FBEDEA" stroke="#B00020"
        strokeWidth="3" />
      {[10, 70, 130, 190, 250, 310].map((d, i) => turn(d, i))}
      <circle cx={cx} cy={cy} r={mid} fill="none" stroke="#1F6FBF" strokeWidth="3.4"
        strokeDasharray="12 8" />
      <Arrow x1={cx + mid * 0.6} y1={cy - mid * 0.8} x2={cx + mid * 0.86} y2={cy - mid * 0.5}
        color="#1F6FBF" w={4.4} />
      <Arrow x1={cx - mid * 0.6} y1={cy + mid * 0.8} x2={cx - mid * 0.86} y2={cy + mid * 0.5}
        color="#1F6FBF" w={4.4} />
      <text x={cx + 6} y={cy - mid - 12} textAnchor="middle" fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#1F6FBF">H</text>
      <text x={cx + R2 + 10} y={cy - 104} fontSize="24" fontFamily={HEI} fill="#8A6A3A">N 匝</text>
      <text x={cx - 104} y={cy + 58} textAnchor="middle" fontSize="22" fontFamily={HEI}
        fill="#B00020">介质芯</text>
      <line x1={cx} y1={cy} x2={cx + mid * 0.98} y2={cy} stroke="#9AA7B5" strokeWidth="2.4" />
      <text x={cx + 54} y={cy - 12} fontSize="24" fontStyle="italic" fontFamily={SERIF}
        fill="#555">R</text>
      <text x={cx} y="432" textAnchor="middle" fontSize="26" fontFamily={SERIF} fill="#B00020">
        H · 2πR = N I₀
      </text>
    </svg>
  )
}

/* ================= 7-9 铁磁质 ================= */

/** 7-9 P3：磁畴 —— 未磁化时取向杂乱，外场下畴壁移动并转向 */
export function MagDomain() {
  const xs0 = [64, 280, 496]
  const dirs = [
    [0.4, 1.4, 2.5, 3.6, 4.7, 5.6, 0.9, 2.8, 4.2],
    [-1.57, -1.57, 0.9, -1.57, -1.57, 3.1, -1.57, -1.57, 2.5],
    Array(9).fill(-1.57),
  ]
  return (
    <svg viewBox="44 84 648 392" width="100%" height="100%">
      {xs0.map((x0, k) => (
        <g key={k}>
          <rect x={x0} y="136" width="190" height="190" fill="#F4F7FB" stroke="#333"
            strokeWidth="3" />
          {dirs[k].map((a, i) => {
            const x = x0 + 38 + (i % 3) * 57
            const y = 174 + Math.floor(i / 3) * 57
            return <Arrow key={i} x1={x - 26 * Math.cos(a)} y1={y - 26 * Math.sin(a)}
              x2={x + 26 * Math.cos(a)} y2={y + 26 * Math.sin(a)}
              color={k === 0 ? '#8A6A3A' : k === 1 ? '#B00020' : '#D0021B'} w={3.8} />
          })}
        </g>
      ))}
      <text x="159" y="112" textAnchor="middle" fontSize="25" fontFamily={HEI} fill="#8A6A3A">未磁化</text>
      <text x="375" y="112" textAnchor="middle" fontSize="25" fontFamily={HEI} fill="#B00020">磁化中</text>
      <text x="591" y="112" textAnchor="middle" fontSize="25" fontFamily={HEI} fill="#D0021B">饱和</text>
      <text x="159" y="360" textAnchor="middle" fontSize="22" fontFamily={HEI} fill="#333">磁矩互相抵消</text>
      <text x="375" y="360" textAnchor="middle" fontSize="22" fontFamily={HEI} fill="#333">畴壁移动、长大</text>
      <text x="591" y="360" textAnchor="middle" fontSize="22" fontFamily={HEI} fill="#333">全体转向外场</text>
      <text x="159" y="394" textAnchor="middle" fontSize="22" fontFamily={SERIF} fill="#777">M = 0</text>
      <text x="375" y="394" textAnchor="middle" fontSize="22" fontFamily={SERIF} fill="#777">0 &lt; M &lt; M<tspan dy="5" fontSize="15">s</tspan></text>
      <text x="591" y="394" textAnchor="middle" fontSize="22" fontFamily={SERIF} fill="#777">M = M<tspan dy="5" fontSize="15">s</tspan></text>
      <text x="350" y="444" textAnchor="middle" fontSize="24" fontFamily={HEI} fill="#666">
        一个磁畴约 10⁻⁴ m，含 10¹⁵ 个原子
      </text>
    </svg>
  )
}

/** 磁滞回线族：给定 (矫顽力, 剩磁, 饱和值) 画一条闭合回线 */
const hysLoop = (Hc: number, Br: number, Hm: number, Bs: number, cx = 330, cy = 250) => {
  const X = (h: number) => cx + h
  const Y = (b: number) => cy - b
  return `M ${X(Hm)} ${Y(Bs)}
    C ${X(Hm * 0.92)} ${Y(Bs)} ${X(Br * 0.35)} ${Y(Br)} ${X(0)} ${Y(Br)}
    C ${X(-Hc * 0.62)} ${Y(Br)} ${X(-Hc)} ${Y(Br * 0.5)} ${X(-Hc)} ${Y(0)}
    C ${X(-Hc)} ${Y(-Br * 0.5)} ${X(-Hm)} ${Y(-Bs * 0.7)} ${X(-Hm)} ${Y(-Bs)}
    C ${X(-Hm * 0.5)} ${Y(-Bs)} ${X(-Br * 0.35)} ${Y(-Br)} ${X(0)} ${Y(-Br)}
    C ${X(Hc * 0.62)} ${Y(-Br)} ${X(Hc)} ${Y(-Br * 0.5)} ${X(Hc)} ${Y(0)}
    C ${X(Hc)} ${Y(Br * 0.5)} ${X(Hm)} ${Y(Bs * 0.7)} ${X(Hm)} ${Y(Bs)} Z`
}

/** 7-9 P5：磁滞回线 —— 剩磁 Br、矫顽力 Hc、饱和 */
export function Hysteresis() {
  return (
    <svg viewBox="132 58 512 424" width="100%" height="100%">
      <line x1="152" y1="250" x2="520" y2="250" stroke="#333" strokeWidth="2.8" />
      <line x1="330" y1="84" x2="330" y2="414" stroke="#333" strokeWidth="2.8" />
      <text x="528" y="258" fontSize="27" fontStyle="italic" fontFamily={SERIF} fill="#111">H</text>
      <text x="344" y="102" fontSize="27" fontStyle="italic" fontFamily={SERIF} fill="#111">B</text>
      {/* 起始磁化曲线：从原点到饱和点 */}
      <path d="M 330 250 C 374 240 424 176 480 106" fill="none" stroke="#9AA7B5"
        strokeWidth="2.6" strokeDasharray="9 7" />
      <text x="504" y="82" textAnchor="end" fontSize="22" fontFamily={HEI} fill="#777">起始磁化曲线</text>
      {/* 回线 */}
      <path d={hysLoop(70, 122, 150, 146)} fill="none" stroke="#7B1FA2" strokeWidth="4.4" />
      <circle cx="330" cy="128" r="6.5" fill="#B00020" />
      <text x="312" y="122" textAnchor="end" fontSize="25" fontFamily={SERIF} fill="#B00020">B<Sb c="r" /></text>
      <circle cx="260" cy="250" r="6.5" fill="#1F4E9C" />
      <text x="252" y="288" textAnchor="end" fontSize="25" fontFamily={SERIF} fill="#1F4E9C">−H<Sb c="c" /></text>
      <circle cx="400" cy="250" r="6.5" fill="#1F4E9C" />
      <text x="408" y="288" textAnchor="start" fontSize="25" fontFamily={SERIF} fill="#1F4E9C">H<Sb c="c" /></text>
      <text x="352" y="438" textAnchor="middle" fontSize="25" fontFamily={HEI} fill="#333">
        磁滞：B 的变化落后于 H
      </text>
      <text x="352" y="470" textAnchor="middle" fontSize="23" fontFamily={HEI} fill="#666">
        H 回到零时 B 不为零 —— 这就是剩磁
      </text>
    </svg>
  )
}

/** 7-9 P6：软磁与硬磁 —— 两条回线分画在各自的坐标里，直接比胖瘦 */
export function SoftHard() {
  const panel = (cx: number, cy: number, Hc: number, Br: number, color: string, stroke: string) => (
    <g>
      <line x1={cx - 108} y1={cy} x2={cx + 108} y2={cy} stroke="#333" strokeWidth="2.6" />
      <line x1={cx} y1={cy + 104} x2={cx} y2={cy - 104} stroke="#333" strokeWidth="2.6" />
      <text x={cx + 116} y={cy - 8} fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#111">H</text>
      <text x={cx + 8} y={cy - 110} fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#111">B</text>
      <path d={hysLoop(Hc, Br, 96, 92, cx, cy)} fill="none" stroke={color} strokeWidth="4.2"
        opacity={stroke === '#1F4E9C' ? 1 : 0.92} />
    </g>
  )
  return (
    <svg viewBox="56 76 628 396" width="100%" height="100%">
      {panel(190, 268, 18, 68, '#1F4E9C', '#1F4E9C')}
      {panel(510, 268, 72, 84, '#B00020', '#B00020')}
      <text x="190" y="104" textAnchor="middle" fontSize="26" fontFamily={HEI} fill="#1F4E9C">软磁材料</text>
      <text x="510" y="104" textAnchor="middle" fontSize="26" fontFamily={HEI} fill="#B00020">硬磁材料</text>
      <text x="190" y="140" textAnchor="middle" fontSize="22" fontFamily={HEI} fill="#666">回线窄而陡</text>
      <text x="510" y="140" textAnchor="middle" fontSize="22" fontFamily={HEI} fill="#666">回线宽而胖</text>
      <text x="190" y="414" textAnchor="middle" fontSize="23" fontFamily={HEI} fill="#1F4E9C">易磁化、易退磁</text>
      <text x="190" y="446" textAnchor="middle" fontSize="23" fontFamily={HEI} fill="#666">变压器铁芯、电机</text>
      <text x="510" y="414" textAnchor="middle" fontSize="23" fontFamily={HEI} fill="#B00020">剩磁大、矫顽力大</text>
      <text x="510" y="446" textAnchor="middle" fontSize="23" fontFamily={HEI} fill="#666">永磁体、磁记录</text>
    </svg>
  )
}

/* ================= 8-1 电磁感应定律 ================= */

/** 8-1 P3：磁铁插入 / 静止 / 抽出线圈，电流计三种表现 */
export function FaradayCoil() {
  const panel = (px: number, state: number, title: string, sub: string) => {
    const cx = px + 128
    const ang = state === 0 ? 32 : state === 2 ? -32 : 0
    const nx = cx + 22 * Math.sin((ang * Math.PI) / 180)
    const ny = 330 - 22 * Math.cos((ang * Math.PI) / 180)
    return (
      <g key={px}>
        {/* 线圈 */}
        {[0, 1, 2].map(i => (
          <ellipse key={i} cx={cx - 18 + i * 18} cy="196" rx="9" ry="38" fill="none"
            stroke="#1F4E9C" strokeWidth="3.2" />
        ))}
        {/* 引线到电流计 */}
        <line x1={cx - 18} y1="234" x2={cx - 18} y2="306" stroke="#1F4E9C" strokeWidth="2.6" />
        <line x1={cx + 18} y1="234" x2={cx + 18} y2="306" stroke="#1F4E9C" strokeWidth="2.6" />
        <circle cx={cx} cy="330" r="24" fill="#F4F7FB" stroke="#555" strokeWidth="2.6" />
        <line x1={cx} y1="330" x2={nx} y2={ny} stroke={state === 1 ? '#888' : '#D0021B'}
          strokeWidth="3.4" />
        <text x={cx} y="376" textAnchor="middle" fontSize="21" fontFamily={HEI} fill="#555">
          电流计
        </text>
        {/* 磁铁 */}
        <rect x={px + 22} y="180" width="34" height="16" fill="#E8453C" />
        <rect x={px + 22} y="196" width="34" height="16" fill="#2F6DB5" />
        <text x={px + 39} y="194" textAnchor="middle" fontSize="15" fontFamily={SERIF}
          fill="#fff">N</text>
        <text x={px + 39} y="210" textAnchor="middle" fontSize="15" fontFamily={SERIF}
          fill="#fff">S</text>
        {/* 运动方向 */}
        {state !== 1 && (
          <Arrow x1={state === 0 ? px + 18 : px + 62} y1={150}
            x2={state === 0 ? px + 66 : px + 14} y2={150} color="#7B1FA2" w={4} />
        )}
        <text x={px + 100} y="66" textAnchor="middle" fontSize="24" fontFamily={HEI}
          fill="#B00020">{title}</text>
        <text x={px + 100} y="404" textAnchor="middle" fontSize="21" fontFamily={HEI}
          fill="#666">{sub}</text>
      </g>
    )
  }
  return (
    <svg viewBox="0 0 700 424" width="100%" height="100%">
      {panel(6, 0, '插入', '指针偏转')}
      {panel(238, 1, '静止', '指针不动')}
      {panel(470, 2, '抽出', '反向偏转')}
    </svg>
  )
}

/** 8-1 P4：楞次定律 —— 磁铁在下方靠近/远离，线圈轴竖直
 *  靠近：向上的磁通量增大 ⇒ 感应磁场向下；远离 ⇒ 感应磁场向上。
 *  近侧电流方向由右手定则给出：B′ 向上时近侧电流向右，向下时向左。 */
export function LenzRule() {
  const panel = (cx: number, near: boolean) => {
    // B′：靠近时向下，远离时向上
    const yTop = 150, yBot = 300
    const by1 = near ? yTop : yBot
    const by2 = near ? yBot : yTop
    // 近侧电流：B′ 向下 ⇒ 向左（dir=1 即向左）；B′ 向上 ⇒ 向右
    const dir = near ? 1 : -1
    const x0 = cx + 34 * dir
    const x1 = cx - 34 * dir
    const head = dir === 1
      ? `${x1},174 ${x1 - 10},168 ${x1 - 10},180`
      : `${x1},174 ${x1 + 10},168 ${x1 + 10},180`
    return (
      <g key={cx}>
        {/* 线圈：三个水平椭圆（轴竖直） */}
        {[180, 208, 236].map((yy, i) => (
          <ellipse key={i} cx={cx} cy={yy} rx="54" ry="14" fill="none" stroke="#1F4E9C"
            strokeWidth="3.4" />
        ))}
        {/* 近侧感应电流 */}
        <path d={`M ${x0} 174 Q ${cx} ${190} ${x1} 174`} fill="none" stroke="#D0021B"
          strokeWidth="3.6" />
        <polygon points={head} fill="#D0021B" />
        <text x={cx} y="132" textAnchor="middle" fontSize="21" fontFamily={HEI} fill="#B00020">
          感应电流
        </text>
        {/* 感应磁场 */}
        <Arrow x1={cx + 78} y1={by1} x2={cx + 78} y2={by2} color="#7B1FA2" w={4.6} />
        <text x={cx + 92} y={(yTop + yBot) / 2} fontSize="25" fontStyle="italic"
          fontFamily={SERIF} fill="#7B1FA2">B′</text>
        {/* 磁铁（在下方，N 极朝上） */}
        <rect x={cx - 34} y="352" width="68" height="26" fill="#E8453C" />
        <rect x={cx - 34} y="378" width="68" height="26" fill="#2F6DB5" />
        <text x={cx} y="372" textAnchor="middle" fontSize="20" fontFamily={SERIF}
          fill="#fff">N</text>
        <text x={cx} y="398" textAnchor="middle" fontSize="20" fontFamily={SERIF}
          fill="#fff">S</text>
        {/* 运动方向 */}
        <Arrow x1={cx - 78} y1={near ? 386 : 330} x2={cx - 78} y2={near ? 330 : 386}
          color="#12852F" w={4.2} />
        <text x={cx - 94} y={near ? 366 : 356} textAnchor="end" fontSize="21" fontFamily={HEI}
          fill="#12852F">{near ? '靠近' : '远离'}</text>
      </g>
    )
  }
  return (
    <svg viewBox="64 38 600 402" width="100%" height="100%">
      {panel(210, true)}
      {panel(500, false)}
      <text x="210" y="72" textAnchor="middle" fontSize="24" fontFamily={HEI} fill="#B00020">
        磁通量增大 ⇒ B′ 向下
      </text>
      <text x="500" y="72" textAnchor="middle" fontSize="24" fontFamily={HEI} fill="#1F4E9C">
        磁通量减小 ⇒ B′ 向上
      </text>
      <line x1="352" y1="90" x2="352" y2="424" stroke="#DCE5F0" strokeWidth="2.4"
        strokeDasharray="10 8" />
    </svg>
  )
}

/** 8-1 P5：Φ–t 曲线，斜率就是电动势（负号 = 楞次） */
export function FluxCurve() {
  return (
    <svg viewBox="0 0 700 440" width="100%" height="100%">
      <line x1="120" y1="330" x2="620" y2="330" stroke="#333" strokeWidth="2.8" />
      <line x1="120" y1="330" x2="120" y2="74" stroke="#333" strokeWidth="2.8" />
      <text x="630" y="338" fontSize="26" fontStyle="italic" fontFamily={SERIF} fill="#111">t</text>
      <text x="96" y="72" textAnchor="end" fontSize="26" fontFamily={SERIF} fill="#111">Φ</text>
      {/* 三角脉冲 */}
      <path d="M 180 320 L 366 120 L 560 316" fill="none" stroke="#7B1FA2" strokeWidth="5" />
      <circle cx="366" cy="120" r="7" fill="#7B1FA2" />
      <text x="366" y="100" textAnchor="middle" fontSize="21" fontFamily={HEI} fill="#7B1FA2">
        最大
      </text>
      {/* 斜率标注 */}
      <line x1="232" y1="320" x2="300" y2="230" stroke="#D0021B" strokeWidth="2.6"
        strokeDasharray="8 6" />
      <text x="142" y="252" fontSize="22" fontFamily={HEI} fill="#B00020">斜率陡</text>
      <text x="142" y="282" fontSize="22" fontFamily={HEI} fill="#B00020">ε 大</text>
      <line x1="430" y1="200" x2="498" y2="292" stroke="#1F4E9C" strokeWidth="2.6"
        strokeDasharray="8 6" />
      <text x="506" y="192" fontSize="22" fontFamily={HEI} fill="#1F4E9C">斜率反号</text>
      <text x="506" y="222" fontSize="22" fontFamily={HEI} fill="#1F4E9C">ε 反向</text>
      <text x="380" y="386" textAnchor="middle" fontSize="27" fontFamily={SERIF} fill="#333">
        ε = − dΦ / dt
      </text>
      <text x="380" y="418" textAnchor="middle" fontSize="22" fontFamily={HEI} fill="#777">
        负号就是楞次定律：感应电动势反抗磁通量的变化
      </text>
    </svg>
  )
}

/** 8-1 P6：改变 Φ 的三条途径 —— B 变、S 变、θ 变 */
