/** 8-2 P5：绕一端转动的金属棒 —— 各点速度不同，要积分
 *  转动方向画成顺时针（俯视时 ω 向里），v 与转动方向一致，切向。 */
export function RotatingRod() {
  const Ox = 236, Oy = 300, L = 300
  const a = -Math.PI / 6
  const ux = Math.cos(a), uy = Math.sin(a)
  const ex = Ox + L * ux, ey = Oy + L * uy
  const r1 = 190
  const px = Ox + r1 * ux, py = Oy + r1 * uy
  const vx = -uy, vy = ux
  const tipX = px + vx * 92, tipY = py + vy * 92
  // ω 弧的末端与切线方向
  const th = -8 * D2R
  const ex2 = Ox + 78 * Math.cos(th), ey2 = Oy + 78 * Math.sin(th)
  const deg = (Math.atan2(Math.cos(th), -Math.sin(th)) * 180) / Math.PI
  return (
    <svg viewBox="80 46 580 420" width="100%" height="100%">
      {/* 磁场 */}
      {[[200, 130], [300, 130], [400, 130], [500, 150], [220, 250], [300, 400], [420, 420],
        [260, 360], [420, 350]].map((p, i) => (
        <g key={i} opacity="0.45">
          <line x1={p[0] - 7} y1={p[1] - 7} x2={p[0] + 7} y2={p[1] + 7} stroke="#1F4E9C"
            strokeWidth="2.4" />
          <line x1={p[0] + 7} y1={p[1] - 7} x2={p[0] - 7} y2={p[1] + 7} stroke="#1F4E9C"
            strokeWidth="2.4" />
        </g>
      ))}
      {/* 棒 */}
      <line x1={Ox} y1={Oy} x2={ex} y2={ey} stroke="#D0021B" strokeWidth="8" />
      <circle cx={Ox} cy={Oy} r="9" fill="#111" />
      <text x={Ox - 8} y={Oy + 36} fontSize="26" fontStyle="italic" fontFamily={SERIF}
        fill="#111">O</text>
      <text x={(Ox + ex) / 2 + 4} y={(Oy + ey) / 2 - 16} fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#B00020">l</text>
      {/* 转动方向：弧 + 切向箭头 */}
      <ArcLine cx={Ox} cy={Oy} r={78} a0={-78 * D2R} a1={th} color="#7B1FA2" w={3.2} />
      <g transform={`translate(${ex2},${ey2}) rotate(${deg})`}>
        <polygon points="2,0 -13,-7 -13,7" fill="#7B1FA2" />
      </g>
      <text x={Ox + 30} y={Oy - 86} fontSize="26" fontStyle="italic" fontFamily={SERIF}
        fill="#7B1FA2">ω</text>
      {/* 速度 v = ωx */}
      <Arrow x1={px} y1={py} x2={tipX} y2={tipY} color="#12852F" w={4.6} />
      <text x={tipX + 14} y={tipY - 2} fontSize="24" fontStyle="italic" fontFamily={SERIF}
        fill="#12852F">v</text>
      <text x={tipX + 14} y={tipY + 30} fontSize="20" fontFamily={HEI} fill="#12852F">
        v = ωx
      </text>
      <text x="380" y="440" textAnchor="middle" fontSize="25" fontFamily={SERIF} fill="#333">
        ε = ½ B ω l²
      </text>
    </svg>
  )
}

