/** 8-2 P8：涡电流 —— 整块铁芯形成大回路；叠片把回路切断 */
export function EddyCurrent() {
  const loop = (cx: number, cy: number, rx: number, ry: number, key: string) => (
    <g key={key}>
      <ellipse cx={cx} cy={cy} rx={rx} ry={ry} fill="none" stroke="#D0021B" strokeWidth="3" />
      <polygon points={`${cx + (ry > 30 ? 13 : 8)},${cy - ry} ${cx - (ry > 30 ? 2 : 1)},${cy - ry - (ry > 30 ? 8 : 5)} ${cx - (ry > 30 ? 2 : 1)},${cy - ry + (ry > 30 ? 8 : 5)}`}
        fill="#D0021B" />
    </g>
  )
  return (
    <svg viewBox="96 76 540 340" width="100%" height="100%">
      {/* 整块 */}
      <rect x="150" y="150" width="150" height="180" fill="#F0E4DC" stroke="#8A6A3A"
        strokeWidth="3" />
      {loop(225, 240, 54, 74, 'big')}
      <text x="225" y="126" textAnchor="middle" fontSize="23" fontFamily={HEI} fill="#B00020">
        整块铁芯：涡流大
      </text>
      {/* 叠片：四片，片间留缝 */}
      {[0, 1, 2, 3].map(i => (
        <g key={i}>
          <rect x="404" y={150 + i * 45} width="150" height="34" fill="#F0E4DC" stroke="#8A6A3A"
            strokeWidth="2.6" />
          {loop(479, 167 + i * 45, 56, 11, `l${i}`)}
        </g>
      ))}
      <text x="479" y="126" textAnchor="middle" fontSize="23" fontFamily={HEI} fill="#B00020">
        叠片铁芯：涡流小
      </text>
      <text x="368" y="392" textAnchor="middle" fontSize="22" fontFamily={HEI} fill="#666">
        涡流损耗 ∝ 片厚的平方 ⇒ 用薄片叠起来
      </text>
    </svg>
  )
}


