/* ================= 5-8 电偶极子 ================= */

/** 5-8 P3：电偶极子在匀强电场中受力矩 M = p × E */
export function DipoleTorque() {
  const cx = 470, cy = 380
  const th = (-34 * Math.PI) / 180
  const L = 165
  const A: [number, number] = [cx + L * Math.cos(th), cy + L * Math.sin(th)]
  const B: [number, number] = [cx - L * Math.cos(th), cy - L * Math.sin(th)]
  // p 与偶极子轴平行，整体沿轴向下平移一段后画出（避免穿过 +q）
  const ux = Math.cos(th), uy = Math.sin(th)
  const P0: [number, number] = [B[0] - ux * 46 + uy * 96, B[1] - uy * 46 - ux * 96]
  const P1: [number, number] = [P0[0] + ux * 150, P0[1] + uy * 150]
  return (
    <svg viewBox="220 140 660 490" width="100%" height="100%">
      {/* 匀强电场 */}
      {[210, 288, 366, 444, 522].map((y, i) => (
        <Arrow key={i} x1={280} y1={y} x2={830} y2={y} color="#1F6FBF" w={3} />
      ))}
      <text x="844" y="206" fontSize="30" fontStyle="italic" fontFamily={SERIF}
        fill="#1F6FBF">E</text>
      {/* 偶极子 */}
      <line x1={B[0]} y1={B[1]} x2={A[0]} y2={A[1]} stroke="#333" strokeWidth="5" />
      <circle cx={A[0]} cy={A[1]} r="24" fill="#FBFCFE" stroke="#333" strokeWidth="2.6" />
      <line x1={A[0] - 12} y1={A[1]} x2={A[0] + 12} y2={A[1]} stroke="#D0021B" strokeWidth="5" />
      <line x1={A[0]} y1={A[1] - 12} x2={A[0]} y2={A[1] + 12} stroke="#D0021B" strokeWidth="5" />
      <circle cx={B[0]} cy={B[1]} r="24" fill="#FBFCFE" stroke="#333" strokeWidth="2.6" />
      <line x1={B[0] - 12} y1={B[1]} x2={B[0] + 12} y2={B[1]} stroke="#1F4E9C" strokeWidth="5" />
      <text x={A[0] + 30} y={A[1] - 14} fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">+q</text>
      <text x={B[0] - 66} y={B[1] + 20} fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#1F4E9C">−q</text>
      {/* 电偶极矩：与轴平行 */}
      <Arrow x1={P0[0]} y1={P0[1]} x2={P1[0]} y2={P1[1]} color="#7B1FA2" w={5.5} />
      <text x={P1[0] + 10} y={P1[1] - 8} fontSize="30" fontStyle="italic"
        fontFamily={SERIF} fill="#7B1FA2">p</text>
      {/* 一对力：构成力偶 */}
      <Arrow x1={A[0] + 26} y1={A[1]} x2={A[0] + 150} y2={A[1]} color="#D0021B" w={5.5} />
      <Arrow x1={B[0] - 26} y1={B[1]} x2={B[0] - 150} y2={B[1]} color="#1F4E9C" w={5.5} />
      <text x={A[0] + 156} y={A[1] - 6} fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#D0021B">F</text>
      <text x={B[0] - 200} y={B[1] - 6} fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#1F4E9C">F</text>
      {/* 转轴 */}
      <circle cx={cx} cy={cy} r="7" fill="#333" />
      <text x={cx - 8} y={cy + 40} textAnchor="middle" fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#555">O</text>
      {/* θ */}
      <line x1={cx - 210} y1={cy} x2={cx + 250} y2={cy} stroke="#8FA3B8" strokeWidth="2"
        strokeDasharray="9 7" />
      <ArcLine cx={cx} cy={cy} r={112} a0={0} a1={th} color="#12852F" w={3} />
      <text x={cx + 118} y={cy - 32} fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#12852F">θ</text>
    </svg>
  )
}

