/** 6-1 P3：导体内任意两点电势相等，表面也是等势面 */
export function CondEquipot() {
  const board = 'M 300 250 C 420 206 600 214 690 268 C 764 314 758 430 676 480 '
    + 'C 580 540 396 536 312 486 C 240 442 236 296 300 250 Z'
  const A: [number, number] = [430, 372]
  const B: [number, number] = [592, 330]
  return (
    <svg viewBox="230 176 580 424" width="100%" height="100%">
      <path d={board} fill="#E7EDF5" stroke="#333" strokeWidth="3.2" />
      {/* 表面等势线：贴着轮廓的一圈内缩虚线 */}
      <path d={board} fill="none" stroke="#12852F" strokeWidth="2.4"
        strokeDasharray="10 7"
        transform="translate(490 380) scale(0.945) translate(-490 -380)" />
      {/* 内部 E=0 */}
      <text x="490" y="452" textAnchor="middle" fontSize="30" fontFamily={SERIF}
        fill="#12852F">E = 0</text>
      {/* 两点与连线 */}
      <line x1={A[0]} y1={A[1]} x2={B[0]} y2={B[1]} stroke="#D0021B" strokeWidth="2.6"
        strokeDasharray="9 7" />
      <circle cx={A[0]} cy={A[1]} r="7" fill="#111" />
      <circle cx={B[0]} cy={B[1]} r="7" fill="#111" />
      <text x={A[0] - 26} y={A[1] + 8} fontSize="30" fontStyle="italic" fontFamily={SERIF}
        fill="#111">A</text>
      <text x={B[0] + 12} y={B[1] - 6} fontSize="30" fontStyle="italic" fontFamily={SERIF}
        fill="#111">B</text>
      {/* 结论 */}
      <text x="490" y="576" textAnchor="middle" fontSize="32" fontFamily={SERIF}
        fill="#D0021B">V<tspan fontSize="22" dy="7">A</tspan>
        <tspan dy="-7"> = V</tspan><tspan fontSize="22" dy="7">B</tspan></text>
      <text x="490" y="216" textAnchor="middle" fontSize="24" fontFamily={HEI}
        fill="#12852F">表面也是等势面</text>
    </svg>
  )
}

