/** 6-1 P4：表面场强只有法向分量（切向分量被静电平衡「禁止」） */
export function SurfaceNormal() {
  const A: [number, number] = [330, 520]
  const B: [number, number] = [790, 378]
  const u: [number, number] = [B[0] - A[0], B[1] - A[1]]
  const L = Math.hypot(u[0], u[1])
  const tx = u[0] / L, ty = u[1] / L
  const nx = ty, ny = -tx                                   // 外法线：指向左上方
  const P: [number, number] = [A[0] + u[0] * 0.52, A[1] + u[1] * 0.52]
  const at = (k: number, sx: number, sy: number): [number, number] =>
    [P[0] + sx * k, P[1] + sy * k]
  const e0 = at(34, nx, ny), e1 = at(190, nx, ny)
  const n0 = at(34, nx, ny), n1 = at(150, nx, ny)
  const t0 = at(16, tx, ty), t1 = at(165, tx, ty)
  const cx0 = P[0] + tx * 100 + nx * 44, cy0 = P[1] + ty * 100 + ny * 44
  const ax = tx * 24, ay = ty * 24, bx = nx * 24, by = ny * 24
  return (
    <svg viewBox="278 214 588 434" width="100%" height="100%">
      <polygon points={`${A[0]},${A[1]} ${B[0]},${B[1]} ${B[0]},${B[1] + 120} ${A[0]},${A[1] + 120}`}
        fill="#E7EDF5" />
      <line x1={A[0]} y1={A[1]} x2={B[0]} y2={B[1]} stroke="#333" strokeWidth="4" />
      {/* 表面电荷 */}
      {[0.08, 0.22, 0.36, 0.5, 0.64, 0.78, 0.92].map((t, i) => (
        <text key={i} x={A[0] + u[0] * t + nx * 24} y={A[1] + u[1] * t + ny * 24 + 9}
          textAnchor="middle" fontSize="24" fontFamily={SERIF} fill="#D0021B">+</text>
      ))}
      {/* 法向场强 E */}
      <Arrow x1={e0[0]} y1={e0[1]} x2={e1[0]} y2={e1[1]} color="#1F6FBF" w={6.5} />
      <text x={e1[0] - 42} y={e1[1] - 6} fontSize="32" fontStyle="italic"
        fontFamily={SERIF} fill="#1F6FBF">E</text>
      {/* 外法线 n（与 E 平行，靠右） */}
      <line x1={n0[0] + tx * 46} y1={n0[1] + ty * 46} x2={n1[0] + tx * 46}
        y2={n1[1] + ty * 46} stroke="#12852F" strokeWidth="2.6" strokeDasharray="9 7" />
      <text x={n1[0] + tx * 54} y={n1[1] + ty * 54 + 8} fontSize="27" fontStyle="italic"
        fontFamily={SERIF} fill="#12852F">n</text>
      {/* 假设的切向分量 E_t（沿表面） */}
      <Arrow x1={t0[0]} y1={t0[1]} x2={t1[0]} y2={t1[1]} color="#E07A00" w={5.5} dashed />
      <text x={t1[0] + 12} y={t1[1] + 4} fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#E07A00">E</text>
      <text x={t1[0] + 30} y={t1[1] + 10} fontSize="18" fontFamily={SERIF}
        fill="#E07A00">t</text>
      {/* 打叉 */}
      <g stroke="#D0021B" strokeWidth="6" strokeLinecap="round">
        <line x1={cx0 - ax - bx} y1={cy0 - ay - by} x2={cx0 + ax + bx} y2={cy0 + ay + by} />
        <line x1={cx0 - ax + bx} y1={cy0 - ay + by} x2={cx0 + ax - bx} y2={cy0 + ay - by} />
      </g>
      <text x="344" y="612" fontSize="26" fontFamily={HEI} fill="#555">导体</text>
    </svg>
  )
}

/** 6-1 P6：尖端处电荷密、场线密 ⇒ 尖端放电 */
export function SharpTip() {
  // 右侧带尖端的导体轮廓
  const body = 'M 300 300 L 560 300 C 640 300 700 330 742 382 C 700 432 640 462 560 462 L 300 462 Z'
  const tip: [number, number] = [742, 381]
  return (
    <svg viewBox="250 170 640 420" width="100%" height="100%">
      <path d={body} fill="#E7EDF5" stroke="#333" strokeWidth="3.2" />
      {/* 电荷：左侧稀疏、尖端密集（沿二次贝塞尔轮廓取点） */}
      {[340, 400, 460, 520].map((x, i) => (
        <text key={`s${i}`} x={x} y={286} textAnchor="middle" fontSize="26"
          fontFamily={SERIF} fill="#D0021B">+</text>
      ))}
      {[0, 0.22, 0.42, 0.58, 0.7, 0.8, 0.88, 0.94].map((t, i) => {
        const bx = (1 - t) * (1 - t) * 560 + 2 * (1 - t) * t * 700 + t * t * 742
        const by = (1 - t) * (1 - t) * 300 + 2 * (1 - t) * t * 315 + t * t * 382
        const nx = 2 * (1 - t) * 56 + 2 * t * 42
        const ny = 2 * (1 - t) * 15 + 2 * t * 67
        const nl = Math.hypot(nx, ny)
        return <text key={`c${i}`} x={bx + nx / nl * 26} y={by + ny / nl * 26 + 8}
          textAnchor="middle" fontSize="26" fontFamily={SERIF} fill="#D0021B">+</text>
      })}
      {/* 场线：尖端最密 */}
      {[-0.5, -0.3, -0.12, 0.05, 0.2, 0.34, 0.46].map((k, i) => {
        const ang = k * Math.PI / 2
        const r0 = 18, r1 = 130
        const sx = tip[0] + r0 * Math.cos(ang), sy = tip[1] + r0 * Math.sin(ang)
        return <Arrow key={i} x1={sx} y1={sy} x2={tip[0] + r1 * Math.cos(ang)}
          y2={tip[1] + r1 * Math.sin(ang)} color="#1F6FBF" w={3.4} />
      })}
      {/* 平缓处：两条稀场线 */}
      {[360, 470].map((x, i) => (
        <Arrow key={`f${i}`} x1={x} y1={286} x2={x} y2={200} color="#1F6FBF" w={3.4} />
      ))}
      <text x="352" y="188" fontSize="24" fontFamily={HEI} fill="#555">疏</text>
      <text x="694" y="244" fontSize="25" fontFamily={HEI} fill="#D0021B">密</text>
    </svg>
  )
}

