/** 6-4 P4：平行板电容器（板间匀强场，标 S、d） */
export function CapParallel() {
  const L = 400, R = 660, y0 = 250, y1 = 560
  return (
    <svg viewBox="310 160 480 500" width="100%" height="100%">
      <rect x={L - 14} y={y0} width="14" height={y1 - y0} fill="#C62828" />
      <rect x={R} y={y0} width="14" height={y1 - y0} fill="#1F4E9C" />
      {/* 电荷 */}
      {[290, 340, 390, 440, 490, 540].map((y, i) => (
        <text key={`p${i}`} x={L - 30} y={y} textAnchor="middle" fontSize="26"
          fontFamily={SERIF} fill="#C62828">+</text>
      ))}
      {[290, 340, 390, 440, 490, 540].map((y, i) => (
        <text key={`n${i}`} x={R + 32} y={y} textAnchor="middle" fontSize="26"
          fontFamily={SERIF} fill="#1F4E9C">−</text>
      ))}
      {/* 场线 */}
      {[300, 355, 410, 465, 520].map((y, i) => (
        <Arrow key={`f${i}`} x1={L + 26} y1={y} x2={R - 24} y2={y} color="#1F6FBF" w={3.2} />
      ))}
      {/* 间距 d */}
      <line x1={L + 30} y1={y1 + 62} x2={R - 30} y2={y1 + 62} stroke="#12852F"
        strokeWidth="2.4" />
      <polygon points={`${L + 30},${y1 + 62} ${L + 52},${y1 + 55} ${L + 52},${y1 + 69}`}
        fill="#12852F" />
      <polygon points={`${R - 30},${y1 + 62} ${R - 52},${y1 + 55} ${R - 52},${y1 + 69}`}
        fill="#12852F" />
      <text x={(L + R) / 2} y={y1 + 92} textAnchor="middle" fontSize="30"
        fontStyle="italic" fontFamily={SERIF} fill="#12852F">d</text>
      {/* 极板标注 */}
      <text x={L - 14} y={y1 - 18} textAnchor="end" fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#C62828">+Q</text>
      <text x={R + 22} y={y1 - 18} fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#1F4E9C">−Q</text>
      <text x={(L + R) / 2} y={y0 - 24} textAnchor="middle" fontSize="26" fontFamily={HEI}
        fill="#555">面积 S</text>
    </svg>
  )
}

/** 6-4 P5：圆柱形（同轴）电容器 */
export function CapCyl() {
  const cx = 500, cy = 380, R1 = 92, R2 = 186
  return (
    <svg viewBox="270 170 500 440" width="100%" height="100%">
      <circle cx={cx} cy={cy} r={R2} fill="#E7EDF5" stroke="#333" strokeWidth="3" />
      <circle cx={cx} cy={cy} r={R1} fill="#FBFCFE" stroke="#333" strokeWidth="3" />
      {/* 内导体上的正电荷、外导体上的负电荷 */}
      {Array.from({ length: 8 }).map((_, i) => {
        const a = (i * 2 * Math.PI) / 8 + 0.3
        return <circle key={`p${i}`} cx={cx + (R1 - 14) * Math.cos(a)}
          cy={cy + (R1 - 14) * Math.sin(a)} r="6" fill="#C62828" />
      })}
      {Array.from({ length: 12 }).map((_, i) => {
        const a = (i * 2 * Math.PI) / 12
        return <circle key={`n${i}`} cx={cx + (R2 - 13) * Math.cos(a)}
          cy={cy + (R2 - 13) * Math.sin(a)} r="6" fill="#1F4E9C" />
      })}
      {/* 径向场线 */}
      {Array.from({ length: 8 }).map((_, i) => {
        const a = (i * 2 * Math.PI) / 8 + 0.1
        return <Arrow key={`f${i}`} x1={cx + (R1 + 14) * Math.cos(a)}
          y1={cy + (R1 + 14) * Math.sin(a)} x2={cx + (R2 - 18) * Math.cos(a)}
          y2={cy + (R2 - 18) * Math.sin(a)} color="#1F6FBF" w={3.2} />
      })}
      {/* R₁ 沿水平方向，R₂ 沿右下 34° 方向 */}
      <line x1={cx} y1={cy} x2={cx + R1 * Math.cos(-0.6)} y2={cy + R1 * Math.sin(-0.6)}
        stroke="#12852F" strokeWidth="2.4" />
      <text x={cx + R1 * 0.55 * Math.cos(-0.6) - 4}
        y={cy + R1 * 0.55 * Math.sin(-0.6) - 12} textAnchor="middle" fontSize="27"
        fontStyle="italic" fontFamily={SERIF} fill="#12852F">R₁</text>
      <line x1={cx} y1={cy} x2={cx + R2 * Math.cos(0.62)} y2={cy + R2 * Math.sin(0.62)}
        stroke="#12852F" strokeWidth="2.4" />
      <text x={cx + R2 * 0.72 * Math.cos(0.62) + 6}
        y={cy + R2 * 0.72 * Math.sin(0.62) + 18} textAnchor="middle" fontSize="27"
        fontStyle="italic" fontFamily={SERIF} fill="#12852F">R₂</text>
    </svg>
  )
}

