/* ================= 5-8 电偶极子（补充） ================= */

/** 5-8 P4：势能随取向变化 W = −pE cosθ */
export function DipoleEnergy() {
  const x0 = 320, x1 = 800, yMid = 380, amp = 132
  const pts: string[] = []
  for (let i = 0; i <= 40; i++) {
    const t = (i / 40) * Math.PI                     // 0..π
    const x = x0 + ((x1 - x0) * i) / 40
    const y = yMid + amp * Math.cos(t)
    pts.push(`${x.toFixed(1)},${y.toFixed(1)}`)
  }
  const mark = (deg: number, tag: string, dy: number) => {
    const t = (deg * Math.PI) / 180
    const x = x0 + ((x1 - x0) * deg) / 180
    const y = yMid + amp * Math.cos(t)
    return (
      <g key={tag}>
        <circle cx={x} cy={y} r="8" fill="#C62828" />
        <text x={x} y={y + dy} textAnchor="middle" fontSize="26" fontFamily={SERIF}
          fill="#C62828">{tag}</text>
      </g>
    )
  }
  return (
    <svg viewBox="250 170 640 460" width="100%" height="100%">
      {/* 坐标轴 */}
      <line x1={x0 - 30} y1={yMid} x2={x1 + 40} y2={yMid} stroke="#333" strokeWidth="2.4" />
      <polygon points={`${x1 + 48},${yMid} ${x1 + 26},${yMid - 8} ${x1 + 26},${yMid + 8}`}
        fill="#333" />
      <line x1={x0} y1={yMid + amp + 40} x2={x0} y2={yMid - amp - 40} stroke="#333"
        strokeWidth="2.4" />
      <polygon points={`${x0},${yMid - amp - 50} ${x0 - 8},${yMid - amp - 28} ${x0 + 8},${yMid - amp - 28}`}
        fill="#333" />
      <text x={x1 + 44} y={yMid + 34} fontSize="26" fontStyle="italic" fontFamily={SERIF}
        fill="#111">θ</text>
      <text x={x0 - 22} y={yMid - amp - 56} textAnchor="end" fontSize="26"
        fontStyle="italic" fontFamily={SERIF} fill="#111">W</text>
      {/* θ 刻度 */}
      {[0, 90, 180].map((d, i) => {
        const x = x0 + ((x1 - x0) * d) / 180
        return <text key={i} x={x} y={yMid + 34} textAnchor="middle" fontSize="24"
          fontFamily={SERIF} fill="#555">{d === 0 ? '0' : d === 90 ? '90°' : '180°'}</text>
      })}
      {/* 曲线 */}
      <polyline points={pts.join(' ')} fill="none" stroke="#1F6FBF" strokeWidth="3.6" />
      {/* 三个特殊点 */}
      {mark(0, '−pE', -18)}
      {mark(90, '0', -18)}
      {mark(180, '+pE', -18)}
      <text x={(x0 + x1) / 2} y={yMid + amp + 88} textAnchor="middle" fontSize="24"
        fontFamily={HEI} fill="#555">W = −pE cosθ</text>
    </svg>
  )
}

/** 5-8 P2：匀强场中一对反向力构成力偶（两力平行反向、不共线） */
export function DipolePair() {
  const cx = 540, cy = 396
  const L = 158
  const th = (-38 * Math.PI) / 180
  const A: [number, number] = [cx + L * Math.cos(th), cy + L * Math.sin(th)]   // +q
  const B: [number, number] = [cx - L * Math.cos(th), cy - L * Math.sin(th)]   // −q
  const F = 148
  return (
    <svg viewBox="250 180 640 460" width="100%" height="100%">
      {/* 匀强场：四条等间距水平场线（背景，淡） */}
      {[250, 360, 470, 580].map((y, i) => (
        <line key={i} x1="300" y1={y} x2="820" y2={y} stroke="#B9D0E6" strokeWidth="2.2" />
      ))}
      <Arrow x1={760} y1={580} x2={836} y2={580} color="#8FB6DA" w={2.6} />
      <text x="844" y="590" fontSize="30" fontStyle="italic" fontFamily={SERIF}
        fill="#1F6FBF">E</text>
      {/* 偶极子 */}
      <line x1={B[0]} y1={B[1]} x2={A[0]} y2={A[1]} stroke="#333" strokeWidth="5" />
      <circle cx={A[0]} cy={A[1]} r="22" fill="#FBFCFE" stroke="#C62828" strokeWidth="2.6" />
      <line x1={A[0] - 10} y1={A[1]} x2={A[0] + 10} y2={A[1]} stroke="#C62828" strokeWidth="5" />
      <line x1={A[0]} y1={A[1] - 10} x2={A[0]} y2={A[1] + 10} stroke="#C62828" strokeWidth="5" />
      <circle cx={B[0]} cy={B[1]} r="22" fill="#FBFCFE" stroke="#1F4E9C" strokeWidth="2.6" />
      <line x1={B[0] - 10} y1={B[1]} x2={B[0] + 10} y2={B[1]} stroke="#1F4E9C" strokeWidth="5" />
      <text x={A[0] + 26} y={A[1] - 14} fontSize="26" fontStyle="italic" fontFamily={SERIF}
        fill="#C62828">+q</text>
      <text x={B[0] - 56} y={B[1] + 24} fontSize="26" fontStyle="italic" fontFamily={SERIF}
        fill="#1F4E9C">−q</text>
      {/* 一对力：平行、反向、不共线 */}
      <Arrow x1={A[0] + 22} y1={A[1]} x2={A[0] + 22 + F} y2={A[1]} color="#C62828" w={6} />
      <Arrow x1={B[0] - 22} y1={B[1]} x2={B[0] - 22 - F} y2={B[1]} color="#1F4E9C" w={6} />
      <text x={A[0] + 22 + F / 2 - 8} y={A[1] - 14} textAnchor="middle" fontSize="26"
        fontStyle="italic" fontFamily={SERIF} fill="#C62828">F</text>
      <text x={B[0] - 22 - F / 2 + 8} y={B[1] - 14} textAnchor="middle" fontSize="26"
        fontStyle="italic" fontFamily={SERIF} fill="#1F4E9C">F</text>
      {/* 两力作用线之间的垂距（力臂） */}
      <line x1={B[0] - 22 - F + 16} y1={B[1]} x2={A[0] + 22 + F - 16} y2={B[1]}
        stroke="#12852F" strokeWidth="1.8" strokeDasharray="7 6" />
      <line x1={B[0] - 22 - F + 16} y1={A[1]} x2={A[0] + 22 + F - 16} y2={A[1]}
        stroke="#12852F" strokeWidth="1.8" strokeDasharray="7 6" />
      <line x1={B[0] - 30} y1={B[1]} x2={B[0] - 30} y2={A[1]} stroke="#12852F"
        strokeWidth="2.4" />
      <polygon points={`${B[0] - 30},${B[1]} ${B[0] - 37},${B[1] - 18} ${B[0] - 23},${B[1] - 18}`}
        fill="#12852F" />
      <polygon points={`${B[0] - 30},${A[1]} ${B[0] - 37},${A[1] + 18} ${B[0] - 23},${A[1] + 18}`}
        fill="#12852F" />
      <text x={B[0] - 42} y={(A[1] + B[1]) / 2 + 8} textAnchor="end" fontSize="25"
        fontStyle="italic" fontFamily={SERIF} fill="#12852F">l sinθ</text>
      {/* θ：p 与 E 的夹角 */}
      <ArcLine cx={cx} cy={cy} r={92} a0={0} a1={th} color="#7B1FA2" w={3.2} />
      <text x={cx + 100} y={cy - 30} fontSize="27" fontStyle="italic"
        fontFamily={SERIF} fill="#7B1FA2">θ</text>
      <circle cx={cx} cy={cy} r="6" fill="#333" />
    </svg>
  )
}

/** 5-8 P6：非均匀场中两力不等 ⇒ 净力指向强场区 */
export function DipoleNonuniform() {
  // 场线水平，右端向中线收拢 ⇒ 右端明显更密（场更强）
  const ys0 = [200, 262, 324, 386, 448, 510, 572]
  const mid = 386
  const xs = 300, xe = 760
  const A: [number, number] = [612, 386]        // +q（靠强场）
  const B: [number, number] = [462, 386]        // −q
  return (
    <svg viewBox="250 160 640 480" width="100%" height="100%">
      {ys0.map((y, i) => {
        const yEnd = mid + (y - mid) * 0.34
        return (
          <g key={i}>
            <path d={`M ${xs} ${y} C 460 ${y} 620 ${y} 700 ${y} L ${xe} ${yEnd}`}
              fill="none" stroke="#B9D0E6" strokeWidth="2.4" />
          </g>
        )
      })}
      {/* 方向箭头：最上一条 */}
      <Arrow x1={708} y1={386} x2={782} y2={386} color="#8FB6DA" w={3} />
      <text x="790" y="396" fontSize="28" fontStyle="italic" fontFamily={SERIF}
        fill="#1F6FBF">E</text>
      <text x="296" y="182" fontSize="25" fontFamily={HEI} fill="#555">场弱</text>
      <text x="686" y="182" fontSize="25" fontFamily={HEI} fill="#D0021B">场强</text>
      {/* 偶极子：p 与 E 同向（水平） */}
      <line x1={B[0]} y1={B[1]} x2={A[0]} y2={A[1]} stroke="#333" strokeWidth="5" />
      <circle cx={A[0]} cy={A[1]} r="21" fill="#FBFCFE" stroke="#C62828" strokeWidth="2.6" />
      <line x1={A[0] - 9} y1={A[1]} x2={A[0] + 9} y2={A[1]} stroke="#C62828" strokeWidth="5" />
      <line x1={A[0]} y1={A[1] - 9} x2={A[0]} y2={A[1] + 9} stroke="#C62828" strokeWidth="5" />
      <circle cx={B[0]} cy={B[1]} r="21" fill="#FBFCFE" stroke="#1F4E9C" strokeWidth="2.6" />
      <line x1={B[0] - 9} y1={B[1]} x2={B[0] + 9} y2={B[1]} stroke="#1F4E9C" strokeWidth="5" />
      <text x={A[0]} y={A[1] - 34} textAnchor="middle" fontSize="24"
        fontStyle="italic" fontFamily={SERIF} fill="#C62828">+q</text>
      <text x={B[0]} y={B[1] - 34} textAnchor="middle" fontSize="24"
        fontStyle="italic" fontFamily={SERIF} fill="#1F4E9C">−q</text>
      {/* 两力：+q 处大、−q 处小 */}
      <Arrow x1={A[0] + 22} y1={A[1]} x2={A[0] + 22 + 108} y2={A[1]} color="#C62828" w={6} />
      <text x={A[0] + 22 + 62} y={A[1] - 14} textAnchor="middle" fontSize="24"
        fontStyle="italic" fontFamily={SERIF} fill="#C62828">F₊</text>
      <Arrow x1={B[0] - 22} y1={B[1]} x2={B[0] - 22 - 66} y2={B[1]} color="#1F4E9C" w={6} />
      <text x={B[0] - 22 - 40} y={B[1] - 14} textAnchor="middle" fontSize="24"
        fontStyle="italic" fontFamily={SERIF} fill="#1F4E9C">F₋</text>
      {/* 合力 */}
      <Arrow x1={520} y1={486} x2={628} y2={486} color="#7B1FA2" w={6.5} />
      <text x="640" y="496" fontSize="28" fontStyle="italic" fontFamily={SERIF}
        fill="#7B1FA2">F</text>
      <text x="520" y="524" textAnchor="middle" fontSize="23" fontFamily={HEI}
        fill="#7B1FA2">合力指向强场区</text>
    </svg>
  )
}

/** 5-7 P4：沿等势面移动不做功（E ⟂ 位移） */
export function EquipotWork() {
  const O: [number, number] = [470, 372]
  const R = 176
  const a0 = -0.62, a1 = 0.62
  const A: [number, number] = [O[0] + R * Math.cos(a0), O[1] + R * Math.sin(a0)]
  const B: [number, number] = [O[0] + R * Math.cos(a1), O[1] + R * Math.sin(a1)]
  return (
    <svg viewBox="240 150 660 470" width="100%" height="100%">
      {/* 等势面 */}
      {[86, 132, 176, 220].map((r, i) => (
        <circle key={i} cx={O[0]} cy={O[1]} r={r} fill="none" stroke="#12852F"
          strokeWidth="2.2" strokeDasharray="9 7" />
      ))}
      {/* 场源 */}
      <circle cx={O[0]} cy={O[1]} r="26" fill="#FBFCFE" stroke="#333" strokeWidth="3" />
      <line x1={O[0] - 13} y1={O[1]} x2={O[0] + 13} y2={O[1]} stroke="#D0021B" strokeWidth="5" />
      <line x1={O[0]} y1={O[1] - 13} x2={O[0]} y2={O[1] + 13} stroke="#D0021B" strokeWidth="5" />
      {/* 沿等势面从 A 到 B */}
      <ArcArrow cx={O[0]} cy={O[1]} r={R} a0={a0} a1={a1} color="#1F6FBF" w={5} />
      <circle cx={A[0]} cy={A[1]} r="8" fill="#111" />
      <circle cx={B[0]} cy={B[1]} r="8" fill="#111" />
      <text x={A[0] - 30} y={A[1] - 6} fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#111">A</text>
      <text x={B[0] + 12} y={B[1] - 6} fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#111">B</text>
      {/* 一点处的 E：沿半径向外，与位移垂直 */}
      <Arrow x1={O[0]} y1={O[1]} x2={O[0] + R * Math.cos(0.08)} y2={O[1] + R * Math.sin(0.08)}
        color="#1F6FBF" w={4.5} dashed />
      <text x={O[0] + 118} y={O[1] + 16} fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#1F6FBF">E</text>
      {/* 直角标记 */}
      <line x1={O[0] + 150} y1={O[1] + 4} x2={O[0] + 156} y2={O[1] + 22} stroke="#555"
        strokeWidth="2.2" />
      <text x={O[0] + 214} y={O[1] + 40} fontSize="25" fontFamily={HEI} fill="#555">E ⟂ 位移</text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 8-3 P3：自感现象演示电路 —— 纯电阻支路（R + A₁）与含线圈支路（L + A₂）并联。
 *  电池上端为正 ⇒ 闭合开关后外电路电流自正极流出、上母线向右、两支路向下、下母线向左。
 *  电流方向用小三角（不占位），箭头长度与线宽无关，避免 Arrow 的 26px 箭头在小段导线上只剩三角。 */
export function SelfInductExp() {
  const xB = 58, xN1 = 292, xN2 = 524, yT = 70, yB = 322
  const cur = (x: number, y: number, dx: number, dy: number, key: string) => (
    <g key={key} transform={`translate(${x},${y}) rotate(${(Math.atan2(dy, dx) * 180) / Math.PI})`}>
      <polygon points="0,0 -15,-6.5 -15,6.5" fill="#7B1FA2" />
    </g>
  )
  const bulb = (cx: number, cy: number, r: number, key: string) => (
    <g key={key}>
      <circle cx={cx} cy={cy} r={r} fill="#FFFDF2" stroke="#333" strokeWidth="3" />
      <line x1={cx - r * 0.6} y1={cy - r * 0.6} x2={cx + r * 0.6} y2={cy + r * 0.6}
        stroke="#333" strokeWidth="2.6" />
      <line x1={cx + r * 0.6} y1={cy - r * 0.6} x2={cx - r * 0.6} y2={cy + r * 0.6}
        stroke="#333" strokeWidth="2.6" />
    </g>
  )
  return (
    <svg viewBox="0 0 620 381" width="100%" height="100%">
      {/* 电池（上端为长线、正极） */}
      <line x1={xB} y1={yT} x2={xB} y2="188" stroke="#333" strokeWidth="4" />
      <line x1={xB} y1="206" x2={xB} y2={yB} stroke="#333" strokeWidth="4" />
      <line x1={xB - 19} y1="188" x2={xB + 19} y2="188" stroke="#333" strokeWidth="5" />
      <line x1={xB - 10} y1="206" x2={xB + 10} y2="206" stroke="#333" strokeWidth="5" />
      <text x="88" y="203" fontSize="26" fontStyle="italic" fontFamily={SERIF} fill="#333">ε</text>

      {/* 上、下母线 */}
      <line x1={xB} y1={yT} x2={xN2} y2={yT} stroke="#333" strokeWidth="4" />
      <line x1={xB} y1={yB} x2={xN2} y2={yB} stroke="#333" strokeWidth="4" />

      {/* 开关（断开位置，斜向上） */}
      <circle cx="130" cy={yT} r="5" fill="#333" />
      <circle cx="200" cy={yT} r="5" fill="#333" />
      <line x1="134" y1={yT - 1} x2="196" y2="40" stroke="#333" strokeWidth="4" />
      <text x="168" y="30" textAnchor="middle" fontSize="23" fontFamily={HEI} fill="#333">S</text>

      {/* 支路 1：R + A₁ */}
      <line x1={xN1} y1={yT} x2={xN1} y2="100" stroke="#333" strokeWidth="4" />
      <line x1={xN1} y1="152" x2={xN1} y2="204" stroke="#333" strokeWidth="4" />
      <line x1={xN1} y1="260" x2={xN1} y2={yB} stroke="#333" strokeWidth="4" />
      <rect x="276" y="100" width="32" height="52" fill="#FFFFFF" stroke="#333" strokeWidth="3" />
      {bulb(xN1, 232, 28, 'a1')}
      <text x="330" y="241" fontSize="24" fontFamily={HEI} fill="#B00020">A₁</text>
      <text x="262" y="127" textAnchor="end" fontSize="26" fontStyle="italic" fontFamily={SERIF}
        fill="#1F4E9C">R</text>

      {/* 支路 2：L + A₂ */}
      <line x1={xN2} y1={yT} x2={xN2} y2="104" stroke="#333" strokeWidth="4" />
      <line x1={xN2} y1="176" x2={xN2} y2="218" stroke="#333" strokeWidth="4" />
      <line x1={xN2} y1="274" x2={xN2} y2={yB} stroke="#333" strokeWidth="4" />
      <path d={`M ${xN2} 104 a 12 12 0 0 1 0 24 a 12 12 0 0 1 0 24 a 12 12 0 0 1 0 24`}
        fill="none" stroke="#8A6A3A" strokeWidth="4.4" />
      <line x1="542" y1="100" x2="542" y2="180" stroke="#9AA7B5" strokeWidth="3" />
      <line x1="549" y1="100" x2="549" y2="180" stroke="#9AA7B5" strokeWidth="3" />
      {bulb(xN2, 246, 28, 'a2')}
      <text x="562" y="255" fontSize="24" fontFamily={HEI} fill="#B00020">A₂</text>
      <text x="498" y="146" textAnchor="end" fontSize="26" fontStyle="italic" fontFamily={SERIF}
        fill="#1F4E9C">L</text>

      {/* 电流方向（闭合开关瞬间） */}
      {cur(346, yT, 1, 0, 'c1')}
      {cur(xN1, 298, 0, 1, 'c2')}
      {cur(xN2, 196, 0, 1, 'c3')}
      {cur(456, yB, -1, 0, 'c4')}
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 8-3 P4：自感电动势的方向 —— 阻碍电流变化。
 *  左：i 增大（di/dt>0）⇒ ε_L 与 i 反向；右：i 减小 ⇒ ε_L 与 i 同向。
 *  i 画在导线左侧、ε_L 画在右侧，两者平行，方向关系一眼可读。 */
export function SelfEmfSign() {
  const yA = 206, yB = 276
  const grp = (x: number, iUp: boolean, key: string) => (
    <g key={key}>
      <line x1={x} y1="70" x2={x} y2="300" stroke="#555" strokeWidth="4" />
      <path d={`M ${x} 112 a 12 12 0 0 1 0 24 a 12 12 0 0 1 0 24 a 12 12 0 0 1 0 24`}
        fill="none" stroke="#8A6A3A" strokeWidth="4.4" />
      <Arrow x1={x - 34} y1={iUp ? yB : yA} x2={x - 34} y2={iUp ? yA : yB}
        color="#7B1FA2" w={5} />
      <text x={x - 46} y={yA + 34} textAnchor="end" fontSize="27"
        fontStyle="italic" fontFamily={SERIF} fill="#7B1FA2">i</text>
      <Arrow x1={x + 50} y1={yA} x2={x + 50} y2={yB} color="#C00000" w={5} />
      <text x={x + 64} y={yA + 38} fontSize="25" fontStyle="italic" fontFamily={SERIF}
        fill="#C00000">ε<tspan dy="6" fontSize="17">L</tspan></text>
      <text x={x} y="326" textAnchor="middle" fontSize="25" fontFamily={HEI} fill="#333">
        <tspan fontStyle="italic" fontFamily={SERIF}>i</tspan>{iUp ? ' 增大' : ' 减小'}
      </text>
      <text x={x} y="354" textAnchor="middle" fontSize="22" fontFamily={HEI} fill="#777">
        {iUp ? '与 i 反向' : '与 i 同向'}
      </text>
    </g>
  )
  return (
    <svg viewBox="0 0 600 369" width="100%" height="100%">
      {grp(150, true, 'g1')}
      {grp(450, false, 'g2')}
      <line x1="300" y1="60" x2="300" y2="368" stroke="#DCE5F0" strokeWidth="2.4"
        strokeDasharray="9 8" />
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 8-3 P5：长直螺线管的自感 —— 侧视示意。
 *  绕线用参数方程生成的正弦曲线（透视螺旋），内部三条磁力线表示均匀磁场 B=μ₀ni。
 *  下方尺寸线标长度 l，右侧圆标截面 S。 */
export function SolenoidSelf() {
  const x0 = 100, x1 = 470, cy = 170, R = 50, N = 9, M = 252
  const pts: string[] = []
  for (let i = 0; i <= M; i++) {
    const th = (i / M) * 2 * Math.PI * N
    const x = x0 + ((x1 - x0) * i) / M
    pts.push(`${x.toFixed(1)},${(cy - R * Math.cos(th)).toFixed(1)}`)
  }
  const flux = (y: number, key: string) => (
    <g key={key}>
      <polyline points={`${x0 + 26},${y} ${x1 - 26},${y}`} fill="none" stroke="#1F4E9C"
        strokeWidth="2.6" opacity="0.75" />
      <polygon points={`${x1 - 40},${y - 6} ${x1 - 26},${y} ${x1 - 40},${y + 6}`}
        fill="#1F4E9C" opacity="0.75" />
    </g>
  )
  return (
    <svg viewBox="0 0 640 393" width="100%" height="100%">
      {/* 端面 */}
      <ellipse cx={x0} cy={cy} rx="10" ry={R} fill="none" stroke="#9AA7B5" strokeWidth="2.6" />
      <ellipse cx={x1} cy={cy} rx="10" ry={R} fill="none" stroke="#9AA7B5" strokeWidth="2.6" />
      {/* 内部磁场 */}
      {flux(cy - 28, 'f1')}
      {flux(cy, 'f2')}
      {flux(cy + 28, 'f3')}
      <text x="300" y={cy + 7} textAnchor="middle" fontSize="25" fontStyle="italic"
        fontFamily={SERIF} fill="#1F4E9C" stroke="#FFFFFF" strokeWidth="7"
        paintOrder="stroke">B</text>
      {/* 绕线 */}
      <polyline points={pts.join(' ')} fill="none" stroke="#8A6A3A" strokeWidth="3.6"
        strokeLinejoin="round" />
      <text x="285" y="94" textAnchor="middle" fontSize="21" fontFamily={HEI} fill="#555">
        共 N 匝，n = N / l
      </text>
      {/* 长度尺寸线 */}
      <line x1={x0} y1="292" x2={x0} y2="316" stroke="#666" strokeWidth="2" />
      <line x1={x1} y1="292" x2={x1} y2="316" stroke="#666" strokeWidth="2" />
      <line x1={x0} y1="304" x2="272" y2="304" stroke="#666" strokeWidth="2" />
      <line x1="330" y1="304" x2={x1} y2="304" stroke="#666" strokeWidth="2" />
      <text x="301" y="312" textAnchor="middle" fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#333">l</text>
      {/* 截面 */}
      <circle cx="562" cy="128" r="40" fill="#EFF6FF" stroke="#1F4E9C" strokeWidth="2.8" />
      <circle cx="562" cy="128" r="6" fill="#1F4E9C" />
      <line x1="562" y1="128" x2="590" y2="104" stroke="#12852F" strokeWidth="2.2" />
      <text x="594" y="100" fontSize="21" fontStyle="italic" fontFamily={SERIF}
        fill="#12852F">R</text>
      <text x="562" y="192" textAnchor="middle" fontSize="22" fontFamily={HEI} fill="#1F4E9C">
        S = πR²
      </text>
      <line x1="500" y1="150" x2="520" y2="140" stroke="#9AA7B5" strokeWidth="2"
        strokeDasharray="6 5" />
      <text x="300" y="366" textAnchor="middle" fontSize="27" fontFamily={SERIF} fill="#333">
        B = μ₀ n i，Φ = B S，Ψ = N Φ
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 8-3 P6：同轴电缆的截面 —— 内导体半径 R₁、外导体内半径 R₂。
 *  内导体电流向里（⊗）⇒ 两导体之间的 B 沿顺时针环绕（右手定则，屏幕 y 向下）。
 *  安培环路取半径 r，B = μ₀I/(2πr)。三个 B 箭头放在 -90°、-30°、150°，避开 R₁/R₂ 引线。 */
export function CoaxInduct() {
  const cx = 200, cy = 180
  const R1 = 96, R2 = 112, r = 58
  const tang = (a: number, key: string) => {
    const x = cx + r * Math.cos(a), y = cy + r * Math.sin(a)
    const tx = -Math.sin(a), ty = Math.cos(a)
    return (
      <g key={key} transform={`translate(${x},${y}) rotate(${(Math.atan2(ty, tx) * 180) / Math.PI})`}>
        <polygon points="0,0 -13,-6 -13,6" fill="#7B1FA2" />
      </g>
    )
  }
  // 半径引线：从圆心出发，穿过导体后折向外侧，文字落在圆外
  const lead = (ang: number, ex: number, ey: number, key: string) => {
    const x1 = cx + R2 * Math.cos(ang), y1 = cy + R2 * Math.sin(ang)
    return (
      <g key={key}>
        <line x1={cx} y1={cy} x2={x1} y2={y1} stroke="#666" strokeWidth="1.8" />
        <line x1={x1} y1={y1} x2={ex} y2={ey} stroke="#666" strokeWidth="1.8" />
      </g>
    )
  }
  return (
    <svg viewBox="0 0 620 381" width="100%" height="100%">
      <circle cx={cx} cy={cy} r={R1} fill="#EFF6FF" stroke="#7FB0D8" strokeWidth="2.6" />
      <circle cx={cx} cy={cy} r={(R1 + R2) / 2} fill="none" stroke="#9AA7B5"
        strokeWidth={R2 - R1} />
      <circle cx={cx} cy={cy} r={R1} fill="none" stroke="#8A6A3A" strokeWidth="2" />
      <circle cx={cx} cy={cy} r={R2} fill="none" stroke="#8A6A3A" strokeWidth="2" />

      {/* 内导体，电流向里 */}
      <circle cx={cx} cy={cy} r="20" fill="#C08A4A" stroke="#8A6A3A" strokeWidth="2" />
      <line x1={cx - 11} y1={cy - 11} x2={cx + 11} y2={cy + 11} stroke="#3A2A16"
        strokeWidth="2.8" />
      <line x1={cx + 11} y1={cy - 11} x2={cx - 11} y2={cy + 11} stroke="#3A2A16"
        strokeWidth="2.8" />

      {/* 安培环路 */}
      <circle cx={cx} cy={cy} r={r} fill="none" stroke="#12852F" strokeWidth="2.4"
        strokeDasharray="9 7" />
      {tang(-Math.PI / 2, 't1')}
      {tang(-Math.PI / 6, 't2')}
      {tang((5 * Math.PI) / 6, 't3')}
      <line x1={cx} y1={cy} x2={cx + r * Math.cos(-Math.PI / 3.2)}
        y2={cy + r * Math.sin(-Math.PI / 3.2)} stroke="#12852F" strokeWidth="2.2" />
      <text x={cx + 30} y={cy - 56} fontSize="25" fontStyle="italic" fontFamily={SERIF}
        fill="#12852F">r</text>

      {/* 半径标注（引线穿出圆外再写字） */}
      {lead(0, cx + R2 + 6, cy, 'l1')}
      <text x={cx + R2 + 12} y={cy - 8} fontSize="24" fontStyle="italic" fontFamily={SERIF}
        fill="#333">R<tspan dy="4" fontSize="17">1</tspan></text>
      {lead(Math.PI * 1.12, cx - R2 - 26, cy + 34, 'l2')}
      <text x={cx - R2 - 32} y={cy + 40} textAnchor="end" fontSize="24" fontStyle="italic"
        fontFamily={SERIF} fill="#333">R<tspan dy="4" fontSize="17">2</tspan></text>

      <text x="452" y="150" textAnchor="middle" fontSize="26" fontFamily={SERIF} fill="#333">
        B = μ₀I / (2πr)
      </text>
      <text x="452" y="200" textAnchor="middle" fontSize="23" fontFamily={HEI} fill="#777">
        两导体之间才有磁场
      </text>
      <text x="452" y="240" textAnchor="middle" fontSize="22" fontFamily={HEI} fill="#777">
        ⊗ 表示电流流入纸面
      </text>
      <text x="310" y="336" textAnchor="middle" fontSize="26" fontFamily={SERIF} fill="#333">
        L/l = (μ₀/2π) ln(R₂/R₁)
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 8-3 P8：两个共轴线圈的互感 —— 线圈 1 的电流产生的磁通穿过线圈 2。
 *  磁通画成三条穿过两线圈内部的水平线（右向），线圈 1 的电流用绕行弧箭头表示。
 *  两线圈拉开到 c1=160 / c2=500，内容占满 viewBox，避免图在页面上显小。 */
export function MutualCoils() {
  const c1 = 160, c2 = 500, cy = 190
  const ring = (cx: number, key: string) => (
    <g key={key}>
      <ellipse cx={cx} cy={cy} rx="14" ry="62" fill="none" stroke="#8A6A3A" strokeWidth="3.4" />
      <ellipse cx={cx + 20} cy={cy} rx="14" ry="62" fill="none" stroke="#8A6A3A"
        strokeWidth="3.4" opacity="0.72" />
    </g>
  )
  const flux = (dy: number, key: string) => (
    <g key={key}>
      <line x1={c1 - 32} y1={cy + dy} x2={c2 + 56} y2={cy + dy} stroke="#1F4E9C"
        strokeWidth="2.8" opacity="0.75" />
      <polygon points={`${c2 + 40},${cy + dy - 7} ${c2 + 56},${cy + dy} ${c2 + 40},${cy + dy + 7}`}
        fill="#1F4E9C" opacity="0.75" />
    </g>
  )
  const ea = -1.35
  const ex = c1 + 10 + 90 * Math.cos(ea), ey = cy + 90 * Math.sin(ea)
  return (
    <svg viewBox="96 60 510 314" width="100%" height="100%">
      {flux(-38, 'f1')}
      {flux(0, 'f2')}
      {flux(38, 'f3')}

      {ring(c1, 'r1')}
      {ring(c2, 'r2')}

      {/* 线圈 1 的绕行电流 */}
      <ArcLine cx={c1 + 10} cy={cy} r={90} a0={-2.15} a1={ea} color="#7B1FA2" w={3.6} />
      <g transform={`translate(${ex},${ey}) rotate(12)`}>
        <polygon points="0,0 -15,-6.5 -15,6.5" fill="#7B1FA2" />
      </g>
      <text x={c1 + 10} y={cy - 100} textAnchor="middle" fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#7B1FA2">i₁</text>

      {/* 线圈 2 的感应电动势 */}
      <text x={c2 + 44} y={cy - 74} fontSize="25" fontStyle="italic" fontFamily={SERIF}
        fill="#C00000">ε<tspan dy="6" fontSize="17">2</tspan></text>
      <text x={c2 + 44} y={cy - 44} fontSize="20" fontFamily={HEI} fill="#C00000">感应</text>

      <text x={c1 + 10} y="320" textAnchor="middle" fontSize="24" fontFamily={HEI}
        fill="#333">线圈 1</text>
      <text x={c2 + 10} y="320" textAnchor="middle" fontSize="24" fontFamily={HEI}
        fill="#333">线圈 2</text>
      <text x="320" y="366" textAnchor="middle" fontSize="27" fontFamily={SERIF} fill="#1F4E9C">
        Φ₂₁ = M <tspan fontStyle="italic">i</tspan>₁
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 8-3 P10：同轴螺线管组的互感 —— 内管 n₁ 与外绕线圈 n₂ 共享同一段体积 V。
 *  外绕线圈画成一组套在管外的竖直椭圆环（比正弦绕线更清楚地表达「套在外面」）。
 *  完全耦合（无漏磁）时 Φ₂₁ = n₂·B₁·S = μ₀ n₁ n₂ V i₁。 */
export function MutualSolenoid() {
  const cy = 190, x0 = 80, x1 = 560, R1 = 44
  const xa = 210, xb = 430
  const helix = (a0: number, a1: number, R: number, N: number, color: string, key: string) => {
    const M = 200
    const pts: string[] = []
    for (let i = 0; i <= M; i++) {
      const th = (i / M) * 2 * Math.PI * N
      const x = a0 + ((a1 - a0) * i) / M
      pts.push(`${x.toFixed(1)},${(cy - R * Math.cos(th)).toFixed(1)}`)
    }
    return (
      <polyline key={key} points={pts.join(' ')} fill="none" stroke={color} strokeWidth="3.4"
        strokeLinejoin="round" />
    )
  }
  const turns = [232, 281, 330, 379, 428]
  return (
    <svg viewBox="0 0 640 393" width="100%" height="100%">
      <ellipse cx={x0} cy={cy} rx="9" ry={R1} fill="none" stroke="#9AA7B5" strokeWidth="2.4" />
      <ellipse cx={x1} cy={cy} rx="9" ry={R1} fill="none" stroke="#9AA7B5" strokeWidth="2.4" />

      {/* 管内磁场 */}
      {[-26, 0, 26].map((dy, i) => (
        <g key={i}>
          <line x1={x0 + 20} y1={cy + dy} x2={x1 - 30} y2={cy + dy} stroke="#1F4E9C"
            strokeWidth="2.4" opacity="0.62" />
          <polygon points={`${x1 - 44},${cy + dy - 6} ${x1 - 30},${cy + dy} ${x1 - 44},${cy + dy + 6}`}
            fill="#1F4E9C" opacity="0.62" />
        </g>
      ))}

      {helix(x0, x1, R1, 10, '#8A6A3A', 'h1')}
      {turns.map((x, i) => (
        <ellipse key={i} cx={x} cy={cy} rx="13" ry="66" fill="none" stroke="#1F6FBF"
          strokeWidth="3.2" />
      ))}

      {/* 共享体积 */}
      <line x1={xa} y1="86" x2={xa} y2="112" stroke="#666" strokeWidth="2" />
      <line x1={xb} y1="86" x2={xb} y2="112" stroke="#666" strokeWidth="2" />
      <line x1={xa} y1="96" x2="303" y2="96" stroke="#666" strokeWidth="2" />
      <line x1="337" y1="96" x2={xb} y2="96" stroke="#666" strokeWidth="2" />
      <text x="320" y="104" textAnchor="middle" fontSize="25" fontStyle="italic"
        fontFamily={SERIF} fill="#333">V</text>

      <text x="112" y="272" fontSize="24" fontFamily={HEI} fill="#8A6A3A">n₁</text>
      <text x="440" y="272" fontSize="24" fontFamily={HEI} fill="#1F6FBF">n₂</text>
      <text x="320" y="346" textAnchor="middle" fontSize="26" fontFamily={SERIF} fill="#333">
        M = μ₀ <tspan fontStyle="italic">n</tspan>₁ <tspan fontStyle="italic">n</tspan>₂ V
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 8-4 P3：RL 电路接通时电流按指数上升 —— 电源做的功一部分变成焦耳热，一部分储存在磁场里。
 *  i(t) = I(1−e^(−t/τ))，τ = L/R；曲线下面积 × ε 即电源做的功。 */
export function RlCharge() {
  const ox = 116, oy = 322, tau = 106, yTop = 116
  const I = oy - yTop
  const pts: string[] = []
  for (let i = 0; i <= 60; i++) {
    const t = (i / 60) * 4
    const x = ox + t * tau
    const y = oy - I * (1 - Math.exp(-t))
    pts.push(`${x.toFixed(1)},${y.toFixed(1)}`)
  }
  const areaPts = [`${ox},${oy}`, ...pts, `${ox + 4 * tau},${oy}`].join(' ')
  return (
    <svg viewBox="0 0 640 393" width="100%" height="100%">
      {/* 坐标轴 */}
      <line x1={ox} y1={oy} x2={ox + 4 * tau + 44} y2={oy} stroke="#555" strokeWidth="2.6" />
      <line x1={ox} y1={oy} x2={ox} y2="76" stroke="#555" strokeWidth="2.6" />
      <polygon points={`${ox + 4 * tau + 44},${oy} ${ox + 4 * tau + 32},${oy - 6} ${ox + 4 * tau + 32},${oy + 6}`} fill="#555" />
      <polygon points={`${ox},76 ${ox - 6},88 ${ox + 6},88`} fill="#555" />
      <text x={ox + 4 * tau + 40} y={oy + 30} fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#333">t</text>
      <text x={ox - 30} y="94" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#333">i</text>

      {/* 电源做功的面积 */}
      <polygon points={areaPts} fill="#1F6FBF" opacity="0.12" />

      {/* 渐近线 I = ε/R */}
      <line x1={ox} y1={yTop} x2={ox + 4 * tau + 30} y2={yTop} stroke="#B00020"
        strokeWidth="2.2" strokeDasharray="8 6" />
      <text x={ox + 20} y={yTop - 12} fontSize="24" fontFamily={SERIF} fill="#B00020">
        ε / R
      </text>

      {/* 电流曲线 */}
      <polyline points={pts.join(' ')} fill="none" stroke="#12852F" strokeWidth="4" />

      {/* τ 处的读数 */}
      <line x1={ox + tau} y1={oy} x2={ox + tau} y2={oy - I * 0.632} stroke="#666"
        strokeWidth="1.8" strokeDasharray="6 5" />
      <line x1={ox} y1={oy - I * 0.632} x2={ox + tau} y2={oy - I * 0.632} stroke="#666"
        strokeWidth="1.8" strokeDasharray="6 5" />
      <circle cx={ox + tau} cy={oy - I * 0.632} r="5" fill="#12852F" />
      <text x={ox + tau - 6} y={oy + 28} textAnchor="middle" fontSize="23" fontStyle="italic"
        fontFamily={SERIF} fill="#333">τ</text>
      <text x={ox + 10} y={oy - I * 0.632 - 10} fontSize="21" fontFamily={SERIF} fill="#333">
        0.63 ε/R
      </text>

      <text x={ox + 2.1 * tau} y={oy - I * 0.42} fontSize="22" fontFamily={HEI} fill="#12852F">
        i(t)
      </text>
      <text x={ox + 2.2 * tau} y={oy - I * 0.16} fontSize="21" fontFamily={HEI} fill="#1F6FBF">
        电源做的功 ∫ε i dt
      </text>
      <text x={ox + 30} y="368" fontSize="21" fontFamily={HEI} fill="#777">
        τ = L / R，越大越慢
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 8-4 P5：磁能分布在磁场里 —— 体积元 dV 内的磁能 w·dV，w = B²/(2μ₀)。
 *  螺线管内部磁场均匀 ⇒ 各点能量密度相同；斜二测画一个小体积元表示 dV。 */
export function MagEnergyVol() {
  const x0 = 90, x1 = 470, yT = 148, yB = 244, cy = 196
  // 斜二测立方体：正面 (dx,dy)，后偏移 (ox,oy)
  const cx0 = 236, cy0 = 206, w = 62, h = 62, ox = 20, oy = -15
  return (
    <svg viewBox="0 0 640 393" width="100%" height="100%">
      {/* 螺线管（矩形侧视 + 绕线） */}
      <rect x={x0} y={yT} width={x1 - x0} height={yB - yT} fill="#F7FAFE" stroke="#9AA7B5"
        strokeWidth="2.4" />
      {Array.from({ length: 13 }, (_, i) => x0 + 14 + i * 29).map((x, i) => (
        <line key={i} x1={x - 5} y1={yT - 13} x2={x + 5} y2={yB + 13} stroke="#8A6A3A"
          strokeWidth="3.2" opacity="0.8" />
      ))}
      <ellipse cx={x0} cy={cy} rx="8" ry="48" fill="none" stroke="#9AA7B5" strokeWidth="2.2" />
      <ellipse cx={x1} cy={cy} rx="8" ry="48" fill="none" stroke="#9AA7B5" strokeWidth="2.2" />

      {/* 磁力线 */}
      {[cy - 24, cy, cy + 24].map((y, i) => (
        <g key={i}>
          <line x1={x0 + 16} y1={y} x2={x1 - 26} y2={y} stroke="#1F4E9C" strokeWidth="2.6"
            opacity="0.7" />
          <polygon points={`${x1 - 40},${y - 6} ${x1 - 26},${y} ${x1 - 40},${y + 6}`}
            fill="#1F4E9C" opacity="0.7" />
        </g>
      ))}

      {/* 体积元 dV */}
      <g>
        <polygon points={`${cx0 + ox},${cy0 - h + oy} ${cx0 + w + ox},${cy0 - h + oy} ${cx0 + w},${cy0 - h} ${cx0},${cy0 - h}`}
          fill="#FFFFFF" opacity="0.55" stroke="#B00020" strokeWidth="2.4" />
        <rect x={cx0} y={cy0 - h} width={w} height={h} fill="#FFFFFF" opacity="0.55"
          stroke="#B00020" strokeWidth="2.8" />
        <polygon points={`${cx0},${cy0} ${cx0 + ox},${cy0 + oy} ${cx0 + w + ox},${cy0 + oy} ${cx0 + w},${cy0}`}
          fill="#B00020" opacity="0.1" stroke="#B00020" strokeWidth="2.4" />
        <line x1={cx0} y1={cy0 - h} x2={cx0 + ox} y2={cy0 - h + oy} stroke="#B00020"
          strokeWidth="2.4" />
        <line x1={cx0 + w} y1={cy0 - h} x2={cx0 + w + ox} y2={cy0 - h + oy} stroke="#B00020"
          strokeWidth="2.4" />
        <text x={cx0 + w / 2} y={cy0 - h / 2 + 8} textAnchor="middle" fontSize="24"
          fontStyle="italic" fontFamily={SERIF} fill="#B00020">dV</text>
      </g>

      <text x={x0 + 60} y={yT - 34} fontSize="23" fontFamily={HEI} fill="#1F4E9C">
        管内 B 均匀
      </text>
      <text x="502" y="128" fontSize="26" fontStyle="italic" fontFamily={SERIF}
        fill="#1F4E9C" stroke="#FFFFFF" strokeWidth="6" paintOrder="stroke">B</text>
      <text x="320" y="330" textAnchor="middle" fontSize="27" fontFamily={SERIF} fill="#333">
        dW = w dV
      </text>
      <text x="320" y="368" textAnchor="middle" fontSize="27" fontFamily={SERIF} fill="#B00020">
        w = B² / (2μ₀)
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 8-4 P7：同轴电缆里的磁场能量 —— B ∝ 1/r ⇒ w ∝ 1/r²，能量集中在内导体附近。
 *  左侧画截面，右侧画 w(r) 曲线（只在 R₁ < r < R₂ 之间非零）。 */
export function CoaxEnergy() {
  const cx = 150, cy = 190, R1 = 44, R2 = 84
  const ox = 300, oy = 300, xa = 336, xb = 560
  const wOf = (r: number) => 196 * Math.pow(R1 / r, 2)
  const curve: string[] = []
  const N = 40
  for (let i = 0; i <= N; i++) {
    const r = R1 + ((R2 - R1) * i) / N
    const x = xa + ((xb - xa) * (r - R1)) / (R2 - R1)
    curve.push(`${x.toFixed(1)},${(oy - wOf(r)).toFixed(1)}`)
  }
  return (
    <svg viewBox="0 0 640 393" width="100%" height="100%">
      {/* 截面 */}
      <circle cx={cx} cy={cy} r={R1} fill="#EFF6FF" stroke="#7FB0D8" strokeWidth="2.4" />
      <circle cx={cx} cy={cy} r={R2} fill="none" stroke="#9AA7B5" strokeWidth="14" />
      <circle cx={cx} cy={cy} r="16" fill="#C08A4A" stroke="#8A6A3A" strokeWidth="2" />
      <line x1={cx - 9} y1={cy - 9} x2={cx + 9} y2={cy + 9} stroke="#3A2A16" strokeWidth="2.4" />
      <line x1={cx + 9} y1={cy - 9} x2={cx - 9} y2={cy + 9} stroke="#3A2A16" strokeWidth="2.4" />
      <text x={cx} y={cy + R2 + 30} textAnchor="middle" fontSize="22" fontFamily={HEI}
        fill="#555">磁场只在这里</text>

      {/* w(r) 曲线 */}
      <line x1={ox} y1={oy} x2="592" y2={oy} stroke="#555" strokeWidth="2.4" />
      <line x1={ox} y1={oy} x2={ox} y2="94" stroke="#555" strokeWidth="2.4" />
      <text x="596" y={oy + 24} fontSize="22" fontStyle="italic" fontFamily={SERIF}
        fill="#333">r</text>
      <text x={ox - 26} y="108" fontSize="22" fontStyle="italic" fontFamily={SERIF}
        fill="#333">w</text>
      <polyline points={curve.join(' ')} fill="none" stroke="#B00020" strokeWidth="4" />
      <line x1={xa} y1={oy} x2={xa} y2={oy - wOf(R1)} stroke="#666" strokeWidth="1.8"
        strokeDasharray="6 5" />
      <line x1={xb} y1={oy} x2={xb} y2={oy - wOf(R2)} stroke="#666" strokeWidth="1.8"
        strokeDasharray="6 5" />
      <text x={xa} y={oy + 26} textAnchor="middle" fontSize="24" fontStyle="italic"
        fontFamily={SERIF} fill="#333">R₁</text>
      <text x={xb} y={oy + 26} textAnchor="middle" fontSize="24" fontStyle="italic"
        fontFamily={SERIF} fill="#333">R₂</text>
      <text x="446" y="150" textAnchor="middle" fontSize="24" fontFamily={HEI}
        fill="#B00020">w ∝ 1/r²</text>

      <text x="320" y="366" textAnchor="middle" fontSize="26" fontFamily={SERIF} fill="#333">
        W = ∫ w dV
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 8-5 P3：安培环路定理的困难 —— 同一个环路 L 可以张成两个曲面。
 *  S₁ 被导线穿过（有传导电流 I），S₂ 绕过极板间隙（没有传导电流）。
 *  同一 L 却给出两个不同的 ∮H·dl ⇒ 稳恒电流的安培定理不适用于非稳恒情形。 */
export function AmpereCapacitor() {
  const cy = 180, xL = 60, xR = 560, yB = 322
  const lx = 190, ry = 72
  return (
    <svg viewBox="0 0 640 393" width="100%" height="100%">
      {/* 回路 */}
      <line x1={xL} y1={cy} x2="290" y2={cy} stroke="#333" strokeWidth="4" />
      <line x1="350" y1={cy} x2={xR} y2={cy} stroke="#333" strokeWidth="4" />
      <line x1={xL} y1={cy} x2={xL} y2={yB} stroke="#333" strokeWidth="4" />
      <line x1={xR} y1={cy} x2={xR} y2={yB} stroke="#333" strokeWidth="4" />
      <line x1={xL} y1={yB} x2={xR} y2={yB} stroke="#333" strokeWidth="4" />
      <line x1={xL - 18} y1="240" x2={xL + 18} y2="240" stroke="#333" strokeWidth="5" />
      <line x1={xL - 9} y1="258" x2={xL + 9} y2="258" stroke="#333" strokeWidth="5" />

      {/* S₂：绕过间隙的曲面 */}
      <path d={`M ${lx} ${cy - ry} C 218 52 320 50 332 116 L 332 248 C 320 314 218 312 ${lx} ${cy + ry} Z`}
        fill="#FFF3D6" stroke="#C8A24A" strokeWidth="2.4" strokeDasharray="8 6" opacity="0.6" />
      {/* 极板 */}
      <line x1="290" y1="106" x2="290" y2="254" stroke="#1F4E9C" strokeWidth="8" />
      <line x1="350" y1="106" x2="350" y2="254" stroke="#1F4E9C" strokeWidth="8" />
      <text x="250" y="156" textAnchor="end" fontSize="26" fontFamily={SERIF} fill="#B00020">+</text>
      <text x="368" y="156" fontSize="26" fontFamily={SERIF} fill="#1F4E9C">−</text>

      {/* S₁：平面圆盘 */}
      <ellipse cx={lx} cy={cy} rx="16" ry={ry} fill="#DDEBFA" stroke="#1F6FBF" strokeWidth="2.6" />

      {/* 环路 L */}
      <text x={lx - 26} y={cy - ry - 10} textAnchor="end" fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#333">L</text>
      <text x={lx} y={cy + 44} textAnchor="middle" fontSize="24" fontFamily={HEI}
        fill="#1F6FBF">S₁</text>
      <text x="266" y="78" textAnchor="middle" fontSize="24" fontFamily={HEI}
        fill="#A67C1A">S₂</text>

      {/* 电流方向 */}
      <polygon points="120,174 136,180 120,186" fill="#7B1FA2" />
      <text x="128" y="160" textAnchor="middle" fontSize="22" fontStyle="italic"
        fontFamily={SERIF} fill="#7B1FA2">I</text>

      <text x="320" y="344" textAnchor="middle" fontSize="24" fontFamily={HEI} fill="#333">
        同一个 L，两个曲面
      </text>
      <text x="320" y="374" textAnchor="middle" fontSize="23" fontFamily={SERIF} fill="#B00020">
        ∮H·dl 给出两个值 ⇒ 矛盾
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

