/** 10-4 P3：惠更斯原理 —— 波面 S 上每一点都是新的子波源，
 *  它们发出的子波在稍后时刻的包迹，就是新的波面。
 *  这里用球面波画：旧波面是以 O 为心的圆弧，新波面是同一心的同心大圆弧。 */
export function HuygensPrinciple() {
  const ox = 120, oy = 210, r1 = 120, rs = 56, r2 = 176
  const angs = [-38, -25, -13, 0, 13, 25, 38].map((d) => (d * Math.PI) / 180)
  const arc = (r: number, a0: number, a1: number, n = 60) => {
    const pts: string[] = []
    for (let i = 0; i <= n; i++) {
      const a = a0 + ((a1 - a0) * i) / n
      pts.push(`${(ox + r * Math.cos(a)).toFixed(1)},${(oy + r * Math.sin(a)).toFixed(1)}`)
    }
    return pts.join(' ')
  }
  return (
    <svg viewBox="0 0 700 430" width="100%" height="100%">
      {/* 旧波面 S */}
      <polyline points={arc(r1, -0.72, 0.72)} fill="none" stroke="#1F6FBF" strokeWidth="5" />
      {/* 子波：以 S 上各点为心的圆 */}
      {angs.map((a, i) => (
        <circle key={i} cx={ox + r1 * Math.cos(a)} cy={oy + r1 * Math.sin(a)} r={rs}
          fill="none" stroke="#9DBBE6" strokeWidth="1.6" opacity="0.9" />
      ))}
      {/* 新波面（包迹） */}
      <polyline points={arc(r2, -0.72, 0.72)} fill="none" stroke="#C00000" strokeWidth="4.4"
        strokeDasharray="11 8" />
      {/* 圆心与半径 */}
      <circle cx={ox} cy={oy} r="6" fill="#333" />
      <text x={ox - 22} y={oy + 8} textAnchor="end" fontSize="24" fontStyle="italic"
        fontFamily={'"Times New Roman", SimSun, serif'} fill="#333">O</text>
      {angs.map((a, i) => (
        <circle key={i} cx={ox + r1 * Math.cos(a)} cy={oy + r1 * Math.sin(a)} r="5"
          fill="#1F6FBF" />
      ))}

      {/* 标注 */}
      <text x="206" y="98" textAnchor="middle" fontSize="23" fontFamily={'SimHei, SimSun, serif'}
        fill="#1F6FBF">波面 S</text>
      <line x1="206" y1="104" x2={ox + r1 * Math.cos(-0.68)} y2={oy + r1 * Math.sin(-0.68)}
        stroke="#1F6FBF" strokeWidth="1.5" />
      <text x="330" y="60" fontSize="23" fontFamily={'SimHei, SimSun, serif'} fill="#8FA6C4">
        子波
      </text>
      <line x1="326" y1="64" x2={ox + r1 * Math.cos(-0.05) + 40} y2={oy + r1 * Math.sin(-0.05) - 40}
        stroke="#8FA6C4" strokeWidth="1.5" />
      <text x="320" y="372" fontSize="23" fontFamily={'SimHei, SimSun, serif'} fill="#C00000">
        新波面
      </text>
      <line x1="316" y1="364" x2={ox + r2 * Math.cos(0.66)} y2={oy + r2 * Math.sin(0.66)}
        stroke="#C00000" strokeWidth="1.5" />

      {/* 右侧说明 */}
      <text x="336" y="118" fontSize="24" fontFamily={'SimHei, SimSun, serif'} fill="#333">
        波面上的每一点
      </text>
      <text x="336" y="158" fontSize="24" fontFamily={'SimHei, SimSun, serif'} fill="#333">
        都是新的子波源
      </text>
      <text x="336" y="222" fontSize="24" fontFamily={'SimHei, SimSun, serif'} fill="#333">
        子波的包迹
      </text>
      <text x="336" y="262" fontSize="24" fontFamily={'SimHei, SimSun, serif'} fill="#333">
        ＝ 新的波面
      </text>
    </svg>
  )
}

/** 11-5 P4：惠更斯-菲涅耳原理——波阵面 Σ 上的面元 ΔS 作为子波源，在 P 点相干叠加。 */
export function HuygensFresnel() {
  const S: [number, number] = [300, 330]
  const P: [number, number] = [820, 300]
  return (
    <svg viewBox="0 0 1000 640" width="100%" height="100%">
      {/* 波阵面 */}
      <path d="M 160 120 Q 300 330 200 560" fill="none" stroke={OPT_BLUE} strokeWidth="3.4" />
      <text x="150" y="600" fontSize="30" fontStyle="italic" fontFamily={SERIF}
        fill={OPT_BLUE}>Σ</text>
      <text x="150" y="96" fontSize="24" fontFamily={HEI} fill="#555">t 时刻波阵面</text>

      {/* 面元 ΔS */}
      <ellipse cx={S[0]} cy={S[1]} rx="26" ry="52" fill="#F7C6C6" stroke={OPT_RED}
        strokeWidth="2.4" transform="rotate(-12 300 330)" />
      <text x={S[0] - 96} y={S[1] - 56} fontSize="28" fontFamily={SERIF}
        fill={OPT_RED}>ΔS</text>

      {/* 法线 e 与 r、θ */}
      <line x1={S[0]} y1={S[1]} x2={S[0] + 190} y2={S[1] - 90} stroke="#1F8A4C"
        strokeWidth="2.4" />
      <text x={S[0] + 196} y={S[1] - 96} fontSize="28" fontStyle="italic" fontFamily={SERIF}
        fill="#1F8A4C">e</text>
      <line x1={S[0]} y1={S[1]} x2={P[0]} y2={P[1]} stroke="#C000C0" strokeWidth="2.6" />
      <text x={(S[0] + P[0]) / 2} y={S[1] - 20} fontSize="28" fontStyle="italic"
        fontFamily={SERIF} fill="#C000C0">r</text>
      <ArcLine cx={S[0]} cy={S[1]} r={90} a0={-0.44} a1={-0.03} color="#E8821E" w={2.4} />
      <text x={S[0] + 86} y={S[1] - 66} fontSize="26" fontStyle="italic" fontFamily={SERIF}
        fill="#E8821E">θ</text>

      {/* 子波 */}
      {[40, 70, 100].map((r) => (
        <ArcLine key={r} cx={S[0]} cy={S[1]} r={r} a0={-0.9} a1={0.9} color={OPT_VIOLET}
          w={1.8} />
      ))}

      {/* P 点 */}
      <circle cx={P[0]} cy={P[1]} r="8" fill="#111" />
      <text x={P[0] + 18} y={P[1] + 6} fontSize="30" fontStyle="italic" fontFamily={SERIF}
        fill="#111">P</text>
    </svg>
  )
}

