/** 11-5 P7：用两个透镜在实验中实现夫琅禾费衍射（L₁ 准直、L₂ 会聚）。 */
export function FraunhoferSetup() {
  return (
    <svg viewBox="0 0 1200 620" width="100%" height="100%">
      {/* 光源 */}
      <circle cx="110" cy="310" r="14" fill="#F2C230" stroke="#B8860B" strokeWidth="2" />
      <text x="80" y="360" fontSize="26" fontFamily={SERIF} fill="#111">S</text>

      {/* 发散光到 L1 */}
      {[[300, 250], [300, 310], [300, 370]].map(([x, y], i) => (
        <line key={i} x1="124" y1="310" x2={x - 14} y2={y} stroke={OPT_BLUE} strokeWidth="2.2" />
      ))}
      <ellipse cx="300" cy="310" rx="20" ry="90" fill="#BFE9E2" stroke="#2E8B57"
        strokeWidth="2.4" />
      <text x="282" y="196" fontSize="28" fontFamily={SERIF} fill="#111">L₁</text>

      {/* 平行光到缝 */}
      {[250, 310, 370].map((y) => (
        <line key={y} x1="318" y1={y} x2="596" y2={y} stroke={OPT_BLUE} strokeWidth="2.2"
          markerEnd="url(#fsArrow)" />
      ))}
      <rect x="600" y="150" width="18" height="120" fill="#C9A227" />
      <rect x="600" y="350" width="18" height="120" fill="#C9A227" />
      <text x="620" y="140" fontSize="26" fontFamily={SERIF} fill="#111">R</text>
      <defs>
        <marker id="fsArrow" markerWidth="8" markerHeight="8" refX="4" refY="7" orient="auto">
          <path d="M0,0 L8,0 L4,8 z" fill={OPT_BLUE} />
        </marker>
      </defs>

      {/* 衍射光到 L2 */}
      {[[820, 200], [820, 310], [820, 420]].map(([x, y], i) => (
        <line key={i} x1="618" y1="310" x2={x - 16} y2={y} stroke={OPT_BLUE} strokeWidth="2.2" />
      ))}
      <ellipse cx="820" cy="310" rx="20" ry="110" fill="#BFE9E2" stroke="#2E8B57"
        strokeWidth="2.4" />
      <text x="806" y="180" fontSize="28" fontFamily={SERIF} fill="#111">L₂</text>

      {/* 会聚到屏 */}
      {[[1050, 280], [1050, 310], [1050, 340]].map(([x, y], i) => (
        <line key={i} x1="838" y1="310" x2={x} y2={y} stroke={OPT_BLUE} strokeWidth="2.2" />
      ))}
      <rect x="1050" y="120" width="14" height="380" fill="#333" />
      <text x="1080" y="320" fontSize="26" fontFamily={SERIF} fill="#111">P</text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 10-4 P4：衍射 —— 同一个屏障，缝宽不同，波的行为完全不同。
 *  窄缝（d ≈ λ）：缝上各点成为子波源，波面向各方向弯开，绕到屏障后面；
 *  宽缝（d ≫ λ）：中间大部分子波的包迹仍近似平面，只有边缘略弯。 */
export function DiffractionGap() {
  const bx = 286
  const fronts = [80, 130, 180, 230]
  /* ---------- (a) 窄缝 ---------- */
  const aTop = 50, aBot = 250, gapA0 = 130, gapA1 = 186
  const ca = (gapA0 + gapA1) / 2
  const arcs: string[] = []
  for (const r of [34, 66, 98, 130]) {
    const pts: string[] = []
    for (let i = 0; i <= 44; i++) {
      const a = -Math.PI / 2 + (Math.PI * i) / 44
      pts.push(`${(bx + r * Math.cos(a)).toFixed(1)},${(ca + r * Math.sin(a)).toFixed(1)}`)
    }
    arcs.push(pts.join(' '))
  }
  /* ---------- (b) 宽缝 ---------- */
  const bTop = 318, bBot = 578, gapB0 = 338, gapB1 = 498
  const cb = (gapB0 + gapB1) / 2
  const half = (gapB1 - gapB0) / 2
  const beams = [44, 100, 158].map((dx) => {
    const pts: string[] = []
    for (let i = 0; i <= 34; i++) {
      const t = -1 + (2 * i) / 34
      pts.push(`${(bx + dx - 24 * Math.abs(t) ** 3).toFixed(1)},${(cb + half * t).toFixed(1)}`)
    }
    return pts.join(' ')
  })
  return (
    <svg viewBox="0 0 700 600" width="100%" height="100%">
      {/* ===== (a) 窄缝 ===== */}
      <text x="60" y="40" fontSize="24" fontFamily={'SimHei, SimSun, serif'} fill="#333">
        （a）缝宽 ≈ 波长：明显衍射
      </text>
      {fronts.map((x) => (
        <line key={x} x1={x} y1={aTop + 10} x2={x} y2={aBot - 10} stroke="#9DBBE6"
          strokeWidth="2.4" />
      ))}
      <line x1={bx} y1={aTop} x2={bx} y2={gapA0} stroke="#555" strokeWidth="9" />
      <line x1={bx} y1={gapA1} x2={bx} y2={aBot} stroke="#555" strokeWidth="9" />
      {arcs.map((p, i) => (
        <polyline key={i} points={p} fill="none" stroke="#1F6FBF" strokeWidth="2.6"
          opacity={0.95 - i * 0.1} />
      ))}
      {/* 缝宽 d */}
      <line x1={bx - 24} y1={gapA0} x2={bx - 24} y2={gapA1} stroke="#C00000" strokeWidth="2" />
      <line x1={bx - 30} y1={gapA0} x2={bx - 18} y2={gapA0} stroke="#C00000" strokeWidth="1.8" />
      <line x1={bx - 30} y1={gapA1} x2={bx - 18} y2={gapA1} stroke="#C00000" strokeWidth="1.8" />
      <text x={bx - 24} y="116" textAnchor="middle" fontSize="23"
        fontFamily={'SimHei, SimSun, serif'} fill="#C00000">d</text>

      {/* ===== (b) 宽缝 ===== */}
      <text x="60" y="300" fontSize="24" fontFamily={'SimHei, SimSun, serif'} fill="#333">
        （b）缝宽 ≫ 波长：几乎直行
      </text>
      {fronts.map((x) => (
        <line key={x} x1={x} y1={bTop + 10} x2={x} y2={bBot - 10} stroke="#9DBBE6"
          strokeWidth="2.4" />
      ))}
      <line x1={bx} y1={bTop} x2={bx} y2={gapB0} stroke="#555" strokeWidth="9" />
      <line x1={bx} y1={gapB1} x2={bx} y2={bBot} stroke="#555" strokeWidth="9" />
      {beams.map((p, i) => (
        <polyline key={i} points={p} fill="none" stroke="#1F6FBF" strokeWidth="2.6"
          opacity={0.95 - i * 0.12} />
      ))}
      <line x1={bx - 24} y1={gapB0} x2={bx - 24} y2={gapB1} stroke="#C00000" strokeWidth="2" />
      <line x1={bx - 30} y1={gapB0} x2={bx - 18} y2={gapB0} stroke="#C00000" strokeWidth="1.8" />
      <line x1={bx - 30} y1={gapB1} x2={bx - 18} y2={gapB1} stroke="#C00000" strokeWidth="1.8" />
      <text x={bx - 24} y="324" textAnchor="middle" fontSize="23"
        fontFamily={'SimHei, SimSun, serif'} fill="#C00000">d</text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 10-4 P8：两相干波源到 P 点的波程差 —— r₂ − r₁ 叫波程差 δ。
 *  同相波源时，相位差只由 δ 决定；两源连线的中垂线上 δ=0，永远加强。 */
export function InterferencePath() {
  const s1 = [150, 120], s2 = [150, 320]
  const P = [534, 214]
  const circles = (c: number[], color: string) =>
    [64, 128, 192, 256].map((r, i) => (
      <circle key={r} cx={c[0]} cy={c[1]} r={r} fill="none" stroke={color}
        strokeWidth="1.5" opacity={0.5 - i * 0.06} />
    ))
  const mid = [150, 220]
  return (
    <svg viewBox="0 0 700 470" width="100%" height="100%">
      {/* 两列波的等相面（同心圆） */}
      {circles(s1, '#1F6FBF')}
      {circles(s2, '#1F6FBF')}
      {/* 中垂线：δ = 0 */}
      <line x1={mid[0]} y1={mid[1]} x2="672" y2={mid[1]} stroke="#C00000" strokeWidth="2.6"
        strokeDasharray="12 9" />
      <text x="182" y={mid[1] - 14} fontSize="22" fontFamily={'SimHei, SimSun, serif'}
        fill="#C00000">δ = 0 ⇒ 加强</text>

      {/* 两源 */}
      <circle cx={s1[0]} cy={s1[1]} r="10" fill="#C00000" />
      <circle cx={s2[0]} cy={s2[1]} r="10" fill="#C00000" />
      <text x={s1[0] - 34} y={s1[1] - 6} fontSize="24" fontFamily={'SimHei, SimSun, serif'}
        fill="#C00000">
        S<tspan dy="6" fontSize="17">1</tspan>
      </text>
      <text x={s2[0] - 34} y={s2[1] + 18} fontSize="24" fontFamily={'SimHei, SimSun, serif'}
        fill="#C00000">
        S<tspan dy="6" fontSize="17">2</tspan>
      </text>

      {/* 到 P 的两条波线 */}
      <line x1={s1[0]} y1={s1[1]} x2={P[0]} y2={P[1]} stroke="#0A8A0A" strokeWidth="3" />
      <line x1={s2[0]} y1={s2[1]} x2={P[0]} y2={P[1]} stroke="#7B1FA2" strokeWidth="3" />
      <text x="300" y="150" fontSize="24" fontStyle="italic"
        fontFamily={'"Times New Roman", SimSun, serif'} fill="#0A8A0A">
        r<tspan dy="6" fontSize="17">1</tspan>
      </text>
      <text x="300" y="292" fontSize="24" fontStyle="italic"
        fontFamily={'"Times New Roman", SimSun, serif'} fill="#7B1FA2">
        r<tspan dy="6" fontSize="17">2</tspan>
      </text>

      {/* P 点 */}
      <circle cx={P[0]} cy={P[1]} r="8" fill="#333" />
      <text x={P[0] + 14} y={P[1] - 10} fontSize="25" fontStyle="italic"
        fontFamily={'"Times New Roman", SimSun, serif'} fill="#333">P</text>

      {/* 波程差说明 */}
      <text x="150" y="424" fontSize="24" fontFamily={'SimHei, SimSun, serif'} fill="#333">
        波程差 δ = r₂ − r₁
      </text>
      <text x="150" y="462" fontSize="22" fontFamily={'SimHei, SimSun, serif'} fill="#777">
        （两源同相时，相位差只由 δ 决定）
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 10-4 P9：合振幅的矢量合成 —— 两个振幅矢量首尾相接，夹角就是相位差 Δφ。
 *  余弦定理给出 A² = A₁² + A₂² + 2A₁A₂cosΔφ：
 *  Δφ=0 时 A=A₁+A₂（加强）；Δφ=π 时 A=|A₁−A₂|（减弱）。 */
export function InterferencePhasor() {
  const ox = 118, oy = 306
  const a1 = 316, a2 = 222
  const deg = -56
  const rad = (deg * Math.PI) / 180
  const t1: [number, number] = [ox + a1, oy]
  const t2: [number, number] = [t1[0] + a2 * Math.cos(rad), t1[1] + a2 * Math.sin(rad)]
  /** 从 p 到 q 的箭头：箭杆 + 随方向旋转的箭头三角 */
  const arrow = (p: [number, number], q: [number, number], color: string, w: number, dash?: string) => {
    const ang = (Math.atan2(q[1] - p[1], q[0] - p[0]) * 180) / Math.PI
    return (
      <g>
        <line x1={p[0]} y1={p[1]} x2={q[0]} y2={q[1]} stroke={color} strokeWidth={w}
          strokeDasharray={dash} />
        <g transform={`rotate(${ang} ${q[0]} ${q[1]})`}>
          <polygon points={`${q[0] + 15},${q[1]} ${q[0] - 7},${q[1] - 9} ${q[0] - 7},${q[1] + 9}`}
            fill={color} />
        </g>
      </g>
    )
  }
  const arc = (() => {
    const pts: string[] = []
    const r = 62
    for (let i = 0; i <= 24; i++) {
      const a = rad * (i / 24)
      pts.push(`${(t1[0] + r * Math.cos(a)).toFixed(1)},${(t1[1] + r * Math.sin(a)).toFixed(1)}`)
    }
    return pts.join(' ')
  })()
  return (
    <svg viewBox="0 0 700 450" width="100%" height="100%">
      <text x="118" y="66" fontSize="24" fontFamily={'SimHei, SimSun, serif'} fill="#555">
        两个振幅矢量首尾相接，夹角就是 Δφ
      </text>

      {arrow([ox, oy], t1, '#1F6FBF', 6)}
      {arrow(t1, t2, '#7B1FA2', 6)}
      {arrow([ox, oy], t2, '#C00000', 6, '13 8')}

      <text x={(ox + t1[0]) / 2} y={oy + 38} textAnchor="middle" fontSize="26"
        fontStyle="italic" fontFamily={'"Times New Roman", SimSun, serif'} fill="#1F6FBF">
        A<tspan dy="6" fontSize="18">1</tspan>
      </text>
      <text x={(t1[0] + t2[0]) / 2 + 26} y={(t1[1] + t2[1]) / 2 - 14} fontSize="26"
        fontStyle="italic" fontFamily={'"Times New Roman", SimSun, serif'} fill="#7B1FA2">
        A<tspan dy="6" fontSize="18">2</tspan>
      </text>
      <text x={(ox + t2[0]) / 2 - 30} y={(oy + t2[1]) / 2 - 18} textAnchor="middle"
        fontSize="26" fontStyle="italic"
        fontFamily={'"Times New Roman", SimSun, serif'} fill="#C00000">A</text>

      <polyline points={arc} fill="none" stroke="#333" strokeWidth="2" />
      <text x={t1[0] + 26} y={t1[1] - 26} fontSize="24" fontFamily={'SimHei, SimSun, serif'}
        fill="#333">Δφ</text>

      <circle cx={t1[0]} cy={t1[1]} r="6" fill="#333" />
      <circle cx={ox} cy={oy} r="6" fill="#333" />
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 10-5 P3：驻波 —— 蓝线是合成波形（随时间上下翻），灰虚线是固定的包络。
 *  y = 2A sin(kx)·cos(ωt)：包络零点（波节）与极大处（波腹）都不动，所以叫「驻」波。 */
export function StandingWave({ t = 0 }: { t?: number }) {
  const xa = 100, xb = 660, y0 = 222, A = 70, LAM = 180
  const k = (2 * Math.PI) / LAM
  const P = 4.0
  const up: string[] = []
  const dn: string[] = []
  const inst: string[] = []
  const N = 220
  for (let i = 0; i <= N; i++) {
    const x = xa + ((xb - xa) * i) / N
    const env = A * Math.sin(k * (x - xa))
    up.push(`${x.toFixed(1)},${(y0 - env).toFixed(1)}`)
    dn.push(`${x.toFixed(1)},${(y0 + env).toFixed(1)}`)
    inst.push(`${x.toFixed(1)},${(y0 - env * Math.cos((2 * Math.PI * t) / P)).toFixed(1)}`)
  }
  const nodes = [100, 190, 280, 370, 460, 550, 640]
  return (
    <svg viewBox="0 0 700 430" width="100%" height="100%">
      <text x={xa} y="52" fontSize="22" fontFamily={'SimHei, SimSun, serif'} fill="#555">
        蓝线：合成波形　灰虚线：包络（固定不动）
      </text>
      {/* 平衡位置 */}
      <line x1={xa - 24} y1={y0} x2={xb + 20} y2={y0} stroke="#999" strokeWidth="1.6"
        strokeDasharray="8 6" />
      {/* 包络 */}
      <polyline points={up.join(' ')} fill="none" stroke="#B9B9B9" strokeWidth="2.4"
        strokeDasharray="9 7" />
      <polyline points={dn.join(' ')} fill="none" stroke="#B9B9B9" strokeWidth="2.4"
        strokeDasharray="9 7" />
      {/* 瞬时波形 */}
      <polyline points={inst.join(' ')} fill="none" stroke="#1F6FBF" strokeWidth="5" />
      {/* 波节 */}
      {nodes.map((x) => (
        <circle key={x} cx={x} cy={y0} r="6" fill="#333" />
      ))}
      {/* 波腹标注 */}
      <line x1="145" y1={y0 - A} x2="145" y2={y0 + A} stroke="#C00000" strokeWidth="1.6"
        strokeDasharray="5 5" />
      <text x="152" y={y0 - A - 12} fontSize="22" fontFamily={'SimHei, SimSun, serif'}
        fill="#C00000">波腹</text>
      <text x="92" y={y0 + A + 34} textAnchor="middle" fontSize="22"
        fontFamily={'SimHei, SimSun, serif'} fill="#333">波节</text>

      {/* λ/2 尺寸线 */}
      <line x1="100" y1="344" x2="190" y2="344" stroke="#555" strokeWidth="2" />
      <polygon points="114,344 102,338 102,350" fill="#555" />
      <polygon points="176,344 188,338 188,350" fill="#555" />
      <text x="145" y="376" textAnchor="middle" fontSize="23" fontStyle="italic"
        fontFamily={'"Times New Roman", SimSun, serif'} fill="#333">λ/2</text>
      <text x="205" y="376" fontSize="21" fontFamily={'SimHei, SimSun, serif'} fill="#777">
        相邻两波节的距离
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 10-5 P6：驻波各点的相位 —— 同一段内同相，跨过一个波节就反相。
 *  三条曲线是三个点的振动图：蓝、绿在同一段（同相），红色在相邻段（反相）。
 *  反相不是「落后」，而是恒定的 π：两条曲线的峰与谷始终对齐。 */
export function StandingPhase() {
  const xa = 110, xb = 640, y0 = 214, P = 240
  const wave = (amp: number, phase: number, color: string) => {
    const pts: string[] = []
    for (let i = 0; i <= 180; i++) {
      const x = xa + ((xb - xa) * i) / 180
      const y = y0 - amp * Math.cos((2 * Math.PI * (x - xa)) / P + phase)
      pts.push(`${x.toFixed(1)},${y.toFixed(1)}`)
    }
    return <polyline points={pts.join(' ')} fill="none" stroke={color} strokeWidth="4" />
  }
  return (
    <svg viewBox="0 0 700 420" width="100%" height="100%">
      <text x={xa} y="52" fontSize="22" fontFamily={'SimHei, SimSun, serif'} fill="#555">
        三个点的振动图（横轴 t，纵轴位移）
      </text>
      {/* 时间轴 */}
      <line x1={xa - 26} y1={y0} x2={xb + 24} y2={y0} stroke="#999" strokeWidth="1.6"
        strokeDasharray="8 6" />
      <text x={xb + 36} y={y0 + 8} fontSize="24" fontStyle="italic"
        fontFamily={'"Times New Roman", SimSun, serif'} fill="#555">t</text>

      {wave(76, 0, '#1F6FBF')}
      {wave(52, 0, '#12852F')}
      {wave(76, Math.PI, '#C00000')}

      {/* 说明线：取一个时刻，看三点位移方向 */}
      <line x1={xa + 120} y1="118" x2={xa + 120} y2="310" stroke="#B9B9B9" strokeWidth="1.4"
        strokeDasharray="6 6" />

      {/* 图例 */}
      <rect x="120" y="326" width="26" height="4" fill="#1F6FBF" />
      <text x="156" y="334" fontSize="21" fontFamily={'SimHei, SimSun, serif'} fill="#333">
        A 点（第 1 段）
      </text>
      <rect x="120" y="366" width="26" height="4" fill="#C00000" />
      <text x="156" y="374" fontSize="21" fontFamily={'SimHei, SimSun, serif'} fill="#333">
        B 点（第 2 段）与 A 反相
      </text>
      <rect x="120" y="400" width="26" height="4" fill="#12852F" />
      <text x="156" y="408" fontSize="21" fontFamily={'SimHei, SimSun, serif'} fill="#333">
        C 点（第 3 段）与 A 同相
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 10-5 P8：半波损失 —— 弦遇到固定端（波密介质）反射时相位突变 π，
 *  端点是波节；遇到自由端（波疏介质）没有突变，端点是波腹。
 *  每条曲线的包络用虚线画，弦本身用实线画在一个固定时刻。 */
export function HalfWaveLoss() {
  const xa = 96, xb = 512
  const lam = 240
  const kk = (2 * Math.PI) / lam
  /* 固定端：x = xb 处为节点，包络 ∝ sin(k(xb − x)) */
  const envA = (x: number) => 62 * Math.sin(kk * (xb - x))
  /* 自由端：x = xb 处为腹点，包络 ∝ cos(k(xb − x)) */
  const envB = (x: number) => 62 * Math.cos(kk * (xb - x))
  const curve = (f: (x: number) => number, y0: number, sign: number) => {
    const pts: string[] = []
    for (let i = 0; i <= 160; i++) {
      const x = xa + ((xb - xa) * i) / 160
      pts.push(`${x.toFixed(1)},${(y0 - sign * f(x)).toFixed(1)}`)
    }
    return pts.join(' ')
  }
  const yA = 136, yB = 356
  return (
    <svg viewBox="0 0 700 500" width="100%" height="100%">
      {/* ===== (a) 固定端 ===== */}
      <text x="96" y="40" fontSize="23" fontFamily={'SimHei, SimSun, serif'} fill="#333">
        （a）固定端（波密介质）：半波损失，端点是波节
      </text>
      <line x1={xa - 20} y1={yA} x2={xb + 16} y2={yA} stroke="#999" strokeWidth="1.5"
        strokeDasharray="8 6" />
      <polyline points={curve(envA, yA, 1)} fill="none" stroke="#B9B9B9" strokeWidth="2.2"
        strokeDasharray="8 6" />
      <polyline points={curve(envA, yA, -1)} fill="none" stroke="#B9B9B9" strokeWidth="2.2"
        strokeDasharray="8 6" />
      <polyline points={curve(envA, yA, 0.62)} fill="none" stroke="#1F6FBF" strokeWidth="4.4" />
      <line x1={xb} y1={yA - 96} x2={xb} y2={yA + 96} stroke="#555" strokeWidth="9" />
      <circle cx={xb} cy={yA} r="7" fill="#C00000" />
      <text x={xb + 12} y={yA + 28} fontSize="21" fontFamily={'SimHei, SimSun, serif'}
        fill="#C00000">波节</text>
      <text x="120" y={yA - 74} fontSize="21" fontFamily={'SimHei, SimSun, serif'}
        fill="#0A8A0A">入射 →</text>
      <text x="266" y={yA + 82} fontSize="21" fontFamily={'SimHei, SimSun, serif'}
        fill="#7B1FA2">← 反射（相位突变 π）</text>

      {/* ===== (b) 自由端 ===== */}
      <text x="96" y="286" fontSize="23" fontFamily={'SimHei, SimSun, serif'} fill="#333">
        （b）自由端（波疏介质）：无半波损失，端点是波腹
      </text>
      <line x1={xa - 20} y1={yB} x2={xb + 16} y2={yB} stroke="#999" strokeWidth="1.5"
        strokeDasharray="8 6" />
      <polyline points={curve(envB, yB, 1)} fill="none" stroke="#B9B9B9" strokeWidth="2.2"
        strokeDasharray="8 6" />
      <polyline points={curve(envB, yB, -1)} fill="none" stroke="#B9B9B9" strokeWidth="2.2"
        strokeDasharray="8 6" />
      <polyline points={curve(envB, yB, 0.62)} fill="none" stroke="#1F6FBF" strokeWidth="4.4" />
      <line x1={xb} y1={yB - 96} x2={xb} y2={yB + 96} stroke="#555" strokeWidth="9" />
      <circle cx={xb} cy={yB - 62} r="7" fill="#C00000" />
      <text x={xb + 16} y={yB - 40} fontSize="21" fontFamily={'SimHei, SimSun, serif'}
        fill="#C00000">波腹</text>
      <text x="300" y={yB + 130} fontSize="21" fontFamily={'SimHei, SimSun, serif'}
        fill="#7B1FA2">反射与入射同相（无半波损失）</text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 10-5 P9：弦的简正模式 —— 两端固定，长度 L 上必须容纳整数个半波。
 *  L = n·λ/2 ⇒ f_n = n·u/(2L)；n=1 是基频，其余是谐频。 */
export function StringModes() {
  const xa = 108, xb = 588
  const L = xb - xa
  const centers = [104, 288, 472]
  const amps = [56, 50, 44]
  return (
    <svg viewBox="0 0 700 590" width="100%" height="100%">
      <text x="96" y="22" fontSize="22" fontFamily={'SimHei, SimSun, serif'} fill="#555">
        两端固定的弦：L = n·λ/2（n = 1, 2, 3 …）
      </text>
      {centers.map((cy, i) => {
        const n = i + 1
        const pts: string[] = []
        for (let j = 0; j <= 220; j++) {
          const x = xa + (L * j) / 220
          const s = Math.sin((n * Math.PI * (x - xa)) / L)
          pts.push(`${x.toFixed(1)},${(cy - amps[i] * s).toFixed(1)}`)
        }
        return (
          <g key={cy}>
            {/* 两端固定 */}
            <line x1={xa} y1={cy - 64} x2={xa} y2={cy + 64} stroke="#555" strokeWidth="8" />
            <line x1={xb} y1={cy - 64} x2={xb} y2={cy + 64} stroke="#555" strokeWidth="8" />
            <line x1={xa} y1={cy} x2={xb} y2={cy} stroke="#CCC" strokeWidth="1.4"
              strokeDasharray="7 6" />
            <polyline points={pts.join(' ')} fill="none" stroke="#1F6FBF" strokeWidth="4.6" />
            <text x="612" y={cy - 4} fontSize="23" fontFamily={'SimHei, SimSun, serif'}
              fill="#333">n = {n}</text>
            <text x="612" y={cy + 26} fontSize="20" fontFamily={'"Times New Roman", SimSun, serif'}
              fill="#777">λ = {n === 1 ? '2L' : n === 2 ? 'L' : '2L/3'}</text>
            {/* 弦长 L 的尺寸线（只画在最下面一条） */}
            {i === 2 && (
              <g>
                <line x1={xa} y1={cy + 84} x2={xb} y2={cy + 84} stroke="#C00000" strokeWidth="2" />
                <polygon points={`${xa + 12},${cy + 84} ${xa},${cy + 78} ${xa},${cy + 90}`} fill="#C00000" />
                <polygon points={`${xb - 12},${cy + 84} ${xb},${cy + 78} ${xb},${cy + 90}`} fill="#C00000" />
                <text x={(xa + xb) / 2} y={cy + 116} textAnchor="middle" fontSize="23"
                  fontStyle="italic" fontFamily={'"Times New Roman", SimSun, serif'}
                  fill="#C00000">L</text>
              </g>
            )}
          </g>
        )
      })}
    </svg>
  )
}

