/** 11-3 P7：垂直入射的两种情形（上：n₂>n₁ 只有一次半波损失；下：n₃>n₂>n₁ 两次抵消）。 */
export function VerticalFilm() {
  const arrows = (x: number, yTop: number, yFilm: number) => (
    <g>
      <line x1={x} y1={yTop} x2={x} y2={yFilm - 6} stroke={OPT_RED} strokeWidth="3"
        markerEnd="url(#optArrowDown)" />
      <line x1={x + 26} y1={yTop + 30} x2={x + 26} y2={yFilm - 6} stroke={OPT_RED}
        strokeWidth="3" markerEnd="url(#optArrowDown)" />
      <line x1={x + 12} y1={yFilm - 8} x2={x + 12} y2={yTop} stroke="#E8821E" strokeWidth="3"
        markerEnd="url(#optArrowUp)" />
      <line x1={x + 40} y1={yFilm - 8} x2={x + 40} y2={yTop + 20} stroke="#E8821E"
        strokeWidth="3" markerEnd="url(#optArrowUp)" />
    </g>
  )
  return (
    <svg viewBox="280 80 580 690" width="100%" height="100%">
      <defs>
        <marker id="optArrowDown" markerWidth="8" markerHeight="8" refX="4" refY="7"
          orient="auto"><path d="M0,0 L8,0 L4,8 z" fill={OPT_RED} /></marker>
        <marker id="optArrowUp" markerWidth="8" markerHeight="8" refX="4" refY="1"
          orient="auto"><path d="M0,8 L8,8 L4,0 z" fill="#E8821E" /></marker>
      </defs>

      {/* 上：n2 > n1 */}
      <rect x="300" y="250" width="500" height="120" fill="#E8F2FC" stroke={OPT_BLUE}
        strokeWidth="2.4" />
      <text x="820" y="200" fontSize="30" fontFamily={SERIF} fill="#111">n₁</text>
      <text x="820" y="322" fontSize="30" fontFamily={SERIF} fill="#111">n₂</text>
      <text x="820" y="420" fontSize="30" fontFamily={SERIF} fill="#111">n₁</text>
      <text x="330" y="200" fontSize="26" fontFamily={HEI} fill="#555">n₂ &gt; n₁：只有上表面有半波损失</text>
      {arrows(470, 110, 250)}

      {/* 下：n3 > n2 > n1 */}
      <rect x="300" y="580" width="500" height="90" fill="#E8F2FC" stroke={OPT_BLUE}
        strokeWidth="2.4" />
      <rect x="300" y="670" width="500" height="70" fill="#DDF0DC" stroke="#2E8B57"
        strokeWidth="2.4" />
      <text x="820" y="540" fontSize="30" fontFamily={SERIF} fill="#111">n₁</text>
      <text x="820" y="632" fontSize="30" fontFamily={SERIF} fill="#111">n₂</text>
      <text x="820" y="716" fontSize="30" fontFamily={SERIF} fill="#111">n₃</text>
      <text x="330" y="540" fontSize="26" fontFamily={HEI} fill="#555">n₃ &gt; n₂ &gt; n₁：两次半波损失相互抵消</text>
      {arrows(470, 450, 580)}
    </svg>
  )
}

