/* ============ 2-1 牛顿定律 图示 ============ */

/** 10-6 P4：观察者运动、波源静止 —— 波前是以波源为圆心的同心圆，
 *  相邻波前间距恒为 λ = u/ν；观察者迎着波走，单位时间遇到的波前变多。 */
export function DopplerObserver() {
  const sx = 230, sy = 210
  return (
    <svg viewBox="0 0 700 420" width="100%" height="100%">
      {/* 波前：同心圆 */}
      {[45, 90, 135, 180].map((r, i) => (
        <circle key={r} cx={sx} cy={sy} r={r} fill="none" stroke="#9DBBE6"
          strokeWidth="2.6" opacity={0.95 - i * 0.12} />
      ))}
      {/* 波源 */}
      <circle cx={sx} cy={sy} r="9" fill="#C00000" />
      <text x={sx} y={sy + 40} textAnchor="middle" fontSize="23"
        fontFamily={'SimHei, SimSun, serif'} fill="#C00000">波源</text>

      {/* 观察者 */}
      <circle cx="470" cy={sy} r="9" fill="#0A8A0A" />
      <line x1="470" y1={sy} x2="396" y2={sy} stroke="#0A8A0A" strokeWidth="4.6" />
      <polygon points="376,210 400,200 400,220" fill="#0A8A0A" />
      <text x="500" y={sy - 22} fontSize="24" fontStyle="italic"
        fontFamily={'"Times New Roman", SimSun, serif'} fill="#0A8A0A">
        v<tspan dy="6" fontSize="17">R</tspan>
      </text>
      <text x="470" y={sy + 44} textAnchor="middle" fontSize="23"
        fontFamily={'SimHei, SimSun, serif'} fill="#0A8A0A">观察者迎着波走</text>

      {/* λ：在 y=300 这条线上，左侧相邻两圈的间距 */}
      <line x1="74" y1="300" x2="129" y2="300" stroke="#333" strokeWidth="2" />
      <polygon points="86,300 74,294 74,306" fill="#333" />
      <polygon points="117,300 129,294 129,306" fill="#333" />
      <text x="101" y="282" textAnchor="middle" fontSize="23" fontStyle="italic"
        fontFamily={'"Times New Roman", SimSun, serif'} fill="#333">λ</text>

      {/* 说明 */}
      <text x="96" y="360" fontSize="23" fontFamily={'SimHei, SimSun, serif'} fill="#333">
        单位时间内遇到的波前数
      </text>
      <text x="96" y="402" fontSize="25" fontFamily={'"Times New Roman", SimSun, serif'}
        fill="#C00000">
        (u + v<tspan dy="6" fontSize="18">R</tspan><tspan dy="-6">) / λ</tspan>
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 10-6 P5：波源运动、观察者静止 —— 波前不再同心：
 *  波源向前发出的波前被挤密（λ′ 变短），身后的被拉开（λ″ 变长）。
 *  圆心取波源「发射该波前时所处的位置」，半径 = u × 已经过的时间。 */
export function DopplerSource() {
  const x0 = 400, y0 = 180
  const U = 42, VS = 21              // u 与 v_S 的画图比例
  const circles = [1, 2, 3, 4].map((i) => ({
    cx: x0 - VS * i,
    cy: y0,
    r: U * i,
  }))
  return (
    <svg viewBox="0 0 700 430" width="100%" height="100%">
      {circles.map((c, i) => (
        <circle key={i} cx={c.cx} cy={c.cy} r={c.r} fill="none" stroke="#9DBBE6"
          strokeWidth="2.4" opacity={0.95 - i * 0.13} />
      ))}
      {/* 波源与速度 */}
      <circle cx={x0} cy={y0} r="9" fill="#C00000" />
      <line x1={x0 + 10} y1={y0} x2={x0 + 46} y2={y0} stroke="#C00000" strokeWidth="4.6" />
      <polygon points={`${x0 + 66},${y0} ${x0 + 42},${y0 - 10} ${x0 + 42},${y0 + 10}`} fill="#C00000" />
      <text x={x0 + 22} y={y0 - 16} fontSize="24" fontStyle="italic"
        fontFamily={'"Times New Roman", SimSun, serif'} fill="#C00000">
        v<tspan dy="6" fontSize="17">S</tspan>
      </text>

      {/* 前方波前挤密：λ′ */}
      <line x1="459" y1="148" x2="481" y2="148" stroke="#333" strokeWidth="2" />
      <polygon points="468,148 459,143 459,153" fill="#333" />
      <polygon points="472,148 481,143 481,153" fill="#333" />
      <text x="470" y="130" textAnchor="middle" fontSize="23" fontStyle="italic"
        fontFamily={'"Times New Roman", SimSun, serif'} fill="#333">λ′</text>

      {/* 后方波前拉开：λ″ */}
      <line x1="151" y1="148" x2="215" y2="148" stroke="#333" strokeWidth="2" />
      <polygon points="163,148 151,143 151,153" fill="#333" />
      <polygon points="203,148 215,143 215,153" fill="#333" />
      <text x="183" y="130" textAnchor="middle" fontSize="23" fontStyle="italic"
        fontFamily={'"Times New Roman", SimSun, serif'} fill="#333">λ″</text>

      {/* 观察者 */}
      <circle cx="566" cy={y0} r="9" fill="#0A8A0A" />
      <text x="566" y={y0 + 40} textAnchor="middle" fontSize="23"
        fontFamily={'SimHei, SimSun, serif'} fill="#0A8A0A">观察者（静止）</text>

      {/* 说明 */}
      <text x="96" y="382" fontSize="23" fontFamily={'SimHei, SimSun, serif'} fill="#333">
        前进方向波前挤密 ⇒ λ′ 变短 ⇒ 接收频率变高
      </text>
      <text x="96" y="416" fontSize="23" fontFamily={'SimHei, SimSun, serif'} fill="#777">
        身后波前拉开 ⇒ λ″ 变长 ⇒ 频率变低
      </text>
    </svg>
  )
}

