/** 11-6 P3：半波带法——缝上波阵面按 λ/2 分成若干带，相邻带两两相消。 */
export function HalfZone() {
  const draw = (ox: number, n: number, color: string, caption: string, sub: string) => {
    const top = 150
    const bot = 470
    const h = (bot - top) / n
    return (
      <g>
        {/* 缝 */}
        <rect x={ox} y={top - 40} width="18" height="40" fill="#C9A227" />
        <rect x={ox} y={bot} width="18" height="40" fill="#C9A227" />
        {Array.from({ length: n }, (_, i) => (
          <rect key={i} x={ox} y={top + i * h} width="18" height={h} fill={color}
            opacity="0.85" stroke="#8a6d1a" strokeWidth="1" />
        ))}
        {/* 波阵面（斜线） */}
        <line x1={ox + 18} y1={top} x2={ox + 18 + (bot - top) * 0.45} y2={bot}
          stroke={OPT_RED} strokeWidth="3" />
        <text x={ox + 18} y={top - 52} fontSize="26" fontFamily={SERIF} fill="#111">A</text>
        <text x={ox + 18} y={bot + 44} fontSize="26" fontFamily={SERIF} fill="#111">B</text>
        <text x={ox - 54} y={(top + bot) / 2} fontSize="26" fontStyle="italic"
          fontFamily={SERIF} fill="#111">b</text>
        <line x1={ox - 30} y1={top} x2={ox - 30} y2={bot} stroke="#111" strokeWidth="1.8" />
        <text x={ox + 30} y={(top + bot) / 2 + 8} fontSize="26" fontFamily={HEI} fill="#111">
          {n} 个半波带
        </text>
        <text x={ox} y={bot + 116} fontSize="30" fontFamily={HEI} fill={n === 2 ? OPT_RED : OPT_BLUE}>
          {caption}
        </text>
        <text x={ox} y={bot + 158} fontSize="26" fontFamily={SERIF} fill="#333">{sub}</text>
      </g>
    )
  }
  return (
    <svg viewBox="0 0 1100 640" width="100%" height="100%">
      {draw(200, 2, '#F7C6C6', "两带相消 → 暗纹", "b sin θ = 2 · λ/2 = λ")}
      {draw(620, 3, "#DDF0DC", "剩一带 → 明纹", "b sin θ = 3 · λ/2")}
      <text x="560" y="620" textAnchor="middle" fontSize="24" fontFamily={HEI} fill="#666">
        把缝上的波阵面按 λ/2 划分：相邻两带的光程差恰为 λ/2，互相抵消
      </text>
    </svg>
  )
}

/** 11-6 P5：单缝衍射的光强分布与条纹图样。 */
export function SlitPattern() {
  const W = 1000
  const mid = 300
  const pts: string[] = []
  for (let i = 0; i <= 400; i++) {
    const t = (i / 400) * 12 - 6
    const u = t * 0.9
    const I = u === 0 ? 1 : Math.pow(Math.sin(u) / u, 2)
    pts.push(`${60 + (i / 400) * W},${mid - I * 200}`)
  }
  return (
    <svg viewBox="0 0 1120 520" width="100%" height="100%">
      {/* 图样 */}
      <rect x="60" y="60" width={W} height="70" fill="#151515" />
      <rect x={60 + W / 2 - 84} y="60" width="168" height="70" fill="#F2C230" />
      {[1, 2, 3, 4].map((k) => (
        <g key={k}>
          <rect x={60 + W / 2 - 84 - k * 84 - 26} y="60" width="52" height="70" fill="#C98A10"
            opacity={0.85 - k * 0.15} />
          <rect x={60 + W / 2 + 84 + k * 84 - 26} y="60" width="52" height="70" fill="#C98A10"
            opacity={0.85 - k * 0.15} />
        </g>
      ))}
      {/* 光强曲线 */}
      <line x1="60" y1={mid} x2={60 + W} y2={mid} stroke="#666" strokeWidth="1.8" />
      <line x1="60" y1="90" x2="60" y2={mid} stroke="#666" strokeWidth="1.8" />
      <polyline points={pts.join(' ')} fill="none" stroke={OPT_RED} strokeWidth="3" />
      <text x="20" y="120" fontSize="24" fontFamily={SERIF} fill="#555">I</text>
      <text x={60 + W + 8} y={mid + 8} fontSize="24" fontFamily={SERIF} fill="#555">sinθ</text>
      <text x={60 + W / 2} y={mid + 44} textAnchor="middle" fontSize="24" fontFamily={HEI}
        fill="#555">0</text>
      <text x="150" y="470" fontSize="24" fontFamily={HEI} fill="#555">
        中央明纹最宽最亮，两侧依次减弱
      </text>
    </svg>
  )
}

/** 11-6 P9：中央明纹宽度——屏上两个第一暗纹之间，宽 2fλ/b。 */
