/** 12-1 P6：三条实验定律在 p–V 图上的样子 —— 等温是双曲线、等压是水平线、等容是竖线。 */
export function GasLawsPV() {
  const pts: string[] = []
  for (let x = 175; x <= 400; x += 4) {
    pts.push(`${x},${(352 - 42000 / x).toFixed(1)}`)
  }
  return (
    <svg viewBox="0 0 700 440" width="100%" height="100%">
      {/* 坐标轴 */}
      <Arrow x1={110} y1={352} x2={620} y2={352} color="#333" w={2.6} />
      <Arrow x1={110} y1={352} x2={110} y2={60} color="#333" w={2.6} />
      <text x="86" y="66" textAnchor="end" fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#333">p</text>
      <text x="632" y="364" fontSize="26" fontStyle="italic" fontFamily={SERIF} fill="#333">V</text>
      <text x="94" y="374" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#333">O</text>

      {/* 等温线：pV = C（双曲线的一段） */}
      <polyline points={pts.join(' ')} fill="none" stroke="#C00000" strokeWidth="3.4" />
      <text x="404" y="268" fontSize="24" fontFamily={SERIF} fill="#C00000">pV = C</text>

      {/* 等压线：p = C（水平） */}
      <Arrow x1={158} y1={300} x2={578} y2={300} color="#0000CD" w={3.2} />
      <text x="160" y="290" fontSize="24" fontFamily={SERIF} fill="#0000CD">p = C</text>

      {/* 等容线：V = C（竖直） */}
      <Arrow x1={320} y1={334} x2={320} y2={104} color="#12852F" w={3.2} />
      <text x="330" y="96" fontSize="24" fontFamily={SERIF} fill="#12852F">V = C</text>

      {/* 一个点 = 一个平衡态 */}
      <circle cx="320" cy="300" r="5.5" fill="#333" />
      <text x="334" y="326" fontSize="21" fontFamily={HEI} fill="#333">状态点</text>
    </svg>
  )
}

