/** 12-1 P9：标准状况下的分子数与分子间距 —— 每个分子分到一个小立方格，
 *  格子边长 l 比分子直径 d 大一个数量级，气体的「空」就在这里。 */
export function MoleculeSpacing() {
  const cells: [number, number][] = []
  for (const x of [70, 190, 310]) for (const y of [90, 210]) cells.push([x, y])
  return (
    <svg viewBox="0 0 700 430" width="100%" height="100%">
      {/* 3×2 个小立方格 */}
      {cells.map(([x, y], i) => (
        <g key={i}>
          <rect x={x} y={y} width="120" height="120" fill="#F7FBFF" stroke="#CFE0F2" strokeWidth="1.6" />
          <circle cx={x + 60} cy={y + 60} r="7" fill="#1F6FBF" />
        </g>
      ))}

      {/* l：格子边长 */}
      <line x1="70" y1="76" x2="190" y2="76" stroke="#333" strokeWidth="1.8" />
      <line x1="70" y1="70" x2="70" y2="82" stroke="#333" strokeWidth="1.8" />
      <line x1="190" y1="70" x2="190" y2="82" stroke="#333" strokeWidth="1.8" />
      <text x="130" y="64" textAnchor="middle" fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#333">l</text>

      {/* 放大一格：d 是分子直径 */}
      <rect x="470" y="100" width="200" height="200" fill="#FAFCFF" stroke="#9DBBE6"
        strokeWidth="1.6" strokeDasharray="8 7" />
      <circle cx="570" cy="200" r="26" fill="#1F6FBF" />
      <line x1="544" y1="200" x2="544" y2="262" stroke="#666" strokeWidth="1.5" />
      <line x1="596" y1="200" x2="596" y2="262" stroke="#666" strokeWidth="1.5" />
      <line x1="544" y1="252" x2="596" y2="252" stroke="#666" strokeWidth="1.8" />
      <polygon points="544,252 554,246 554,258" fill="#666" />
      <polygon points="596,252 586,246 586,258" fill="#666" />
      <text x="570" y="286" textAnchor="middle" fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#333">d</text>
      <text x="570" y="330" textAnchor="middle" fontSize="21" fontFamily={HEI} fill="#7A8699">
        把一格放大看
      </text>

      {/* 结论（图内只放关系式） */}
      <text x="70" y="376" fontSize="23" fontFamily={HEI} fill="#333">
        格子边长 <tspan fontStyle="italic" fontFamily={SERIF}>l</tspan>，分子直径 <tspan fontStyle="italic" fontFamily={SERIF}>d</tspan>
      </text>
      <text x="70" y="414" fontSize="26" fontFamily={SERIF} fill="#C00000">
        <tspan fontStyle="italic">l</tspan> ≈ 10 <tspan fontStyle="italic">d</tspan>
      </text>
      <text x="390" y="414" fontSize="22" fontFamily={HEI} fill="#7A8699">
        体积只占千分之一
      </text>
    </svg>
  )
}

