/** 12-2 P4：分子在两壁之间往返，撞同一面壁的间隔就是 2l/v_x（右图 x–t 的三角波）。 */
export function WallImpact() {
  const t0 = 378, t1 = 664
  const yb = 290, yt = 150
  const pts: string[] = []
  let up = true, x = t0, y = yb
  pts.push(`${x},${y}`)
  while (x < t1 - 40) {
    x += 46
    y = up ? yt : yb
    pts.push(`${x},${y}`)
    up = !up
  }
  return (
    <svg viewBox="0 0 700 420" width="100%" height="100%">
      {/* ---------- 左：两壁之间的一维往返 ---------- */}
      <rect x="56" y="150" width="9" height="150" fill="#8899AA" />
      <rect x="295" y="150" width="9" height="150" fill="#8899AA" />
      <circle cx="240" cy="225" r="8.5" fill="#C00000" />
      <line x1="240" y1="225" x2="284" y2="225" stroke="#C00000" strokeWidth="3" />
      <polygon points="292,225 278,219 278,231" fill="#C00000" />
      <text x="250" y="206" fontSize="25" fontStyle="italic" fontFamily={SERIF} fill="#C00000">
        v<tspan dy="5" fontSize="15" fontStyle="normal">x</tspan>
      </text>

      {/* 边长 l */}
      <line x1="60" y1="322" x2="300" y2="322" stroke="#333" strokeWidth="1.8" />
      <line x1="60" y1="314" x2="60" y2="330" stroke="#333" strokeWidth="1.8" />
      <line x1="300" y1="314" x2="300" y2="330" stroke="#333" strokeWidth="1.8" />
      <text x="180" y="352" textAnchor="middle" fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#333">l</text>

      {/* ---------- 右：x–t 图，撞壁间隔 Δt ---------- */}
      <Arrow x1={t0} y1={320} x2={t1} y2={320} color="#666" w={2.2} />
      <Arrow x1={t0} y1={320} x2={t0} y2={118} color="#666" w={2.2} />
      <text x={t0 - 16} y="114" textAnchor="end" fontSize="24" fontStyle="italic"
        fontFamily={SERIF} fill="#444">x</text>
      <text x={t1 + 8} y="328" fontSize="24" fontStyle="italic" fontFamily={SERIF}
        fill="#444">t</text>

      <line x1={t0} y1={yt} x2={t1} y2={yt} stroke="#C9D4E2" strokeWidth="1.4"
        strokeDasharray="7 6" />
      <line x1={t0} y1={yb} x2={t1} y2={yb} stroke="#C9D4E2" strokeWidth="1.4"
        strokeDasharray="7 6" />
      <text x={t0 - 14} y={yt + 7} textAnchor="end" fontSize="24" fontStyle="italic"
        fontFamily={SERIF} fill="#666">l</text>
      <text x={t0 - 14} y={yb + 7} textAnchor="end" fontSize="22" fontFamily={SERIF}
        fill="#666">0</text>

      <polyline points={pts.join(' ')} fill="none" stroke="#1F6FBF" strokeWidth="3.2" />
      <circle cx={t0 + 46} cy={yt} r="4.6" fill="#C00000" />
      <circle cx={t0 + 138} cy={yt} r="4.6" fill="#C00000" />
      <circle cx={t0 + 230} cy={yt} r="4.6" fill="#C00000" />

      {/* Δt：相邻两次撞壁的间隔 */}
      <line x1={t0 + 46} y1="320" x2={t0 + 46} y2="332" stroke="#C00000" strokeWidth="1.8" />
      <line x1={t0 + 138} y1="320" x2={t0 + 138} y2="332" stroke="#C00000" strokeWidth="1.8" />
      <text x={t0 + 92} y="360" textAnchor="middle" fontSize="24" fontFamily={SERIF}
        fill="#C00000">Δt</text>
    </svg>
  )
}

