/** 12-2 P8：压强是统计量 —— 分子数少时读数上下跳（涨落大），分子数多时几乎是一条直线。 */
export function PressureFluctuation() {
  const rnd = (k: number) => {
    const v = Math.sin(k * 12.9898 + 4.1414) * 43758.5453
    return v - Math.floor(v)
  }
  const n = 44
  const px = (i: number) => 100 + (i * 540) / (n - 1)
  const small = Array.from({ length: n }, (_, i) => `${px(i).toFixed(1)},${(210 + (rnd(i + 1) - 0.5) * 72).toFixed(1)}`)
  const big = Array.from({ length: n }, (_, i) => `${px(i).toFixed(1)},${(210 + (rnd(i + 61) - 0.5) * 15).toFixed(1)}`)
  return (
    <svg viewBox="0 0 700 420" width="100%" height="100%">
      {/* 坐标轴 */}
      <Arrow x1={90} y1={320} x2={660} y2={320} color="#666" w={2.2} />
      <Arrow x1={90} y1={320} x2={90} y2={100} color="#666" w={2.2} />
      <text x={666} y="330" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#444">t</text>
      <text x={78} y="96" textAnchor="end" fontSize="24" fontStyle="italic"
        fontFamily={SERIF} fill="#444">p</text>

      {/* 平均值 */}
      <line x1="96" y1="210" x2="652" y2="210" stroke="#9AA7B8" strokeWidth="1.5"
        strokeDasharray="8 7" />
      <line x1="58" y1="192" x2="80" y2="192" stroke="#9AA7B8" strokeWidth="2" />
      <text x={70} y="212" textAnchor="middle" fontSize="22" fontStyle="italic"
        fontFamily={SERIF} fill="#77839A">p</text>

      {/* 两条曲线 */}
      <polyline points={big.join(' ')} fill="none" stroke="#1F6FBF" strokeWidth="2.6" />
      <polyline points={small.join(' ')} fill="none" stroke="#C00000" strokeWidth="2.2"
        opacity="0.85" />

      {/* 图例 */}
      <line x1="100" y1="356" x2="140" y2="356" stroke="#C00000" strokeWidth="3" />
      <text x="152" y="364" fontSize="22" fontFamily={HEI} fill="#333">N 小：读数上下跳</text>
      <line x1="100" y1="392" x2="140" y2="392" stroke="#1F6FBF" strokeWidth="3" />
      <text x="152" y="400" fontSize="22" fontFamily={HEI} fill="#333">N 大：几乎一条直线</text>
    </svg>
  )
}

