/** 11-8 P6：缝数越多，主极大越细越亮。 */
export function GratingPeaks() {
  const draw = (ox: number, N: number, label: string) => {
    const W = 300
    const base = 300
    const pts: string[] = []
    for (let i = 0; i <= 600; i++) {
      const t = (i / 600) * 12 - 6 // -6..6
      const u = Math.PI * t * 0.5
      const env = Math.abs(t) < 1e-6 ? 1 : Math.pow(Math.sin(u) / u, 2)
      let inter: number
      if (Math.abs(t - Math.round(t)) < 1e-6) inter = 1
      else {
        const d2 = Math.PI * t
        const s = Math.sin((N * d2) / 2) / (N * Math.sin(d2 / 2))
        inter = s * s
      }
      const I = env * inter
      pts.push(`${ox + (i / 600) * W},${base - I * 190}`)
    }
    return (
      <g>
        <line x1={ox} y1={base} x2={ox + W} y2={base} stroke="#999" strokeWidth="1.4" />
        <polyline points={pts.join(' ')} fill="none" stroke={OPT_RED} strokeWidth="2" />
        <text x={ox + W / 2} y={base + 34} textAnchor="middle" fontSize="24"
          fontFamily={HEI} fill="#111">{label}</text>
      </g>
    )
  }
  return (
    <svg viewBox="0 80 1100 380" width="100%" height="100%">
      {draw(60, 2, '2 条缝')}
      {draw(400, 6, '6 条缝')}
      {draw(740, 20, '20 条缝')}
    </svg>
  )
}

/** 11-8 P5：缺级——d/b = 3 时，第 3 级（及 6、9 级）主极大被单缝衍射的零点吃掉。 */
