/* ============ 2-1 牛顿定律 图示 ============ */

/** 12-3 P5：能量按自由度均分 —— 每个自由度一格 kT/2，双原子分子排成 3+2 五格。 */
export function Equipartition() {
  const seg = 100
  const x0 = 70
  const yT = 112, yB = 172
  const groups = [
    { n: 3, fill: '#1F6FBF', label: '平动 3' },
    { n: 2, fill: '#E08A1E', label: '转动 2' },
  ]
  let x = x0
  const segs: { x: number; fill: string }[] = []
  for (const g of groups) {
    for (let i = 0; i < g.n; i++) { segs.push({ x, fill: g.fill }); x += seg }
  }
  return (
    <svg viewBox="0 0 700 322" width="100%" height="100%">
      <text x={x0} y="84" fontSize="21" fontFamily={HEI} fill="#5B7290">
        以双原子分子为例（i = 5）
      </text>

      {segs.map((s, i) => (
        <g key={i}>
          <rect x={s.x} y={yT} width={seg - 4} height={yB - yT} rx="6" fill={s.fill} opacity="0.9" />
          <text x={s.x + (seg - 4) / 2} y={(yT + yB) / 2 + 8} textAnchor="middle" fontSize="22"
            fontFamily={SERIF} fill="#FFFFFF">kT/2</text>
        </g>
      ))}

      {/* 两组括号 */}
      <line x1={x0} y1={yB + 22} x2={x0 + 3 * seg - 4} y2={yB + 22} stroke="#1F6FBF" strokeWidth="2" />
      <line x1={x0} y1={yB + 14} x2={x0} y2={yB + 30} stroke="#1F6FBF" strokeWidth="2" />
      <line x1={x0 + 3 * seg - 4} y1={yB + 14} x2={x0 + 3 * seg - 4} y2={yB + 30}
        stroke="#1F6FBF" strokeWidth="2" />
      <text x={(x0 + x0 + 3 * seg) / 2 - 2} y={yB + 54} textAnchor="middle" fontSize="22"
        fontFamily={HEI} fill="#1F6FBF">平动 3</text>

      <line x1={x0 + 3 * seg} y1={yB + 22} x2={x0 + 5 * seg - 4} y2={yB + 22}
        stroke="#E08A1E" strokeWidth="2" />
      <line x1={x0 + 3 * seg} y1={yB + 14} x2={x0 + 3 * seg} y2={yB + 30}
        stroke="#E08A1E" strokeWidth="2" />
      <line x1={x0 + 5 * seg - 4} y1={yB + 14} x2={x0 + 5 * seg - 4} y2={yB + 30}
        stroke="#E08A1E" strokeWidth="2" />
      <text x={(x0 + 3 * seg + x0 + 5 * seg) / 2 - 2} y={yB + 54} textAnchor="middle" fontSize="22"
        fontFamily={HEI} fill="#E08A1E">转动 2</text>

      <text x="350" y="294" textAnchor="middle" fontSize="24" fontFamily={SERIF} fill="#333">
        ε = <tspan fontStyle="italic">i</tspan> × kT / 2
      </text>
    </svg>
  )
}

