/** 12-3 P8：理想气体内能只随温度变 —— U–T 是一条过原点的直线，斜率随自由度 i 增大。 */
export function UvsT() {
  const ox = 100, oy = 360
  const ex = 600
  const v = [3, 5, 6]
  const yEnd = (i: number) => 360 - 44 * i
  return (
    <svg viewBox="0 0 700 440" width="100%" height="100%">
      <Arrow x1={ox} y1={oy} x2={640} y2={oy} color="#666" w={2.2} />
      <Arrow x1={ox} y1={oy} x2={ox} y2={70} color="#666" w={2.2} />
      <text x={648} y={370} fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#444">T</text>
      <text x={86} y={66} textAnchor="end" fontSize="24" fontStyle="italic"
        fontFamily={SERIF} fill="#444">U</text>
      <text x={ox - 12} y={382} textAnchor="end" fontSize="22" fontFamily={SERIF} fill="#666">O</text>

      {/* 一条等温虚线，说明同一温度下不同气体内能不同 */}
      <line x1="400" y1="360" x2="400" y2="190" stroke="#C9D4E2" strokeWidth="1.5"
        strokeDasharray="7 6" />
      <text x="400" y="386" textAnchor="middle" fontSize="21" fontFamily={SERIF} fill="#8A95A5">T₁</text>

      {v.map((i, k) => (
        <g key={i}>
          <line x1={ox} y1={oy} x2={ex} y2={yEnd(i)}
            stroke={k === 0 ? '#1F6FBF' : k === 1 ? '#C00000' : '#12852F'} strokeWidth="3" />
          <circle cx="400" cy={oy - (oy - yEnd(i)) * 0.6} r="5" fill={k === 0 ? '#1F6FBF' : k === 1 ? '#C00000' : '#12852F'} />
          <text x={ex + 10} y={yEnd(i) + 8} fontSize="23" fontFamily={SERIF}
            fill={k === 0 ? '#1F6FBF' : k === 1 ? '#C00000' : '#12852F'}>i = {i}</text>
        </g>
      ))}
    </svg>
  )
}

