/** 11-9 P2：横波与纵波的区别——只有横波才有偏振。 */
export function TransverseLongitudinalPanel() {
  const waveY = (x: number) => 210 - 60 * Math.sin((x - 120) / 55)
  const pts: string[] = []
  for (let x = 120; x <= 620; x += 6) pts.push(`${x},${waveY(x)}`)
  return (
    <svg viewBox="0 0 1200 560" width="100%" height="100%">
      {/* 左：横波 + 竖直狭缝 */}
      <text x="120" y="70" fontSize="28" fontFamily={HEI} fill="#111">横波（光波）</text>
      <polyline points={pts.join(' ')} fill="none" stroke={OPT_BLUE} strokeWidth="3.4" />
      {[200, 300, 400, 500].map((x, i) => (
        <line key={x} x1={x} y1={waveY(x)} x2={x} y2={waveY(x) - 46 - (i % 2) * 10}
          stroke={OPT_RED} strokeWidth="2.6" markerEnd="url(#tlArrow)" />
      ))}
      <defs>
        <marker id="tlArrow" markerWidth="8" markerHeight="8" refX="4" refY="7" orient="auto">
          <path d="M0,0 L8,0 L4,8 z" fill={OPT_RED} />
        </marker>
      </defs>
      <rect x="640" y="110" width="18" height="90" fill="#8B5A2B" />
      <rect x="640" y="270" width="18" height="90" fill="#8B5A2B" />
      <text x="660" y="240" fontSize="24" fontFamily={HEI} fill="#555">竖直狭缝</text>

      {/* 右：纵波 + 狭缝 */}
      <text x="760" y="70" fontSize="28" fontFamily={HEI} fill="#111">纵波（声波）</text>
      <line x1="760" y1="420" x2="1120" y2="420" stroke={OPT_BLUE} strokeWidth="3.4" />
      {Array.from({ length: 9 }, (_, i) => (
        <line key={i} x1={770 + i * 38} y1="404" x2={770 + i * 38} y2="436" stroke={OPT_VIOLET}
          strokeWidth="4" />
      ))}
      <rect x="1100" y="360" width="16" height="120" fill="#8B5A2B" opacity="0.6" />
      <text x="780" y="480" fontSize="24" fontFamily={HEI} fill="#555">
        纵波：狭缝方向不影响通过
      </text>

      <text x="120" y="330" fontSize="24" fontFamily={HEI} fill="#555">
        振动方向竖直时可通过；转到水平就被挡住
      </text>
      <text x="120" y="380" fontSize="26" fontFamily={HEI} fill={OPT_RED}>
        只有横波才有偏振现象
      </text>
    </svg>
  )
}

