﻿/* ============ 11-10 反射光和折射光的偏振 图示 ============ */

const dot = (x: number, y: number, c = OPT_RED) => (
  <circle cx={x} cy={y} r="5" fill={c} />
)
const tick = (x: number, y: number, ang: number, c = OPT_BLUE) => {
  const dx = Math.cos(ang) * 11
  const dy = Math.sin(ang) * 11
  return <line x1={x - dx} y1={y - dy} x2={x + dx} y2={y + dy} stroke={c} strokeWidth="3" />
}

