/** 11-13 P4：三种液晶相的分子排列（近晶 / 向列 / 胆甾）。 */
export function LcPhases() {
  const rod = (x: number, y: number, ang: number, c: string) => (
    <line x1={x - 16 * Math.cos(ang)} y1={y - 16 * Math.sin(ang)}
      x2={x + 16 * Math.cos(ang)} y2={y + 16 * Math.sin(ang)}
      stroke={c} strokeWidth="6" strokeLinecap="round" />
  )
  return (
    <svg viewBox="0 0 1200 560" width="100%" height="100%">
      {/* 近晶型 */}
      <text x="60" y="60" fontSize="28" fontFamily={HEI} fill="#111">近晶型（层状）</text>
      {[120, 190, 260, 330, 400].map((y) => (
        <g key={y}>
          {[110, 160, 210, 260, 310].map((x) => rod(x, y, 0, OPT_BLUE))}
        </g>
      ))}
      <text x="60" y="470" fontSize="22" fontFamily={HEI} fill="#666">分子成层，层内平行</text>

      {/* 向列型 */}
      <text x="450" y="60" fontSize="28" fontFamily={HEI} fill="#111">向列型（丝状）</text>
      {[110, 160, 210, 260, 310, 360, 410].map((y) => (
        <g key={y}>
          {[470, 520, 570, 620, 670].map((x) => rod(x, y + (x % 40) * 0.4, 0, OPT_RED))}
        </g>
      ))}
      <text x="450" y="470" fontSize="22" fontFamily={HEI} fill="#666">平行排列但不分层</text>

      {/* 胆甾型 */}
      <text x="810" y="60" fontSize="28" fontFamily={HEI} fill="#111">胆甾型（螺旋）</text>
      {[110, 160, 210, 260, 310, 360, 410].map((y, i) => {
        const ang = (i * 18 * Math.PI) / 180
        return (
          <g key={y}>
            {[840, 890, 940, 990].map((x) => rod(x, y, ang, OPT_VIOLET))}
          </g>
        )
      })}
      <text x="810" y="470" fontSize="22" fontFamily={HEI} fill="#666">逐层旋转，形成螺旋</text>
    </svg>
  )
}

/** 11-13 P7：扭曲向列液晶盒——无电场时偏振面旋转 90°，有电场时不旋转。 */
export function TnLcd() {
  const panel = (ox: number, twisted: boolean, title: string, result: string, ok: boolean, idx: number) => (
    <g>
      <text x={ox} y="60" fontSize="26" fontFamily={HEI} fill="#111">{title}</text>
      {/* 起偏器 */}
      <rect x={ox} y="90" width="22" height="260" fill="#BFE9E2" stroke="#2E8B57"
        strokeWidth="2.2" />
      {[110, 145, 180, 215, 250, 285, 320].map((y) => (
        <line key={y} x1={ox + 3} y1={y} x2={ox + 19} y2={y} stroke="#2E8B57"
          strokeWidth="1.4" />
      ))}
      <text x={ox - 4} y="376" fontSize="20" fontFamily={HEI} fill="#555">起偏器</text>

      {/* 液晶盒 */}
      <rect x={ox + 70} y="90" width="150" height="260" fill="#EEF6FB" stroke="#5A7FB0"
        strokeWidth="2" />
      {Array.from({ length: 5 }, (_, i) => {
        const y = 130 + i * 55
        const ang = twisted ? ((-90 + i * 22.5) * Math.PI) / 180 : 0
        const cx = ox + 145
        return (
          <line key={i} x1={cx - 22 * Math.cos(ang)} y1={y - 22 * Math.sin(ang)}
            x2={cx + 22 * Math.cos(ang)} y2={y + 22 * Math.sin(ang)}
            stroke={OPT_VIOLET} strokeWidth="4" />
        )
      })}
      <text x={ox + 96} y="376" fontSize="20" fontFamily={HEI} fill="#555">液晶盒</text>

      {/* 检偏器（与起偏器平行） */}
      <rect x={ox + 268} y="90" width="22" height="260" fill="#BFE9E2" stroke="#2E8B57"
        strokeWidth="2.2" />
      {[110, 145, 180, 215, 250, 285, 320].map((y) => (
        <line key={y} x1={ox + 271} y1={y} x2={ox + 287} y2={y} stroke="#2E8B57"
          strokeWidth="1.4" />
      ))}
      <text x={ox + 262} y="376" fontSize="20" fontFamily={HEI} fill="#555">检偏器</text>

      {/* 光 */}
      <line x1={ox - 60} y1="220" x2={ox - 2} y2="220" stroke={ok ? OPT_RED : '#999'}
        strokeWidth="3" markerEnd={`url(#tnArrow${idx})`} />
      <line x1={ox + 292} y1="220" x2={ox + 360} y2="220" stroke={ok ? OPT_RED : '#999'}
        strokeWidth={ok ? 3 : 1.2} strokeDasharray={ok ? undefined : '6 6'}
        markerEnd={`url(#tnArrow${idx})`} />
      <text x={ox} y="430" fontSize="22" fontFamily={HEI} fill={ok ? OPT_RED : '#555'}>
        {result}
      </text>
      <defs>
        <marker id={`tnArrow${idx}`} markerWidth="9" markerHeight="9" refX="7" refY="4.5"
          orient="auto"><path d="M0,0 L9,4.5 L0,9 z" fill={ok ? OPT_RED : '#999'} /></marker>
      </defs>
    </g>
  )
  return (
    <svg viewBox="0 0 1200 500" width="100%" height="100%">
      {panel(120, true, "无电场", "偏振面被旋转 90° → 被挡住（暗）", false, 0)}
      {panel(700, false, "加电压", "分子沿电场排列 → 光通过（亮）", true, 1)}
    </svg>
  )
}

