/* ============ 2-1 牛顿定律 图示 ============ */

/** 13-2 P4：内能是状态量 —— A 到 B 的两条路径，W 与 Q 各不相同，
 *  但「外界对系统做的功 + 系统吸收的热量」恒为同一个值，于是定义内能增量 ΔE。 */
export function PvAbPaths() {
  const A: [number, number] = [190, 140]
  const B: [number, number] = [530, 250]
  const C1: [number, number] = [360, 110]
  const C2: [number, number] = [360, 290]
  const quad = (C: [number, number], s: number): [number, number] => {
    const u = 1 - s
    return [
      u * u * A[0] + 2 * u * s * C[0] + s * s * B[0],
      u * u * A[1] + 2 * u * s * C[1] + s * s * B[1],
    ]
  }
  const path = (C: [number, number]) => {
    const pts: string[] = []
    for (let i = 0; i <= 48; i++) {
      const [x, y] = quad(C, i / 48)
      pts.push(`${i === 0 ? 'M' : 'L'} ${x.toFixed(1)} ${y.toFixed(1)}`)
    }
    return pts.join(' ')
  }
  const head = (C: [number, number], s: number) => {
    const p = quad(C, s + 0.02)
    const q = quad(C, s - 0.02)
    const dx = p[0] - q[0], dy = p[1] - q[1]
    const L = Math.hypot(dx, dy) || 1
    const ux = dx / L, uy = dy / L
    const nx = -uy, ny = ux
    const T = (k: number): string =>
      `${(p[0] + ux * k + nx * k * 0.55).toFixed(1)},${(p[1] + uy * k + ny * k * 0.55).toFixed(1)}`
    return `${(p[0] + ux * 13).toFixed(1)},${(p[1] + uy * 13).toFixed(1)} ${T(-8.5)} ${T(8.5)}`
  }
  return (
    <svg viewBox="0 0 700 400" width="100%" height="100%">
      {/* 坐标轴 */}
      <line x1="110" y1="330" x2="648" y2="330" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="660,330 646,324 646,336" fill="#8A96A6" />
      <line x1="110" y1="330" x2="110" y2="38" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="110,26 104,40 116,40" fill="#8A96A6" />
      <text x="86" y="54" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#40556F">p</text>
      <text x="632" y="364" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#40556F">V</text>
      <text x="92" y="350" fontSize="22" fontStyle="italic" fontFamily={SERIF} fill="#40556F">O</text>

      {/* 两条路径 */}
      <path d={path(C1)} fill="none" stroke="#C00000" strokeWidth="4" strokeLinecap="round" />
      <polygon points={head(C1, 0.5)} fill="#C00000" />
      <path d={path(C2)} fill="none" stroke="#1F6FBF" strokeWidth="4" strokeLinecap="round" />
      <polygon points={head(C2, 0.5)} fill="#1F6FBF" />

      {/* 状态点 */}
      <circle cx={A[0]} cy={A[1]} r="6.5" fill="#111" />
      <circle cx={B[0]} cy={B[1]} r="6.5" fill="#111" />
      <text x="164" y="132" fontSize="26" fontWeight="bold" fontStyle="italic"
        fontFamily={SERIF} fill="#111">A</text>
      <text x="546" y="258" fontSize="26" fontWeight="bold" fontStyle="italic"
        fontFamily={SERIF} fill="#111">B</text>

      {/* 路径编号 */}
      <text x="286" y="112" fontSize="24" fontWeight="bold" fontFamily={HEI} fill="#C00000">1</text>
      <text x="424" y="286" fontSize="24" fontWeight="bold" fontFamily={HEI} fill="#1F6FBF">2</text>

      <text x="350" y="390" textAnchor="middle" fontSize="19" fontFamily={HEI} fill="#5B7290">
        两条路径：W 不同、Q 也不同，但 Q + W<tspan dy="5" fontSize="0.7em">外</tspan> 相同
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 13-2 P5：绕一圈回到原处 —— A→1→B→2→A 是一个循环，内能增量 ΔE = 0，
 *  于是净吸热等于净做功（Q = W）。 */
export function PvAbCycle() {
  const A: [number, number] = [190, 140]
  const B: [number, number] = [530, 250]
  const C1: [number, number] = [360, 110]
  const C2: [number, number] = [360, 290]
  const quad = (C: [number, number], s: number): [number, number] => {
    const u = 1 - s
    return [
      u * u * A[0] + 2 * u * s * C[0] + s * s * B[0],
      u * u * A[1] + 2 * u * s * C[1] + s * s * B[1],
    ]
  }
  const pts = (C: [number, number], rev = false) => {
    const out: string[] = []
    for (let i = 0; i <= 48; i++) {
      const s = rev ? 1 - i / 48 : i / 48
      const [x, y] = quad(C, s)
      out.push(`${x.toFixed(1)} ${y.toFixed(1)}`)
    }
    return out
  }
  const upper = pts(C1)
  const lowerRev = pts(C2, true)
  const lens = `M ${upper.join(' L ')} L ${lowerRev.join(' L ')} Z`
  const head = (C: [number, number], s: number, sgn: number) => {
    const p = quad(C, s)
    const q = quad(C, s + 0.02 * sgn)
    const dx = q[0] - p[0], dy = q[1] - p[1]
    const L = Math.hypot(dx, dy) || 1
    const ux = dx / L, uy = dy / L
    const nx = -uy, ny = ux
    const T = (k: number, n: number): string =>
      `${(p[0] + ux * k + nx * n).toFixed(1)},${(p[1] + uy * k + ny * n).toFixed(1)}`
    return `${(p[0] + ux * 13).toFixed(1)},${(p[1] + uy * 13).toFixed(1)} ${T(-8, 5)} ${T(-8, -5)}`
  }
  return (
    <svg viewBox="0 0 700 400" width="100%" height="100%">
      {/* 回路包围的面积 */}
      <path d={lens} fill="#E6F0FB" stroke="none" />

      {/* 坐标轴 */}
      <line x1="110" y1="330" x2="648" y2="330" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="660,330 646,324 646,336" fill="#8A96A6" />
      <line x1="110" y1="330" x2="110" y2="38" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="110,26 104,40 116,40" fill="#8A96A6" />
      <text x="86" y="54" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#40556F">p</text>
      <text x="632" y="364" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#40556F">V</text>
      <text x="92" y="350" fontSize="22" fontStyle="italic" fontFamily={SERIF} fill="#40556F">O</text>

      {/* 两条路径 */}
      <path d={`M ${upper.join(' L ')}`} fill="none" stroke="#C00000" strokeWidth="4"
        strokeLinecap="round" />
      <path d={`M ${lowerRev.join(' L ')}`} fill="none" stroke="#1F6FBF" strokeWidth="4"
        strokeLinecap="round" />
      <polygon points={head(C1, 0.5, 1)} fill="#C00000" />
      <polygon points={head(C2, 0.5, -1)} fill="#1F6FBF" />

      {/* 状态点 */}
      <circle cx={A[0]} cy={A[1]} r="6.5" fill="#111" />
      <circle cx={B[0]} cy={B[1]} r="6.5" fill="#111" />
      <text x="164" y="132" fontSize="26" fontWeight="bold" fontStyle="italic"
        fontFamily={SERIF} fill="#111">A</text>
      <text x="546" y="258" fontSize="26" fontWeight="bold" fontStyle="italic"
        fontFamily={SERIF} fill="#111">B</text>

      <text x="286" y="112" fontSize="24" fontWeight="bold" fontFamily={HEI} fill="#C00000">1</text>
      <text x="424" y="286" fontSize="24" fontWeight="bold" fontFamily={HEI} fill="#1F6FBF">2</text>

      <text x="350" y="390" textAnchor="middle" fontSize="19" fontFamily={HEI} fill="#5B7290">
        A → 1 → B → 2 → A：ΔE = 0，所以 Q = W
      </text>
    </svg>
  )
}

