/* ============ 2-1 牛顿定律 图示 ============ */

/** 13-2 P6：理想气体的内能 —— E 与 T 成正比，直线过原点，
 *  所以内能只是温度的函数（与体积、压强无关）。 */
export function IdealGasEnergy() {
  const X0 = 120, Y0 = 320
  const xT = (t: number) => X0 + t * 440
  const yE = (t: number) => Y0 - t * 200
  return (
    <svg viewBox="0 0 700 380" width="100%" height="100%">
      {/* 坐标轴 */}
      <line x1={X0} y1={Y0} x2="632" y2={Y0} stroke="#8A96A6" strokeWidth="2" />
      <polygon points="644,320 630,314 630,326" fill="#8A96A6" />
      <line x1={X0} y1={Y0} x2={X0} y2="58" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="120,46 114,60 126,60" fill="#8A96A6" />
      <text x="94" y="74" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#40556F">E</text>
      <text x="626" y="352" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#40556F">T</text>
      <text x="102" y="340" fontSize="22" fontStyle="italic" fontFamily={SERIF} fill="#40556F">O</text>

      {/* 射线 */}
      <line x1={X0} y1={Y0} x2={xT(1)} y2={yE(1)} stroke="#C00000" strokeWidth="4" strokeLinecap="round" />

      {/* 两个状态 */}
      {[{ t: 0.36, name: '1' }, { t: 0.78, name: '2' }].map((s, i) => (
        <g key={i}>
          <line x1={xT(s.t)} y1={Y0} x2={xT(s.t)} y2={yE(s.t)} stroke="#9AA7B8" strokeWidth="1.5"
            strokeDasharray="7 6" />
          <line x1={X0} y1={yE(s.t)} x2={xT(s.t)} y2={yE(s.t)} stroke="#9AA7B8" strokeWidth="1.5"
            strokeDasharray="7 6" />
          <circle cx={xT(s.t)} cy={yE(s.t)} r="6" fill="#C00000" />
          <text x={xT(s.t)} y={Y0 + 28} textAnchor="middle" fontSize="21" fontStyle="italic"
            fontFamily={SERIF} fill="#40556F">T<tspan dy="5" fontSize="0.66em">{s.name}</tspan></text>
          <text x={X0 - 12} y={yE(s.t) + 7} textAnchor="end" fontSize="21" fontStyle="italic"
            fontFamily={SERIF} fill="#40556F">E<tspan dy="5" fontSize="0.66em">{s.name}</tspan></text>
        </g>
      ))}

      <text x="352" y="182" textAnchor="middle" fontSize="22" fontStyle="italic"
        fontFamily={SERIF} fill="#C00000">E ∝ T</text>

      <text x="350" y="362" textAnchor="middle" fontSize="19" fontFamily={HEI} fill="#5B7290">
        直线过原点：内能只由温度 T 决定
      </text>
    </svg>
  )
}

