/* ============ 2-1 牛顿定律 图示 ============ */

/** 13-5 P4：循环过程 —— p–V 图上一条闭合曲线，转一圈回到原状态，
 *  包围的面积就是净功；顺时针为正循环，逆时针为逆循环。 */
export function PvCycle() {
  const A: [number, number] = [230, 150]
  const B: [number, number] = [540, 260]
  const up: [number, number] = [400, 78]
  const dn: [number, number] = [380, 322]
  const quad = (C: [number, number], s: number): [number, number] => {
    const u = 1 - s
    return [u * u * A[0] + 2 * u * s * C[0] + s * s * B[0],
      u * u * A[1] + 2 * u * s * C[1] + s * s * B[1]]
  }
  const seg = (C: [number, number], rev = false) => {
    const out: string[] = []
    for (let i = 0; i <= 40; i++) {
      const s = rev ? 1 - i / 40 : i / 40
      const [x, y] = quad(C, s)
      out.push(`${x.toFixed(1)} ${y.toFixed(1)}`)
    }
    return out
  }
  const loop = `M ${seg(up).join(' L ')} L ${seg(dn, true).join(' L ')} Z`
  const head = (C: [number, number], s: number, sgn: number) => {
    const p = quad(C, s)
    const q = quad(C, s + 0.03 * sgn)
    const dx = q[0] - p[0], dy = q[1] - p[1]
    const L = Math.hypot(dx, dy) || 1
    const ux = dx / L, uy = dy / L
    return `${(p[0] + ux * 14).toFixed(1)},${(p[1] + uy * 14).toFixed(1)} ` +
      `${(p[0] - ux * 9 - uy * 6).toFixed(1)},${(p[1] - uy * 9 + ux * 6).toFixed(1)} ` +
      `${(p[0] - ux * 9 + uy * 6).toFixed(1)},${(p[1] - uy * 9 - ux * 6).toFixed(1)}`
  }
  return (
    <svg viewBox="0 0 700 400" width="100%" height="100%">
      <path d={loop} fill="#E6F0FB" stroke="none" />

      <line x1="120" y1="340" x2="648" y2="340" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="660,340 646,334 646,346" fill="#8A96A6" />
      <line x1="120" y1="340" x2="120" y2="44" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="120,32 114,46 126,46" fill="#8A96A6" />
      <text x="96" y="56" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#40556F">p</text>
      <text x="632" y="374" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#40556F">V</text>
      <text x="98" y="358" fontSize="22" fontStyle="italic" fontFamily={SERIF} fill="#40556F">O</text>

      <path d={`M ${seg(up).join(' L ')}`} fill="none" stroke="#C00000" strokeWidth="4" />
      <path d={`M ${seg(dn, true).join(' L ')}`} fill="none" stroke="#1F6FBF" strokeWidth="4" />
      <polygon points={head(up, 0.5, 1)} fill="#C00000" />
      <polygon points={head(dn, 0.5, -1)} fill="#1F6FBF" />

      <circle cx={A[0]} cy={A[1]} r="6.5" fill="#111" />
      <circle cx={B[0]} cy={B[1]} r="6.5" fill="#111" />
      <text x={A[0] - 14} y={A[1] - 12} textAnchor="end" fontSize="25" fontWeight="bold"
        fontStyle="italic" fontFamily={SERIF} fill="#111">A</text>
      <text x={B[0] + 14} y={B[1] + 20} fontSize="25" fontWeight="bold" fontStyle="italic"
        fontFamily={SERIF} fill="#111">B</text>

      <text x="352" y="212" textAnchor="middle" fontSize="24" fontFamily={HEI} fill="#1F6FBF">
        净功 = 包围面积
      </text>
      <text x="352" y="392" textAnchor="middle" fontSize="20" fontFamily={HEI} fill="#5B7290">
        顺时针（A→上→B→下→A）对外做正功
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

