/* ============ 2-1 牛顿定律 图示 ============ */

/** 13-6 P7：可逆与不可逆 —— 可逆过程能沿原路返回、外界也一起复原；
 *  不可逆过程回不去，总会留下痕迹。 */
export function ReversibleVsNot() {
  const panel = (dx: number, ok: boolean) => (
    <g key={dx}>
      <rect x={30 + dx} y="40" width="290" height="300" rx="10"
        fill={ok ? '#F2FBF5' : '#FDF6F6'} stroke={ok ? '#2E8B57' : '#C0607A'} strokeWidth="2" />
      <circle cx={90 + dx} cy="150" r="30" fill="#DCE9F9" stroke="#1F6FBF" strokeWidth="2.4" />
      <text x={90 + dx} y="159" textAnchor="middle" fontSize="24" fontStyle="italic"
        fontFamily={SERIF} fill="#1F6FBF">A</text>
      <circle cx={260 + dx} cy="150" r="30" fill="#DCE9F9" stroke="#1F6FBF" strokeWidth="2.4" />
      <text x={260 + dx} y="159" textAnchor="middle" fontSize="24" fontStyle="italic"
        fontFamily={SERIF} fill="#1F6FBF">B</text>

      <path d={`M ${124 + dx} 132 Q ${175 + dx} 96 ${226 + dx} 132`} fill="none"
        stroke={ok ? '#2E8B57' : '#C00000'} strokeWidth="4" />
      <polygon points={`${232 + dx},136 ${214 + dx},130 ${218 + dx},146`}
        fill={ok ? '#2E8B57' : '#C00000'} />

      {ok ? (
        <>
          <path d={`M ${226 + dx} 168 Q ${175 + dx} 204 ${124 + dx} 168`} fill="none"
            stroke="#2E8B57" strokeWidth="4" />
          <polygon points={`${118 + dx},164 ${136 + dx},170 ${132 + dx},154`} fill="#2E8B57" />
        </>
      ) : (
        <>
          <path d={`M ${226 + dx} 168 Q ${175 + dx} 204 ${124 + dx} 168`} fill="none"
            stroke="#9AA7B8" strokeWidth="3.4" strokeDasharray="8 6" />
          <line x1={`${150 + dx}`} y1="196" x2={`${192 + dx}`} y2="216" stroke="#C00000" strokeWidth="5" />
          <line x1={`${192 + dx}`} y1="196" x2={`${150 + dx}`} y2="216" stroke="#C00000" strokeWidth="5" />
        </>
      )}

      <text x={175 + dx} y="264" textAnchor="middle" fontSize="22" fontFamily={HEI}
        fill={ok ? '#2E8B57' : '#C00000'}>{ok ? '可逆过程' : '不可逆过程'}</text>
      <text x={175 + dx} y="300" textAnchor="middle" fontSize="19" fontFamily={HEI}
        fill="#5B7290">{ok ? '原路返回，外界也复原' : '回不去，总留下痕迹'}</text>
    </g>
  )
  return (
    <svg viewBox="0 0 700 380" width="100%" height="100%">
      {panel(0, true)}
      {panel(330, false)}
    </svg>
  )
}

