/* ============ 2-1 牛顿定律 图示 ============ */

/** 13-7 P3：T–S 图上的卡诺循环是一个矩形 —— 上边是 T₁ 等温吸热，下边是 T₂ 等温放热，
 *  两条竖边是绝热（S 不变）；矩形面积 = Q₁ − Q₂ = 净功。 */
export function TsCarnot() {
  const X = (s: number) => 140 + s * 110
  const Y = (T: number) => 340 - T * 82
  const S1 = 1.0, S2 = 3.0, T1 = 3.0, T2 = 1.4
  const a: [number, number] = [X(S1), Y(T1)]
  const b: [number, number] = [X(S2), Y(T1)]
  const c: [number, number] = [X(S2), Y(T2)]
  const d: [number, number] = [X(S1), Y(T2)]
  return (
    <svg viewBox="0 0 700 400" width="100%" height="100%">
      <rect x={a[0]} y={a[1]} width={b[0] - a[0]} height={d[1] - a[1]} fill="#E6F0FB" />

      <line x1="140" y1="340" x2="648" y2="340" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="660,340 646,334 646,346" fill="#8A96A6" />
      <line x1="140" y1="340" x2="140" y2="54" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="140,42 134,56 146,56" fill="#8A96A6" />
      <text x="116" y="66" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#40556F">T</text>
      <text x="632" y="374" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#40556F">S</text>
      <text x="118" y="358" fontSize="22" fontStyle="italic" fontFamily={SERIF} fill="#40556F">O</text>

      {/* 矩形四条边 */}
      <line x1={a[0]} y1={a[1]} x2={b[0]} y2={b[1]} stroke="#C00000" strokeWidth="4.5" />
      <line x1={c[0]} y1={c[1]} x2={d[0]} y2={d[1]} stroke="#1F6FBF" strokeWidth="4.5" />
      <line x1={b[0]} y1={b[1]} x2={c[0]} y2={c[1]} stroke="#2E8B57" strokeWidth="4" />
      <line x1={d[0]} y1={d[1]} x2={a[0]} y2={a[1]} stroke="#2E8B57" strokeWidth="4" />

      <polygon points={`${(a[0] + b[0]) / 2 + 8},${a[1]} ${(a[0] + b[0]) / 2 - 8},${a[1] - 8} ${(a[0] + b[0]) / 2 - 8},${a[1] + 8}`} fill="#C00000" />
      <polygon points={`${(c[0] + d[0]) / 2 - 8},${c[1]} ${(c[0] + d[0]) / 2 + 8},${c[1] - 8} ${(c[0] + d[0]) / 2 + 8},${c[1] + 8}`} fill="#1F6FBF" />
      <polygon points={`${b[0]},${(b[1] + c[1]) / 2} ${b[0] - 8},${(b[1] + c[1]) / 2 - 10} ${b[0] + 8},${(b[1] + c[1]) / 2 - 10}`} fill="#2E8B57" />

      <text x={a[0] - 12} y={a[1] - 10} textAnchor="end" fontSize="23" fontWeight="bold"
        fontStyle="italic" fontFamily={SERIF} fill="#111">A</text>
      <text x={b[0] + 12} y={b[1] - 10} fontSize="23" fontWeight="bold" fontStyle="italic"
        fontFamily={SERIF} fill="#111">B</text>
      <text x={c[0] + 12} y={c[1] + 8} fontSize="23" fontWeight="bold" fontStyle="italic"
        fontFamily={SERIF} fill="#111">C</text>
      <text x={d[0] - 12} y={d[1] + 8} textAnchor="end" fontSize="23" fontWeight="bold"
        fontStyle="italic" fontFamily={SERIF} fill="#111">D</text>

      <text x="128" y={a[1] + 8} textAnchor="end" fontSize="21" fontStyle="italic"
        fontFamily={SERIF} fill="#40556F">T₁</text>
      <text x="128" y={d[1] + 8} textAnchor="end" fontSize="21" fontStyle="italic"
        fontFamily={SERIF} fill="#40556F">T₂</text>
      <text x={a[0]} y="366" textAnchor="middle" fontSize="21" fontStyle="italic"
        fontFamily={SERIF} fill="#40556F">S₁</text>
      <text x={b[0]} y="366" textAnchor="middle" fontSize="21" fontStyle="italic"
        fontFamily={SERIF} fill="#40556F">S₂</text>

      <text x={(a[0] + b[0]) / 2} y={a[1] - 18} textAnchor="middle" fontSize="20" fontFamily={HEI}
        fill="#C00000">吸热 Q₁ = T₁(S₂−S₁)</text>
      <text x={(c[0] + d[0]) / 2} y={c[1] + 32} textAnchor="middle" fontSize="20" fontFamily={HEI}
        fill="#1F6FBF">放热 Q₂ = T₂(S₂−S₁)</text>
      <text x={(a[0] + b[0]) / 2} y={(a[1] + d[1]) / 2 + 8} textAnchor="middle" fontSize="21"
        fontFamily={HEI} fill="#2E8B57">W = 面积</text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 13-7 P4：任意可逆循环可以切成许多微小卡诺循环 —— 每个小矩形贡献的热温比
 *  相互抵消，整圈的热温比之和为零。 */
export function TsMicro() {
  const loop = 'M 250 128 C 330 74 470 82 522 152 C 572 220 502 300 402 312 ' +
    'C 302 324 210 262 232 192 Z'
  const hs = [130, 168, 206, 244, 282]
  const vs = [268, 306, 344, 382, 420, 462, 500]
  return (
    <svg viewBox="0 0 700 400" width="100%" height="100%">
      <defs>
        <clipPath id="tsloop">
          <path d={loop} />
        </clipPath>
      </defs>

      <line x1="140" y1="340" x2="648" y2="340" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="660,340 646,334 646,346" fill="#8A96A6" />
      <line x1="140" y1="340" x2="140" y2="54" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="140,42 134,56 146,56" fill="#8A96A6" />
      <text x="116" y="66" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#40556F">T</text>
      <text x="632" y="374" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#40556F">S</text>
      <text x="118" y="358" fontSize="22" fontStyle="italic" fontFamily={SERIF} fill="#40556F">O</text>

      <path d={loop} fill="#F4F8FD" stroke="#1F6FBF" strokeWidth="4" />
      <g clipPath="url(#tsloop)">
        {hs.map((y, i) => (
          <line key={`h${i}`} x1="200" y1={y} x2="580" y2={y} stroke="#9AA7B8" strokeWidth="1.4"
            strokeDasharray="6 5" />
        ))}
        {vs.map((x, i) => (
          <line key={`v${i}`} x1={x} y1="90" x2={x} y2="330" stroke="#9AA7B8" strokeWidth="1.4"
            strokeDasharray="6 5" />
        ))}
        {/* 一个被选中的微小卡诺循环 */}
        <rect x="344" y="206" width="38" height="38" fill="#FBE3EC" stroke="#C00000" strokeWidth="2.2" />
      </g>

      <text x="392" y="200" fontSize="20" fontFamily={HEI} fill="#C00000">一个微小卡诺循环</text>
      <line x1="386" y1="206" x2="366" y2="212" stroke="#C00000" strokeWidth="1.6" />

      <text x="350" y="386" textAnchor="middle" fontSize="20" fontFamily={HEI} fill="#5B7290">
        任意可逆循环 ≈ 许多微小卡诺循环 ⇒ ∮ dQ/T = 0
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 13-7 P5：熵是态函数 —— 从 A 到 B 不管走哪条路径，热温比的积分都一样，
 *  所以这个积分只由初末状态决定。 */
export function EntropyPaths() {
  const A: [number, number] = [200, 140]
  const B: [number, number] = [530, 250]
  const C1: [number, number] = [360, 110]
  const C2: [number, number] = [360, 300]
  const quad = (C: [number, number], s: number): [number, number] => {
    const u = 1 - s
    return [u * u * A[0] + 2 * u * s * C[0] + s * s * B[0],
      u * u * A[1] + 2 * u * s * C[1] + s * s * B[1]]
  }
  const line = (C: [number, number]) => {
    const p: string[] = []
    for (let i = 0; i <= 44; i++) {
      const [x, y] = quad(C, i / 44)
      p.push(`${i === 0 ? 'M' : 'L'} ${x.toFixed(1)} ${y.toFixed(1)}`)
    }
    return p.join(' ')
  }
  const head = (C: [number, number], s: number) => {
    const p = quad(C, s + 0.02)
    const q = quad(C, s - 0.02)
    const dx = p[0] - q[0], dy = p[1] - q[1]
    const L = Math.hypot(dx, dy) || 1
    const ux = dx / L, uy = dy / L
    const nx = -uy, ny = ux
    const T = (k: number, n: number): string =>
      `${(p[0] + ux * k + nx * n).toFixed(1)},${(p[1] + uy * k + ny * n).toFixed(1)}`
    return `${(p[0] + ux * 13).toFixed(1)},${(p[1] + uy * 13).toFixed(1)} ${T(-8, 5)} ${T(-8, -5)}`
  }
  return (
    <svg viewBox="0 0 700 400" width="100%" height="100%">
      <line x1="120" y1="330" x2="648" y2="330" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="660,330 646,324 646,336" fill="#8A96A6" />
      <line x1="120" y1="330" x2="120" y2="44" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="120,32 114,46 126,46" fill="#8A96A6" />
      <text x="96" y="56" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#40556F">p</text>
      <text x="632" y="364" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#40556F">V</text>
      <text x="98" y="348" fontSize="22" fontStyle="italic" fontFamily={SERIF} fill="#40556F">O</text>

      <path d={line(C1)} fill="none" stroke="#C00000" strokeWidth="4" strokeLinecap="round" />
      <polygon points={head(C1, 0.5)} fill="#C00000" />
      <path d={line(C2)} fill="none" stroke="#1F6FBF" strokeWidth="4" strokeLinecap="round" />
      <polygon points={head(C2, 0.5)} fill="#1F6FBF" />

      <circle cx={A[0]} cy={A[1]} r="6.5" fill="#111" />
      <circle cx={B[0]} cy={B[1]} r="6.5" fill="#111" />
      <text x="174" y="132" fontSize="25" fontWeight="bold" fontStyle="italic"
        fontFamily={SERIF} fill="#111">A</text>
      <text x="546" y="258" fontSize="25" fontWeight="bold" fontStyle="italic"
        fontFamily={SERIF} fill="#111">B</text>
      <text x="286" y="112" fontSize="23" fontWeight="bold" fontFamily={HEI} fill="#C00000">1</text>
      <text x="424" y="292" fontSize="23" fontWeight="bold" fontFamily={HEI} fill="#1F6FBF">2</text>

      <text x="350" y="390" textAnchor="middle" fontSize="20" fontFamily={HEI} fill="#5B7290">
        两条路径的 ∫dQ/T 相同 ⇒ 这个积分只由 A、B 决定
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 13-7 P9：熵增加原理 —— 孤立系统里的自发过程总让熵增大；
 *  到达平衡态时熵最大，之后不再变化。 */
export function EntropyGrowth() {
  const X = (t: number) => 150 + t * 440
  const Y = (s: number) => 320 - s * 210
  const pts: string[] = []
  for (let i = 0; i <= 60; i++) {
    const t = i / 60
    pts.push(`${i === 0 ? 'M' : 'L'} ${X(t).toFixed(1)} ${Y(0.18 + 0.72 * (1 - Math.exp(-4.2 * t))).toFixed(1)}`)
  }
  const curve = pts.join(' ')
  return (
    <svg viewBox="0 0 700 380" width="100%" height="100%">
      <line x1="150" y1="320" x2="628" y2="320" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="640,320 626,314 626,326" fill="#8A96A6" />
      <line x1="150" y1="320" x2="150" y2="54" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="150,42 144,56 156,56" fill="#8A96A6" />
      <text x="126" y="66" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#40556F">S</text>
      <text x="620" y="354" fontSize="24" fontStyle="italic" fontFamily={SERIF} fill="#40556F">t</text>
      <text x="128" y="338" fontSize="22" fontStyle="italic" fontFamily={SERIF} fill="#40556F">O</text>

      {/* 平衡态渐近线 */}
      <line x1="150" y1={Y(0.9)} x2="620" y2={Y(0.9)} stroke="#C00000" strokeWidth="1.8"
        strokeDasharray="8 6" />
      <text x="618" y="118" textAnchor="end" fontSize="19" fontFamily={HEI} fill="#C00000">
        平衡态：S 最大
      </text>

      <path d={curve} fill="none" stroke="#1F6FBF" strokeWidth="4.5" strokeLinecap="round" />

      <circle cx={X(0)} cy={Y(0.18)} r="6" fill="#111" />
      <text x={X(0) + 14} y={Y(0.18) + 6} fontSize="21" fontStyle="italic" fontFamily={SERIF}
        fill="#111">A</text>
      <text x="330" y="252" textAnchor="middle" fontSize="20" fontFamily={HEI} fill="#1F6FBF">
        自发过程：熵只增不减
      </text>

      <text x="350" y="366" textAnchor="middle" fontSize="20" fontFamily={HEI} fill="#5B7290">
        孤立系统：ΔS ≥ 0（可逆取等号，不可逆取大于号）
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 13-8 P5：N = 4 个可分辨粒子在左右两空间的 5 种分布 ——
 *  均匀分布 (2:2) 的微观状态数最多，所以概率最大。 */
export function Microstates4() {
  const dists = [
    { l: 4, r: 0, W: 1 },
    { l: 3, r: 1, W: 4 },
    { l: 2, r: 2, W: 6 },
    { l: 1, r: 3, W: 4 },
    { l: 0, r: 4, W: 1 },
  ]
  const BW = 56, BH = 96
  const pos = (i: number): [number, number] => {
    const cx = i % 2 === 0 ? 16 : 40
    const cy = i < 2 ? 26 : 70
    return [cx, cy]
  }
  return (
    <svg viewBox="0 0 700 330" width="100%" height="100%">
      {dists.map((d, k) => {
        const x0 = 18 + k * 136
        return (
          <g key={k}>
            <rect x={x0} y="34" width={BW} height={BH} fill="#F7FAFF" stroke="#5B7290" strokeWidth="2" />
            <rect x={x0 + BW + 6} y="34" width={BW} height={BH} fill="#FFFFFF" stroke="#5B7290"
              strokeWidth="2" strokeDasharray={d.r === 0 ? '6 5' : undefined} />
            {Array.from({ length: d.l }, (_, i) => {
              const [cx, cy] = pos(i)
              return <circle key={`l${i}`} cx={x0 + cx} cy={34 + cy} r="9" fill="#1F6FBF" />
            })}
            {Array.from({ length: d.r }, (_, i) => {
              const [cx, cy] = pos(i)
              return <circle key={`r${i}`} cx={x0 + BW + 6 + cx} cy={34 + cy} r="9" fill="#C00000" />
            })}
            <text x={x0 + BW + 3} y="152" textAnchor="middle" fontSize="19" fontFamily={HEI}
              fill="#40556F">{d.l} : {d.r}</text>
            <text x={x0 + BW + 3} y="186" textAnchor="middle" fontSize="20" fontFamily={HEI}
              fill={d.W === 6 ? '#C00000' : '#40556F'}>W = {d.W}</text>
          </g>
        )
      })}
      <text x="350" y="24" textAnchor="middle" fontSize="19" fontFamily={HEI} fill="#5B7290">
        左 4 个 ─ 3:1 ─ 2:2 ─ 1:3 ─ 右 4 个（共 16 种微观状态）
      </text>
      <text x="350" y="226" textAnchor="middle" fontSize="20" fontFamily={HEI} fill="#C00000">
        均匀分布 W = 6，占 6/16 —— 概率最大
      </text>
      <text x="350" y="266" textAnchor="middle" fontSize="19" fontFamily={HEI} fill="#5B7290">
        每种分布的状态数 W = N! /（n₁! n₂!），N = 4
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 13-8 P6：N = 20 时微观状态数随分布的变化 —— 中间高、两边低，
 *  最可几分布是左右各 10 个；粒子越多，峰越尖。 */
export function BinomialPeak() {
  const N = 20
  const C: number[] = []
  for (let n = 0; n <= N; n++) {
    let v = 1
    for (let i = 0; i < n; i++) v = (v * (N - i)) / (i + 1)
    C.push(v)
  }
  const max = Math.max(...C)
  const X0 = 80, Y0 = 320, BW = 22, GAP = 3.5
  return (
    <svg viewBox="0 0 700 400" width="100%" height="100%">
      <line x1={X0} y1={Y0} x2="648" y2={Y0} stroke="#8A96A6" strokeWidth="2" />
      <polygon points="660,320 646,314 646,326" fill="#8A96A6" />
      <line x1={X0} y1={Y0} x2={X0} y2="50" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="80,38 74,52 86,52" fill="#8A96A6" />
      <text x="56" y="62" fontSize="23" fontStyle="italic" fontFamily={SERIF} fill="#40556F">W</text>
      <text x="640" y="346" fontSize="22" fontStyle="italic" fontFamily={SERIF} fill="#40556F">n</text>

      {C.map((v, n) => {
        const h = (v / max) * 250
        const x = X0 + 10 + n * (BW + GAP)
        const peak = n === 10
        return (
          <g key={n}>
            <rect x={x} y={Y0 - h} width={BW} height={h} rx="2"
              fill={peak ? '#C00000' : '#1F6FBF'} opacity={peak ? 1 : 0.75} />
            {n % 5 === 0 && (
              <text x={x + BW / 2} y={Y0 + 24} textAnchor="middle" fontSize="18"
                fontFamily={HEI} fill="#40556F">{n}</text>
            )}
          </g>
        )
      })}

      <text x={X0 + 10 + 10 * (BW + GAP) + BW / 2} y="46" textAnchor="middle"
        fontSize="18" fontFamily={HEI} fill="#C00000">最可几</text>

      <text x="360" y="386" textAnchor="middle" fontSize="19" fontFamily={HEI} fill="#5B7290">
        N = 20：均匀分布的状态数比全挤在一边多十几万倍
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 13-8 P11：开放系统的熵变 = 熵流 + 熵产生 ——
 *  熵产生 dSi 永远非负，但熵流 dSe 可以为负：把熵排出去，系统就能维持低熵。 */
export function OpenSystem() {
  return (
    <svg viewBox="0 0 700 380" width="100%" height="100%">
      {/* 环境 */}
      <rect x="26" y="106" width="180" height="150" rx="10" fill="#F3F4F6" stroke="#8A96A6" strokeWidth="2.2" />
      <text x="116" y="176" textAnchor="middle" fontSize="21" fontFamily={HEI} fill="#40556F">环境</text>
      <text x="116" y="206" textAnchor="middle" fontSize="18" fontFamily={HEI} fill="#5B7290">热源 / 物质</text>

      {/* 系统 */}
      <rect x="290" y="106" width="180" height="150" rx="10" fill="#DCE9F9" stroke="#1F6FBF" strokeWidth="2.6" />
      <text x="380" y="166" textAnchor="middle" fontSize="21" fontFamily={HEI} fill="#1F6FBF">开放系统</text>
      <text x="380" y="222" textAnchor="middle" fontSize="20" fontFamily={HEI} fill="#C00000">
        内部产生 dSᵢ ≥ 0
      </text>

      {/* 熵流 */}
      <line x1="212" y1="160" x2="278" y2="160" stroke="#2E8B57" strokeWidth="5" />
      <polygon points="290,160 272,152 272,168" fill="#2E8B57" />
      <line x1="278" y1="196" x2="212" y2="196" stroke="#2E8B57" strokeWidth="5" strokeDasharray="9 6" />
      <polygon points="200,196 218,188 218,204" fill="#2E8B57" />
      <text x="246" y="140" textAnchor="middle" fontSize="19" fontStyle="italic"
        fontFamily={SERIF} fill="#2E8B57">dSₑ</text>
      <text x="246" y="234" textAnchor="middle" fontSize="17" fontFamily={HEI} fill="#2E8B57">
        可正可负
      </text>

      {/* 汇总 */}
      <text x="350" y="306" textAnchor="middle" fontSize="26" fontStyle="italic"
        fontFamily={SERIF} fill="#111">dS = dSₑ + dSᵢ</text>
      <text x="350" y="348" textAnchor="middle" fontSize="19" fontFamily={HEI} fill="#5B7290">
        熵产生非负；把熵排出去（dSₑ &lt; 0），系统就能维持低熵
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 13-9 P4：麦克斯韦妖 —— 小妖守在隔板门口，只放快分子去右边、慢分子去左边，
 *  于是不需要做功就造出了温差。它靠的正是「信息」。 */
export function MaxwellDemon() {
  const rnd = (k: number) => {
    const s = Math.sin(k * 12.9898 + 4.1414) * 43758.5453
    return s - Math.floor(s)
  }
  const slow = Array.from({ length: 6 }, (_, i) => ({
    cx: 100 + rnd(i + 1) * 200, cy: 160 + rnd(i + 31) * 150,
  }))
  const fast = Array.from({ length: 6 }, (_, i) => ({
    cx: 400 + rnd(i + 61) * 200, cy: 160 + rnd(i + 91) * 150,
  }))
  return (
    <svg viewBox="0 0 700 400" width="100%" height="100%">
      {/* 容器 */}
      <rect x="50" y="110" width="600" height="240" fill="#F7FAFF" stroke="#5B7290" strokeWidth="3" />
      {/* 隔板（中间留门） */}
      <rect x="342" y="110" width="16" height="90" fill="#B99A6B" />
      <rect x="342" y="250" width="16" height="100" fill="#B99A6B" />
      <text x="350" y="238" textAnchor="middle" fontSize="18" fontFamily={HEI} fill="#8A7346">门</text>

      {/* 慢分子 */}
      {slow.map((d, i) => (
        <g key={`s${i}`}>
          <circle cx={d.cx} cy={d.cy} r="11" fill="#1F6FBF" opacity="0.85" />
          <line x1={d.cx + 13} y1={d.cy} x2={d.cx + 27} y2={d.cy} stroke="#1F6FBF" strokeWidth="2.4" />
        </g>
      ))}
      {/* 快分子 */}
      {fast.map((d, i) => (
        <g key={`f${i}`}>
          <circle cx={d.cx} cy={d.cy} r="11" fill="#C00000" opacity="0.85" />
          <line x1={d.cx + 13} y1={d.cy} x2={d.cx + 45} y2={d.cy} stroke="#C00000" strokeWidth="2.4" />
          <polygon points={`${d.cx + 52},${d.cy} ${d.cx + 42},${d.cy - 5} ${d.cx + 42},${d.cy + 5}`} fill="#C00000" />
        </g>
      ))}

      {/* 小妖 */}
      <circle cx="350" cy="86" r="14" fill="#E8D9A8" stroke="#8A7346" strokeWidth="2" />
      <text x="350" y="92" textAnchor="middle" fontSize="16" fontFamily={HEI} fill="#5B4A22">妖</text>
      <text x="350" y="58" textAnchor="middle" fontSize="19" fontFamily={HEI} fill="#8A7346">麦克斯韦妖</text>

      <text x="170" y="378" textAnchor="middle" fontSize="20" fontFamily={HEI} fill="#1F6FBF">
        左边越来越冷
      </text>
      <text x="530" y="378" textAnchor="middle" fontSize="20" fontFamily={HEI} fill="#C00000">
        右边越来越热
      </text>
      <text x="350" y="34" textAnchor="middle" fontSize="20" fontFamily={HEI} fill="#5B7290">
        只放快分子向右、慢分子向左 —— 不做功就造出了温差
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 13-9 P5：信息量的单位 —— 在两种等概率的可能性之间作出选择，需要 1 bit；
 *  n 种等概率可能，就需要 log₂n bit。 */
export function BitChoice() {
  const group = (x: number, n: number, bits: number, label: string) => {
    const cols = n === 8 ? 4 : n
    const rows = n === 8 ? 2 : 1
    const bw = 34, bh = 30, gap = 8
    return (
      <g key={x}>
        {Array.from({ length: n }, (_, i) => {
          const c = i % cols, r = Math.floor(i / cols)
          return (
            <rect key={i} x={x + c * (bw + gap)} y={110 + r * (bh + gap)} width={bw} height={bh}
              rx="4" fill="#DCE9F9" stroke="#1F6FBF" strokeWidth="2" />
          )
        })}
        <text x={x + (cols * (bw + gap) - gap) / 2} y={rows === 2 ? 206 : 168} textAnchor="middle"
          fontSize="19" fontFamily={HEI} fill="#40556F">{label}</text>
        <text x={x + (cols * (bw + gap) - gap) / 2} y={rows === 2 ? 238 : 200} textAnchor="middle"
          fontSize="22" fontFamily={HEI} fill="#C00000">{bits} bit</text>
      </g>
    )
  }
  return (
    <svg viewBox="0 0 700 340" width="100%" height="100%">
      {group(40, 2, 1, '2 种可能')}
      {group(200, 4, 2, '4 种可能')}
      {group(400, 8, 3, '8 种可能')}
      <text x="350" y="60" textAnchor="middle" fontSize="21" fontFamily={HEI} fill="#5B7290">
        等概率的 n 种可能，确定一个需要 log₂n bit
      </text>
      <text x="350" y="300" textAnchor="middle" fontSize="20" fontFamily={HEI} fill="#2E8B57">
        每多一种可能，就多一分不确定 —— 也多一分信息
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 13-9 P7：二元信源的信息熵 —— 越不确定熵越大，p = 0.5 时最大（1 bit）；
 *  越确定熵越小，p = 0 或 1 时熵为零。 */
export function BinaryEntropy() {
  const X = (p: number) => 130 + p * 450
  const Y = (h: number) => 330 - h * 250
  const H = (p: number) => {
    if (p <= 0 || p >= 1) return 0
    return -p * Math.log2(p) - (1 - p) * Math.log2(1 - p)
  }
  const pts: string[] = []
  for (let i = 0; i <= 100; i++) {
    const p = 0.005 + (0.99 * i) / 100
    pts.push(`${i === 0 ? 'M' : 'L'} ${X(p).toFixed(1)} ${Y(H(p)).toFixed(1)}`)
  }
  const curve = pts.join(' ')
  const p1 = 0.2, p2 = 0.1
  return (
    <svg viewBox="0 0 700 400" width="100%" height="100%">
      <line x1="130" y1="330" x2="620" y2="330" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="632,330 618,324 618,336" fill="#8A96A6" />
      <line x1="130" y1="330" x2="130" y2="60" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="130,48 124,62 136,62" fill="#8A96A6" />
      <text x="106" y="72" fontSize="23" fontStyle="italic" fontFamily={SERIF} fill="#40556F">H</text>
      <text x="612" y="364" fontSize="23" fontStyle="italic" fontFamily={SERIF} fill="#40556F">p</text>
      <text x="108" y="348" fontSize="21" fontStyle="italic" fontFamily={SERIF} fill="#40556F">O</text>

      {/* 刻度 */}
      {[0, 0.5, 1].map(v => (
        <g key={v}>
          <line x1={X(v)} y1="330" x2={X(v)} y2="338" stroke="#8A96A6" strokeWidth="2" />
          <text x={X(v)} y="356" textAnchor="middle" fontSize="19" fontStyle="italic"
            fontFamily={SERIF} fill="#40556F">{v === 0 ? '0' : v === 1 ? '1' : '0.5'}</text>
        </g>
      ))}
      <line x1="130" y1={Y(1)} x2="580" y2={Y(1)} stroke="#9AA7B8" strokeWidth="1.4"
        strokeDasharray="7 6" />
      <text x="136" y={Y(1) - 10} fontSize="18" fontFamily={HEI} fill="#8A96A6">1 bit</text>

      <path d={curve} fill="none" stroke="#1F6FBF" strokeWidth="4.5" strokeLinecap="round" />

      <circle cx={X(0.5)} cy={Y(1)} r="6" fill="#C00000" />
      <text x={X(0.5)} y={Y(1) - 24} textAnchor="middle" fontSize="19" fontFamily={HEI}
        fill="#C00000">最不确定：1 bit</text>

      <circle cx={X(p1)} cy={Y(H(p1))} r="5.5" fill="#2E8B57" />
      <text x={X(p1) - 14} y={Y(H(p1)) + 4} textAnchor="end" fontSize="18" fontFamily={HEI}
        fill="#2E8B57">0.2 → 0.72</text>
      <circle cx={X(p2)} cy={Y(H(p2))} r="5.5" fill="#2E8B57" />
      <text x={X(p2) - 14} y={Y(H(p2)) + 22} textAnchor="end" fontSize="18" fontFamily={HEI}
        fill="#2E8B57">0.1 → 0.47</text>

      <text x="350" y="388" textAnchor="middle" fontSize="19" fontFamily={HEI} fill="#5B7290">
        越确定，熵越小；p = 0 或 1 时结果已知，熵为零
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 14-1 P3：伽利略变换 —— S′ 系相对 S 系以速度 u 沿 x 轴运动，
 *  同一事件 P 在两系中的坐标满足 x′ = x − ut、t′ = t。 */
export function GalileanFrames() {
  return (
    <svg viewBox="0 0 700 400" width="100%" height="100%">
      {/* S 系 */}
      <line x1="70" y1="330" x2="620" y2="330" stroke="#40556F" strokeWidth="2.4" />
      <polygon points="634,330 618,323 618,337" fill="#40556F" />
      <line x1="70" y1="330" x2="70" y2="80" stroke="#40556F" strokeWidth="2.4" />
      <polygon points="70,66 63,82 77,82" fill="#40556F" />
      <text x="60" y="96" textAnchor="end" fontSize="22" fontStyle="italic"
        fontFamily={SERIF} fill="#40556F">y</text>
      <text x="620" y="358" textAnchor="end" fontSize="22" fontStyle="italic"
        fontFamily={SERIF} fill="#40556F">x</text>
      <text x="52" y="352" textAnchor="end" fontSize="21" fontStyle="italic"
        fontFamily={SERIF} fill="#40556F">O</text>

      {/* S′ 系 */}
      <line x1="250" y1="248" x2="590" y2="248" stroke="#C00000" strokeWidth="2.2" strokeDasharray="9 6" />
      <line x1="250" y1="248" x2="250" y2="96" stroke="#C00000" strokeWidth="2.2" strokeDasharray="9 6" />
      <text x="240" y="112" textAnchor="end" fontSize="21" fontStyle="italic"
        fontFamily={SERIF} fill="#C00000">y′</text>
      <text x="600" y="240" fontSize="21" fontStyle="italic" fontFamily={SERIF} fill="#C00000">x′</text>
      <text x="236" y="272" textAnchor="end" fontSize="21" fontStyle="italic"
        fontFamily={SERIF} fill="#C00000">O′</text>

      {/* 相对速度 */}
      <line x1="300" y1="180" x2="404" y2="180" stroke="#2E8B57" strokeWidth="4" />
      <polygon points="418,180 400,172 400,188" fill="#2E8B57" />
      <text x="356" y="166" textAnchor="middle" fontSize="22" fontStyle="italic"
        fontFamily={SERIF} fill="#2E8B57">u</text>

      {/* 事件 P */}
      <circle cx="470" cy="150" r="7" fill="#111" />
      <text x="484" y="146" fontSize="23" fontStyle="italic" fontFamily={SERIF} fill="#111">P</text>
      <line x1="470" y1="150" x2="470" y2="330" stroke="#9AA7B8" strokeWidth="1.6" strokeDasharray="6 5" />
      <line x1="70" y1="150" x2="470" y2="150" stroke="#9AA7B8" strokeWidth="1.6" strokeDasharray="6 5" />
      <line x1="470" y1="150" x2="470" y2="248" stroke="#9AA7B8" strokeWidth="1.6" strokeDasharray="6 5" />
      <text x="470" y="352" textAnchor="middle" fontSize="21" fontStyle="italic"
        fontFamily={SERIF} fill="#40556F">x</text>
      <text x="150" y="142" textAnchor="middle" fontSize="20" fontStyle="italic"
        fontFamily={SERIF} fill="#40556F">y</text>

      <text x="350" y="386" textAnchor="middle" fontSize="19" fontFamily={HEI} fill="#5B7290">
        x′ = x − ut　　y′ = y　　z′ = z　　t′ = t
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 14-1 P4：伽利略速度变换 —— 质点在 S′ 系中的速度 v′ 加上牵连速度 u，
 *  就得到它在 S 系中的速度 v（矢量三角形）。 */
export function VelocityAdd() {
  const A: [number, number] = [120, 300]
  const B: [number, number] = [420, 300]
  const C: [number, number] = [420, 150]
  return (
    <svg viewBox="0 0 700 380" width="100%" height="100%">
      {/* 三角形 */}
      <line x1={A[0]} y1={A[1]} x2={B[0]} y2={B[1]} stroke="#C00000" strokeWidth="4" />
      <polygon points="434,300 416,293 416,307" fill="#C00000" />
      <line x1={B[0]} y1={B[1]} x2={C[0]} y2={C[1]} stroke="#1F6FBF" strokeWidth="4" />
      <polygon points="420,136 412,154 428,154" fill="#1F6FBF" />
      <line x1={A[0]} y1={A[1]} x2={C[0]} y2={C[1]} stroke="#2E8B57" strokeWidth="4.5" />
      <polygon points="430,142 412,138 418,152" fill="#2E8B57" />

      <text x="270" y="326" textAnchor="middle" fontSize="23" fontStyle="italic"
        fontFamily={SERIF} fill="#C00000">u</text>
      <text x="446" y="232" fontSize="23" fontStyle="italic" fontFamily={SERIF} fill="#1F6FBF">v′</text>
      <text x="238" y="212" fontSize="23" fontStyle="italic" fontFamily={SERIF} fill="#2E8B57">v</text>

      <text x="352" y="360" textAnchor="middle" fontSize="21" fontFamily={HEI} fill="#40556F">
        v = v′ + u　（分量式：vₓ = v′ₓ + u）
      </text>
      <text x="352" y="60" textAnchor="middle" fontSize="20" fontFamily={HEI} fill="#5B7290">
        不同惯性系里速度不同 —— 这是伽利略变换的直接后果
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 14-1 P9：投球的光 —— 若光速也服从伽利略变换，投出后光速变成 c+v，
 *  观察者会「先看到投出后的球、后看到投出前的球」，荒谬。 */
export function BallLight() {
  const row = (y: number, fast: boolean, t: string) => (
    <g key={y}>
      {/* 投球者 */}
      <circle cx="120" cy={y - 58} r="12" fill="#111" />
      <line x1="120" y1={y - 46} x2="120" y2={y - 8} stroke="#111" strokeWidth="3" />
      <line x1="120" y1={y - 8} x2="106" y2={y + 20} stroke="#111" strokeWidth="3" />
      <line x1="120" y1={y - 8} x2="134" y2={y + 20} stroke="#111" strokeWidth="3" />
      <line x1="120" y1={y - 34} x2="150" y2={y - 46} stroke="#111" strokeWidth="3" />
      {/* 球 */}
      <circle cx="158" cy={y - 46} r="17" fill="#E8C65A" stroke="#8A7346" strokeWidth="2" />
      {/* 光波 */}
      <path d={`M 180 ${y - 46} q 9 -12 18 0 q 9 12 18 0 q 9 -12 18 0 q 9 12 18 0`}
        fill="none" stroke="#C00000" strokeWidth="3" />
      <polygon points={`${fast ? 268 : 252},${y - 46} ${fast ? 250 : 236},${y - 52} ${fast ? 250 : 236},${y - 40}`}
        fill="#C00000" />
      {/* 观察者 */}
      <circle cx="600" cy={y - 58} r="12" fill="#111" />
      <line x1="600" y1={y - 46} x2="600" y2={y - 8} stroke="#111" strokeWidth="3" />
      <line x1="600" y1={y - 8} x2="586" y2={y + 20} stroke="#111" strokeWidth="3" />
      <line x1="600" y1={y - 8} x2="614" y2={y + 20} stroke="#111" strokeWidth="3" />
      <line x1="600" y1={y - 34} x2="574" y2={y - 50} stroke="#111" strokeWidth="3" />
      <text x="622" y={y - 40} fontSize="19" fontFamily={HEI} fill="#40556F">观察者</text>
      <text x="486" y={y - 62} textAnchor="middle" fontSize="19" fontStyle="italic"
        fontFamily={SERIF} fill="#40556F">d</text>
      <line x1="286" y1={y - 62} x2="580" y2={y - 62} stroke="#9AA7B8" strokeWidth="1.4"
        strokeDasharray="6 5" />
      <text x={fast ? 216 : 200} y={y - 70} textAnchor="middle" fontSize="20" fontStyle="italic"
        fontFamily={SERIF} fill="#C00000">{t}</text>
    </g>
  )
  return (
    <svg viewBox="0 0 700 400" width="100%" height="100%">
      <text x="90" y="60" fontSize="20" fontFamily={HEI} fill="#40556F">球投出前</text>
      {row(120, false, 'c')}
      <line x1="60" y1="212" x2="660" y2="212" stroke="#D8E0EA" strokeWidth="1.6" />
      <text x="90" y="258" fontSize="20" fontFamily={HEI} fill="#40556F">球投出后</text>
      {row(320, true, 'c + v')}

      <text x="352" y="30" textAnchor="middle" fontSize="19" fontFamily={HEI} fill="#C00000">
        若光速也服从伽利略变换：Δt₁ = d/c &gt; Δt₂ = d/(c+v)
      </text>
      <text x="352" y="386" textAnchor="middle" fontSize="19" fontFamily={HEI} fill="#5B7290">
        结果是「先看到出球、后看到投球」—— 荒谬，说明光速不能与源速相加
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 14-1 P10：蟹状星云的超新星 —— 若光速服从伽利略变换，
 *  朝地球飞来的抛射物发光会「抢跑」，公众应能看到约 25 年的强光；实际只有 22 个月。 */
