/* ============ 2-1 牛顿定律 图示 ============ */

/** 14-8 P4/P6：大质量天体附近的时空被「压弯」，光线沿着弯曲的时空走；
 *  压得足够狠，光就再也出不来 —— 那就是黑洞。 */
export function SpacetimeBend() {
  const grid: string[] = []
  for (let i = -9; i <= 9; i++) {
    const pts: string[] = []
    for (let j = -9; j <= 9; j++) {
      const x = 350 + i * 32
      const y = 190 + j * 26
      const dx = x - 350, dy = y - 150
      const r = Math.hypot(dx, dy) + 1
      const pull = 2600 / (r * r + 400)
      pts.push(`${(x - (dx / r) * pull).toFixed(1)} ${(y - (dy / r) * pull).toFixed(1)}`)
    }
    grid.push(pts.join(' '))
  }
  const cols: string[] = []
  for (let i = -9; i <= 9; i++) {
    const pts: string[] = []
    for (let j = -9; j <= 9; j++) {
      const x = 350 + j * 32
      const y = 190 + i * 26
      const dx = x - 350, dy = y - 150
      const r = Math.hypot(dx, dy) + 1
      const pull = 2600 / (r * r + 400)
      pts.push(`${(x - (dx / r) * pull).toFixed(1)} ${(y - (dy / r) * pull).toFixed(1)}`)
    }
    cols.push(pts.join(' '))
  }
  return (
    <svg viewBox="0 0 700 380" width="100%" height="100%">
      {grid.map((p, i) => (
        <polyline key={`h${i}`} points={p} fill="none" stroke="#C9D6E4" strokeWidth="1.2" />
      ))}
      {cols.map((p, i) => (
        <polyline key={`v${i}`} points={p} fill="none" stroke="#C9D6E4" strokeWidth="1.2" />
      ))}

      {/* 天体 */}
      <circle cx="350" cy="150" r="26" fill="#111" />
      <circle cx="350" cy="150" r="36" fill="none" stroke="#8A96A6" strokeWidth="1.5"
        strokeDasharray="5 5" />

      {/* 光线 */}
      <path d="M 70 96 Q 350 172 640 74" fill="none" stroke="#C00000" strokeWidth="3.6" />
      <polygon points="652,72 634,66 636,80" fill="#C00000" />
      <text x="120" y="80" fontSize="18" fontFamily={HEI} fill="#C00000">光</text>

      <text x="350" y="330" textAnchor="middle" fontSize="19" fontFamily={HEI} fill="#5B7290">
        光走的是「最直的路」—— 但时空本身已经弯了
      </text>
      <text x="350" y="360" textAnchor="middle" fontSize="18" fontFamily={HEI} fill="#C00000">
        压得足够狠：连光都出不来 = 黑洞
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 15-1 P4：黑体单色辐出度曲线 —— 温度升高，整条曲线上移，峰值移向短波。
 *  曲线形状取自普朗克函数（峰值高度做了视觉归一，便于对照）。 */
export function BlackbodyCurves() {
  const X = (l: number) => 120 + (l / 3000) * 500
  const Y = (m: number) => 320 - m * 240
  const planck = (l: number, T: number) => {
    const x = 1.4388e7 / (l * T)
    if (x > 60) return 0
    return 1 / (Math.pow(l, 5) * (Math.exp(x) - 1))
  }
  const curve = (T: number, h: number) => {
    const lm = 2.898e6 / T
    const peak = planck(lm, T)
    const pts: string[] = []
    for (let i = 1; i <= 180; i++) {
      const l = (3000 * i) / 180
      pts.push(`${i === 1 ? 'M' : 'L'} ${X(l).toFixed(1)} ${Y((planck(l, T) / peak) * h).toFixed(1)}`)
    }
    return pts.join(' ')
  }
  return (
    <svg viewBox="0 0 700 380" width="100%" height="100%">
      <line x1="120" y1="320" x2="640" y2="320" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="652,320 638,314 638,326" fill="#8A96A6" />
      <line x1="120" y1="320" x2="120" y2="60" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="120,48 114,62 132,62" fill="#8A96A6" />
      <text x="96" y="72" fontSize="19" fontFamily={HEI} fill="#40556F">辐出度</text>
      <text x="620" y="352" fontSize="19" fontFamily={HEI} fill="#40556F">λ / nm</text>

      <rect x={X(400)} y="80" width={X(760) - X(400)} height="240" fill="#FFF6E0" />
      <text x={(X(400) + X(760)) / 2} y="312" textAnchor="middle" fontSize="16"
        fontFamily={HEI} fill="#B08A2E">可见光</text>

      <path d={curve(3000, 0.42)} fill="none" stroke="#1F6FBF" strokeWidth="3.6" />
      <path d={curve(6000, 1.0)} fill="none" stroke="#C00000" strokeWidth="3.6" />

      <line x1={X(483)} y1={Y(1.0)} x2={X(483)} y2="320" stroke="#C00000" strokeWidth="1.4"
        strokeDasharray="6 5" />
      <line x1={X(966)} y1={Y(0.42)} x2={X(966)} y2="320" stroke="#1F6FBF" strokeWidth="1.4"
        strokeDasharray="6 5" />

      <text x={X(483) + 12} y="96" fontSize="19" fontFamily={HEI} fill="#C00000">6000 K</text>
      <text x={X(966) + 12} y={Y(0.42) + 6} fontSize="19" fontFamily={HEI} fill="#1F6FBF">3000 K</text>

      <text x="350" y="372" textAnchor="middle" fontSize="18" fontFamily={HEI} fill="#5B7290">
        温度越高：总能量越大，峰值越靠短波
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 15-1 P7：紫外灾难 —— 瑞利-金斯公式在长波端与实验吻合，
 *  短波端却趋于无穷；普朗克公式才全波段吻合。 */
export function UvCatastrophe() {
  const X = (l: number) => 120 + (l / 2.4) * 500
  const Y = (m: number) => 320 - m * 250
  const planck = (l: number) => {
    const T = 2000
    const x = 1.4388e7 / (l * 1000 * T)
    return 1 / (Math.pow(l * 1000, 5) * (Math.exp(x) - 1))
  }
  const lm = (2.898e6 / 2000) / 1000
  const peak = planck(lm)
  const rj = (l: number) => 0.16 / Math.pow(l, 4)
  const line = (f: (x: number) => number) => {
    const pts: string[] = []
    for (let i = 1; i <= 150; i++) {
      const x = (2.4 * i) / 150
      pts.push(`${i === 1 ? 'M' : 'L'} ${X(x).toFixed(1)} ${Y(Math.min(f(x), 1.08)).toFixed(1)}`)
    }
    return pts.join(' ')
  }
  return (
    <svg viewBox="0 0 700 380" width="100%" height="100%">
      <line x1="120" y1="320" x2="640" y2="320" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="652,320 638,314 638,326" fill="#8A96A6" />
      <line x1="120" y1="320" x2="120" y2="60" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="120,48 114,62 132,62" fill="#8A96A6" />
      <text x="96" y="72" fontSize="19" fontFamily={HEI} fill="#40556F">辐出度</text>
      <text x="620" y="352" fontSize="19" fontFamily={HEI} fill="#40556F">λ / μm</text>

      {Array.from({ length: 9 }, (_, i) => {
        const x = 0.3 + i * 0.24
        return <circle key={i} cx={X(x)} cy={Y(planck(x) / peak)} r="4" fill="#40556F" />
      })}

      <path d={line(l => planck(l) / peak)} fill="none" stroke="#2E8B57" strokeWidth="3.6" />
      <path d={line(rj)} fill="none" stroke="#C00000" strokeWidth="3.4" strokeDasharray="9 6" />

      <text x={X(1.5)} y={Y(0.62)} fontSize="18" fontFamily={HEI} fill="#C00000">瑞利-金斯</text>
      <text x={X(1.5)} y={Y(0.52)} fontSize="16" fontFamily={HEI} fill="#C00000">（短波发散）</text>
      <text x={X(0.55)} y={Y(1.12)} fontSize="18" fontFamily={HEI} fill="#2E8B57">普朗克公式</text>
      <text x={X(0.55)} y={Y(1.02)} fontSize="16" fontFamily={HEI} fill="#40556F">● 实验值</text>

      <text x="350" y="372" textAnchor="middle" fontSize="18" fontFamily={HEI} fill="#C00000">
        紫外灾难：经典理论在短波端给出无穷大
      </text>
    </svg>
  )
}

