/* ============ 2-1 牛顿定律 图示 ============ */

/** 15-2 P4：光电流与电压的关系 —— 不同光强曲线形状相同、
 *  饱和电流成正比；反向电压到 -U_a 时电流为零。 */
export function IvCurve() {
  const X = (v: number) => 300 + v * 90
  const Y = (i: number) => 300 - i * 190
  const curve = (sat: number, _k: number) => {
    const pts: string[] = []
    for (let i = 0; i <= 120; i++) {
      const v = -1.2 + (4.2 * i) / 120
      const x = v + 1.2
      const val = sat * (1 - Math.exp(-3.2 * Math.pow(Math.max(x, 0), 0.9)))
      pts.push(`${i === 0 ? 'M' : 'L'} ${X(v).toFixed(1)} ${Y(val).toFixed(1)}`)
    }
    return pts.join(' ')
  }
  return (
    <svg viewBox="0 0 700 380" width="100%" height="100%">
      <line x1="180" y1="300" x2="640" y2="300" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="652,300 638,294 638,306" fill="#8A96A6" />
      <line x1={X(0)} y1="300" x2={X(0)} y2="60" stroke="#8A96A6" strokeWidth="2" />
      <polygon points={`${X(0)},48 ${X(0) - 6},62 ${X(0) + 6},62`} fill="#8A96A6" />
      <text x={X(0) + 14} y="70" fontSize="18" fontFamily={HEI} fill="#40556F">I</text>
      <text x="620" y="332" fontSize="18" fontFamily={HEI} fill="#40556F">U</text>
      <text x={X(0) - 12} y="322" textAnchor="end" fontSize="17" fontFamily={HEI} fill="#40556F">O</text>

      <path d={curve(1.0, 1)} fill="none" stroke="#C00000" strokeWidth="3.6" />
      <path d={curve(0.55, 1)} fill="none" stroke="#1F6FBF" strokeWidth="3.6" />
      <path d={curve(0.25, 1)} fill="none" stroke="#2E8B57" strokeWidth="3.6" />

      <line x1={X(-1.0)} y1="300" x2={X(-1.0)} y2="316" stroke="#40556F" strokeWidth="2" />
      <text x={X(-1.0)} y="336" textAnchor="middle" fontSize="17" fontStyle="italic"
        fontFamily={SERIF} fill="#40556F">−U_a</text>

      <text x={X(2.6)} y={Y(1.0) + 6} fontSize="17" fontFamily={HEI} fill="#C00000">强光</text>
      <text x={X(2.6)} y={Y(0.55) + 6} fontSize="17" fontFamily={HEI} fill="#1F6FBF">中强</text>
      <text x={X(2.6)} y={Y(0.25) + 6} fontSize="17" fontFamily={HEI} fill="#2E8B57">弱光</text>

      <text x="350" y="366" textAnchor="middle" fontSize="18" fontFamily={HEI} fill="#5B7290">
        同一频率：饱和电流与光强成正比，遏止电压相同
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 15-2 P8：遏止电压与频率的关系 —— 直线斜率是 h/e，
 *  与横轴的交点就是红限频率 ν₀，纵轴截距对应逸出功。 */
export function StoppingLine() {
  const X = (n: number) => 140 + n * 430
  const Y = (v: number) => 300 - v * 62
  const nu0 = 0.22
  const line = (n: number) => (n - nu0) * 1.55
  return (
    <svg viewBox="0 0 700 380" width="100%" height="100%">
      <line x1="140" y1="300" x2="620" y2="300" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="632,300 618,294 618,306" fill="#8A96A6" />
      <line x1="140" y1="300" x2="140" y2="80" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="140,68 134,82 146,82" fill="#8A96A6" />
      <text x="116" y="92" fontSize="18" fontFamily={HEI} fill="#40556F">U_a</text>
      <text x="600" y="332" fontSize="18" fontFamily={HEI} fill="#40556F">ν</text>

      {/* 不同金属：不同截距、同一斜率 */}
      <line x1={X(0.30)} y1={Y(line(0.30))} x2={X(0.98)} y2={Y(line(0.98))}
        stroke="#C00000" strokeWidth="3.4" />
      <line x1={X(nu0)} y1="300" x2={X(0.98)} y2={Y(line(0.98))} stroke="#C00000"
        strokeWidth="3.4" strokeDasharray="2 6" />

      <line x1={X(0.52)} y1={Y(0)} x2={X(0.95)} y2={Y(line(0.95) - 0.55)} stroke="#1F6FBF"
        strokeWidth="3.4" />
      <line x1={X(0.52)} y1="300" x2={X(0.52)} y2={Y(-0.02)} stroke="#1F6FBF" strokeWidth="1.4"
        strokeDasharray="5 4" />
      <text x={X(0.52)} y="322" textAnchor="middle" fontSize="17" fontStyle="italic"
        fontFamily={SERIF} fill="#1F6FBF">ν₀₂</text>
      <text x={X(nu0)} y="322" textAnchor="middle" fontSize="17" fontStyle="italic"
        fontFamily={SERIF} fill="#C00000">ν₀₁</text>

      <text x={X(0.72)} y={Y(0.62)} fontSize="17" fontFamily={HEI} fill="#C00000">金属 1</text>
      <text x={X(0.80)} y={Y(0.02)} fontSize="17" fontFamily={HEI} fill="#1F6FBF">金属 2</text>

      <text x="380" y="80" fontSize="17" fontFamily={HEI} fill="#40556F">
        斜率 = h/e —— 与材料无关
      </text>
      <text x="350" y="366" textAnchor="middle" fontSize="18" fontFamily={HEI} fill="#5B7290">
        不同金属的直线平行，截距不同 ⇒ 红限不同、逸出功不同
      </text>
    </svg>
  )
}

