/* ============ 2-1 牛顿定律 图示 ============ */

/** 15-8 P8：一维无限深方势阱 —— 阱内势能为零，阱外无穷大；
 *  波函数在壁上必须为零，所以只能容纳半波长的整数倍。 */
export function InfiniteWell() {
  const X = (x: number) => 110 + x * 440
  const n = (k: number) => [1, 2, 3][k]
  return (
    <svg viewBox="0 0 700 380" width="100%" height="100%">
      {/* 阱壁 */}
      <line x1={X(0)} y1="60" x2={X(0)} y2="300" stroke="#40556F" strokeWidth="4" />
      <line x1={X(1)} y1="60" x2={X(1)} y2="300" stroke="#40556F" strokeWidth="4" />
      <line x1="70" y1="60" x2={X(0)} y2="60" stroke="#40556F" strokeWidth="2.4" />
      <line x1={X(1)} y1="60" x2="590" y2="60" stroke="#40556F" strokeWidth="2.4" />
      <line x1="70" y1="300" x2="590" y2="300" stroke="#8A96A6" strokeWidth="2" />
      <text x="66" y="66" textAnchor="end" fontSize="17" fontStyle="italic"
        fontFamily={SERIF} fill="#40556F">U</text>
      <text x="60" y="306" textAnchor="end" fontSize="17" fontFamily={HEI} fill="#40556F">0</text>
      <text x={X(0)} y="326" textAnchor="middle" fontSize="17" fontFamily={HEI} fill="#40556F">0</text>
      <text x={X(1)} y="326" textAnchor="middle" fontSize="17" fontStyle="italic"
        fontFamily={SERIF} fill="#40556F">a</text>
      <text x="350" y="348" textAnchor="middle" fontSize="17" fontFamily="sans-serif" fill="#5B7290">
        阱内 U = 0，阱外 U → ∞；波函数在 x = 0 与 x = a 处必须为零
      </text>

      {/* n=1,2,3 波函数 */}
      {n(0) && [0, 1, 2].map(k => {
        const nn = k + 1
        const pts: string[] = []
        for (let i = 0; i <= 60; i++) {
          const x = i / 60
          const y = Math.sin(nn * Math.PI * x)
          pts.push(`${i === 0 ? 'M' : 'L'} ${X(x).toFixed(1)} ${(200 - y * 46).toFixed(1)}`)
        }
        return <path key={k} d={pts.join(' ')} fill="none"
          stroke={['#C00000', '#2E8B57', '#1F6FBF'][k]} strokeWidth="2.6" />
      })}
      <text x="596" y="196" fontSize="15" fontFamily={HEI} fill="#C00000">n=1</text>
      <text x="596" y="228" fontSize="15" fontFamily={HEI} fill="#8A96A6">（示意）</text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 15-8 P10：概率密度 |ψ|² —— n=1 时中间最大，n=2 时中间为零，
 *  节点数 = n−1。 */
export function ProbDensity() {
  const X = (x: number) => 110 + x * 440
  const panel = (k: number, y0: number) => {
    const nn = k + 1
    const pts: string[] = []
    for (let i = 0; i <= 80; i++) {
      const x = i / 80
      const v = Math.pow(Math.sin(nn * Math.PI * x), 2)
      pts.push(`${i === 0 ? 'M' : 'L'} ${X(x).toFixed(1)} ${(y0 - v * 60).toFixed(1)}`)
    }
    const color = ['#C00000', '#2E8B57', '#1F6FBF'][k]
    return (
      <g key={k}>
        <line x1={X(0)} y1={y0} x2={X(1)} y2={y0} stroke="#C9D6E4" strokeWidth="1.6" />
        <line x1={X(0)} y1={y0} x2={X(0)} y2={y0 - 66} stroke="#40556F" strokeWidth="2" />
        <line x1={X(1)} y1={y0} x2={X(1)} y2={y0 - 66} stroke="#40556F" strokeWidth="2" />
        <path d={pts.join(' ')} fill="none" stroke={color} strokeWidth="2.6" />
        <text x={X(1) + 12} y={y0 - 30} fontSize="16" fontFamily={HEI} fill={color}>n={nn}</text>
      </g>
    )
  }
  return (
    <svg viewBox="0 0 700 380" width="100%" height="100%">
      {panel(0, 110)}
      {panel(1, 214)}
      {panel(2, 318)}
      <text x="350" y="36" textAnchor="middle" fontSize="17" fontFamily={HEI} fill="#5B7290">
        概率密度 |ψ|²：n=1 中间最大；n=2 中间恰为零
      </text>
      <text x="330" y="366" textAnchor="middle" fontSize="16" fontFamily={HEI} fill="#8A96A6">
        节点（概率为零处）有 n−1 个
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 15-9 P6：角动量的空间量子化 —— 角动量大小固定，
 *  但它在外磁场方向的投影只能取 m_l ħ，共 2l+1 个方向。 */
export function SpaceQuantization() {
  const C: [number, number] = [300, 210]
  const R = 120
  const angles = [-60, -20, 20, 60]
  return (
    <svg viewBox="0 0 700 380" width="100%" height="100%">
      {/* 磁场方向 */}
      <line x1={C[0]} y1={C[1] + 140} x2={C[0]} y2={C[1] - 150} stroke="#8A96A6"
        strokeWidth="2" strokeDasharray="7 6" />
      <text x={C[0] + 10} y={C[1] - 140} fontSize="18" fontStyle="italic"
        fontFamily={SERIF} fill="#40556F">z（B 方向）</text>

      {/* 投影刻度 */}
      {[-2, -1, 0, 1, 2].map(k => (
        <g key={k}>
          <line x1={C[0] - 8} y1={C[1] - k * 34} x2={C[0] + 8} y2={C[1] - k * 34}
            stroke="#40556F" strokeWidth="2" />
          <text x={C[0] - 18} y={C[1] - k * 34 + 6} textAnchor="end" fontSize="16"
            fontStyle="italic" fontFamily={SERIF} fill="#40556F">
            {k === 0 ? '0' : `${k}ħ`}
          </text>
        </g>
      ))}

      {/* 四个取向 */}
      {angles.map((a, i) => {
        const rad = (a * Math.PI) / 180
        const x2 = C[0] + R * Math.sin(rad)
        const y2 = C[1] - R * Math.cos(rad)
        return (
          <g key={i}>
            <line x1={C[0]} y1={C[1]} x2={x2} y2={y2} stroke="#C00000" strokeWidth="3" />
            <polygon points={`${x2},${y2} ${x2 - 8},${y2 + 12} ${x2 + 8},${y2 + 12}`}
              fill="#C00000" />
            <line x1={x2} y1={y2} x2={C[0]} y2={y2} stroke="#C9D6E4" strokeWidth="1.4"
              strokeDasharray="5 4" />
          </g>
        )
      })}
      <circle cx={C[0]} cy={C[1]} r="6" fill="#111" />

      <text x="470" y="120" fontSize="20" fontStyle="italic" fontFamily="serif"
        fill="#C00000">L_z = m_l ħ</text>
      <text x="470" y="156" fontSize="17" fontFamily="sans-serif" fill="#5B7290">
        共 2l+1 个取向
      </text>
      <text x="470" y="192" fontSize="17" fontFamily="sans-serif" fill="#5B7290">
        这就是空间量子化
      </text>

      <text x="350" y="362" textAnchor="middle" fontSize="16" fontFamily="sans-serif"
        fill="#5B7290">
        外磁场中谱线分裂（正常塞曼效应）就源于此
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 15-9 P9：基态径向概率密度 —— 电子出现在 r 到 r+dr 之间的概率，
 *  在 r = a₀（玻尔半径）处最大。 */
export function RadialProb() {
  const X = (r: number) => 110 + (r / 6) * 470
  const Y = (p: number) => 300 - p * 230
  const f = (r: number) => {
    const a = 1
    return 4 * (r * r) / (a * a * a) * Math.exp((-2 * r) / a)
  }
  const pts: string[] = []
  for (let k = 0; k <= 180; k++) {
    const r = (6 * k) / 180
    pts.push(`${k === 0 ? 'M' : 'L'} ${X(r).toFixed(1)} ${Y(Math.min(f(r) / 1.1, 1.05)).toFixed(1)}`)
  }
  return (
    <svg viewBox="0 0 700 380" width="100%" height="100%">
      <line x1="110" y1="300" x2="620" y2="300" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="632,300 618,294 618,306" fill="#8A96A6" />
      <line x1="110" y1="300" x2="110" y2="60" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="110,48 104,62 116,62" fill="#8A96A6" />
      <text x="86" y="72" fontSize="17" fontFamily="sans-serif" fill="#40556F">p(r)</text>
      <text x="600" y="330" textAnchor="end" fontSize="17" fontStyle="italic"
        fontFamily="serif" fill="#40556F">r</text>

      <path d={pts.join(' ')} fill="none" stroke="#1F6FBF" strokeWidth="3.2" />

      <line x1={X(1)} y1="300" x2={X(1)} y2={Y(f(1) / 1.1)} stroke="#C00000"
        strokeWidth="1.6" strokeDasharray="6 5" />
      <circle cx={X(1)} cy={Y(f(1) / 1.1)} r="6" fill="#C00000" />
      <text x={X(1)} y="324" textAnchor="middle" fontSize="17" fontStyle="italic"
        fontFamily="serif" fill="#C00000">a₀</text>
      <text x={X(1) + 14} y={Y(f(1) / 1.1) - 12} fontSize="16" fontFamily="sans-serif"
        fill="#C00000">概率最大</text>

      <text x="350" y="360" textAnchor="middle" fontSize="16" fontFamily="sans-serif"
        fill="#5B7290">
        玻尔半径不是「轨道半径」，而是电子最可能出现的距离
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 15-13 P3：超导转变 —— 温度降到临界温度 Tc 时，电阻率突降为零。 */
export function SuperResistance() {
  const X = (t: number) => 110 + (t / 5) * 480
  const Y = (r: number) => 300 - r * 230
  const pts: string[] = []
  for (let k = 0; k <= 200; k++) {
    const t = (5 * k) / 200
    const r = t < 4.2 ? 0 : 0.02 + 0.00008 * Math.pow(t - 4.2, 2.2) * 20
    pts.push(`${k === 0 ? 'M' : 'L'} ${X(t).toFixed(1)} ${Y(Math.min(r, 1)).toFixed(1)}`)
  }
  return (
    <svg viewBox="0 0 700 360" width="100%" height="100%">
      <line x1="110" y1="300" x2="620" y2="300" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="632,300 618,294 618,306" fill="#8A96A6" />
      <line x1="110" y1="300" x2="110" y2="60" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="110,48 104,62 116,62" fill="#8A96A6" />
      <text x="86" y="72" fontSize="17" fontFamily="sans-serif" fill="#40556F">ρ</text>
      <text x="600" y="330" textAnchor="end" fontSize="17" fontStyle="italic"
        fontFamily="serif" fill="#40556F">T / K</text>

      <path d={pts.join(' ')} fill="none" stroke="#1F6FBF" strokeWidth="3.2" />
      <line x1={X(4.2)} y1="300" x2={X(4.2)} y2="86" stroke="#C00000" strokeWidth="1.6"
        strokeDasharray="6 5" />
      <text x={X(4.2)} y="326" textAnchor="middle" fontSize="17" fontStyle="italic"
        fontFamily="serif" fill="#C00000">Tc = 4.2 K</text>
      <text x={X(2.0)} y="150" textAnchor="middle" fontSize="17" fontFamily="sans-serif"
        fill="#C00000">超导态 ρ = 0</text>
      <text x={X(4.6)} y="120" fontSize="17" fontFamily="sans-serif" fill="#40556F">正常态</text>

      <text x="350" y="350" textAnchor="middle" fontSize="16" fontFamily="sans-serif"
        fill="#5B7290">
        1911 年，昂尼斯在汞上首次发现：4.2 K 附近电阻突然消失
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 15-15 P4：表面原子比例随粒径减小而急剧上升（数据取自教案表格）。 */
export function NanoSurface() {
  const data = [
    { d: 10, p: 20 },
    { d: 4, p: 40 },
    { d: 2, p: 80 },
    { d: 1, p: 99 },
  ]
  const X = (i: number) => 150 + i * 120
  const Y = (p: number) => 300 - p * 2.2
  return (
    <svg viewBox="0 0 700 380" width="100%" height="100%">
      <line x1="120" y1="300" x2="620" y2="300" stroke="#8A96A6" strokeWidth="2" />
      <line x1="120" y1="300" x2="120" y2="60" stroke="#8A96A6" strokeWidth="2" />
      <text x="96" y="72" fontSize="16" fontFamily="sans-serif" fill="#40556F">%</text>
      <text x="600" y="330" textAnchor="end" fontSize="16" fontFamily="sans-serif"
        fill="#40556F">粒径 / nm</text>

      {[0, 50, 100].map(v => (
        <g key={v}>
          <line x1="112" y1={Y(v)} x2="120" y2={Y(v)} stroke="#8A96A6" strokeWidth="2" />
          <text x="106" y={Y(v) + 6} textAnchor="end" fontSize="15" fontFamily="sans-serif"
            fill="#5B7290">{v}</text>
        </g>
      ))}

      {data.map((d, i) => (
        <g key={d.d}>
          <rect x={X(i) - 26} y={Y(d.p)} width="52" height={300 - Y(d.p)} fill="#DCE9F9"
            stroke="#1F6FBF" strokeWidth="2" />
          <text x={X(i)} y={Y(d.p) - 10} textAnchor="middle" fontSize="17"
            fontFamily="sans-serif" fill="#C00000">{d.p}%</text>
          <text x={X(i)} y="324" textAnchor="middle" fontSize="16" fontFamily="sans-serif"
            fill="#40556F">{d.d}</text>
        </g>
      ))}

      <text x="350" y="356" textAnchor="middle" fontSize="16" fontFamily="sans-serif"
        fill="#5B7290">
        粒径越小，表面原子占比越大 —— 1 nm 时几乎全是表面原子
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 15-10 P6：能级填充顺序 —— 按能量由低到高填，
 *  所以 4s 先于 3d，5s 先于 4d（化学里的「对角线规则」）。 */
export function FillingOrder() {
  const rows = [
    { n: 1, subs: ['1s'] },
    { n: 2, subs: ['2s', '2p'] },
    { n: 3, subs: ['3s', '3p', '3d'] },
    { n: 4, subs: ['4s', '4p', '4d'] },
    { n: 5, subs: ['5s', '5p'] },
  ]
  const X = (col: number) => 170 + col * 120
  const Y = (row: number) => 92 + row * 52
  return (
    <svg viewBox="0 0 700 380" width="100%" height="100%">
      {['s', 'p', 'd'].map((t, c) => (
        <text key={t} x={X(c)} y="62" textAnchor="middle" fontSize="16"
          fontFamily="sans-serif" fill="#5B7290">{t}</text>
      ))}
      {rows.map((r, i) => (
        <g key={r.n}>
          <text x="120" y={Y(i) + 6} textAnchor="end" fontSize="16" fontStyle="italic"
            fontFamily="serif" fill="#40556F">n={r.n}</text>
          {r.subs.map((name, c) => (
            <g key={name}>
              <rect x={X(c) - 42} y={Y(i) - 18} width="84" height="34" rx="5"
                fill="#DCE9F9" stroke="#1F6FBF" strokeWidth="2" />
              <text x={X(c)} y={Y(i) + 6} textAnchor="middle" fontSize="17"
                fontFamily="sans-serif" fill="#1F6FBF">{name}</text>
            </g>
          ))}
        </g>
      ))}

      <path d="M 210 80 L 330 132 L 450 184" fill="none" stroke="#C00000"
        strokeWidth="2.2" strokeDasharray="7 5" />
      <text x="470" y="150" fontSize="16" fontFamily="sans-serif" fill="#C00000">
        填充方向 →
      </text>

      <text x="350" y="356" textAnchor="middle" fontSize="16" fontFamily="sans-serif"
        fill="#5B7290">
        1s → 2s → 2p → 3s → 3p → 4s → 3d …… 顺序不是简单按 n 排
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

