      {[0, 1, 2].map(i => (
        <g key={i}>
          <circle cx={250 + i * 90} cy={150 + (i % 2) * 24} r="7" fill="#C00000" />
        </g>
      ))}
      <line x1="200" y1="258" x2="480" y2="258" stroke="#2E8B57" strokeWidth="2.4" />
