/* ============ 2-1 牛顿定律 图示 ============ */

/** 15-12 P3：能带的分裂 —— 原子越靠近，能级分裂成越多的子能级，
 *  N 个原子就分裂成 N 条，密集成「带」。 */
export function BandSplit() {
  const panel = (x: number, n: number, label: string, spread: number) => (
    <g key={x}>
      <line x1={x + 20} y1="90" x2={x + 120} y2="90" stroke="#8A96A6" strokeWidth="1.4"
        strokeDasharray="5 4" />
      <line x1={x + 20} y1="250" x2={x + 120} y2="250" stroke="#8A96A6" strokeWidth="1.4"
        strokeDasharray="5 4" />
      {Array.from({ length: n }, (_, i) => {
        const dy = n === 1 ? 0 : (i / (n - 1) - 0.5) * spread
        const dy2 = n === 1 ? 0 : (i / (n - 1) - 0.5) * spread * 0.8
        return (
          <g key={i}>
            <line x1={x + 20} y1={90 + dy} x2={x + 120} y2={90 + dy} stroke="#1F6FBF"
              strokeWidth="2" />
            <line x1={x + 20} y1={250 + dy2} x2={x + 120} y2={250 + dy2} stroke="#C00000"
              strokeWidth="2" />
          </g>
        )
      })}
      <text x={x + 70} y="300" textAnchor="middle" fontSize="15" fontFamily="sans-serif"
        fill="#40556F">{label}</text>
    </g>
  )
  return (
    <svg viewBox="0 0 700 340" width="100%" height="100%">
      {panel(40, 1, '1 个原子', 0)}
      {panel(240, 4, '4 个原子', 34)}
      {panel(440, 12, 'N 个原子', 90)}
      <text x="350" y="34" textAnchor="middle" fontSize="17" fontFamily="sans-serif"
        fill="#5B7290">
        原子越靠近，能级分裂得越细，最后密集成「能带」
      </text>
      <text x="140" y="330" fontSize="14" fontFamily="sans-serif" fill="#8A96A6">2p</text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 16-1 P8：放射性衰变曲线 —— N = N₀e^(−λt)，每过一个半衰期减半。 */
export function DecayCurve() {
  const X = (t: number) => 110 + t * 160
  const Y = (n: number) => 300 - n * 220
  const pts: string[] = []
  for (let k = 0; k <= 200; k++) {
    const t = (k / 200) * 3.4
    pts.push(`${k === 0 ? 'M' : 'L'} ${X(t).toFixed(1)} ${Y(Math.exp(-0.693 * t)).toFixed(1)}`)
  }
  return (
    <svg viewBox="0 0 700 360" width="100%" height="100%">
      <line x1="110" y1="300" x2="620" y2="300" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="632,300 618,294 618,306" fill="#8A96A6" />
      <line x1="110" y1="300" x2="110" y2="60" stroke="#8A96A6" strokeWidth="2" />
      <polygon points="110,48 104,62 116,62" fill="#8A96A6" />
      <text x="86" y="72" fontSize="17" fontStyle="italic" fontFamily="serif"
        fill="#40556F">N</text>
      <text x="642" y="336" textAnchor="end" fontSize="17" fontStyle="italic"
        fontFamily="serif" fill="#40556F">t</text>

      <path d={pts.join(' ')} fill="none" stroke="#1F6FBF" strokeWidth="3.2" />

      {[1, 2, 3].map(k => (
        <g key={k}>
          <line x1={X(k)} y1={Y(Math.pow(0.5, k))} x2={X(k)} y2="300" stroke="#C00000"
            strokeWidth="1.4" strokeDasharray="6 5" />
          <line x1="110" y1={Y(Math.pow(0.5, k))} x2={X(k)} y2={Y(Math.pow(0.5, k))}
            stroke="#C9D6E4" strokeWidth="1.4" strokeDasharray="5 4" />
          <circle cx={X(k)} cy={Y(Math.pow(0.5, k))} r="5" fill="#C00000" />
          <text x={X(k)} y="322" textAnchor="middle" fontSize="15" fontStyle="italic"
            fontFamily="serif" fill="#C00000">{k}T</text>
        </g>
      ))}
      <text x="124" y={Y(0.5) + 6} fontSize="15" fontFamily="sans-serif" fill="#40556F">N₀/2</text>
      <text x="124" y={Y(0.25) + 6} fontSize="15" fontFamily="sans-serif" fill="#40556F">N₀/4</text>

      <text x="350" y="350" textAnchor="middle" fontSize="15" fontFamily="sans-serif"
        fill="#5B7290">
        每过一个半衰期，剩下的核数减半 —— 这是统计规律，不是单个核的寿命
      </text>
    </svg>
  )
}

/* ============ 2-1 牛顿定律 图示 ============ */

/** 16-2 P5：四种基本相互作用的强度与力程对比（对数坐标的示意）。 */
export function FourForces() {
  const rows = [
    { name: '强力', rel: '1', range: '10⁻¹⁵ m', w: 340, c: '#C00000' },
    { name: '电磁力', rel: '10⁻²', range: '∞', w: 210, c: '#1F6FBF' },
    { name: '弱力', rel: '10⁻¹³', range: '10⁻¹⁸ m', w: 110, c: '#2E8B57' },
    { name: '万有引力', rel: '10⁻³⁸', range: '∞', w: 40, c: '#8A96A6' },
  ]
  return (
    <svg viewBox="0 0 700 320" width="100%" height="100%">
      {rows.map((r, i) => (
        <g key={r.name}>
          <text x="110" y={70 + i * 58} textAnchor="end" fontSize="17" fontFamily="sans-serif"
            fill="#40556F">{r.name}</text>
          <rect x="130" y={54 + i * 58} width={r.w} height="24" rx="4" fill={r.c} opacity="0.85" />
          <text x={140 + r.w} y={70 + i * 58} fontSize="15" fontFamily="sans-serif"
            fill="#5B7290">相对强度 {r.rel}</text>
          <text x={640} y={70 + i * 58} textAnchor="end" fontSize="15" fontFamily="sans-serif"
            fill="#8A96A6">{r.range}</text>
        </g>
      ))}
      <text x="350" y="300" textAnchor="middle" fontSize="16" fontFamily="sans-serif"
        fill="#5B7290">
        强度差几十个数量级 —— 所以万有引力在粒子世界里完全可忽略
      </text>
    </svg>
  )
}

